async function loadServiceDataOnce({ silent = false } = {}) {
  if (!requireClient({ silent })) {
    state.serviceError = "연결 없음";
    render();
    return;
  }
  try {
    await ensureSingleSongActivation();
    await loadWorshipData();
    if (state.selectedServiceId && presenterServiceNeedsHymnScoreManifest(state.selectedServiceId)) {
      await loadHymnScoreManifest({ silent });
    }
    restorePresenterControllerSession();
    if (state.module === "presenter") {
      await loadWorshipPresenterSlides(presenterViewServiceId(), { renderControls: false });
      restorePresenterControllerSession();
    }
    state.dirtyServiceTypeIds.clear();
    state.dirty.service = false;
    captureCleanFingerprint("service");
    state.serviceError = "";
    render();
    return;
  } catch (err) {
    if (!silent) console.error("[Service] loadWorshipData failed:", err);
    state.serviceError = err.message || String(err) || "Could not load worship data.";
    if (!silent && isServiceDataModule()) showToast(state.serviceError, "error");
    render();
  }
}

async function fetchSupabasePaged(table, select = "*", buildQuery = (query) => query, pageSize = 1000) {
  pageSize = Math.min(Math.max(1, Number(pageSize) || 1000), 1000);
  const rows = [];
  for (let start = 0; ; start += pageSize) {
    const end = start + pageSize - 1;
    const query = buildQuery(state.client.from(table).select(select)).range(start, end);
    const { data, error } = await query;
    if (error) throw error;
    rows.push(...(data || []));
    if (!data || data.length < pageSize) return rows;
  }
}

async function fetchSupabaseBatches(ids, fetchBatch, { concurrency = 3 } = {}) {
  const rows = [];
  const batches = chunkArray([...new Set(ids)], 80);
  for (const group of chunkArray(batches, concurrency)) {
    // Settle the whole group before releasing a load lock or falling back to cache.
    const results = await Promise.allSettled(group.map((batch) => fetchBatch(batch)));
    const failure = results.find((result) => result.status === "rejected");
    if (failure) throw failure.reason;
    rows.push(...results.flatMap((result) => result.value));
  }
  return rows;
}

function yieldToBrowser() {
  return new Promise((resolve) => globalThis.setTimeout(resolve, 0));
}

const SUPABASE_STATIC_CACHE_TTL_MS = 6 * 60 * 60 * 1000;
const SUPABASE_STATIC_CACHE_PREFIX = "mindex.supabase.static.v1.";
const BIBLE_CHAPTER_CACHE_TTL_MS = 12 * 60 * 60 * 1000;
const BIBLE_CHAPTER_CACHE_PREFIX = "mindex.bible.chapter.v3.";
// Discard reproducible corpus caches once; personal/service storage is untouched.
function purgeLegacyBibleCaches(storage) {
  const marker = "mindex.bible.source-cache-purged.20261016";
  if (storage.getItem(marker) === "complete") return 0;
  let removed = 0;
  const catalogues = ["mindex_bible_translations", "mindex_bible_verses", "mindex_scripture_books"];
  for (let i = storage.length - 1; i >= 0; i--) {
    const key = storage.key(i);
    if (key?.startsWith("mindex.bible.chapter.") || catalogues.some(table => key?.startsWith(`mindex.supabase.static.v1.${table}:`))) {
      storage.removeItem(key);removed++;
    }
  }
  storage.setItem(marker, "complete");return removed;
}
try { purgeLegacyBibleCaches(window.localStorage); } catch { /* Optional cache storage can be unavailable. */ }
function refreshAsvCatalogueCache(storage) {
  const marker = "mindex.bible.asv-catalogue.20261016";
  if (storage.getItem(marker) === "complete") return;
  for (let i = storage.length - 1; i >= 0; i--) {
    const key = storage.key(i);
    if (key?.startsWith("mindex.supabase.static.v1.mindex_bible_translations:")) storage.removeItem(key);
  }
  storage.setItem(marker, "complete");
}
try { refreshAsvCatalogueCache(window.localStorage); } catch { /* Reproducible catalogue only. */ }

