function sundayMainWorshipServiceVariantForDate(dateValue = "") {
  const targetDate = toLocalDateStr(dateValue);
  if (!targetDate || !isAllGenerationsWorshipDate(targetDate)) return null;
  return {
    title: ALL_GENERATION_MAIN_PRAISE_SERVICE_ALIAS,
    alias: ALL_GENERATION_MAIN_PRAISE_SERVICE_ALIAS,
    sourceRef: {
      sunday_main_variant: "all_generations",
      sunday_main_variant_name: ALL_GENERATION_MAIN_PRAISE_SERVICE_ALIAS,
      auto_generated: true,
    },
  };
}

function fridayWeekOfMonth(dateValue = "") {
  const target = parseLocalDate(dateValue);
  if (Number.isNaN(target.getTime()) || target.getDay() !== 5) return 0;
  let count = 0;
  for (let day = 1; day <= target.getDate(); day += 1) {
    const date = new Date(target);
    date.setDate(day);
    if (date.getDay() === 5) count += 1;
  }
  return count;
}

function fridayServiceVariantForDate(dateValue = "") {
  const date = String(dateValue || "").trim().slice(0, 10);
  if (!date || date < FRIDAY_SERVICE_VARIANT_START_DATE) return null;
  const week = fridayWeekOfMonth(date);
  if ((week === 2 || week === 3) && date.slice(0, 7) !== "2026-08") return null;
  return FRIDAY_SERVICE_VARIANTS[week] || null;
}

function autoFridayServiceTarget(date = "") {
  const variant = fridayServiceVariantForDate(date);
  if (!variant) return { typeId: "friday", date };
  return {
    typeId: variant.typeId,
    date,
    title: variant.title,
    alias: variant.alias,
    sourceRef: {
      friday_variant: variant.key,
      friday_variant_name: variant.displayName,
      friday_template: variant.templateNote,
      ...(variant.noGathering ? { no_gathering: true } : {}),
    },
  };
}

function isAllGenerationsWorshipContext(text = "") {
  const compact = compactSearchValue(text);
  return compact.includes("온세대찬양예배");
}

function calendarTextForDate(date) {
  const targetDate = toLocalDateStr(date);
  if (!targetDate) return "";
  return (state.calendarData || [])
    .filter((row) => toLocalDateStr(row?.date) === targetDate)
    .map((row) => row.church_schedule)
    .join(" ");
}

function isAllGenerationsWorshipDate(date) {
  return isAllGenerationsWorshipContext(calendarTextForDate(date));
}

const CALENDAR_SERVICE_SKIP_CONTEXTS = [
  { typeId: "children", aliases: ["어린이부", "아동부", "유초등부"] },
  { typeId: "nursery", aliases: ["유치부", "유아부"] },
  { typeId: "youth", aliases: ["청소년부", "중고등부"] },
  { typeId: "young-adult", aliases: ["청년부", "청년"] },
];
const CALENDAR_SERVICE_SKIP_KEYWORDS = ["야외예배", "문화예배"];

function calendarSkippedServiceTypesForDate(date) {
  const compact = compactSearchValue(calendarTextForDate(date));
  const skipped = new Set();
  if (!compact) return skipped;
  for (const context of CALENDAR_SERVICE_SKIP_CONTEXTS) {
    const matchesAlternative = context.aliases.some((alias) => {
      const aliasKey = compactSearchValue(alias);
      return CALENDAR_SERVICE_SKIP_KEYWORDS.some((keyword) => {
        const keywordKey = compactSearchValue(keyword);
        return compact.includes(`${aliasKey}${keywordKey}`)
          || compact.includes(`${keywordKey}${aliasKey}`);
      });
    });
    if (matchesAlternative) skipped.add(context.typeId);
  }
  return skipped;
}

function isAllGenerationsWorshipService(service = null) {
  if (!service || typeof service !== "object") return false;
  if (worshipAppServiceTypeId(service?.type_id || service?.service_type_id || "") !== "sunday-main") return false;
  const sourceRef = serviceRawSourceRef(service);
  const variant = String(sourceRef.sunday_main_variant || "").trim().toLowerCase();
  // A saved, explicitly named service must not turn into a regular 3rd service
  // while calendar data is loading. Automatic scheduling still uses the calendar.
  if (variant === "all_generations") return true;
  if ([service.alias, service.service_alias].some(alias =>
    compactSearchValue(alias || "") === compactSearchValue(ALL_GENERATION_MAIN_PRAISE_SERVICE_ALIAS))) return true;
  return isAllGenerationsWorshipDate(service?.date || service?.service_date || service?.serviceDate || "")
    || isAllGenerationsWorshipDate(service?._worshipServiceDate || "");
}

function allGenerationsHasOfferingReplacement(service, items = null) {
  if (allGenerationsOfferingMediaSpec(service)) return true;
  const candidates = items || state.serviceItems[service?.id] || [];
  return candidates.some(item => {
    const slot = serviceItemSlotKey(item);
    const label = compactSearchValue(item.label || "");
    return ["offering.special", "offering.media"].includes(slot)
      || (templateProjectionSectionKey(item) === "offering"
        && ["봉헌특송", "봉헌영상", "감사이미지"].includes(label));
  });
}

function worshipServiceParticipatesInSharedSundayContent(service = null, item = null) {
  if (!isAllGenerationsWorshipService(service)) return true;
  return Boolean(item && sundaySharedContentKey(item, service) === "offering-hymn"
    && !allGenerationsHasOfferingReplacement(service));
}

function worshipServiceExistsForTarget(target = {}) {
  const targetTypeId = worshipAppServiceTypeId(target.typeId);
  const targetDate = String(target.date || "").trim();
  if (!targetTypeId || !targetDate) return true;
  return state.services.some((service) =>
    worshipAppServiceTypeId(service.type_id) === targetTypeId
    && String(service.date || "").trim() === targetDate);
}

function autoWorshipServicePayload(target = {}) {
  const typeId = worshipAppServiceTypeId(target.typeId);
  const persistedAt = new Date().toISOString();
  const sourceRef = target.sourceRef && typeof target.sourceRef === "object" ? target.sourceRef : {};
  const payload = {
    id: createUuid(),
    service_type_id: canonicalWorshipServiceTypeId(typeId),
    service_date: target.date,
    created_at: persistedAt,
    updated_at: persistedAt,
    title: String(target.title || "").trim(),
    status: "draft",
    worship_leader: "",
    praise_leader: serviceUsesPraiseLeader(typeId) ? defaultServicePraiseLeader(typeId, { date: target.date, alias: target.alias, source_ref: sourceRef }) : "",
    source_kind: "mindex",
    source_ref: {
      created_from: "mindex_auto_schedule",
      app_service_type_id: typeId,
      auto_generated: true,
      ...sourceRef,
    },
    notes: "",
  };
  if (state.serviceAliasSupported) payload.service_alias = String(target.alias || "").trim();
  return payload;
}

async function ensureUpcomingPublicWorshipServices(baseDate = new Date()) {
  if (!state.client) return [];
  await loadCalendarData({ silent: true });
  // Scheduling only creates missing instances; existing services require explicit user deletion.
  const missingTargets = autoUpcomingPublicServiceTargets(baseDate).filter((target) => !worshipServiceExistsForTarget(target));
  if (!missingTargets.length) return [];
  const payloads = missingTargets.map(autoWorshipServicePayload);
  const data = await insertWorshipServicesWithCalendarAssignees(payloads);
  return data.map(normalizeWorshipService);
}

function worshipAppServiceTypeId(typeId) {
  return Object.hasOwn(WORSHIP_SERVICE_TYPE_ALIASES, typeId) ? WORSHIP_SERVICE_TYPE_ALIASES[typeId] : typeId || "";
}

async function loadWorshipData() {
  const [types, services] = await Promise.all([
    fetchCachedSupabasePaged("mindex_worship_service_types", WORSHIP_SERVICE_TYPE_SELECT, (query) =>
      query.order("sort_order", { ascending: true })).catch((error) => {
        console.warn("Could not load worship service types; using defaults.", error);
        return [];
      }),
    fetchWorshipServiceListRows(),
  ]);

  const resolvedTypes = types.length ? types : defaultWorshipServiceTypes();
  state.serviceTypes = resolvedTypes.map(normalizeWorshipServiceType);
  state.services = services.map(normalizeWorshipService);
  state.templateElementSuppressions.clear();
  state.worshipTemplates = [];
  state.worshipTemplateItems = [];

  // Home cards are the actual service overview, so preload their lightweight
  // row data before rendering them. Other modules can show their shell first.
  state.worshipSections = [];
  state.worshipElements = [];
  state.loadedWorshipServiceIds = new Set();
  serviceViewLoadErrors.clear();
  // Unopened services project lazily through getServiceItems; do not build every archive.
  state.serviceItems = {};
  state.worshipPresenterSlides = {};
  state.worshipPresenterSlidesLoaded = false;
  state.loadedWorshipPresenterServiceIds = new Set();
  worshipPresenterSlideLoadPromises.clear();
  worshipScripturePreloadPromises.clear();
  serviceItemScripturePreloadPromises.clear();

  const preloadServiceIds = initialWorshipElementServiceIds(state.services);
  const deferSelectedPresenterRender = Boolean(
    state.module === "presenter"
    && state.selectedServiceId
    && preloadServiceIds.includes(state.selectedServiceId),
  );
  let sections = [];
  let elements = [];
  if (!deferSelectedPresenterRender) render();
  if (preloadServiceIds.length) {
    ({ sections, elements } = await fetchWorshipRowsForServiceIds(preloadServiceIds));
    state.worshipSections = sections;
    state.worshipElements = elements;
    state.loadedWorshipServiceIds = new Set(preloadServiceIds);
    state.serviceItems = projectGroupedWorshipItemsFromTemplates(groupWorshipElements(sections, elements), preloadServiceIds);
  }
  const prioritizedPresenterSongLoad = Boolean(
    state.module === "presenter"
    && state.selectedServiceId
    && elements.some((item) => item.song_id),
  );
  if (prioritizedPresenterSongLoad) {
    await loadSongsForIds(elements.map((item) => item.song_id));
  }
  state.serviceItemAssigneeSupported = true;
  state.serviceItemVersionSupported = true;
  state.serviceItemMemoSupported = true;

  // loadServiceDataOnce renders the completed rows after restoring controller
  // state and clearing load flags. Do not rebuild all home cards immediately
  // before that same final render; other modules keep their intermediate view.
  if (!prioritizedPresenterSongLoad && state.module !== "home") render();
  void hydrateSupplementalWorshipDataAfterInitialRender().catch((error) => {
    console.warn("Could not hydrate supplemental worship data.", error);
  });
  if (
    state.selectedServiceId
    && state.module !== "bulletin"
    && (state.module === "presenter" || isServiceDataModule())
    && !shouldDeferPastWorshipServiceLoad(state.selectedServiceId)
  ) {
    const hydrationServiceId = state.selectedServiceId;
    void hydratePresenterServiceData(state.selectedServiceId).then(() => {
      if (
        !prioritizedPresenterSongLoad
        && state.selectedServiceId === hydrationServiceId
        && (state.module === "presenter" || state.module === "service")
      ) {
        renderCurrentServiceModuleDetail();
      }
    }).catch((error) => {
      console.warn("Could not hydrate selected worship service in background.", error);
    });
  }
  if (!prioritizedPresenterSongLoad) {
    loadSongsForIdsInBackground(elements.map((item) => item.song_id), {
      render: "detail",
      serviceId: state.selectedServiceId,
    });
  }
}

async function hydrateSupplementalWorshipDataAfterInitialRender() {
  const [templates, templateItems] = await Promise.all([
    fetchCachedSupabasePaged("mindex_worship_templates", "*", (query) =>
      query.order("template_level", { ascending: true }).order("name", { ascending: true })).catch((error) => {
        console.warn("Could not load worship templates; using persisted service rows only.", error);
        return [];
      }),
    fetchCachedSupabasePaged("mindex_worship_template_items", "*", (query) =>
      query.order("template_id", { ascending: true }).order("sort_order", { ascending: true })).catch((error) => {
        console.warn("Could not load worship template items; using persisted service rows only.", error);
        return [];
      }),
    loadCalendarData({ silent: true }),
  ]);
  state.worshipTemplates = templates;
  state.worshipTemplateItems = templateItems;

  if (!WORSHIP_EMERGENCY_TODAY_ONLY) {
    const autoServices = await ensureUpcomingPublicWorshipServices();
    if (autoServices.length) state.services = sortServicesByDate([...state.services, ...autoServices]);
  }

  if (isServiceDataModule()) {
    renderServiceList();
    renderCurrentServiceModuleDetail();
  }
}

async function loadWorshipPresenterSlides(serviceId = "", options = {}) {
  if (!state.client) return;
  const targetServiceId = String(serviceId || "").trim();
  if (targetServiceId && shouldDeferPastWorshipServiceLoad(targetServiceId)) return false;
  if (targetServiceId && state.loadedWorshipPresenterServiceIds.has(targetServiceId)) return;
  if (!targetServiceId && state.worshipPresenterSlidesLoaded) return;
  const loadKey = targetServiceId || "__all__";
  if (worshipPresenterSlideLoadPromises.has(loadKey)) {
    return worshipPresenterSlideLoadPromises.get(loadKey);
  }
  const loadPromise = (async () => {
    const presenterRows = await fetchSupabasePaged("mindex_worship_presenter_slides", "*", (query) =>
      (targetServiceId ? query.eq("service_id", targetServiceId) : query)
        .order("service_date", { ascending: true })
        .order("section_order", { ascending: true })
        .order("element_order", { ascending: true })
        .order("slide_order", { ascending: true }));
    const hiddenElementIds = new Set(
      state.worshipElements
        .filter((element) => {
          const config = element?.config && typeof element.config === "object" ? element.config : {};
          return Boolean(config.hiddenInPresentation || config.hidden_in_presentation || config.hidden);
        })
        .map((element) => element.id)
        .filter(Boolean),
    );
    const groupedSlides = groupWorshipPresenterSlides(presenterRows, hiddenElementIds);
    if (targetServiceId) {
      state.worshipPresenterSlides = {
        ...state.worshipPresenterSlides,
        [targetServiceId]: groupedSlides[targetServiceId] || [],
      };
      state.loadedWorshipPresenterServiceIds.add(targetServiceId);
      refreshPresenterForService(targetServiceId, {
        publish: false,
        renderControls: options.renderControls !== false,
      });
    } else {
      state.worshipPresenterSlides = groupedSlides;
      state.worshipPresenterSlidesLoaded = true;
    }
  })();
  worshipPresenterSlideLoadPromises.set(loadKey, loadPromise);
  try {
    return await loadPromise;
  } finally {
    if (worshipPresenterSlideLoadPromises.get(loadKey) === loadPromise) {
      worshipPresenterSlideLoadPromises.delete(loadKey);
    }
  }
}

function defaultWorshipServiceTypes() {
  return Object.values(SERVICE_CATEGORIES)
    .flat()
    .map((id, index) => ({
      id,
      display_name: SERVICE_TYPE_DISPLAY_NAMES[id] || id,
      short_name: SERVICE_TYPE_DISPLAY_NAMES[id] || id,
      sort_order: index + 1,
      group_key: serviceTypeGroupKey(id),
    }));
}

function normalizeWorshipServiceType(type = {}) {
  const config = type.config && typeof type.config === "object" ? type.config : {};
  return {
    id: worshipAppServiceTypeId(type.id),
    name: type.display_name || type.id || "",
    short_name: type.short_name || "",
    sort_order: Number(type.sort_order) || 0,
    fixed_items: normalizeServiceDefaultItems(config.fixedItems || config.fixed_items || []),
    _worship: true,
    _worshipId: type.id || "",
    _worshipGroupKey: type.group_key || "",
    _worshipOutputContext: type.default_output_context || "auto",
    _worshipChromakey: Boolean(type.chromakey_enabled),
    _worshipConfig: config,
  };
}

function normalizeWorshipService(service = {}) {
  const typeId = worshipAppServiceTypeId(service.service_type_id);
  const worshipLeader = cleanServiceAssignee(service.worship_leader);
  const praiseLeader = cleanServiceAssignee(service.praise_leader);
  const serviceDate = service.service_date;
  const sourceRef = normalizeServiceSourceRef(service.source_ref);
  return {
    id: service.id,
    type_id: typeId,
    date: serviceDate,
    date_end: service.service_date_end || null,
    title: normalizeWorshipServiceTitle(service.title || "", { type_id: typeId, date: serviceDate }),
    alias: String(service.service_alias || "").trim(),
    leader: praiseLeader,
    worshipLeader,
    praiseLeader,
    raw_text: service.notes || "",
    created_at: service.created_at,
    _worship: true,
    _worshipServiceTypeId: service.service_type_id,
    _worshipStatus: service.status || "draft",
    _worshipSourceRef: sourceRef,
    // Rows from the light list view carry flags instead of the document/history payload.
    // Until the full source_ref is fetched, saving this service could drop them.
    _worshipSourceRefPartial: Boolean(service.has_service_document || service.has_service_document_history),
  };
}

function normalizeWorshipServiceTitle(title = "", service = {}) {
  const text = String(title || "").trim();
  const typeId = service?.type_id || service?.service_type_id;
  const typeName = serviceTypeDisplayName(typeId);
  if (serviceTypeUsesCanonicalTitle(typeId)) return typeName;
  if (!text) return "";
  return normalizeServiceDisplayName(text);
}

function serviceTypeUsesCanonicalTitle(typeId) {
  const appTypeId = worshipAppServiceTypeId(typeId);
  return SERVICE_CATEGORIES.public.includes(appTypeId);
}

function deriveWorshipSlotKey(context = {}) {
  const sectionKey = String(context.sectionKey || context.section?.section_key || context.item?._worshipSectionKey || "").trim();
  const elementType = normalizeWorshipElementType(context.elementType || context.element?.element_type || context.parsed?.elementType || context.parsed?.componentType);
  const inputMode = normalizeServiceInputMode(context.inputMode || context.element?.input_mode || context.contentState?.inputMode || context.config?.inputMode || context.config?.input_mode || context.parsed?.inputMode);
  const label = compactSearchValue(
    context.label
    || context.sourceRef?.label
    || context.item?.label
    || context.element?.title
    || context.section?.title
    || context.item?.raw_title
    || "",
  );
  const hasAsset = hasServiceAsset(normalizeServiceAsset(context.asset || context.parsed?.asset || context.config?.asset || context.element?.asset));
  const elementOrder = Number(context.element?.sort_order || context.item?._worshipElementOrder || context.item?.elementOrder || 0) || 0;

  // Reference material is an ordinary media element, never a song/template slot.
  if (label === "참고화면" && inputMode === "asset") {
    return ({ sermon: "sermon.media", announcements: "announcements.media", offering: "offering.media" })[sectionKey] || "";
  }

  // A duplicated praise item can retain its source slot while the operator
  // renames it. Numbered main-praise labels are canonical and must win.
  if (sectionKey === "praise") {
    const numberedPraise = label.match(/^찬양(\d+)$/);
    if (numberedPraise) return `praise.song.${Number(numberedPraise[1])}`;
  }

  const explicit = explicitWorshipSlotKey(context.element, context.sourceRef, context.config, context.item, context.parsed);
  if (explicit) return explicit;

  if (sectionKey === "ready") return "ready.waiting";
  if (sectionKey === "silent_prayer") return "prayer.silent";
  if (sectionKey === "creed") return "faith.creed";
  if (sectionKey === "confession") return label === "사죄의선언" ? "confession.assurance" : "confession.prayer";
  if (sectionKey === "scripture_reading") {
    if (elementType === "scripture_body" || ["성경본문", "성경 본문", "본문"].includes(label)) return "word.body";
    return "word.reading";
  }
  if (sectionKey === "praise") {
    if (label === "환영") return "praise.welcome";
    if (["입례찬양", "입례 찬양"].includes(label)) return "praise.entrance";
    if (label === "찬양" && elementOrder > 0) return `praise.song.${elementOrder}`;
    return "praise.main";
  }
  if (["entrance_praise", "pre_scripture_praise"].includes(sectionKey)) return "praise.entrance";
  if (sectionKey === "prayer") return "prayer.representative";
  if (sectionKey === "hymn_praise") return "hymn.main";
  if (sectionKey === "special_song") return "special.song";
  if (sectionKey === "sermon") {
    if (label === "실시간성구송출") return "sermon.live_scripture";
    if (/^인용구절(\d*)$/.test(label)) return "sermon.citation";
    if (["설교본문", "본문", "성경본문", "말씀본문", "말씀"].includes(label) || inputMode === "scripture" || elementType === "scripture_body") return "sermon.scripture";
    if (["설교", "설교제목"].includes(label)) return "sermon.title";
    if (hasAsset || ["image", "video", "ppt", "pdf"].includes(elementType) || inputMode === "asset") return "sermon.media";
  }
  if (sectionKey === "response_song") return elementType === "praise" || inputMode.includes("db") || servicePraiseUsesDirectLyrics(inputMode) ? "response.song" : "response.prayer";
  if (sectionKey === "response_prayer") return "response.prayer";
  if (sectionKey === "corporate_prayer") {
    const match = label.match(/^공동기도(\d+)$/);
    if (match) return `prayer.corporate.${Number(match[1])}`;
    if (elementType === "praise" || inputMode.includes("db") || servicePraiseUsesDirectLyrics(inputMode)) return "prayer.corporate.song";
    return "prayer.corporate.1";
  }
  if (sectionKey === "prayer_meeting_praise") {
    const match = label.match(/^기도찬양(\d+)$/);
    if (match) return `prayer.meeting.song.${Number(match[1])}`;
    if (label === "자율기도") return "prayer.meeting.free";
    if (elementType === "praise" || inputMode.includes("db") || servicePraiseUsesDirectLyrics(inputMode)) return "prayer.meeting.song.1";
    return "prayer.meeting.free";
  }
  if (sectionKey === "offering") {
    if (hasAsset || ["image", "video", "ppt", "pdf"].includes(elementType) || inputMode === "asset") return "offering.media";
    if (["봉헌기도", "기도"].includes(label) || elementType === "title_person") return "offering.prayer";
    if (["특송", "봉헌특송"].includes(label)) return "offering.special";
    if (["봉헌찬송", "찬송"].includes(label) || elementType === "praise") return "offering.praise";
  }
  if (sectionKey === "new_family") return "new_family.welcome";
  if (sectionKey === "announcements") {
    if (label === "새가족환영") return "announcements.new_family";
    if (label === "참고화면" || hasAsset || ["image", "video", "ppt", "pdf"].includes(elementType) || inputMode === "asset") return "announcements.media";
    if (["청소년부광고", "청년부광고"].includes(label) || (label === "광고" && ["body", "plain_text"].includes(elementType))) return "announcements.department";
    return "announcements.main";
  }
  if (sectionKey === "sending") {
    if (label === "송영" || elementType === "praise") return "sending.doxology";
    if (label === "축도") return "sending.benediction";
    if (label === "주기도문") return "sending.lords_prayer";
  }
  if (sectionKey === "lords_prayer") return "sending.lords_prayer";
  if (sectionKey === "closing_visual") {
    if (label === "폐회찬송" || elementType === "praise") return "closing.hymn";
    return "closing.visual";
  }
  if (sectionKey === "community_confession") return "community.confession";
  if (sectionKey === "fellowship") return "fellowship.person";
  return "";
}

function serviceItemSlotKey(item = {}, memo = null) {
  const parsed = memo || parseServiceItemMemo(item?.memo);
  return deriveWorshipSlotKey({
    item,
    parsed,
    sectionKey: item?._worshipSectionKey || item?.sectionKey || item?.section_key || "",
    label: item?.label || "",
    elementType: serviceMemoElementType(parsed) || item?.element_type || item?.elementType || item?.component_type || item?.componentType || "",
    inputMode: serviceMemoInputMode(parsed, item),
    asset: parsed?.asset,
  });
}

function groupWorshipElements(sections = [], elements = []) {
  const sectionById = Object.fromEntries(sections.map((section) => [section.id, section]));
  const grouped = elements.reduce((grouped, element) => {
    const section = sectionById[element.section_id];
    const serviceId = section?.service_id;
    if (!serviceId) return grouped;
    const sourceRef = element.source_ref && typeof element.source_ref === "object" ? element.source_ref : {};
    const config = element.config && typeof element.config === "object" ? element.config : {};
    const sectionKey = String(section.section_key || "").trim();
    const elementLabel = sourceRef.label || section.title || element.title || "";
    if (!grouped[serviceId]) grouped[serviceId] = [];
    const configuredElementType = serviceMemoElementType({
      elementType: config.elementType || config.element_type || config.componentType || config.component_type,
      componentType: config.componentType || config.component_type,
    }) || normalizeWorshipElementType(element.element_type);
    if (configuredElementType === "live_scripture" && compactSearchValue(elementLabel) === "실시간성구송출") return grouped;
    const departmentAnnouncementBody = sectionKey === "announcements"
      && (["청소년부광고", "청년부광고"].includes(compactSearchValue(elementLabel))
        || (compactSearchValue(elementLabel) === "광고" && ["body", "plain_text"].includes(configuredElementType)));
    const inputMode = canonicalWorshipElementInputMode(element);
    const asset = normalizeServiceAsset(config.asset || config.media || element.asset || sourceRef.asset);
    const mediaAnnouncement = sectionKey === "announcements"
      && !departmentAnnouncementBody
      && (hasServiceAsset(asset) || ["image", "video", "ppt", "pdf"].includes(configuredElementType) || inputMode === "asset");
    const elementType = sectionKey === "announcements" && !departmentAnnouncementBody && !mediaAnnouncement
      ? "title"
      : configuredElementType;
    const audioAsset = normalizeServiceAudioAsset(config.audioAsset || config.audio_asset || sourceRef.audioAsset || sourceRef.audio_asset);
    const playback = normalizeServicePlaybackConfig(config.playback, elementType);
    const presenterRole = normalizeServicePresenterRole(
      config.presenterRole || config.presenter_role || config.role || sourceRef.presenterRole || sourceRef.presenter_role || sourceRef.role,
    );
    const formPresetDisabled = Boolean(
      config.formPresetDisabled
      || config.form_preset_disabled
      || config.disableFormPreset
      || config.disable_form_preset,
    );
    const formHint = formPresetDisabled ? "" : serviceFormHintFromConfig(config);
    const storedFormPreset = normalizeServiceFormPreset(config.formPreset || config.form_preset, formHint);
    const formPreset = formPresetDisabled && !storedFormPreset?.titleSequence ? null : storedFormPreset;
    const formPresetRules = formPresetDisabled ? [] : normalizeServiceFormPresetRules(config.formPresetRules || config.form_preset_rules);
    const scriptureReference = serviceElementScriptureReference(element, section, sourceRef, config);
    const scriptureReferences = serviceElementScriptureReferences(element, section, sourceRef, config);
    const textHighlights = normalizeServiceTextHighlights(
      config.textHighlights || config.text_highlights || config.highlights
      || sourceRef.textHighlights || sourceRef.text_highlights || sourceRef.highlights,
    );
    const introSlide = normalizeServiceIntroSlide(
      config.introSlide || config.intro_slide || config.titleSlide || config.title_slide
      || sourceRef.introSlide || sourceRef.intro_slide || sourceRef.titleSlide || sourceRef.title_slide,
    );
    const connectedPraise = normalizeServiceConnectedPraise(
      config.connectedPraise || config.connected_praise || sourceRef.connectedPraise || sourceRef.connected_praise,
    );
    const manualSlides = serviceElementManualSlides(element, config, { section, sourceRef });
    const slotKey = deriveWorshipSlotKey({
      element,
      section,
      sectionKey,
      sourceRef,
      config,
      label: elementLabel,
      elementType,
      inputMode,
      asset,
      contentState: element.content_state,
    });
    grouped[serviceId].push(normalizeServiceItem({
      id: element.id,
      service_id: serviceId,
      sort_order: (Number(section.sort_order) || 0) * 1000 + (Number(element.sort_order) || 0),
      label: sourceRef.label || section.title || "",
      assignee: element.person || "",
      raw_title: worshipElementDisplayTitle(element, section, sourceRef, config),
      ...(state.singleSongCatalog
        ? state.singleSongCatalog.singleItem({ praise_record_id: element.praise_record_id || null, song_id: element.song_id || null, song_version_id: element.song_version_id || null })
        : { song_id: element.song_id || null, song_version_id: element.song_version_id || null }),
      memo: serializeServiceItemMemo({
        note: config.note,
        elementType,
        inputMode,
        outputMode: ["score_db", "lyrics_db"].includes(normalizeServiceInputMode(element.input_mode)) ? servicePraiseInputModeOutputMode(inputMode) : config.outputMode || config.output_mode || config.renderMode || config.render_mode,
        formHint,
        formPreset,
        formPresetDisabled,
        formPresetRules,
        templateKey: config.templateKey || config.template_key,
        templateVariant: config.templateVariant || config.template_variant,
        corporatePrayers: config.corporatePrayers,
        scriptureReference,
        scriptureReferences,
        scriptureTranslationId: config.scriptureTranslationId || config.scripture_translation_id,
        scriptureReferencePayloads: config.scriptureReferencePayloads || config.scripture_reference_payloads,
        manualScripture: config.manualScripture || config.manual_scripture,
        textHighlights,
        announcementRegions: config.announcementRegions,
        introSlide,
        slides: manualSlides,
        asset,
        audioAsset,
        audioTiming: normalizeServiceAudioTiming(config.audioTiming),
        presentation: normalizeServicePresentation(config.presentation),
        playback,
        presenterRole,
        connectedPraise,
        mediaPlacement: config.mediaPlacement,
        benedictionReplacement: config.benedictionReplacement,
        offeringVariants: config.offeringVariants,
        hiddenInPresentation: Boolean(config.hiddenInPresentation || config.hidden_in_presentation),
        templateSuppressed: Boolean(config.templateSuppressed || config.template_suppressed),
        reviewStatus: element.review_status,
        reviewFlags: sourceRef.review_flags || [],
      }),
      _worship: true,
      _worshipSectionId: section.id,
      _worshipSectionKey: section.section_key || "",
      _worshipSectionTitle: section.title || "",
      _worshipSectionOrder: Number(section.sort_order) || 0,
      _worshipElementOrder: Number(element.sort_order) || 0,
      _worshipSlotKey: slotKey,
      _worshipSectionTemplateModified: Boolean(section.template_modified),
      _worshipElementTemplateModified: Boolean(element.template_modified),
    }));
    return grouped;
  }, {});
  // RPC arrays have no ordering guarantee. Every editor/hydration consumer must
  // start from persisted section/element order before compacting editor ordinals.
  Object.values(grouped).forEach(items => items.sort((a, b) => a.sort_order - b.sort_order));
  return grouped;
}

function serviceElementManualSlides(element = {}, config = {}, context = {}) {
  if (isScriptureBodyWorshipElement(element, context.section, context.sourceRef)) return [];
  if (isConfessionPrayerElement(element, context.section, context.sourceRef)) return [];
  const configured = config.slides || config.slideOverrides || config.slide_overrides;
  if (Array.isArray(configured)) return configured.map((slide) => String(slide || "").trim()).filter(Boolean);
  const body = String(element.body || "").trim();
  if (!body) return [];
  if (!["praise", "plain_text", "body"].includes(normalizeWorshipElementType(element.element_type))) return [];
  const lengths = config.bodySlideLengths;
  if (Array.isArray(lengths) && lengths.length
    && lengths.every(length => Number.isSafeInteger(length) && length > 0 && length <= body.length)
    && lengths.reduce((sum, length) => sum + length, 0) + 2 * (lengths.length - 1) === body.length) {
    let offset = 0;
    const screens = lengths.map(length => {
      const screen = body.slice(offset, offset + length);
      offset += length + 2;
      return screen;
    });
    if (screens.join("\n\n") === body) return screens;
  }
  return body
    .split(/\n\s*\n/g)
    .map((block) => block.trim())
    .filter(Boolean);
}

function serviceFormHintFromConfig(config = {}) {
  if (
    config.formPresetDisabled
    || config.form_preset_disabled
    || config.disableFormPreset
    || config.disable_form_preset
  ) return "";
  const preset = normalizeServiceFormPreset(config.formPreset || config.form_preset, config.formHint || config.form_hint);
  return normalizeServiceFormHint(config.formHint || config.form_hint || preset?.hint);
}

function worshipElementDisplayTitle(element = {}, section = {}, sourceRef = {}, config = {}) {
  if (isScriptureBodyWorshipElement(element, section, sourceRef)) {
    const references = serviceElementScriptureReferences(element, section, sourceRef, config);
    if (references.length) return formatServiceScriptureReferenceList(references);
    return serviceElementScriptureReference(element, section, sourceRef, config);
  }
  const title = String(element.title || "").trim();
  // An element label is structural metadata, not user-entered content.  Keep
  // empty template slots empty unless the template explicitly supplied a title.
  return title;
}

function isScriptureBodyWorshipElement(element = {}, section = {}, sourceRef = {}) {
  const elementType = normalizeWorshipElementType(element.element_type);
  if (elementType === "scripture_body") return true;
  if (elementType === "scripture_reading") return false;
  const sectionKey = String(section?.section_key || section?._worshipSectionKey || "").trim();
  const label = String(sourceRef?.label || section?.title || element?.title || "").replace(/\s+/g, "");
  return label === "본문"
    || label === "성경본문"
    || label === "설교본문"
    || (sectionKey === "scripture_reading" && label === "성경봉독");
}

function serviceElementScriptureReference(element = {}, section = {}, sourceRef = {}, config = {}) {
  const candidates = [
    element.scripture_reference,
    config.scriptureReference,
    config.scripture_reference,
    sourceRef.scriptureReference,
    sourceRef.scripture_reference,
    firstBibleReferenceLine(element.title),
    firstBibleReferenceLine(element.body),
    section.title,
  ];
  for (const candidate of candidates) {
    const referenceText = firstBibleReferenceLine(candidate);
    if (!referenceText) continue;
    const parsed = parseBibleReference(referenceText);
    if (parsed) return formatServiceBibleReference(parsed, referenceText);
  }
  return "";
}

function serviceElementScriptureReferences(element = {}, section = {}, sourceRef = {}, config = {}) {
  const configured = config.scriptureReferences || config.scripture_references
    || sourceRef.scriptureReferences || sourceRef.scripture_references;
  const references = preferCompleteServiceScriptureReferenceList(
    normalizeServiceScriptureReferenceList(configured),
    normalizeServiceScriptureReferenceList(element.title),
  );
  if (references.length) return references;
  const reference = serviceElementScriptureReference(element, section, sourceRef, config);
  return reference ? [reference] : [];
}

function firstBibleReferenceLine(value) {
  return String(value || "")
    .split(/\r?\n/)
    .map((line) => line.trim())
    .find(Boolean) || "";
}

function groupWorshipPresenterSlides(rows = [], hiddenElementIds = new Set()) {
  return rows.reduce((grouped, row, index) => {
    const serviceId = row.service_id;
    if (!serviceId) return grouped;
    if (!grouped[serviceId]) grouped[serviceId] = [];
    grouped[serviceId].push(normalizeWorshipPresenterSlide(row, index, {
      hiddenInPresentation: hiddenElementIds.has(row.element_id),
    }));
    return grouped;
  }, {});
}

function normalizeWorshipPresenterSlide(row = {}, index = 0, options = {}) {
  const elementType = worshipPresenterElementType(row.element_type, row.slide_type);
  const layout = worshipPresenterLayout(row.slide_type, elementType);
  const representativePrayer = elementType === PRESENTER_ELEMENT_TYPES.TITLE_ASSIGNEE
    && String(row.section_key || "").trim() === "prayer";
  const scriptureReading = isPresenterScriptureReadingSource({
    elementType: row.element_type,
    sectionKey: row.section_key,
    label: row.section_title,
  });
  const title = representativePrayer
    ? "대표기도"
    : scriptureReading
      ? (row.slide_title || row.section_title || "성경봉독")
      : (row.slide_title || row.element_title || row.section_title || "");
  const assignee = scriptureReading
    ? cleanPresenterAssignee(row.element_title || row.slide_body || "")
    : cleanPresenterAssignee(row.element_person || "");
  const text = row.slide_body || row.slide_title || row.element_title || "";
  const marker = row.slide_marker || inferWorshipSlideMarker(row, elementType);
  const hasTitleContent = presenterElementTypeSupportsTitleContent(elementType)
    && String(title || "").trim()
    && String(row.slide_body || "").trim();
  return {
    id: row.slide_id || `${row.element_id || "worship"}:${index}`,
    sectionId: row.section_id || row.element_id || `section:${index}`,
    elementId: row.element_id || row.section_id || `element:${index}`,
    sectionIndex: Number(row.section_order) || index + 1,
    sectionKey: row.section_key || "",
    sectionLabel: row.section_title || "",
    sectionRole: row.section_key === "praise" ? "main-praise" : "",
    sectionTitle: row.section_title || "",
    elementLabel: row.element_label || row.section_title || "",
    elementTitle: row.element_title || title,
    sectionAssignee: assignee,
    sectionName: presenterNameParts(row.section_title, row.element_title, assignee).join(" / "),
    elementType,
    layout,
    type: hasTitleContent ? "title-content" : worshipPresenterSlideType(row.slide_type, elementType, layout),
    label: row.section_title || "",
    title,
    assignee,
    marker,
    formKey: `${row.element_id || "element"}:${marker || row.slide_order || index}`,
    bodyText: row.slide_body || "",
    text: elementType === PRESENTER_ELEMENT_TYPES.TITLE_ASSIGNEE ? cleanList([title, assignee]).join("\n") : text,
    hiddenInPresentation: Boolean(
      options.hiddenInPresentation
      || row.hiddenInPresentation
      || row.hidden_in_presentation
      || row.hidden,
    ),
    sort: (Number(row.section_order) || 0) * 10000 + (Number(row.element_order) || 0) * 100 + (Number(row.slide_order) || 0),
    media: row.media || {},
    asset: row.media || {},
  };
}

function inferWorshipSlideMarker(row = {}, elementType = "") {
  if (elementType !== PRESENTER_ELEMENT_TYPES.PRAISE) return "";
  const text = String(row.slide_body || "").trim();
  const bracket = text.match(/^\[([^\]]{1,24})\]/);
  if (bracket) return normalizeImportedPraiseMarker(bracket[1].trim());
  const named = text.match(/^(verse|chorus|pre-chorus|prechorus|pc|bridge|coda|ending|intro|outro|후렴|브릿지)\s*(\d+)?/i);
  if (named) return normalizeImportedPraiseMarker([named[1], named[2]].filter(Boolean).join(" "));
  const numbered = text.match(/^(\d{1,2})[\s.]/);
  if (numbered) return `Verse ${numbered[1]}`;
  return "";
}

function normalizeImportedPraiseMarker(value = "") {
  const raw = String(value || "").trim();
  if (/^(ending|엔딩)(?:\s+\d+)?$/i.test(raw)) return "Coda";
  return songFormPresetDisplayLabel(raw) || raw;
}

function worshipPresenterElementType(elementType, slideType) {
  if (elementType === "praise" || /^praise_/.test(String(slideType || ""))) return PRESENTER_ELEMENT_TYPES.PRAISE;
  if (slideType === "scripture_body" || elementType === "scripture_body") return PRESENTER_ELEMENT_TYPES.SCRIPTURE_TEXT;
  if (slideType === "scripture_reading" || elementType === "scripture_reading") return PRESENTER_ELEMENT_TYPES.TITLE_ASSIGNEE;
  if (elementType === "title") return PRESENTER_ELEMENT_TYPES.TITLE_ASSIGNEE;
  if (elementType === "body") return PRESENTER_ELEMENT_TYPES.BODY_TEXT;
  if (elementType === "title_person") return PRESENTER_ELEMENT_TYPES.TITLE_ASSIGNEE;
  if (elementType === "image") return PRESENTER_ELEMENT_TYPES.IMAGE;
  if (elementType === "video") return PRESENTER_ELEMENT_TYPES.VIDEO;
  if (["file", "ppt", "pptx", "pdf", "key", "score"].includes(elementType)) return PRESENTER_ELEMENT_TYPES.FILE;
  if (elementType === "blank") return PRESENTER_ELEMENT_TYPES.BLANK;
  return PRESENTER_ELEMENT_TYPES.PLAIN_TEXT;
}

function worshipPresenterLayout(slideType, elementType) {
  if (elementType === PRESENTER_ELEMENT_TYPES.PRAISE) return PRESENTER_SLIDE_LAYOUTS.LOWER_BAR_TEXT;
  if (elementType === PRESENTER_ELEMENT_TYPES.TITLE_ASSIGNEE) return PRESENTER_SLIDE_LAYOUTS.LOWER_BAR_TEXT;
  if (elementType === PRESENTER_ELEMENT_TYPES.IMAGE || elementType === PRESENTER_ELEMENT_TYPES.VIDEO) return PRESENTER_SLIDE_LAYOUTS.MEDIA;
  if (elementType === PRESENTER_ELEMENT_TYPES.FILE) return PRESENTER_SLIDE_LAYOUTS.FILE;
  if (slideType === "blank" || elementType === PRESENTER_ELEMENT_TYPES.BLANK) return PRESENTER_SLIDE_LAYOUTS.BLANK;
  return PRESENTER_SLIDE_LAYOUTS.CENTER_TEXT;
}

function worshipPresenterSlideType(slideType, elementType, layout) {
  if (elementType === PRESENTER_ELEMENT_TYPES.PRAISE) return slideType === "praise_title" ? "song-title" : "lyrics";
  if (elementType === PRESENTER_ELEMENT_TYPES.TITLE_ASSIGNEE) return "title-assignee";
  if (layout === PRESENTER_SLIDE_LAYOUTS.LOWER_BAR_TEXT && elementType === PRESENTER_ELEMENT_TYPES.SCRIPTURE_TEXT) return "scripture";
  if (layout === PRESENTER_SLIDE_LAYOUTS.MEDIA) return elementType === PRESENTER_ELEMENT_TYPES.IMAGE ? "image" : "video";
  if (layout === PRESENTER_SLIDE_LAYOUTS.FILE) return "file";
  if (layout === PRESENTER_SLIDE_LAYOUTS.BLANK) return "blank";
  if (elementType === PRESENTER_ELEMENT_TYPES.TITLE) return "title";
  return "component";
}

async function loadReferenceLinks({ silent = false } = {}) {
  if (referenceLinksLoadPromise) return referenceLinksLoadPromise;
  referenceLinksLoadPromise = loadReferenceLinksOnce({ silent });
  try {
    return await referenceLinksLoadPromise;
  } finally {
    referenceLinksLoadPromise = null;
  }
}

async function loadReferenceLinksOnce({ silent = false } = {}) {
  if (!requireClient({ silent })) {
    state.referenceLinks = [];
    state.referenceError = "연결 없음";
    state.referenceLinksLoaded = true;
    render();
    return;
  }

  try {
    state.referenceGroupSupported = await detectTableColumnSupport("mindex_reference_links", "group_name");
    const response = await fetchAllRows(() =>
      state.client
        .from("mindex_reference_links")
        .select("*")
        .order("sort_order", { ascending: true })
        .order("title", { ascending: true })
    );

    if (response.error) throw response.error;
    state.referenceLinks = (response.data || []).map(normalizeReferenceLink).sort(sortReferenceLinks);
    state.referenceLinksLoaded = true;
    state.referenceError = "";
    state.dirty.references = false;
    captureCleanFingerprint("references");
    render();
  } catch (error) {
    state.referenceLinks = [];
    state.referenceLinksLoaded = true;
    state.referenceError = isUnavailableRelationError(error) ? "setup" : (error.message || "error");
    if (!silent && state.module === "references") showToast(state.referenceError, "error");
    render();
  }
}

function normalizeReferenceLink(row = {}) {
  return {
    id: row.id || createLocalId(),
    title: row.title || "",
    url: row.url || "",
    group_name: row.group_name || row.group || row.category || "",
    sort_order: Number(row.sort_order) || 0,
    is_active: row.is_active !== false,
  };
}

function sortReferenceLinks(a, b) {
  return (Number(a.sort_order) || 0) - (Number(b.sort_order) || 0)
    || String(a.group_name || "").localeCompare(String(b.group_name || ""), "ko")
    || TITLE_COLLATOR.compare(String(a.title || ""), String(b.title || ""));
}

async function detectSongVersionPraiseTypesSupport() {
  return detectTableColumnSupport("mindex_song_versions", "praise_types");
}

async function detectTableColumnSupport(table, column) {
  if (!state.client || !/^[a-z_][a-z0-9_]*$/i.test(table) || !/^[a-z_][a-z0-9_]*$/i.test(column)) return false;
  const cacheKey = `${table}.${column}`;
  if (TABLE_COLUMN_SUPPORT_CACHE.has(cacheKey)) return TABLE_COLUMN_SUPPORT_CACHE.get(cacheKey);
  try {
    const { error } = await state.client
      .from(table)
      .select(column)
      .limit(1);
    const supported = !error;
    TABLE_COLUMN_SUPPORT_CACHE.set(cacheKey, supported);
    return supported;
  } catch {
    TABLE_COLUMN_SUPPORT_CACHE.set(cacheKey, false);
    return false;
  }
}

async function loadCalendarData({ silent = false, refresh = false } = {}) {
  if (state.calendarLoaded && !refresh) return;
  if (calendarLoadPromise) return calendarLoadPromise;
  calendarLoadPromise = loadCalendarDataOnce({ silent });
  try {
    return await calendarLoadPromise;
  } finally {
    calendarLoadPromise = null;
  }
}

async function loadCalendarDataOnce({ silent = false } = {}) {
  if (!state.client) return;
  state.calendarLoading = true;
  state.calendarError = "";
  try {
    const { data, error } = await state.client
      .from("mindex_sunday_calendar")
      .select("*")
      .gte("date", CALENDAR_MIN_DATE)
      .order("date");
    if (error) throw error;
    state.calendarData = data || [];
    state.calendarLoaded = true;
    state.calendarError = "";
  } catch (e) {
    state.calendarLoaded = false;
    state.calendarError = e.message || "교회력을 불러오지 못했습니다.";
    if (!silent) showToast(e.message || "교회력을 불러오지 못했습니다.", "error");
  } finally {
    state.calendarLoading = false;
    if (state.module === "calendar") {
      renderSongList();
      renderCalendarView();
    }
  }
}

// Coalesce bursts, but let a safe-state event bring a deferred read forward.
// A failed read retains its backoff even if notifications keep arriving.
function createLiveRefreshScheduler(pending, flush) {
  let timer = null, due = 0, backoff = 0;
  const schedule = (delay = 80) => {
    if (!pending.size) return;
    const now = Date.now();
    if (delay >= 15000) backoff = now + delay;
    const next = Math.max(now + delay, backoff);
    if (timer && due <= next && due >= backoff) return;
    clearTimeout(timer); due = next;
    timer = setTimeout(() => { timer = null; void flush(); }, Math.max(0, next - now));
  };
  for (const event of ['focusout', 'pause', 'ended', 'close']) document.addEventListener(event, () => schedule(), true);
  return schedule;
}

// Local and remote notifications contain identifiers only; committed values come from DB.
let departmentTabSync = null;
function initializeDepartmentTabSync() {
  if (departmentTabSync || isPresenterOutputRoute()) return;
  const sync = departmentTabSync = { channel: null, pending: new Map(), busy: false, seen: new Set(), editRevision: 0 };
  sync.schedule = createLiveRefreshScheduler(sync.pending, refreshDepartmentTabs);
  document.addEventListener("input", () => { sync.editRevision += 1; }, true);
  document.addEventListener("change", () => { sync.editRevision += 1; }, true);
  const receive = message => {
    if (!message || message.project !== state.config.url || typeof message.id !== "string"
      || typeof message.calendarId !== "string" || !Array.isArray(message.serviceIds) || message.serviceIds.length > 100
      || !message.serviceIds.every(id => typeof id === "string") || sync.seen.has(message.id)) return;
    sync.seen.add(message.id);
    if (sync.seen.size > 256) sync.seen.delete(sync.seen.values().next().value);
    const previous = sync.pending.get(message.calendarId);
    sync.pending.set(message.calendarId, { ...message, calendarOnly: message.calendarOnly === true && (!previous || previous.calendarOnly === true), serviceIds: [...new Set([...(previous?.serviceIds || []), ...message.serviceIds])] });
    scheduleDepartmentTabRefresh();
  };
  sync.receive = receive;
  connectDepartmentRealtime();
  setInterval(() => { connectDepartmentRealtime(); void reconcileDepartmentRealtime(); }, 60000);
  try { sync.channel = new BroadcastChannel("mindex.department.assignees.v1"); sync.channel.onmessage = event => receive(event.data); } catch {}
  window.addEventListener("storage", event => {
    if (event.key !== "mindex.department.assignees.v1" || !event.newValue) return;
    try { receive(JSON.parse(event.newValue)); } catch {}
  });
  const wake = () => {
    connectDepartmentRealtime();
    void reconcileDepartmentRealtime();

    scheduleDepartmentTabRefresh();
  };
  window.addEventListener("focus", wake);
  document.addEventListener("visibilitychange", wake);
  window.addEventListener("online", wake);
}
function publishDepartmentTabChange(calendar, serviceIds = [], { calendarOnly = false } = {}) {
  if (!calendar?.id || !state.config.url) return;
  initializeDepartmentTabSync();
  const message = { id: createUuid(), project: state.config.url, calendarId: calendar.id, serviceIds, ...(calendarOnly ? { calendarOnly: true } : {}) };
  if (departmentTabSync) departmentTabSync.editRevision += 1;
  departmentTabSync?.seen.add(message.id);
  connectDepartmentRealtime();
  try { void departmentTabSync?.remote?.send({ type: "broadcast", event: "committed", payload: message }).catch(() => {}); } catch {}
  try { departmentTabSync?.channel?.postMessage(message); } catch {}

}
function departmentRefreshBlocked() {
  const playingMedia = [...document.querySelectorAll("audio,video")].some(media => !media.paused && !media.ended);
  const dialogOpen = [...document.querySelectorAll('dialog[open],[aria-modal="true"]')].some(node => node.getClientRects().length);
  return dialogOpen || serviceMusicHasActivePlayback() || state.serviceMusic.pending || playingMedia || !canUseClientData() || document.hidden || state.calendarLoading || state.calendarCellSaves.size || departmentCalendarWrites.size
    || state.saving || state.loading || isPresenterOutputWindowOpen() || state.presenter.outputPendingAt
    || document.activeElement?.matches('input,textarea,select,[contenteditable="true"]')
    || (["service", "presenter"].includes(state.module) && sundayEditSyncHasLocalDraft(state.selectedServiceId));
}
function connectDepartmentRealtime() {
  const sync = departmentTabSync;
  if (!sync) return;
  const client = canUseClientData() ? state.client : null;
  if (sync.remoteClient === client) return;
  if (sync.remote) { try { void sync.remoteClient.removeChannel(sync.remote).catch(() => {}); } catch {} }
  sync.remote = null; sync.remoteClient = client;
  if (!client?.channel) return;
  try {
    const project = state.config.url;
    const channel = client.channel("mindex.department.assignees.v1", { config: { broadcast: { ack: true, self: false } } });
    sync.remote = channel;
    channel.on("broadcast", { event: "committed" }, ({ payload }) => {
      if (sync.remote === channel && state.client === client && state.config.url === project) sync.receive(payload);
    }).on("broadcast", { event: "worship-committed" }, ({ payload }) => {
      if (sync.remote === channel && state.client === client && state.config.url === project) window.MINDEX_WORSHIP_LIVE?.receive(payload);
    }).on("broadcast", { event: "content-committed" }, ({ payload }) => {
      if (sync.remote === channel && state.client === client && state.config.url === project) window.MINDEX_CONTENT_LIVE?.receive(payload);
    }).subscribe(status => {
      if (sync.remote === channel && status === "SUBSCRIBED") {
        void reconcileDepartmentRealtime();
        void window.MINDEX_WORSHIP_LIVE?.reconcile();
        void window.MINDEX_CONTENT_LIVE?.reconcile();
      }
    });
  } catch { sync.remoteClient = null; }
}
async function reconcileDepartmentRealtime() {
  const sync = departmentTabSync;
  if (!sync || sync.reconciling || departmentRefreshBlocked() || !["calendar", "service", "presenter"].includes(state.module)) return;
  // Editable calendar fields only; never fetch worship documents in the recovery projection.
  const dates = state.module === "calendar" ? [...new Set(state.calendarData.map(row => row.date).filter(Boolean))]
    : [state.services.find(row => row.id === state.selectedServiceId)?.date].filter(Boolean);
  if (!dates.length) return;
  sync.reconciling = true;
  const client = state.client, project = state.config.url, revision = sync.editRevision;
  try {
    for (let offset = 0; offset < dates.length; offset += 100) {
      const { data, error } = await client.from("mindex_sunday_calendar")
        .select(["id", "date", ...CALENDAR_LIVE_FIELDS].join(",")).in("date", dates.slice(offset, offset + 100));
      if (error) throw error;
      if (state.client !== client || state.config.url !== project || revision !== sync.editRevision || departmentRefreshBlocked()) return;
      for (const row of data || []) {
        const previous = state.calendarData.find(item => item.id === row.id);
        if (!previous || CALENDAR_LIVE_FIELDS.some(field => (previous[field] || "") !== (row[field] || ""))) {
          const linkedChanged = !previous || [...DEPARTMENT_ASSIGNEE_FIELDS].some(field => (previous[field] || "") !== (row[field] || ""));
          sync.receive({ id: createUuid(), project, calendarId: row.id, serviceIds: [], calendarOnly: !linkedChanged });
        }
      }
    }
  } catch { /* Reconnect/focus and the low-frequency safety check retry read-only. */ }
  finally { sync.reconciling = false; }
}
function scheduleDepartmentTabRefresh() { departmentTabSync?.schedule(); }
async function refreshDepartmentTabs() {
  const sync = departmentTabSync;
  if (!sync || sync.busy || !sync.pending.size) return;
  const retry = (delay = 2000) => sync.schedule(delay);
  if (departmentRefreshBlocked()) { retry(); return; }
  sync.busy = true;
  const client = state.client, project = state.config.url;
  let retryDelay = 2000;
  try {
    for (const [calendarId, message] of [...sync.pending]) {
      if (message.project !== project) { sync.pending.delete(calendarId); continue; }
      const revision = sync.editRevision;
      const {data, error} = await client.from("mindex_sunday_calendar").select("*").eq("id", calendarId);
      if (error) throw error;
      if (state.client !== client || state.config.url !== project) break;
      if (departmentRefreshBlocked() || revision !== sync.editRevision || sync.pending.get(calendarId) !== message) continue;
      const calendar = data?.[0];
      if (!calendar) { if (sync.pending.get(calendarId) === message) sync.pending.delete(calendarId); continue; }
      let deferred = false;
      const previous = state.calendarData.find(row => row.id === calendarId);
      const linkedChanged = previous && [...DEPARTMENT_ASSIGNEE_FIELDS].some(field => (previous[field] || "") !== (calendar[field] || ""));
      if (previous) {
        for (const field of CALENDAR_LIVE_FIELDS) {
          const cells = [...document.querySelectorAll("[data-cal-id][data-cal-field]")].filter(cell => cell.dataset.calId === calendarId && cell.dataset.calField === field);
          if (state.calendarCellSaves.has(calendarCellSaveKey(calendarId, field)) || departmentCalendarWrites.has(`${calendarId}:${field}`)
            || cells.some(cell => cell.contains(document.activeElement) || cell.classList.contains("is-save-error"))) { deferred = true; continue; }
          previous[field] = calendar[field];
          for (const cell of cells) { cell.textContent = calendar[field] || ""; cell.dataset.initialValue = calendar[field] || ""; }
        }
      } else state.calendarLoaded = false;
      const ids = new Set([...message.serviceIds, ...((message.calendarOnly && !linkedChanged) ? [] : state.services.filter(service => service.date === calendar.date
        && ["children", "youth", "young-adult"].includes(worshipAppServiceTypeId(service.type_id))).map(service => service.id))]);
      for (const id of ids) {
        if (id === state.selectedServiceId && ["service", "presenter"].includes(state.module)) {
          if (!await window.MINDEX_SERVICE_ENTRY?.check(id, undefined, { background: true })) deferred = true;
        } else if (sundayEditSyncHasLocalDraft(id)) deferred = true;
        else { state.loadedWorshipServiceIds.delete(id); state.loadedWorshipPresenterServiceIds.delete(id); presenterSlideBuildCache.delete(id); }
      }
      if (!deferred && sync.pending.get(calendarId) === message) sync.pending.delete(calendarId);
    }
  } catch { retryDelay = 15000; /* Retain the invalidation; never use cached message values. */ }
  finally { sync.busy = false; retry(retryDelay); }
}

const departmentCalendarWrites = new Map();
const DEPARTMENT_ASSIGNEE_FIELDS = new Set(["children_prayer", "youth_prayer", "youth_offering_prayer", "young_adult_prayer"]);
const CALENDAR_LIVE_FIELDS = ["note", "church_schedule", ...CALENDAR_DEPARTMENT_FIELDS.map(([field]) => field), ...CALENDAR_LECTIONARY_FIELDS.map(([field]) => field)];
function departmentAssigneeField(typeId, label) {
  const type = worshipAppServiceTypeId(typeId), name = compactSearchValue(label);
  if (type === "children" && name === "봉헌기도") return "children_prayer";
  if (type === "youth" && name === "봉헌기도") return "youth_offering_prayer";
  if (type === "youth" && ["대표기도", "기도"].includes(name)) return "youth_prayer";
  if (type === "young-adult" && ["대표기도", "기도"].includes(name)) return "young_adult_prayer";
  return "";
}
function adoptDepartmentCalendarReceipt(calendar) {
  if (!calendar?.id) return;
  const previous = state.calendarData.find(row => row.id === calendar.id);
  if (previous) Object.assign(previous, calendar);
  else state.calendarLoaded = false;
}
async function departmentCalendarSave(row, field, value, previousValue) {
  const identity = `${row.id}:${field}`;
  const earlier = departmentCalendarWrites.get(identity) || Promise.resolve();
  const pending = earlier.then(() => departmentCalendarSaveOnce(row, field, value, previousValue));
  departmentCalendarWrites.set(identity, pending);
  try { return await pending; } finally {
    if (departmentCalendarWrites.get(identity) === pending) departmentCalendarWrites.delete(identity);
  }
}
async function departmentCalendarSaveOnce(row, field, value, previousValue) {
  const key = `mindex.department.pending.v1:${JSON.stringify([state.config.url, row.id, field])}`;
  const pending = window.MINDEX_SERVER_STORAGE.journal.getItem(key);
  let request = pending ? JSON.parse(pending) : null;
  if (!request) {
    const context = await state.client.rpc("get_department_assignee_context_v1", { calendar_id: row.id, field_name: field });
    if (context.error) throw context.error;
    if (String(context.data.calendar[field] || "") !== previousValue) {
      throw new Error("담당자가 다른 곳에서 변경됐어요. 교회력을 다시 열어 확인해 주세요.");
    }
    const { prepareWorshipRowsCommit } = await import(`./mindex.worship-atomic-client.mjs?v=${encodeURIComponent(window.MINDEX_RELEASE || "department-links")}`);
    request = { requestId: createUuid(), calendarId: row.id, field, expected: previousValue, value,
      requests: context.data.services.map(aggregate => buildDepartmentCalendarServiceRequest(aggregate, field, value, prepareWorshipRowsCommit)) };
    // Persist before the first write. Transport failures replay this exact batch.
    await window.MINDEX_SERVER_STORAGE.journal.setItem(key, JSON.stringify(request));
  }
  const result = await state.client.rpc("save_calendar_assignee_v1", { req: request });
  if (result.error) {
    if (/^(P0001|22\w{3}|23\w{3}|42501|55P03|57014|40\w{3})$/.test(result.error.code || "")) await window.MINDEX_SERVER_STORAGE.journal.removeItem(key);
    throw result.error;
  }
  await window.MINDEX_SERVER_STORAGE.journal.removeItem(key);
  adoptDepartmentCalendarReceipt(result.data.calendar);
  publishDepartmentTabChange(result.data.calendar, request.requests.map(item => item.serviceId));
  // Invalidate only clean cached services; never overwrite an editor's drafts.
  for (const id of new Set(request.requests.map(item => item.serviceId))) {
    if (sundayEditSyncHasLocalDraft(id) || state.dirtyServiceElementIds.has(id) || state.dirtyServiceStructureIds.has(id)) continue;
    state.loadedWorshipServiceIds.delete(id);
    state.loadedWorshipPresenterServiceIds.delete(id);
    presenterSlideBuildCache.delete(id);
  }
  if (pending || String(result.data.calendar[field] || "") !== value) {
    throw new Error("이전 저장 결과를 확인했어요. 교회력을 다시 열어 현재 담당자를 확인해 주세요.");
  }
  return result.data.calendar;
}
function buildDepartmentCalendarServiceRequest(aggregate, field, value, prepareCommit) {
  const service = normalizeWorshipService(aggregate.service);
  const elements = structuredClone(aggregate.elements), sections = structuredClone(aggregate.sections);
  const matches = elements.filter(row => departmentAssigneeField(service.type_id, row.source_ref?.label) === field);
  if (matches.length > 1) throw new Error("같은 담당 순서가 둘 이상 있어 예배 순서를 먼저 확인해 주세요.");
  const previousItems = groupWorshipElements(sections, elements)[service.id] || [];
  let target = matches[0];
  let insertedSection = null;
  if (!target) {
    const scaffold = buildWorshipServiceScaffold(service.id, service.type_id, { service });
    const candidates = scaffold.elements.filter(row => departmentAssigneeField(service.type_id, row.source_ref?.label) === field);
    if (candidates.length !== 1) throw new Error("담당 순서를 찾지 못했어요. 예배 순서를 확인해 주세요.");
    target = candidates[0];
    const newSection = scaffold.sections.find(row => row.id === target.section_id);
    const existingSection = sections.find(row => row.section_key === newSection.section_key);
    if (existingSection) target.section_id = existingSection.id;
    else { sections.push(newSection); insertedSection = newSection; }
    target.source_ref = { ...target.source_ref, placeholder: false };
    elements.push(target);
  }
  target.person = value;
  const committedItems = groupWorshipElements(sections, elements)[service.id] || [];
  const previousItem = previousItems.find(row => row.id === target.id);
  const committedItem = committedItems.find(row => row.id === target.id);
  const previousDocument = serviceDocumentSnapshotFromRef(service);
  if (previousDocument?.sourceText && !previousDocument.sourceText.endsWith("\n[truncated]") && previousItem && committedItem) {
    service._worshipSourceTextDraft = sundayEditSyncSourceText(previousDocument, previousItem, committedItem, service);
  }
  const document = withServiceDocumentSnapshot(service, committedItems)[MINDEX_SERVICE_DOCUMENT_SOURCE_REF_KEY];
  return { ...prepareCommit({ baseline: aggregate, rows: { sections: insertedSection ? [insertedSection] : [], elements: [target] }, document }),
    protocolVersion: 1, requestId: createUuid() };
}

async function saveCalendarCell(id, field, value, options = {}) {
  const cell = options.cell || null;
  const previousValue = String(options.previousValue || "");
  const row = state.calendarData.find((item) => String(item.id) === String(id));
  const allowedFields = new Set([
    "note",
    "church_schedule",
    ...CALENDAR_DEPARTMENT_FIELDS.map(([fieldName]) => fieldName),
    ...CALENDAR_LECTIONARY_FIELDS.map(([fieldName]) => fieldName),
  ]);
  if (!state.client || !row || row._generatedFeast || !allowedFields.has(field)) {
    if (cell) {
      cell.textContent = previousValue;
      cell.dataset.initialValue = previousValue;
    }
    return false;
  }

  const publishClient = state.client;
  const key = calendarCellSaveKey(id, field);
  const token = createLocalId();
  state.calendarCellSaves.set(key, token);
  setCalendarCellSaveState(cell, "saving");
  try {
    if (DEPARTMENT_ASSIGNEE_FIELDS.has(field)) {
      await departmentCalendarSave(row, field, value, previousValue);
    } else {
      const { error } = await state.client.from("mindex_sunday_calendar").update({ [field]: value }).eq("id", id);
      if (error) throw error;
    }
    row[field] = value;
    if (state.calendarCellSaves.get(key) === token) {
      state.calendarCellSaves.delete(key);
      setCalendarCellSaveState(cell, "saved");
      if (cell) cell.dataset.initialValue = value;
    }
    if (publishClient === state.client && !DEPARTMENT_ASSIGNEE_FIELDS.has(field)) publishDepartmentTabChange(row, [], { calendarOnly: true });
    return true;
  } catch (error) {
    if (state.calendarCellSaves.get(key) === token) {
      state.calendarCellSaves.delete(key);
      if (cell) {
        cell.textContent = previousValue;
        cell.dataset.initialValue = previousValue;
      }
      setCalendarCellSaveState(cell, "error");
    }
    showToast(error.message || "저장하지 못했습니다.", "error");
    return false;
  }
}

function calendarCellSaveKey(id, field) {
  return `${id || ""}:${field || ""}`;
}

function setCalendarCellSaveState(cell, status) {
  if (!cell) return;
  cell.classList.remove("is-saving", "is-saved", "is-save-error");
  cell.removeAttribute("aria-busy");
  if (status === "saving") {
    cell.classList.add("is-saving");
    cell.setAttribute("aria-busy", "true");
    return;
  }
  if (status === "saved") {
    cell.classList.add("is-saved");
    window.setTimeout(() => cell.classList.remove("is-saved"), 700);
    return;
  }
  if (status === "error") {
    cell.classList.add("is-save-error");
    window.setTimeout(() => cell.classList.remove("is-save-error"), 1600);
  }
}

function renderCalendarView() {
  if (!state.client) {
    refs.detailPane.innerHTML = renderConnectionEmptyDetail();
    return;
  }
  if (!state.calendarLoaded && !state.calendarLoading && !state.calendarError) {
    void loadCalendarData({ silent: true });
  }
  if (state.calendarError) {
    refs.detailPane.innerHTML = isConnectionUnavailableMessage(state.calendarError)
      ? renderConnectionEmptyDetail(state.connectionError || state.calendarError)
      : `
        <div class="empty-detail">
          <div class="empty-detail-inner">
            <p class="empty-verse">교회력을 불러올 수 없습니다</p>
            <span>${escapeHtml(state.calendarError)}</span>
          </div>
        </div>`;
    return;
  }
  if (!state.calendarLoaded) {
    refs.detailPane.innerHTML = renderLoadingDetail();
    return;
  }
  const calendarRows = getCalendarDisplayRows();
  if (!calendarRows.length) {
    refs.detailPane.innerHTML = `<div class="empty-detail"><div class="empty-detail-inner"><p class="empty-verse">교회력 데이터가 없습니다.</p></div></div>`;
    return;
  }
  const existingTable = refs.detailPane.querySelector(".cal-table");
  if (
    existingTable?.classList.contains(`cal-table--${state.calendarDetailTab}`) &&
    !state.calendarScrollTargetMonth
  ) return;

  const today = toLocalDateStr(new Date());
  const currentMonth = today.slice(0, 7);
  const visibleMonth = currentCalendarViewportMonth();
  if (!state.calendarScrollTargetMonth && visibleMonth) {
    state.calendarScrollTargetMonth = visibleMonth;
  }
  if (!state.calendarScrollTargetMonth && state.calendarAutoScrolledMonth !== currentMonth) {
    state.calendarScrollTargetMonth = currentMonth;
  }
  const KO_MONTH = ["","1월","2월","3월","4월","5월","6월","7월","8월","9월","10월","11월","12월"];
  const DOW = ["일","월","화","수","목","금","토"];
  const calendarDetailFields = getCalendarDetailFields();

  let tbodyHtml = "";
  let prevMonth = "";
  for (const row of calendarRows) {
    const ym = row.date.slice(0, 7);
    if (ym !== prevMonth) {
      const [y, m] = ym.split("-");
      tbodyHtml += `<tr class="cal-month-row" data-cal-month="${escapeAttr(ym)}"><td colspan="${3 + calendarDetailFields.length}">${y}년 ${KO_MONTH[parseInt(m)]}</td></tr>`;
      prevMonth = ym;
    }
    const d = parseLocalDate(row.date);
    const dateLabel = `${d.getMonth()+1}/${d.getDate()} (${DOW[d.getDay()]})`;
    const isToday = row.date === today;
    const isPast = row.date < today;
    const isUpcomingSunday = row.date === nextSundayDate(today);

    if (isCalendarInlineFeast(row)) {
      tbodyHtml += renderCalendarInlineFeastRow(row, dateLabel, {
        isToday,
        isPast,
        isUpcomingSunday,
        summaryColspan: 2 + calendarDetailFields.length,
      });
      continue;
    }

    const rowCls = [
      "cal-row",
      isToday ? "is-today" : isPast ? "is-past" : "",
      isUpcomingSunday ? "is-upcoming-sunday" : "",
    ].filter(Boolean).join(" ");

    tbodyHtml += `
      <tr class="${rowCls}">
        <td class="cal-date">${dateLabel}</td>
        <td class="cal-lit">${escapeHtml(row.liturgical || "")}</td>
        ${renderCalendarOccasionScheduleCell(row)}
        ${calendarDetailFields.map(([field]) => renderCalendarEditCell(row, field)).join("")}
      </tr>`;
  }

  refs.detailPane.innerHTML = `
    <div class="cal-view">
      <div class="cal-header">
        <span class="cal-subtitle">${escapeHtml(churchYearSeriesSummary(calendarRows))}</span>
        ${renderCalendarDetailTabs()}
      </div>
      <div class="cal-table-wrap">
        <table class="cal-table cal-table--${escapeAttr(state.calendarDetailTab)}">
          ${renderCalendarColumnGroup(calendarDetailFields)}
          <thead>
            <tr>
              <th class="cal-th-date">날짜</th>
              <th class="cal-th-lit">절기</th>
              <th class="cal-th-occasion-schedule">기념/일정</th>
              ${calendarDetailFields.map(([field, department, role]) => renderCalendarRoleHeader(field, department, role)).join("")}
            </tr>
          </thead>
          <tbody>${tbodyHtml}</tbody>
        </table>
      </div>
      <p class="cal-footnote">${escapeHtml(CALENDAR_LECTIONARY_FOOTNOTE.join(" "))}</p>
    </div>`;
  scrollCalendarToTargetMonth();
}

function renderCalendarColumnGroup(calendarDetailFields = []) {
  const columns = [
    "cal-col-date",
    "cal-col-lit",
    "cal-col-occasion-schedule",
    ...calendarDetailFields.map(([field]) => calendarColumnClassForField(field)),
  ];
  return `<colgroup>${columns.map((className) => `<col class="${escapeAttr(className)}">`).join("")}</colgroup>`;
}

function calendarColumnClassForField(field) {
  if (field === "liturgical_color") return "cal-col-color";
  if (field === "psalm") return "cal-col-psalm";
  if (["first_reading", "second_reading", "gospel"].includes(field)) return "cal-col-reading";
  if (field === "youth_offering_prayer") return "cal-col-person-wide";
  return "cal-col-person";
}

function scrollCalendarToTargetMonth({ smooth = false } = {}) {
  const targetMonth = state.calendarScrollTargetMonth;
  if (!targetMonth || state.module !== "calendar") return;
  const wrap = refs.detailPane?.querySelector(".cal-table-wrap");
  const row = [...(wrap?.querySelectorAll(".cal-month-row") || [])]
    .find((monthRow) => monthRow.dataset.calMonth === targetMonth);
  if (!wrap || !row) return;
  const headerHeight = wrap.querySelector("thead")?.getBoundingClientRect().height || 0;
  const wrapTop = wrap.getBoundingClientRect().top;
  const rowTop = row.getBoundingClientRect().top;
  const targetScrollTop = Math.max(0, wrap.scrollTop + rowTop - wrapTop - headerHeight);
  if (smooth) {
    wrap.scrollTop = 0;
    requestAnimationFrame(() => {
      requestAnimationFrame(() => {
        if (!wrap.isConnected || state.module !== "calendar") return;
        wrap.scrollTo({ top: targetScrollTop, behavior: "smooth" });
      });
    });
  } else {
    wrap.scrollTop = targetScrollTop;
  }
  state.calendarScrollTargetMonth = null;
  state.calendarAutoScrolledMonth = targetMonth;
}

function currentCalendarViewportMonth() {
  const wrap = refs.detailPane?.querySelector(".cal-table-wrap");
  const monthRows = [...(wrap?.querySelectorAll(".cal-month-row") || [])];
  if (!wrap || !monthRows.length) return null;
  const headerHeight = wrap.querySelector("thead")?.getBoundingClientRect().height || 0;
  const anchorTop = wrap.getBoundingClientRect().top + headerHeight + 1;
  let month = monthRows[0].dataset.calMonth || null;
  for (const row of monthRows) {
    if (row.getBoundingClientRect().top > anchorTop + 1) break;
    month = row.dataset.calMonth || month;
  }
  return month;
}

function nextSundayDate(todayValue = toLocalDateStr(new Date())) {
  const date = parseLocalDate(todayValue);
  if (Number.isNaN(date.getTime())) return todayValue;
  date.setDate(date.getDate() + ((7 - date.getDay()) % 7));
  return toLocalDateStr(date);
}

function renderCalendarRoleHeader(field, department, role) {
  const className = `cal-th-person ${calendarColumnClassForField(field).replace("cal-col-", "cal-th-")}`;
  if (!role) {
    return `<th class="${escapeAttr(className)} cal-th-simple"><span class="cal-th-role">${escapeHtml(department)}</span></th>`;
  }
  return `
    <th class="${escapeAttr(className)}">
      <span class="cal-th-dept">${escapeHtml(department)}</span>
      <span class="cal-th-role">${escapeHtml(role)}</span>
    </th>`;
}

function getCalendarDetailFields() {
  return state.calendarDetailTab === "lectionary"
    ? CALENDAR_LECTIONARY_FIELDS
    : CALENDAR_DEPARTMENT_FIELDS;
}

function renderCalendarDetailTabs() {
  const tabs = [
    ["departments", "부서 일과"],
    ["lectionary", "성서일과"],
  ];
  return `
    <div class="cal-tabs" role="tablist" aria-label="교회력 표시">
      ${tabs.map(([key, label]) => `
        <button
          class="cal-tab${state.calendarDetailTab === key ? " active" : ""}"
          type="button"
          data-calendar-detail-tab="${escapeAttr(key)}"
          role="tab"
          aria-selected="${state.calendarDetailTab === key ? "true" : "false"}"
        >${escapeHtml(label)}</button>
      `).join("")}
    </div>`;
}

function renderCalendarEditCell(row, field) {
  const val = escapeHtml(row[field] || "");
  return `<td class="cal-cell ${escapeAttr(calendarCellClassForField(field))}" data-cal-id="${escapeAttr(row.id)}" data-cal-field="${escapeAttr(field)}" data-placeholder="—" contenteditable="true" spellcheck="false" title="입력 후 자동 저장">${val}</td>`;
}

function renderCalendarOccasionScheduleCell(row) {
  return `
    <td class="cal-occasion-schedule">
      ${renderCalendarOccasionScheduleItem(row, "note", "기념")}
      ${renderCalendarOccasionScheduleItem(row, "church_schedule", "일정")}
    </td>`;
}

function renderCalendarOccasionScheduleItem(row, field, label) {
  const val = escapeHtml(row[field] || "");
  return `
    <div class="cal-occasion-schedule-item">
      <span class="cal-occasion-schedule-label">${escapeHtml(label)}</span>
      <span class="cal-cell cal-occasion-schedule-value ${escapeAttr(calendarCellClassForField(field))}" data-cal-id="${escapeAttr(row.id)}" data-cal-field="${escapeAttr(field)}" contenteditable="true" spellcheck="false" title="입력 후 자동 저장">${val}</span>
    </div>`;
}

function calendarCellClassForField(field) {
  if (field === "note") return "cal-cell-note";
  if (field === "church_schedule") return "cal-cell-schedule";
  if (field === "liturgical_color") return "cal-cell-color";
  if (field === "psalm") return "cal-cell-reading cal-cell-psalm";
  if (["first_reading", "second_reading", "gospel"].includes(field)) return "cal-cell-reading";
  return "cal-cell-person";
}

// ─── Worship data normalization and service persistence ──────────────────────
function serviceViewHasProtectedSurface(serviceId) {
  const liveRoot = document.getElementById("servicePresenterControls");
  return sundayEditSyncHasLocalDraft(serviceId)
    || (presenterControllerIsLive(serviceId) && liveRoot?.dataset.serviceId === serviceId);
}

function serviceViewIsLoading(serviceId) {
  if (!serviceId || serviceViewHasProtectedSurface(serviceId)) return false;
  return !state.loadedWorshipServiceIds.has(serviceId)
    || serviceItemLoadPromises.has(serviceId)
    || presenterServiceHydrationPromises.has(serviceId)
    || (state.serviceItems[serviceId] || []).some(item => linkedSongLoadPromises.has(item.song_id));
}

function renderServiceViewLoadState(service) {
  const failed = serviceViewLoadErrors.has(service.id);
  if (!failed) return `<section class="service-view-loading" data-service-view-loading="${escapeAttr(service.id)}" aria-busy="true">${renderLoadingRow("예배 자료 불러오는 중…")}<p>${escapeHtml(service.title || serviceTypeDisplayName(service.type_id))}</p></section>`;
  return `<section class="service-view-loading" data-service-view-loading="${escapeAttr(service.id)}" aria-busy="${!failed}">
    ${failed ? '<i data-lucide="cloud-off" aria-hidden="true"></i>' : '<span class="service-view-loading-spinner" aria-hidden="true"></span>'}
    <h2>${failed ? "예배 자료를 불러오지 못했습니다" : "예배를 준비하고 있어요"}</h2>
    <p>${escapeHtml(service.title || serviceTypeDisplayName(service.type_id))}</p>
    <span class="service-view-loading-message" role="status">${failed ? "연결을 확인한 뒤 다시 시도해 주세요." : "예배 순서와 연결된 찬양 자료를 불러오는 중입니다."}</span>
    ${failed ? `<button class="btn secondary" type="button" data-service-load-retry="${escapeAttr(service.id)}">다시 시도</button>` : ""}
  </section>`;
}

function renderServiceViewLoadingIfNeeded(service) {
  if (serviceViewHasProtectedSurface(service.id)) return false;
  if (!serviceViewIsLoading(service.id) && !serviceViewLoadErrors.has(service.id)) return false;
  if (shouldDeferPastWorshipServiceLoad(service.id)) return false;
  setRightSidebarContent("");
  refs.detailPane.innerHTML = renderServiceViewLoadState(service);
  patchPresenterSidebarOutline(service, []);
  refreshIcons(refs.detailPane);
  if (!serviceViewLoadErrors.has(service.id) && !serviceDataLoadPromise
    && !presenterServiceHydrationPromises.has(service.id) && !serviceItemLoadPromises.has(service.id)) {
    void hydratePresenterServiceData(service.id).catch(() => {});
  }
  return true;
}

async function loadServiceItems(serviceId) {
  if (!serviceId) return;
  if (state.loadedWorshipServiceIds.has(serviceId)) {
    loadFullServiceSourceRefInBackground(serviceId);
    if (state.selectedServiceId === serviceId && !state.dirty.service) {
      captureCleanFingerprint("service");
    }
    return;
  }
  if (shouldDeferPastWorshipServiceLoad(serviceId)) return false;
  if (serviceItemLoadPromises.has(serviceId)) return serviceItemLoadPromises.get(serviceId);
  if (!state.client) {
    state.serviceItems[serviceId] = state.serviceItems[serviceId] || [];
    if (state.selectedServiceId === serviceId && !state.dirty.service) {
      captureCleanFingerprint("service");
    }
    return;
  }
  const service = state.services.find((svc) => svc.id === serviceId);
  if (!service) return;
  serviceViewLoadErrors.delete(serviceId);
  const loadPromise = (async () => {
    const previousSectionIds = new Set(
      state.worshipSections
        .filter((section) => section.service_id === serviceId)
        .map((section) => section.id)
        .filter(Boolean),
    );
    const { sections, elements } = await fetchWorshipRowsForServiceIds([serviceId]);
    const hasLocalServiceEdits = state.selectedServiceId === serviceId
      && state.dirty.service
      && Boolean((state.serviceItems[serviceId] || []).length);
    if (hasLocalServiceEdits) return;
    const loadedSectionIds = new Set([
      ...previousSectionIds,
      ...sections.map((section) => section.id).filter(Boolean),
    ]);
    state.worshipSections = [
      ...state.worshipSections.filter((section) => section.service_id !== serviceId),
      ...sections,
    ];
    state.worshipElements = [
      ...state.worshipElements.filter((element) => !loadedSectionIds.has(element.section_id)),
      ...elements,
    ];
    state.loadedWorshipServiceIds.add(serviceId);
    state.serviceItems[serviceId] = projectWorshipServiceItemsFromTemplate(
      service,
      groupWorshipElements(sections, elements)[serviceId] || [],
    );
    const linkedSongIds = elements.map((item) => item.song_id).filter(Boolean);
    const shouldHydrateLinkedSongsBeforeRender = state.selectedServiceId === serviceId
      && (state.module === "presenter" || isServiceDataModule());
    if (shouldHydrateLinkedSongsBeforeRender) {
      await loadSongsForIds(linkedSongIds);
    }
    if (state.selectedServiceId === serviceId && !state.dirty.service) {
      captureCleanFingerprint("service");
    }
    if (!shouldHydrateLinkedSongsBeforeRender) {
      loadSongsForIdsInBackground(linkedSongIds, {
        render: state.selectedServiceId === serviceId ? "detail" : false,
        serviceId,
      });
    }
    warmWorshipScriptureReferencesForService(serviceId);
    warmServiceItemScriptureReferencesForService(serviceId);
  })();
  serviceItemLoadPromises.set(serviceId, loadPromise);
  renderLoadingStatus();
  try {
    await loadPromise;
  } catch (error) {
    serviceViewLoadErrors.set(serviceId, true);
    throw error;
  } finally {
    serviceItemLoadPromises.delete(serviceId);
    renderLoadingStatus();
    if (state.selectedServiceId === serviceId && (state.module === "presenter" || state.module === "service")) {
      // Render once, after the loading lock is cleared. Existing presenter
      // controls preserve focus/scroll through their normal patch path.
      if (state.module === "presenter" && !serviceViewLoadErrors.has(serviceId)) {
        renderPresenterControlState(serviceId);
      } else {
        renderCurrentServiceModuleDetail();
        renderServiceList();
      }
    }
  }
}

// ─── Scripture data and reference workflows ──────────────────────────────────
async function loadBibleTranslations({ silent = false } = {}) {
  if (bibleTranslationLoadPromise) return bibleTranslationLoadPromise;
  bibleTranslationLoadPromise = loadBibleTranslationsOnce({ silent });
  try {
    return await bibleTranslationLoadPromise;
  } finally {
    bibleTranslationLoadPromise = null;
  }
}

async function loadBibleTranslationsOnce({ silent = false } = {}) {
  if (!requireClient({ silent })) return;

  try {
    const data = await fetchCachedSupabasePaged("mindex_bible_translations", "id,translation_key,name,language,abbreviation,source,metadata,is_active", (query) =>
      query.eq("is_active", true).order("name", { ascending: true }));
    state.bibleReaderError = "";
    state.bibleTranslations = (data || []).filter(row => row.is_active !== false && row.metadata?.canonical_source).map(normalizeServerBibleTranslation).sort(sortBibleTranslations);
    if (state.selectedBibleTranslationId && !state.bibleTranslations.some((translation) => translation.id === state.selectedBibleTranslationId)) {
      state.selectedBibleTranslationId = null;
      state.selectedBibleVerse = null;state.selectedBibleVerses = [];state.lastSelectedBibleVerse = null;
    }
    if (!state.selectedBibleTranslationId && state.bibleTranslations.length) {
      state.selectedBibleTranslationId = state.bibleTranslations[0].id;
    }
    persistUiState();
    syncBrowserHistory({ replace: true });
    if (state.selectedBookCode && state.selectedBibleTranslationId) {
      await loadBibleBookVerses({ silent: true });
    } else if (state.module === "scripture") {
      render();
    }
  } catch (error) {
    state.bibleTranslations = [];
    state.bibleBookVerses = [];
    state.bibleReaderError = "Bible verse tables are not ready.";
    if (!silent && state.module === "scripture") showToast(error.message || state.bibleReaderError, "error");
    if (state.module === "scripture") render();
  }
}

async function loadBibleBookVerses({ silent = false } = {}) {
  if (!requireClient({ silent })) return;
  // Edition availability is meaningful only after both catalogs settle.
  if (!state.bibleTranslations.length || !state.scriptureBooks.length) return;
  if(state.selectedBookCode && !getBibleBooks().some(b=>b.code===state.selectedBookCode)){state.selectedBookCode="GEN";state.selectedBibleChapter=1;state.selectedBibleVerse=null;state.selectedBibleVerses=[];state.lastSelectedBibleVerse=null;state.scriptureFilter="all";}
  if (!state.selectedBookCode || !state.selectedBibleTranslationId) {
    state.bibleReaderLoading = false;
    state.bibleBookVerses = [];
    return;
  }

  const chapters = getBibleChapterOptions();
  if (chapters.length && !chapters.includes(state.selectedBibleChapter)) {
    state.selectedBibleChapter = chapters[0];
  }
  const selectedTranslationId = state.selectedBibleTranslationId;
  const selectedBookCode = state.selectedBookCode;
  const selectedChapter = state.selectedBibleChapter;
  const cacheKey = bibleVerseCacheKey(selectedTranslationId, selectedBookCode, selectedChapter);
  if (state.bibleVerseCache.has(cacheKey)) {
    state.bibleReaderLoading = false;
    state.bibleReaderError = "";
    state.bibleBookVerses = state.bibleVerseCache.get(cacheKey);
    persistUiState();
    if (state.module === "scripture") render();
    return;
  }
  const persistentCachedRows = readPersistentBibleChapterCache(selectedTranslationId, selectedBookCode, selectedChapter);
  if (persistentCachedRows) {
    state.bibleReaderLoading = false;
    state.bibleReaderError = "";
    state.bibleVerseCache.set(cacheKey, persistentCachedRows);
    state.bibleBookVerses = persistentCachedRows;
    persistUiState();
    if (state.module === "scripture") render();
    return;
  }

  state.bibleReaderLoading = true;
  if (state.module === "scripture") render();

  if (bibleBookVerseLoadPromises.has(cacheKey)) return bibleBookVerseLoadPromises.get(cacheKey);
  const request = (async () => {
    try {
      const { data, error } = await state.client
        .from("mindex_bible_verses")
        .select("book_code,chapter,verse,verse_end,text,section_title,metadata")
        .eq("is_active", true)
        .eq("translation_id", selectedTranslationId)
        .eq("book_code", selectedBookCode)
        .eq("chapter", selectedChapter)
        .order("verse", { ascending: true });

      if (error) throw error;
      const rows = inferBibleVerseEndRanges((data || []).map(normalizeServerBibleVerse)).sort(sortBibleVerseRows);
      state.bibleVerseCache.set(cacheKey, rows);
      writePersistentBibleChapterCache(selectedTranslationId, selectedBookCode, selectedChapter, rows);
      if (cacheKey !== bibleVerseCacheKey(state.selectedBibleTranslationId, state.selectedBookCode, state.selectedBibleChapter)) {
        return;
      }
      state.bibleReaderError = "";
      state.bibleBookVerses = rows;
      persistUiState();
    } catch (error) {
      if (cacheKey !== bibleVerseCacheKey(state.selectedBibleTranslationId, state.selectedBookCode, state.selectedBibleChapter)) {
        return;
      }
      state.bibleBookVerses = [];
      state.bibleReaderError = "Bible verses could not be loaded.";
      if (!silent && state.module === "scripture") showToast(error.message || state.bibleReaderError, "error");
    } finally {
      if (cacheKey === bibleVerseCacheKey(state.selectedBibleTranslationId, state.selectedBookCode, state.selectedBibleChapter)) {
        state.bibleReaderLoading = false;
        if (state.module === "scripture") render();
      }
    }
  })();
  bibleBookVerseLoadPromises.set(cacheKey, request);
  try {
    return await request;
  } finally {
    bibleBookVerseLoadPromises.delete(cacheKey);
  }
}

async function runBibleTextSearch(value, options = {}) {
  const query = String(value || "").trim();
  if (!query) {
    clearBibleTextSearch();
    renderDetail();
    return;
  }
  if (!requireClient()) return;
  if (!state.bibleTranslations.length && !state.bibleReaderError) await loadBibleTranslations({ silent: true });

  const page = Math.max(0, Number(options.page) || 0);
  state.bibleTextSearchQuery = query;
  state.bibleTextSearchResults = [];
  state.bibleTextSearchError = "";
  state.bibleTextSearchTotal = null;
  state.bibleTextSearchPage = page;
  state.selectedScriptureId = null;

  if (!state.selectedBibleTranslationId) {
    state.bibleTextSearchError = "선택된 성경 역본이 없습니다.";
    renderDetail();
    return;
  }

  const requestId = [state.selectedBibleTranslationId, query, Date.now()].join(":");
  state.bibleTextSearchRequestId = requestId;
  state.bibleTextSearchLoading = true;
  persistUiState();
  syncBrowserHistory();
  renderDetail();

  try {
    const { rows, count, page: resolvedPage } = await fetchBibleTextSearchRows(query, state.selectedBibleTranslationId, page);
    if (state.bibleTextSearchRequestId !== requestId) return;
    state.bibleTextSearchResults = rows.map(normalizeServerBibleVerse).sort(sortBibleVerseRows);
    state.bibleTextSearchTotal = Number.isFinite(count) ? count : state.bibleTextSearchResults.length;
    state.bibleTextSearchPage = resolvedPage;
  } catch (error) {
    if (state.bibleTextSearchRequestId !== requestId) return;
    state.bibleTextSearchResults = [];
    state.bibleTextSearchTotal = null;
    state.bibleTextSearchError = error.message || "본문 검색에 실패했습니다.";
  } finally {
    if (state.bibleTextSearchRequestId === requestId) {
      state.bibleTextSearchLoading = false;
      renderDetail();
    }
  }
}

async function fetchBibleTextSearchRows(query, translationId, page = 0) {
  const rpcRows = await fetchBibleTextSearchRowsViaRpc(query, translationId, page);
  if (rpcRows) return rpcRows;
  return fetchBibleTextSearchRowsByBook(query, translationId, page);
}

async function fetchBibleTextSearchRowsViaRpc(query, translationId, page = 0) {
  try {
    const { data, error } = await state.client.rpc("search_bible_verses", {
      p_query: query,
      p_translation_id: translationId,
      p_page: Math.max(0, Number(page) || 0),
      p_page_size: BIBLE_TEXT_SEARCH_PAGE_SIZE,
    });
    if (error) throw error;

    const responseRows = data || [];
    const firstRow = responseRows[0] || {};
    const count = Number(firstRow.total_count);
    const resolvedPage = Number(firstRow.resolved_page);
    const rows = responseRows.map(({ total_count, resolved_page, ...row }) => row);
    return {
      rows,
      count: Number.isFinite(count) ? count : rows.length,
      page: Number.isFinite(resolvedPage) ? resolvedPage : 0,
    };
  } catch (error) {
    if (isUnavailableRpcError(error)) return null;
    throw error;
  }
}

async function fetchBibleTextSearchRowsByBook(query, translationId, page = 0) {
  const pageSize = BIBLE_TEXT_SEARCH_PAGE_SIZE;
  const requestedPage = Math.max(0, Number(page) || 0);
  const requestedStart = requestedPage * pageSize;
  const requestedEnd = requestedStart + pageSize - 1;
  const { data, error, count } = await state.client
    .from("mindex_bible_verses")
    .select("id,book_code,chapter,verse,verse_end,text,section_title,metadata", { count: "estimated" })
    .eq("is_active", true)
    .eq("translation_id", translationId)
    .ilike("text", `%${escapePostgrestLikePattern(query)}%`)
    .order("book_code", { ascending: true })
    .order("chapter", { ascending: true })
    .order("verse", { ascending: true })
    .range(requestedStart, requestedEnd);

  if (error) throw error;
  const rows = (data || []).sort(sortBibleVerseRows);
  const totalCount = Number(count) || rows.length;
  const maxPage = Math.max(0, Math.ceil(totalCount / pageSize) - 1);
  if (requestedPage > maxPage && totalCount > 0) {
    return fetchBibleTextSearchRowsByBook(query, translationId, maxPage);
  }
  return { rows, count: totalCount, page: Math.min(requestedPage, maxPage) };
}

async function changeBibleTextSearchPage(delta) {
  if (!delta) return;
  const total = Number(state.bibleTextSearchTotal) || state.bibleTextSearchResults.length;
  const maxPage = Math.max(0, Math.ceil(total / BIBLE_TEXT_SEARCH_PAGE_SIZE) - 1);
  const page = Math.min(Math.max(0, state.bibleTextSearchPage + delta), maxPage);
  if (page === state.bibleTextSearchPage) return;
  await runBibleTextSearch(state.bibleTextSearchQuery, { page });
}

async function selectSong(songId) {
  if (songId === state.selectedSongId) {
    const preferredVersionId = getPreferredVersionId(getSelectedSong());
    if (preferredVersionId && preferredVersionId !== state.selectedVersionId && !state.dirty.forms) {
      state.selectedVersionId = preferredVersionId;
      state.forms = [];
    }
    render();
    syncBrowserHistory();
    focusSelectedItemAfterRender();
    if (state.selectedVersionId && !state.forms.length && !state.dirty.forms) {
      await loadForms(state.selectedVersionId);
      focusSelectedItemAfterRender();
    }
    return;
  }
  if (!(await confirmSaveBeforeLeaving())) return;

  state.selectedSongId = songId;
  state.selectedVersionId = getPreferredVersionId(getSelectedSong());
  state.forms = [];
  state.dirty.song = false;
  state.dirty.forms = false;
  persistUiState();
  render();
  syncBrowserHistory();
  focusSelectedItemAfterRender();
  await loadForms(state.selectedVersionId);
  captureCleanFingerprint("praise");
  focusSelectedItemAfterRender();
}

async function selectScripture(scriptureId) {
  if (scriptureId === state.selectedScriptureId) return;
  if (!(await confirmSaveBeforeLeaving())) return;

  state.selectedScriptureId = scriptureId;
  state.dirty.song = false;
  state.dirty.forms = false;
  state.dirty.scripture = false;
  captureCleanFingerprint("scripture");
  persistUiState();
  render();
  syncBrowserHistory();
  focusSelectedItemAfterRender();
}

function buildVerseRange(start, end) {
  if (!start) return [];
  if (!end || end <= start) return [start];
  const range = [];
  for (let v = start; v <= end; v += 1) range.push(v);
  return range;
}

async function selectScriptureBook(bookCode, options = {}) {
  const nextChapter = Number(options.chapter) || 1;
  const nextVerse = Number(options.verse) || null;
  const nextVerseEnd = Number(options.verseEnd) || null;
  const nextVerseRange = buildVerseRange(nextVerse, nextVerseEnd);
  clearBibleTextSearch();
  if (bookCode === state.selectedBookCode && !options.force) {
    if (nextChapter !== state.selectedBibleChapter || nextVerse !== state.selectedBibleVerse) {
      state.selectedBibleChapter = nextChapter;
      state.selectedBibleVerse = nextVerse;
      state.selectedBibleVerses = nextVerseRange;
      state.lastSelectedBibleVerse = nextVerse || null;
      persistUiState();
      syncBrowserHistory();
      await loadBibleBookVerses({ silent: true });
      focusSelectedBibleVerseAfterRender();
    }
    return;
  }
  state.selectedBookCode = bookCode;
  state.selectedScriptureId = null;
  state.selectedBibleChapter = nextChapter;
  state.selectedBibleVerse = nextVerse;
  state.selectedBibleVerses = nextVerseRange;
  state.lastSelectedBibleVerse = nextVerse || null;
  state.bibleBookVerses = [];
  state.dirty.scripture = false;
  persistUiState();
  render();
  syncBrowserHistory();
  focusSelectedItemAfterRender();
  if (!state.bibleTranslations.length && !state.bibleReaderError) await loadBibleTranslations({ silent: true });
  await loadBibleBookVerses({ silent: true });
  focusSelectedBibleVerseAfterRender();
}

async function loadForms(versionId) {
  if (!requireClient()) return;
  if (!versionId) return;

  const song = getSelectedSong();
  const version = (song?.versions || []).find((candidate) => candidate.id === versionId) || getSelectedVersion();
  state.forms = normalizeForms((version?.forms || []).map((form) => withLocalId({ ...form, song_id: versionId })));
  if (!state.dirty.song && !state.dirty.forms) captureCleanFingerprint("praise");
  render();
}

async function createReferenceLink(options = {}) {
  if (!requireClient() || state.saving) return;

  const nextOrder = Math.max(0, ...state.referenceLinks.map((link) => Number(link.sort_order) || 0)) + 10;
  const payload = {
    title: options.title || "새 링크",
    url: "https://",
    sort_order: nextOrder,
    is_active: true,
  };
  if (state.referenceGroupSupported) payload.group_name = nullIfBlank(options.groupName || "");

  state.saving = true;
  updateSaveState();
  try {
    const { data, error } = await state.client
      .from("mindex_reference_links")
      .insert(payload)
      .select("*")
      .single();
    if (error) throw error;

    state.referenceError = "";
    state.referenceLinks = [...state.referenceLinks, normalizeReferenceLink(data)].sort(sortReferenceLinks);
    state.editingReferenceId = data.id;
    state.dirty.references = false;
    captureCleanFingerprint("references");
    window.MINDEX_CONTENT_LIVE?.publish("references", "all");
    render();
    focusEditingReference(data.id);
    showToast("링크를 추가했습니다.");
  } catch (error) {
    showToast(referenceTableErrorMessage(error), "error");
  } finally {
    state.saving = false;
    updateSaveState();
  }
}

// Requests remain immutable after an unknown network outcome. The server keeps
// content-free receipts so retries cannot resurrect a subsequently removed song.
const praiseCreateRequests = new WeakMap();
const praiseDeleteRequests = new WeakMap();
const praiseServiceCreates = new Set();

async function createEmptyPraiseAtomic(options = {}, scope = "sidebar") {
  if (state.singleSongCatalog) {
    const types = normalizePraiseTypes(options.praiseTypes);
    if (options.reuseExisting) {
      const matches = state.songs.filter(song => normalizeTitle(song.title) === normalizeTitle(options.title));
      if (matches.length === 1) return matches[0];
      if (matches.length > 1) throw new Error("같은 제목의 곡이 여러 개입니다. 목록에서 선택해 주세요.");
    }
    const result = await mutateSingleSong("create", {prefix:types.includes("children") ? "kid" : "ccm",
      metadata:{title:options.title || nextPraiseSongTitle(),praise_types:types.length ? types : ["ccm"]},
      content:{name:"기본",raw_section_name:"기본",is_primary:true,forms:[]}}, `create:${scope}`);
    return state.songs.find(song=>song.id===result.id);
  }
  const client = state.client, project = state.config.url;
  if (!client) throw new Error("서버 연결을 확인해 주세요.");
  let pending = praiseCreateRequests.get(client);
  if (!pending) { pending = new Map(); praiseCreateRequests.set(client, pending); }
  const key = `${project}:${scope}`;
  let entry = pending.get(key);
  if (!entry) {
    entry = {req:{protocolVersion:1,requestId:createUuid(),songId:createUuid(),versionId:createUuid(),
      title:options.title,praiseTypes:options.praiseTypes,reuseExisting:!!options.reuseExisting,autoTitle:!!options.autoTitle}};
    pending.set(key,entry);
  }
  if (!entry.promise) entry.promise = (async () => {
    const result = await client.rpc('create_praise_v1',{req:entry.req});
    if (result.error) {
      if (['P0001','23505','23503','42501'].includes(result.error.code)) pending.delete(key);
      throw new Error(result.error.message?.includes('PRAISE_CREATED_THEN_REMOVED')
        ? "만들었던 곡이 이미 삭제되어 다시 만들지 않았습니다."
        : "곡 등록 결과를 확인하지 못했습니다. 다시 누르면 같은 요청을 확인합니다.");
    }
    const song = praiseSnapshotSong(result.data?.snapshot);
    pending.delete(key);
    if (client !== state.client || project !== state.config.url) throw new Error("연결이 변경되었습니다. 원래 프로젝트의 등록 결과를 확인해 주세요.");
    state.songs = [song,...state.songs.filter(row=>row.id!==song.id)].sort(sortSongs);
    clearSearchCaches();
    window.MINDEX_CONTENT_LIVE?.publish("song",song.id);
    return song;
  })().finally(()=>{entry.promise=null;});
  return entry.promise;
}

async function createPraiseSong(options = {}) {
  if (!requireClient() || state.saving) return;
  if (state.loading || songLoadPromise) return;
  if (state.module !== "praise") await switchModule("praise", { clearSearch: false });
  if (state.module !== "praise") return;
  if (state.dirty.song || state.dirty.forms) { showToast("편집 중인 곡을 먼저 저장해 주세요. 입력은 유지됩니다.","info"); return; }

  const selectedBefore = state.selectedSongId, dirtyBefore = JSON.stringify(state.dirty);
  const draft = buildNewPraiseSongDraft(options);
  const publishClient = state.client;
  state.saving = true;
  updateSaveState();
  try {
    const song = await createEmptyPraiseAtomic({title:draft.title,praiseTypes:draft.praise_types,
      autoTitle:!options.title}, "sidebar");
    if (state.module !== "praise" || state.selectedSongId !== selectedBefore || JSON.stringify(state.dirty) !== dirtyBefore) {
      showToast("곡을 추가했습니다. 현재 편집 화면은 유지합니다.");
      return;
    }
    state.songs = [song, ...state.songs.filter((item) => item.id !== song.id)].sort(sortSongs);
    clearSearchCaches();
    state.selectedSongId = song.id;
    state.selectedVersionId = getDefaultVersionId(song);
    state.forms = normalizeForms((getSelectedVersion()?.forms || []).map((form) => withLocalId({ ...form, song_id: state.selectedVersionId })));
    state.search = "";
    refs.searchInput.value = "";
    state.metadataPopupOpen = true;
    state.dirty.song = false;
    state.dirty.forms = false;
    captureCleanFingerprint("praise");
    persistUiState();
    render();
    requestAnimationFrame(() => refs.detailPane.querySelector('[data-song-field="title"]')?.focus());
    if (publishClient === state.client) window.MINDEX_CONTENT_LIVE?.publish("song", song.id);
    showToast("곡을 추가했습니다.");
  } catch (error) {
    showToast(error.message || "곡 추가 실패.", "error");
  } finally {
    state.saving = false;
    updateSaveState();
  }
}

function buildNewPraiseSongDraft(options = {}) {
  const praiseTypes = normalizePraiseTypes(options.praiseTypes || options.praise_types || state.praiseFilter);
  const version = {
    id: createUuid(),
    name: "기본",
    raw_section_name: "기본",
    is_primary: true,
    praise_types: praiseTypes.length ? praiseTypes : ["ccm"],
    forms: [],
  };
  return {
    title: firstNonBlankString(options.title, nextPraiseSongTitle()),
    praise_types: version.praise_types,
    versions: [version],
    scripture: [],
    metadata: {},
    related_song_ids: [],
  };
}

function nextPraiseSongTitle() {
  const base = "새 찬양";
  const used = new Set((state.songs || []).map((song) => normalizeTitle(song.title)));
  if (!used.has(normalizeTitle(base))) return base;
  for (let index = 2; index < 1000; index += 1) {
    const title = `${base} ${index}`;
    if (!used.has(normalizeTitle(title))) return title;
  }
  return `${base} ${Date.now()}`;
}

function songHasDeleteProtectedContent(song = {}) {
  if (song.hymn_no || song.subtitle || song.original_title) return true;
  if (cleanList(song.scripture).length || cleanList(song.related_song_ids).length) return true;
  if (Object.keys(normalizeSongMetadata(song.metadata)).length) return true;
  return (song.versions || []).some((version) => {
    if (version.audio_set || version.subtitle || version.original_title || version.hymn_no || version.deck_key) return true;
    if (Object.keys(normalizeSongMetadata(version.metadata)).length) return true;
    return normalizeForms(version.forms || []).some((form) => normalizeLyricsForCopy(form.lyrics));
  });
}

function canDeletePraiseSong(song = getSelectedSong()) {
  return Boolean(song && !songHasDeleteProtectedContent(song));
}

async function deleteSelectedSong() {
  const song = getSelectedSong();
  if (song?._singleSongRecord) return deleteSingleSong(song);
  if (!song || !requireClient() || state.saving) return;
  if (state.dirty.song || state.dirty.forms) { showToast("편집 중인 입력이 있어 삭제하지 않았습니다. 먼저 저장하거나 변경을 취소해 주세요.","info"); return; }
  if (!canDeletePraiseSong(song)) {
    showToast("내용이 비어 있는 곡만 바로 삭제할 수 있어요.", "error");
    return;
  }
  if (!confirm(`"${song.title}"을 삭제할까요?`)) return;
  const editorBefore = JSON.stringify({song,forms:state.forms});

  const publishClient = state.client;
  state.saving = true;
  updateSaveState();
  try {
    let pending = praiseDeleteRequests.get(song);
    if (pending && (pending.client !== publishClient || pending.project !== state.config.url)) throw new Error("연결이 변경되어 삭제하지 않았습니다.");
    if (!pending) {
      const fresh = await publishClient.rpc('get_praise_snapshot_v1',{sid:song.id});
      if (fresh.error) throw new Error("최신 자료를 확인하지 못해 삭제하지 않았습니다.");
      if (praiseSaveComparable(song) !== praiseSaveComparable(praiseSnapshotSong(fresh.data))) throw new Error("다른 곳에서 곡이 변경되어 삭제하지 않았습니다.");
      pending = {client:publishClient,project:state.config.url,req:{protocolVersion:1,requestId:createUuid(),songId:song.id,expected:fresh.data}};
      praiseDeleteRequests.set(song,pending);
    }
    if (state.selectedSongId === song.id && editorBefore !== JSON.stringify({song,forms:state.forms})) throw new Error("확인 중 입력이 변경되어 삭제하지 않았습니다.");
    const before = JSON.stringify({song,forms:state.forms});
    const result = await publishClient.rpc('delete_empty_praise_v1',{req:pending.req});
    if (result.error) {
      if (['P0001','23503','42501'].includes(result.error.code)) praiseDeleteRequests.delete(song);
      throw new Error(result.error.message?.includes('PRAISE_IN_USE') ? "예배나 다른 자료에 연결된 곡은 삭제할 수 없습니다."
        : result.error.message?.includes('PRAISE_NOT_EMPTY') || result.error.message?.includes('PRAISE_CONFLICT') ? "내용이 있거나 다른 곳에서 변경되어 삭제하지 않았습니다."
        : "삭제 결과를 확인하지 못했습니다. 다시 누르면 같은 요청을 확인합니다.");
    }
    if (!result.data?.deleted) throw new Error("삭제 결과를 확인하지 못했습니다.");
    praiseDeleteRequests.delete(song);
    if (publishClient !== state.client || pending.project !== state.config.url) return;
    if (state.selectedSongId === song.id && before !== JSON.stringify({song,forms:state.forms})) { showToast("서버의 빈 곡은 삭제됐지만, 대기 중 입력한 내용은 화면에 유지했습니다.","info"); return; }
    state.songs = state.songs.filter((item) => item.id !== song.id);
    clearSearchCaches();
    if (state.selectedSongId === song.id) {
      state.selectedSongId = null;
      state.selectedVersionId = null;
      state.forms = [];
      state.dirty.song = false;
      state.dirty.forms = false;
      captureCleanFingerprint("praise");
    }
    persistUiState();
    render();
    if (publishClient === state.client) window.MINDEX_CONTENT_LIVE?.publish("song", song.id);
    showToast("빈 곡을 삭제했습니다.");
  } catch (error) {
    showToast(error.message || "삭제하지 못했습니다. 기존 자료는 유지됩니다.","error");
  } finally {
    state.saving = false;
    updateSaveState();
  }
}

function handleSaveShortcut(event) {
  if (!(event.metaKey || event.ctrlKey) || event.altKey || event.shiftKey) return;
  if (event.code !== "KeyS" && String(event.key).toLowerCase() !== "s") return;
  event.preventDefault();
  event.stopPropagation();
  if (worshipConflictReview) return;
  if (!event.repeat) void saveAll();
}

async function saveAll() {
  const bulletin = refs.detailPane?.querySelector(".bulletin-workbench");
  if (bulletin) {
    const detail={};
    bulletin.dispatchEvent(new CustomEvent("mindex-bulletin-save",{detail}));
    return detail.result ? await detail.result : false;
  }
  if (state.module === "home" || state.module === "bulletin") return;
  const saveState = currentSaveButtonState();
  if (!saveState.available) return false;
  if (isServiceDataModule()) {
    return await saveService(state.module === "presenter" ? presenterViewServiceId() : state.selectedServiceId);
  }
  if (!saveState.dirty) return true;
  if (state.module === "references") {
    await saveReferenceLinks();
    return;
  }
  if (state.module === "scripture") {
    await saveScripture();
    return;
  }

  if (state.module === "praise" && songLoadPromise) return;

  const song = getSelectedSong();
  if (!song || !requireClient() || state.saving) return;

  const title = (song.title || "").trim();
  if (!title) {
    showToast("제목을 입력해 주세요.", "error");
    return;
  }

  const publishClient = state.client;
  state.saving = true;
  updateSaveState();

  try {
    writeFormsToSelectedVersion();
    const savedWithoutNewInput = await saveSongMeta(song);
    if (publishClient !== state.client || getSelectedSong() !== song) return;
    if (publishClient === state.client) window.MINDEX_CONTENT_LIVE?.publish("song", song.id);
    if (!savedWithoutNewInput) {
      showToast("저장했습니다. 저장 중 추가한 입력은 남아 있으니 다시 저장해 주세요.");
      return;
    }
    const selectedVersion = getSelectedVersion();
    if (selectedVersion) state.forms = normalizeForms((selectedVersion.forms || []).map(form => withLocalId({ ...form, song_id: selectedVersion.id })));
    state.songs = state.songs.sort(sortSongs);
    clearSearchCaches();
    state.dirty.song = false;
    state.dirty.forms = false;
    delete song._pendingVersionDeletes;
    captureCleanFingerprint("praise");
    showToast("저장했습니다.");
    render();
  } catch (error) {
    showToast(error.message || "저장하지 못했습니다.", "error");
  } finally {
    state.saving = false;
    updateSaveState();
  }
}

async function saveReferenceLinks() {
  if (!requireClient() || state.saving) return;

  const publishClient = state.client, publishProject = state.config.url;
  const before = dirtyModuleFingerprint("references");
  const links = state.referenceLinks.map(normalizeReferenceLink).sort(sortReferenceLinks);
  const invalid = links.find((link) => !link.title.trim() || !referenceUrlIsValid(link.url));
  if (invalid) {
    showToast("링크 제목과 URL을 입력해 주세요.", "error");
    return;
  }

  state.saving = true;
  updateSaveState();
  try {
    const payload = links.map((link, index) => ({
      id: link.id,
      title: link.title.trim(),
      url: normalizeReferenceUrl(link.url),
      sort_order: Number(link.sort_order) || (index + 1) * 10,
      is_active: link.is_active !== false,
    }));
    payload.forEach((row, index) => {
      const groupName = nullIfBlank(links[index].group_name);
      if (state.referenceGroupSupported) row.group_name = groupName;
    });
    const { data, error } = await state.client
      .from("mindex_reference_links")
      .upsert(payload, { onConflict: "id" })
      .select("*")
      .order("sort_order", { ascending: true })
      .order("title", { ascending: true });
    if (error) throw error;

    if (state.client !== publishClient || state.config.url !== publishProject) return;
    if (dirtyModuleFingerprint("references") !== before) {
      state.cleanFingerprints.references = JSON.stringify(dirtyComparableValue((data || []).map(normalizeReferenceLink).sort(sortReferenceLinks)));
      state.dirty.references = true;
      window.MINDEX_CONTENT_LIVE?.publish("references", "all");
      showToast("저장했습니다. 저장 중 추가한 입력은 유지했습니다.");
      return;
    }
    state.referenceLinks = (data || []).map(normalizeReferenceLink).sort(sortReferenceLinks);
    state.referenceError = "";
    state.referenceLinksLoaded = true;
    state.dirty.references = false;
    captureCleanFingerprint("references");
    showToast("링크를 저장했습니다.");
    window.MINDEX_CONTENT_LIVE?.publish("references", "all");
    render();
  } catch (error) {
    showToast(referenceTableErrorMessage(error), "error");
  } finally {
    state.saving = false;
    updateSaveState();
  }
}

function updateReferenceLinkField(field) {
  const link = state.referenceLinks.find((item) => item.id === field.dataset.referenceId);
  if (!link) return;

  const key = field.dataset.referenceField;
  if (!["title", "url", "group_name", "is_active"].includes(key)) return;
  link[key] = field.value;
  if (key === "is_active") link[key] = field.checked;
  state.dirty.references = true;
  updateSaveState();
}

function normalizeReferenceUrl(value) {
  const raw = String(value || "").trim();
  if (!raw) return "";
  const candidate = /^[a-z][a-z0-9+.-]*:/i.test(raw) ? raw : `https://${raw}`;
  try {
    const parsed = new URL(candidate);
    if (!["http:", "https:"].includes(parsed.protocol)) return "";
    return parsed.toString();
  } catch {
    return "";
  }
}

function referenceUrlIsValid(value) {
  return Boolean(normalizeReferenceUrl(value));
}

function openReferenceLink(link) {
  const url = normalizeReferenceUrl(link?.url);
  if (!url) {
    showToast("열 수 없는 링크입니다.", "error");
    return false;
  }
  window.open(url, "_blank", "noopener,noreferrer");
  return true;
}

function updateReferenceGroupName(field) {
  const originalKey = field.dataset.referenceGroupKey || "ungrouped";
  const nextName = String(field.value || "").trim();
  const links = state.referenceLinks.filter((link) =>
    link._editingGroupKey === originalKey || referenceGroupKey(link.group_name) === originalKey);
  if (!links.length) return;
  links.forEach((link) => {
    link.group_name = nextName;
    link._editingGroupKey = originalKey;
  });
  state.editingReferenceGroupKey = referenceGroupKey(nextName);
  state.dirty.references = true;
  updateSaveState();
}

function beginEditReferenceGroup(key) {
  const groupKey = key || "ungrouped";
  state.editingReferenceGroupKey = groupKey;
  state.referenceLinks.forEach((link) => {
    if (referenceGroupKey(link.group_name) === groupKey) link._editingGroupKey = groupKey;
  });
  requestAnimationFrame(() => {
    refs.detailPane?.querySelector("[data-reference-group-field]")?.focus();
  });
}

function endEditReferenceGroup() {
  state.editingReferenceGroupKey = null;
  state.referenceLinks.forEach((link) => {
    delete link._editingGroupKey;
  });
}

function cssEscape(value) {
  return window.CSS?.escape
    ? window.CSS.escape(String(value || ""))
    : String(value || "").replace(/["\\]/g, "\\$&");
}

function focusEditingReference(id, field = "title") {
  requestAnimationFrame(() => {
    const selector = `[data-reference-id="${cssEscape(id)}"][data-reference-field="${cssEscape(field)}"]`;
    const input = refs.detailPane?.querySelector(selector);
    if (!input) return;
    input.focus();
    if (typeof input.select === "function") input.select();
  });
}

function referenceGroupKey(groupName) {
  const text = String(groupName || "").trim();
  return text || "ungrouped";
}

function nextReferenceGroupName() {
  const existing = new Set(state.referenceLinks.map((link) => normalizeSearchValue(link.group_name)).filter(Boolean));
  let index = 1;
  while (existing.has(normalizeSearchValue(`그룹 ${index}`))) index += 1;
  return `그룹 ${index}`;
}

function moveReferenceLink(id, delta) {
  const groups = referenceGroupBlocks();
  const group = groups.find((item) => item.links.some((link) => link.id === id));
  if (!group) return;
  const index = group.links.findIndex((link) => link.id === id);
  const nextIndex = index + delta;
  if (index < 0 || nextIndex < 0 || nextIndex >= group.links.length) return;

  const [link] = group.links.splice(index, 1);
  group.links.splice(nextIndex, 0, link);
  updateReferenceOrderFromGroups(groups);
}

function moveReferenceGroup(key, delta) {
  const groups = referenceGroupBlocks();
  const index = groups.findIndex((group) => group.key === referenceGroupKey(key));
  const nextIndex = index + delta;
  if (index < 0 || nextIndex < 0 || nextIndex >= groups.length) return;

  const [group] = groups.splice(index, 1);
  groups.splice(nextIndex, 0, group);
  updateReferenceOrderFromGroups(groups);
}

function referenceGroupBlocks() {
  const groups = [];
  for (const link of [...state.referenceLinks].map(normalizeReferenceLink).sort(sortReferenceLinks)) {
    const key = referenceGroupKey(link.group_name);
    let group = groups.find((item) => item.key === key);
    if (!group) {
      group = { key, links: [] };
      groups.push(group);
    }
    group.links.push(link);
  }
  return groups;
}

function updateReferenceOrderFromGroups(groups) {
  const links = groups.flatMap((group) => group.links);
  state.referenceLinks = links.map((item, itemIndex) => ({
    ...item,
    sort_order: (itemIndex + 1) * 10,
  }));
  state.dirty.references = true;
  render();
  updateSaveState();
}

async function deleteReferenceLink(id) {
  const link = state.referenceLinks.find((item) => item.id === id);
  if (!link || !requireClient() || state.saving) return;
  if (!confirm(`"${link.title || "링크"}"을(를) 삭제할까요?`)) return;

  state.saving = true;
  updateSaveState();
  try {
    const { error } = await state.client.from("mindex_reference_links").delete().eq("id", id);
    if (error) throw error;
    state.referenceLinks = state.referenceLinks.filter((item) => item.id !== id);
    state.dirty.references = false;
    captureCleanFingerprint("references");
    window.MINDEX_CONTENT_LIVE?.publish("references", "all");
    render();
    showToast("링크를 삭제했습니다.");
  } catch (error) {
    showToast(referenceTableErrorMessage(error), "error");
  } finally {
    state.saving = false;
    updateSaveState();
  }
}

function referenceTableErrorMessage(error) {
  const code = String(error?.code || "");
  const message = `${error?.message || ""} ${error?.details || ""} ${error?.hint || ""}`;
  if (code === "42501" || /permission denied|row.level security|\brls\b|policy/i.test(message)) {
    return "링크에 접근할 권한이 없습니다. 로그인 상태와 접근 권한을 확인해 주세요.";
  }
  if (code === "42P01" || /relation .* does not exist/i.test(message)) return "링크 테이블이 없습니다.";
  if (isUnavailableRelationError(error)) return "링크 테이블 정보를 확인할 수 없습니다. 서버 설정을 확인해 주세요.";
  return error?.message || "링크를 업데이트하지 못했습니다.";
}

async function saveScripture() {
  const scripture = getSelectedScripture();
  if (!scripture || !requireClient() || state.saving) return;

  const title = (scripture.title || "").trim();
  if (!title) {
    showToast("제목을 입력해 주세요.", "error");
    return;
  }

  const publishClient = state.client, publishProject = state.config.url;
  const before = JSON.stringify(dirtyComparableValue(scripture));
  state.saving = true;
  updateSaveState();

  try {
    const { data, error } = await state.client
      .from("mindex_scriptures")
      .update({
        title,
        book_code: scripture.book_code || null,
        book: scripture.book || "",
        reference: scripture.reference || "",
        translation: scripture.translation || "",
        text: scripture.text || "",
        memo: scripture.memo || null,
      })
      .eq("id", scripture.id)
      .select("*")
      .single();

    if (error) throw error;
    if (!data || data.id !== scripture.id) throw new Error("저장 결과를 확인하지 못했습니다.");

    if (state.client !== publishClient || state.config.url !== publishProject) return;
    if(typeof rememberRecentEdit === "function") rememberRecentEdit({module:"scripture",selectedScriptureId:data.id},data.title);
    window.MINDEX_CONTENT_LIVE?.publish("scripture", "all");
    if (getSelectedScripture() !== scripture) return;
    if (JSON.stringify(dirtyComparableValue(scripture)) !== before) {
      state.cleanFingerprints.scripture = JSON.stringify(dirtyComparableValue(normalizeServerScripture(data)));
      state.dirty.scripture = true;
      showToast("저장했습니다. 저장 중 추가한 입력은 유지했습니다.");
      return;
    }
    Object.assign(scripture, normalizeServerScripture(data));
    state.scriptures = state.scriptures.sort(sortScriptures);
    state.dirty.scripture = false;
    captureCleanFingerprint("scripture");
    showToast("저장했습니다.");
    render();
  } catch (error) {
    showToast(error.message || "저장하지 못했습니다.", "error");
  } finally {
    state.saving = false;
    updateSaveState();
  }
}

function serviceSaveErrorMessage(error) {
  const message = String(error?.message || (typeof error === "string" ? error : "") || "").trim();
  const code = String(error?.code || error?.name || "").trim();
  if (message === "JOURNAL_NOT_CONFIRMED") {
    if (error.journalPhase === "cleanup") return "예배 저장 응답은 받았지만 복구 기록 정리를 확인하지 못했습니다. 입력과 요청은 유지됩니다. 다시 저장하면 기존 요청의 결과부터 확인합니다.";
    const cause = String(error?.cause?.message || "");
    if (cause === "STATE_REVISION_CONFLICT") return "저장 복구 정보가 다른 창의 내용과 충돌했습니다. 입력과 임시 저장본은 유지됩니다. 하단의 ‘충돌 확인’에서 기존 요청을 확인한 뒤 다시 저장해 주세요.";
    return "서버에 저장 복구 정보를 확인하지 못했습니다. 입력과 임시 저장본은 유지됩니다. 연결을 확인한 뒤 다시 저장해 주세요.";
  }
  if (/Failed to fetch|Failed to send a request|NetworkError|Load failed|Network request failed/i.test(message)) {
    return "서버 응답을 받지 못해 저장 완료 여부를 확인하지 못했습니다. 입력은 유지됩니다. 연결을 확인한 뒤 다시 저장해 주세요.";
  }
  if (/QuotaExceededError|SecurityError/.test(code)) {
    return "서버에 저장 복구 정보를 기록하지 못했습니다. 입력은 유지됩니다. 연결을 확인하고 다시 시도해 주세요.";
  }
  if (/PENDING_PROJECT_UNKNOWN/.test(message)) {
    return "이전 저장 요청의 프로젝트를 확인할 수 없어 재전송하지 않았습니다. 입력과 이전 요청은 유지됩니다.";
  }
  if (/PENDING_REQUEST_REQUIRES_RESOLUTION/.test(message)) {
    return "이전 저장 결과를 먼저 확인해야 합니다. 입력은 유지됩니다. 화면을 새로고침한 뒤 다시 저장해 주세요.";
  }
  if (/REVISION_CONFLICT|ATOMIC_RELOAD_REQUIRED/.test(message)) {
    return "다른 저장과 충돌해 덮어쓰지 않았습니다. 입력은 유지됩니다. 최신 DB와 비교한 뒤 다시 저장해 주세요.";
  }
  if (/ATOMIC_RETRY_COMMITTED_RELOAD_REQUIRED/.test(message)) {
    return "응답이 끊겼던 이전 저장은 완료됐습니다. 이후 입력은 유지됩니다. 최신 DB를 확인한 뒤 다시 저장해 주세요.";
  }
  if (/BASELINE_REQUIRED/.test(message)) {
    return "예배의 저장 기준을 확인하지 못했습니다. 입력은 유지됩니다. DB 연결과 최신 예배 상태를 확인해 주세요.";
  }
  if (/SERVICE_NOT_FOUND|SERVICE_DELETED/.test(message)) {
    return "서버에서 이 예배를 찾을 수 없습니다. 입력은 유지됩니다. 예배 목록을 새로고침해 주세요.";
  }
  if (/DOCUMENT_(?:ELEMENT|SECTION)_OWNERSHIP|DOCUMENT_(?:PARENT|SLOT|SONG|VERSION)_MISMATCH|ROW_OWNERSHIP/.test(message)) {
    return "예배 원문과 저장 항목이 맞지 않아 덮어쓰지 않았습니다. 입력은 유지됩니다. 화면을 새로고침한 뒤 다시 저장해 주세요.";
  }
  if (/SONG_VERSION_MISMATCH/.test(message)) {
    return "찬양과 선택한 버전이 맞지 않아 저장하지 않았습니다. 입력은 유지됩니다. 찬양 버전을 다시 선택해 주세요.";
  }
  if (/DUPLICATE_OR_MISSING_ROW_ID|DUPLICATE_(?:DOCUMENT_RECORD|DOCUMENT_SLIDE|ID)|CONFLICTING_STRUCTURE/.test(message)) {
    return "같은 예배 항목이 겹쳐 저장하지 않았습니다. 입력은 유지됩니다. 화면을 새로고침한 뒤 다시 저장해 주세요.";
  }
  if (/ON CONFLICT DO UPDATE command cannot affect row a second time/i.test(message)) {
    return "예배 저장 항목이 겹쳐 저장하지 못했습니다. 항목을 정리한 뒤 다시 저장해 주세요.";
  }
  if (/duplicate key value violates unique constraint/i.test(message)) {
    return "같은 항목이 이미 저장되어 있습니다. 화면을 새로고침한 뒤 다시 시도해 주세요.";
  }
  return message || `예배를 저장하지 못했습니다. 입력은 유지됩니다. 오류: ${code || "UNKNOWN_SAVE_ERROR"}`;
}

let worshipConflictReview = null;
function worshipConflictDraft(serviceId) {
  const service = state.services.find(candidate => candidate.id === serviceId);
  if (!service) return null;
  const items = structuredClone(getServiceItems(serviceId));
  const pendingInputs = [...(refs.detailPane?.querySelectorAll('[data-service-item-field]') || [])]
    .filter(field => (field.dataset.serviceId || state.selectedServiceId) === serviceId)
    .filter(field => isDeferredServiceTextInput(field)
      && field.dataset.initialValue !== undefined && field.value !== field.dataset.initialValue)
    .map(field => ({itemId:items[Number(field.dataset.serviceItemIndex)]?.id || null,
      index:field.dataset.serviceItemIndex, field:field.dataset.serviceItemField,
      initialValue:field.dataset.initialValue, value:field.value}));
  return {service: structuredClone(service), items, pendingInputs,
    sourceText: serviceSourceTextareaForService(serviceId)?.value
      ?? service._worshipSourceTextDraft ?? buildServiceSourceText(service, {items})};
}

async function reopenWorshipConflict(review, isOpen = () => true) {
  const id = review.serviceId;
  const signature = JSON.stringify(review.draft);
  const atomic = await worshipAtomicClient();
    const archive = {schema:1, reason:'before-conflict-reopen', capturedAt:new Date().toISOString(),
      serviceId:id, service:review.draft.service, draft:review.draft,
      serviceDocument:{sourceText:review.draft.sourceText},
      baseline:review.baseline, sections:review.baseline?.sections || [], elements:review.baseline?.elements || []};
    const serialized = JSON.stringify(archive);
    const archiveKey = `${worshipRecoveryLatestSnapshotKey(id)}:conflict:${crypto.randomUUID()}`;
    await persistServerValue('local', archiveKey, serialized);
    await persistServerValue('local', worshipRecoveryLatestSnapshotKey(id), serialized);
  await atomic.reopenReviewed(review, {beforeAdopt: latest => {
    if (!isOpen() || state.saving || JSON.stringify(worshipConflictDraft(id)) !== signature) {
      throw new Error('LOCAL_DRAFT_CHANGED');
    }
    const service = normalizeWorshipService(latest.service);
    const items = projectWorshipServiceItemsFromTemplate(service,
      groupWorshipElements(latest.sections, latest.elements)[id] || []);
    // No DB write or presenter publish: only this service's editable baseline changes.
    const sectionIds = new Set(state.worshipSections.filter(row => row.service_id === id).map(row => row.id));
    state.worshipElements.filter(row => sectionIds.has(row.section_id))
      .forEach(row => state.templateElementSuppressions.delete(row.id));
    state.worshipSections = state.worshipSections.filter(row => row.service_id !== id).concat(latest.sections);
    state.worshipElements = state.worshipElements.filter(row => !sectionIds.has(row.section_id)).concat(latest.elements);
    state.services = state.services.map(row => row.id === id ? service : row);
    state.serviceItems[id] = items;
    state.loadedWorshipServiceIds.add(id);
    state.dirtyServiceElementIds.delete(id);
    state.dirtyServiceStructureIds.delete(id);
    return true;
  }});
}

async function preserveWorshipConflictServerSnapshot(review = {}) {
  const latest = review?.latest;
  const id = String(review?.serviceId || latest?.service?.id || "").trim();
  if (!latest?.service || !id) throw new Error("SERVER_SNAPSHOT_UNAVAILABLE");
  const sourceText = latest.service?.source_ref?.mindexServiceDocument?.sourceText || "";
  const archive = {
    schema: 1,
    reason: "conflict-server-latest",
    capturedAt: new Date().toISOString(),
    serviceId: id,
    service: structuredClone(latest.service),
    serviceDocument: { sourceText },
    baseline: review.baseline || null,
    sections: structuredClone(latest.sections || []),
    elements: structuredClone(latest.elements || []),
  };
  const serialized = JSON.stringify(archive);
  const archiveKey = `${worshipRecoveryLatestSnapshotKey(id)}:conflict-server:${crypto.randomUUID()}`;
  await persistServerValue("local", archiveKey, serialized);
  await persistServerValue("local", worshipRecoveryLatestSnapshotKey(id), serialized);
  scheduleWorshipRecoverySnapshotHistoryWrite(serialized);
  return true;
}

function worshipConflictTextSummary(localText, serverText) {
  if (localText === serverText) return "원문은 같습니다. 순서·곡 연결 등 다른 저장 항목이 변경되었을 수 있습니다.";
  const local = String(localText || "").split(/\r?\n/);
  const remote = String(serverText || "").split(/\r?\n/);
  let start = 0, end = 0;
  while (start < local.length && start < remote.length && local[start] === remote[start]) start++;
  while (end < local.length - start && end < remote.length - start
    && local[local.length - 1 - end] === remote[remote.length - 1 - end]) end++;
  return `${start + 1}행부터 차이가 있습니다 · 내 입력 ${local.length - start - end}행 / 최신본 ${remote.length - start - end}행. 원문 전체 비교에서 확인하세요.`;
}

async function openWorshipConflictReview(serviceId) {
  if (worshipConflictReview || !serviceId) return;
  const service = state.services.find(candidate => candidate.id === serviceId);
  if (!service) return;
  const draft = worshipConflictDraft(serviceId);
  const serviceName = [...new Set(cleanList([
    serviceDisplayTypeName(service),
    serviceAlias(service),
    service.title,
  ]))].join(" · ") || "선택한 예배";
  const serviceDate = service?.date || service?.service_date || "";
  const conflictItems = [...new Set(draft.pendingInputs.map(input => {
    const item = draft.items[Number(input.index)] || {};
    return String(item.label || item.raw_title || input.itemId || "편집 항목").trim();
  }).filter(Boolean))];
  const itemSummary = conflictItems.length
    ? `${conflictItems.slice(0, 2).join(", ")}${conflictItems.length > 2 ? ` 외 ${conflictItems.length - 2}개` : ""}`
    : "예배 원문과 순서 구성";
  const detectedAt = new Intl.DateTimeFormat("ko-KR", {
    month: "long", day: "numeric", hour: "2-digit", minute: "2-digit",
  }).format(new Date());
  const previousFocus = document.activeElement;
  const dialog = document.createElement("dialog");
  dialog.className = "worship-conflict-dialog";
  dialog.innerHTML = `
    <header class="worship-conflict-header">
      <div>
        <p class="worship-conflict-kicker">저장 충돌</p>
        <h2>서버에 새 저장본이 있습니다</h2>
      </div>
      <button class="icon-btn" type="button" data-conflict-close aria-label="닫기" title="닫기"><i data-lucide="x"></i></button>
    </header>
    <section class="worship-conflict-summary" aria-label="저장 충돌 요약">
      <dl class="worship-conflict-facts">
        <div><dt>예배</dt><dd>${escapeHtml(serviceName)}${serviceDate ? `<small>${escapeHtml(formatServiceDate({date:serviceDate}))}</small>` : ""}</dd></div>
        <div><dt>내 편집 항목</dt><dd data-conflict-items>${escapeHtml(itemSummary)}</dd></div>
        <div><dt>확인 시각</dt><dd>${escapeHtml(detectedAt)}</dd></div>
      </dl>
      <div class="worship-conflict-server-change" data-conflict-server-change>
        <strong>서버 변경 요약</strong>
        <span data-conflict-server-summary>최신 저장본을 확인하고 있습니다.</span>
      </div>
    </section>
    <p class="worship-conflict-caution" role="status" data-conflict-status>내 입력은 이 기기에 그대로 유지됩니다. 자동 병합하거나 서버 내용을 덮어쓰지 않습니다.</p>
    <p class="worship-conflict-choice-help">편집 계속하기는 저장하지 않고 창을 닫습니다. 최신본을 열면 내 초안은 원문의 서버 복구본에 보관됩니다.</p>
    <details class="worship-conflict-details">
      <summary>원문 전체 비교</summary>
      <p>내 입력과 최신 서버 원문을 확인한 뒤 선택하세요.</p>
      <div class="worship-conflict-columns">
        <label>내 입력<textarea readonly aria-label="내 입력"></textarea></label>
        <label>최신 서버 원문<textarea readonly aria-label="최신 서버 원문"></textarea></label>
      </div>
      <label data-conflict-pending hidden>저장 직전에 입력한 내용<textarea readonly aria-label="미반영 입력"></textarea></label>
    </details>
    <footer class="worship-conflict-actions">
      <div>
        <button class="btn secondary" type="button" data-conflict-keep>편집 계속하기</button>
        <button class="btn secondary" type="button" data-conflict-retry hidden>최신본 다시 확인</button>
        <button class="btn primary" type="button" data-conflict-reopen disabled>초안 보관 후 최신본 열기</button>
      </div>
    </footer>`;
  dialog.setAttribute("aria-label", "저장 충돌 원문 비교");
  dialog.addEventListener("keydown", event => event.stopPropagation());
  dialog.querySelector('[aria-label="내 입력"]').value = draft.sourceText;
  if (draft.pendingInputs.length) {
    dialog.querySelector('[data-conflict-pending]').hidden = false;
    dialog.querySelector('[aria-label="미반영 입력"]').value = draft.pendingInputs
      .map(input => `${input.itemId || input.index} · ${input.field}\n${input.value}`).join('\n\n');
  }
  let review = {serviceId, draft};
  const reopen = dialog.querySelector('[data-conflict-reopen]');
  const keep = dialog.querySelector('[data-conflict-keep]');
  const setChoiceBusy = (busy) => {
    keep.disabled = busy;
    reopen.disabled = busy;
  };
  keep.addEventListener("click", async () => {
    setChoiceBusy(true);
    let serverSnapshotPreserved = true;
    try {
      if (review.latest) await preserveWorshipConflictServerSnapshot(review);
      else serverSnapshotPreserved = false;
    } catch (error) {
      serverSnapshotPreserved = false;
    }
    dialog.close();
    showToast(toastLines(
      "편집을 계속합니다. 아직 저장하지 않았습니다.",
      serverSnapshotPreserved
        ? "서버 최신본은 별도 보관본으로 남겼습니다."
        : "서버 최신본 복구본은 보관하지 못했지만, 현재 입력은 그대로 유지됩니다.",
    ), "info");
  });
  reopen.addEventListener('click', async () => {
    setChoiceBusy(true);
    try {
      await reopenWorshipConflict(review, () => dialog.isConnected && dialog.open);
    } catch (error) {
      const messages = {
        REVIEW_OUTDATED:'서버 내용이 다시 변경됐습니다. 닫고 다시 비교해 주세요.',
        LOCAL_DRAFT_CHANGED:'내 입력이 변경됐습니다. 닫고 다시 비교해 주세요.',
        DRAFT_NOT_PRESERVED:'내 입력을 보관하지 못해 최신본으로 전환하지 않았습니다. 현재 입력은 그대로 유지됩니다.',
        PENDING_REQUEST_REQUIRES_RESOLUTION:'이전 저장 결과를 먼저 확인해야 합니다. 내 입력을 유지합니다.',
        SERVICE_NOT_FOUND:'서버에서 삭제된 예배입니다. 내 입력을 유지합니다.',
      };
      if (dialog.isConnected) {
        dialog.querySelector('[data-conflict-status]').textContent = messages[error.message] || '최신본 전환에 실패했습니다. 내 입력은 유지됩니다.';
        keep.disabled = false;
        reopen.disabled = !review.latest || Boolean(review.pending);
      }
      return;
    }
    dialog.close();
    renderServiceList();
    renderCurrentServiceModuleDetail();
    finishServiceSaveDirtyState(true);
    updateSaveState();
    showToast(toastLines(
      "최신본을 열었습니다.",
      "기존 입력은 별도 보관본으로 남겼습니다.",
    ), "info");
  });
  worshipConflictReview = dialog;
  const close = () => dialog.close();
  dialog.querySelectorAll("[data-conflict-close]").forEach(button => button.addEventListener("click", close));
  dialog.addEventListener("close", () => {
    dialog.remove();
    if (worshipConflictReview === dialog) worshipConflictReview = null;
    if (previousFocus?.isConnected) previousFocus.focus();
  }, {once:true});
  document.body.append(dialog);
  dialog.showModal();
  dialog.querySelector("[data-conflict-close]").focus();
  if (window.lucide) window.lucide.createIcons({root:dialog});
  const retry = dialog.querySelector('[data-conflict-retry]');
  const loadLatest = async () => {
    retry.hidden = true;
    reopen.disabled = true;
    dialog.querySelector('[data-conflict-server-summary]').textContent = '최신 저장본을 확인하고 있습니다.';
    try {
      const atomic = await worshipAtomicClient();
      review = await atomic.inspectConflict(serviceId, draft);
      if (!dialog.isConnected || !dialog.open) return;
      const latest = review.latest;
      keep.disabled = false;
      retry.hidden = !review.pending;
      reopen.disabled = !latest || Boolean(review.pending);
      const serverText = latest?.service?.source_ref?.mindexServiceDocument?.sourceText || "";
      dialog.querySelector('[aria-label="최신 서버 원문"]').value = serverText;

      dialog.querySelector("[data-conflict-server-summary]").textContent = latest
        ? worshipConflictTextSummary(draft.sourceText, serverText)
        : "서버에서 이 예배를 찾지 못했습니다.";
      dialog.querySelector("[data-conflict-status]").textContent = review.pending
        ? "이전 저장 결과가 아직 확정되지 않았습니다. 내 입력은 유지되며, 결과 확인 전 최신본 전환은 잠겨 있습니다."
        : latest
        ? "내 입력은 아직 저장되지 않았습니다. 아래 원문을 비교한 뒤 최신본을 열거나 편집을 계속하세요."
        : "내 입력은 유지됩니다. 서버에서 삭제된 예배이므로 최신본으로 전환할 수 없습니다.";
    } catch (error) {
      if (dialog.isConnected && dialog.open) {
        dialog.querySelector("[data-conflict-server-summary]").textContent = "서버 변경 내용을 불러오지 못했습니다.";
        dialog.querySelector("[data-conflict-status]").textContent = "내 입력은 유지됩니다. 연결을 확인한 뒤 다시 비교해 주세요.";
      }
      retry.hidden = false;
      console.warn("Could not inspect worship save conflict.", error);
    }
  };
  retry.addEventListener('click', () => void loadLatest());
  await loadLatest();
}

async function waitForServiceSave(options, resume, itemId = "") {
  if (!activeServiceSavePromise) {
    const message = "다른 저장이 끝나는 중입니다. 잠시 후 다시 시도해 주세요.";
    if (!options.silent) showToast(message, "error");
    if (options.throwOnError) throw new Error(message);
    return false;
  }
  try {
    const saved = await activeServiceSavePromise;
    itemId = saved?.itemIds?.get(itemId) || itemId;
  } catch (_error) {
    // The failed save reported its error; resume against the latest draft.
  }
  return resume(itemId);
}

function emitMonitorSaveEvent(kind) {
  try { window.dispatchEvent(new CustomEvent("mindex:save-result", { detail: kind })); }
  catch { /* Diagnostics must never affect persistence. */ }
}

async function runServiceSave(options, save) {
  emitMonitorSaveEvent("save_start");
  const feedback = beginServiceInputFeedback(options.feedbackServiceId, options.feedbackItemId);
  state.saving = true;
  updateSaveState();
  const savePromise = (async () => {
    await saveDirtyServiceTypes();
    return save();
  })();
  activeServiceSavePromise = savePromise;
  try {
    const result = await savePromise;
    finishServiceInputFeedback(feedback, Boolean(result));
    emitMonitorSaveEvent(result ? "save_ok" : "save_failed");
    return result;
  } catch (error) {
    finishServiceInputFeedback(feedback, false);
    emitMonitorSaveEvent("save_failed");
    const message = serviceSaveErrorMessage(error);
    console.warn("Worship save failed", { code: error?.code || error?.name || "UNKNOWN_SAVE_ERROR", message });
    // Silent saves suppress success notices, not errors needed to recover a draft.
    showToast(message, "error");
    if (!options.silent && /REVISION_CONFLICT|ATOMIC_(?:RELOAD_REQUIRED|RETRY_COMMITTED_RELOAD_REQUIRED)/.test(String(error?.message || ""))) {
      void openWorshipConflictReview(options.feedbackServiceId).catch(reviewError => console.warn("Could not open conflict review.", reviewError));
    }
    if (options.throwOnError) throw new Error(message);
    return false;
  } finally {
    if (activeServiceSavePromise === savePromise) activeServiceSavePromise = null;
    state.saving = false;
    updateSaveState();
  }
}

async function saveService(serviceId = state.selectedServiceId, options = {}) {
  if (!requireClient()) return false;
  if (state.saving) return waitForServiceSave(options, () => saveService(serviceId, options));
  commitActiveDeferredServiceTextInput(serviceId);
  const sourceTextHadPendingChanges = serviceSourceTextHasPendingChanges(serviceSourceTextareaForService(serviceId));
  const sourceTextApplied = applyPendingServiceSourceTextBeforeSave(serviceId);
  if (sourceTextHadPendingChanges && !sourceTextApplied) {
    const message = serviceSourceTextareaForService(serviceId)?.dataset.serviceSourceValidationError
      || "예배 원문에서 반영할 항목을 찾지 못해 저장하지 않았습니다. 원문 항목 이름을 확인해 주세요.";
    if (!options.silent) showToast(message, "error");
    if (options.throwOnError) throw new Error(message);
    return false;
  }

  const service = state.services.find((svc) => svc.id === serviceId);
  const inputProblem = service ? serviceInputSaveProblem(service) : null;
  if (inputProblem) {
    showToast(inputProblem, "error");
    if (options.throwOnError) throw new Error(inputProblem);
    return false;
  }

  return Boolean(await runServiceSave({ ...options, feedbackServiceId: serviceId }, async () => {
    const scriptureSaveSnapshot = JSON.stringify(getServiceItems(serviceId));
    for (const item of getServiceItems(serviceId)) await validateServiceItemScriptureInput(item);
    if (scriptureSaveSnapshot !== JSON.stringify(getServiceItems(serviceId))) throw new Error("예배 입력이 변경되었습니다. 다시 저장해 주세요.");
    let saved = { unchanged: true };
    if (service && !service._isExpected) {
      saved = await saveWorshipServiceInstance(service);
    }
    const unchanged = saved?.unchanged !== false;
    if (unchanged) {
      state.dirtyServiceElementIds.delete(serviceId);
      state.dirtyServiceStructureIds.delete(serviceId);
    }
    finishServiceSaveDirtyState(unchanged);
    if (!options.silent) showToast("예배를 저장했습니다.");
    // Field-level commits already refreshed the affected presenter content. Avoid
    // rebuilding the whole application after a small inline edit.
    // Native board/attachment players belong to this DOM. Replacing the detail
    // pane after a save would stop them even though their source did not change.
    const playingInlineAudio = [...(refs.detailPane?.querySelectorAll("audio") || [])]
      .some((audio) => !audio.paused && !audio.ended);
    if (unchanged && !serviceHasPendingTextEdits(serviceId) && options.renderAfterSave !== false
      && !playingInlineAudio) render();
    else renderServiceList();
    return { itemIds: saved?.itemIds };
  }));
}

async function saveDirtyServiceTypes() {
  if (!state.dirtyServiceTypeIds.size || !state.client) return;
  const types = [...state.dirtyServiceTypeIds]
    .map((typeId) => serviceTypeById(typeId))
    .filter(Boolean);
  for (const type of types) {
    const configRest = type._worshipConfig && typeof type._worshipConfig === "object" ? { ...type._worshipConfig } : {};
    delete configRest.orderTemplate;
    delete configRest.order_template;
    delete configRest.fixedItems;
    delete configRest.fixed_items;
    const payload = {
      display_name: type.name || type.id,
      short_name: type.short_name || type.name || type.id,
      group_key: type._worshipGroupKey || serviceTypeGroupKey(type.id),
      sort_order: Number(type.sort_order) || serviceTypeSortOrder(type.id),
      default_output_context: type._worshipOutputContext || "auto",
      chromakey_enabled: Boolean(type._worshipChromakey),
      config: {
        ...configRest,
        fixedItems: serializeServiceDefaultItems(type.id),
      },
    };
    const { error } = await state.client
      .from("mindex_worship_service_types")
      .update(payload)
      .eq("id", type._worshipId || canonicalWorshipServiceTypeId(type.id));
    if (error) throw error;
    window.MINDEX_CONTENT_LIVE?.publish("service-settings", "all");
  }
  state.dirtyServiceTypeIds.clear();
}

async function worshipElementTypedStateColumns() {
  return {
    inputMode: await detectTableColumnSupport("mindex_worship_elements", "input_mode"),
    contentState: await detectTableColumnSupport("mindex_worship_elements", "content_state"),
  };
}

async function saveWorshipServiceInstance(service) {
  const serviceId = service.id;
  await ensureWorshipServiceRowsLoadedForPersistence(serviceId);
  await requireFullServiceSourceRef(serviceId);
  const inputSignature = JSON.stringify(getServiceItems(serviceId));
  const metadataSignature = serviceSaveMetadataSignature(service);
  await captureWorshipRecoverySnapshot(service, "before-full-save");
  const canonicalTypeId = canonicalWorshipServiceTypeId(service.type_id);
  const worshipLeader = "";
  const praiseLeader = serviceUsesPraiseLeader(service.type_id)
    ? cleanServiceAssignee(service.praiseLeader || service.leader)
    : "";
  const items = ensureUniqueServiceItemPersistenceIds(collapseLegacyPresenterCitationItems(
    normalizeServiceItemsForTemplateHierarchy(
      service,
      normalizeServiceItemsInCurrentOrder(getServiceItems(serviceId)),
    ),
  )).filter((item) => !isUnmodifiedTemplatePlaceholder(item));
  let sourceRef;
  const servicePayload = {
    service_type_id: canonicalTypeId,
    service_date: service.date,
    service_date_end: service.date_end || null,
    title: normalizeWorshipServiceTitle(service.title || "", service),
    status: service._worshipStatus || "draft",
    worship_leader: worshipLeader,
    praise_leader: praiseLeader,
    notes: service.raw_text || "",
  };
  if (state.serviceAliasSupported) servicePayload.service_alias = String(service.alias || "").trim();

  const existingSections = state.worshipSections.filter((section) => section.service_id === serviceId);
  const existingElements = state.worshipElements.filter((element) =>
    existingSections.some((section) => section.id === element.section_id));
  const existingSectionById = Object.fromEntries(existingSections.map((section) => [section.id, section]));
  const existingElementById = Object.fromEntries(existingElements.map((element) => [element.id, element]));
  const elementTypedStateColumns = await worshipElementTypedStateColumns();
  const rows = buildWorshipPersistenceRows(service, items, existingSectionById, existingElementById, {
    elementTypedStateColumns,
    singleSongCatalog: state.singleSongCatalog, singleSongStorage: state.singleSongStorage,
  });
  const savedIdentities = new Map(items.map((item, index) => [item.id, {
    id: rows.elements[index].id,
    sectionId: rows.elements[index].section_id,
    sectionKey: item._worshipSectionKey,
  }]));
  const suppressedItems = [...state.templateElementSuppressions.values()]
    .filter((item) => item?.service_id === serviceId);
  const suppressedIds = state.templateElementSuppressions;
  const suppressedElements = existingElements.filter((element) =>
    suppressedIds.has(element.id) || Boolean(element.config?.templateSuppressed || element.config?.template_suppressed));
  const suppressedSectionIds = new Set(suppressedElements.map((element) => element.section_id));
  suppressedElements.forEach((element) => {
    if (rows.elements.some((row) => row.id === element.id)) return;
    rows.elements.push({
      ...element,
      template_modified: true,
      config: { ...(element.config || {}), templateSuppressed: true },
    });
  });
  existingSections
    .filter((section) => suppressedSectionIds.has(section.id) && !rows.sections.some((row) => row.id === section.id))
    .forEach((section) => rows.sections.push(section));

  // A projected item has no database row yet. Persist a suppression marker so a
  // deliberate delete still survives the next template projection.
  const virtualSuppressedItems = suppressedItems
    .filter((item) => !existingElementById[item.id])
    .map((item) => ({
      ...item,
      memo: serializeServiceItemMemo({ ...parseServiceItemMemo(item.memo), templateSuppressed: true }),
      _worshipElementTemplateModified: true,
    }));
  if (virtualSuppressedItems.length) {
    const virtualRows = buildWorshipPersistenceRows(
      service,
      virtualSuppressedItems,
      existingSectionById,
      existingElementById,
      { elementTypedStateColumns, singleSongCatalog: state.singleSongCatalog, singleSongStorage: state.singleSongStorage },
    );
    virtualRows.sections.forEach((section) => {
      if (!rows.sections.some((row) => row.id === section.id)) rows.sections.push(section);
    });
    virtualRows.elements.forEach((element) => {
      if (!rows.elements.some((row) => row.id === element.id)) rows.elements.push(element);
    });
  }

  sanitizeWorshipPersistenceRows(rows, { elementTypedStateColumns });
  compactWorshipPersistenceRows(rows);
  preserveExistingWorshipContentRows(rows, existingSections, existingElements);
  removeSupersededWorshipSuppressionRows(rows);
  normalizeWorshipPersistenceSortOrders(rows);
  validateWorshipPersistenceRows(rows, { serviceId });

  const atomic = await worshipAtomicClient();
  const committedItems = groupWorshipElements(rows.sections, rows.elements)[serviceId] || [];
  sourceRef = withServiceDocumentSnapshot(structuredClone(service), committedItems);
  const nextElementIds = new Set(rows.elements.map(element => element.id));
  const nextSectionIds = new Set(rows.sections.map(section => section.id));
  const committed = await atomic.commit({ serviceId, rows,
    metadata: { ...servicePayload, source_ref: sourceRef },
    document: sourceRef[MINDEX_SERVICE_DOCUMENT_SOURCE_REF_KEY],
    deleteElementIds: existingElements.map(row => row.id).filter(id => !nextElementIds.has(id)),
    deleteSectionIds: existingSections.map(row => row.id).filter(id => !nextSectionIds.has(id)),
  });
  rows.sections = committed.sections;
  rows.elements = committed.elements;
  sourceRef = committed.service.source_ref;

  service._worshipSourceRef = sourceRef;
  const unchanged = inputSignature === JSON.stringify(getServiceItems(serviceId))
    && metadataSignature === serviceSaveMetadataSignature(service);
  state.worshipSections = [
    ...state.worshipSections.filter((section) => section.service_id !== serviceId),
    ...rows.sections,
  ];
  const existingSectionIdsForService = new Set(existingSections.map((section) => section.id));
  state.worshipElements = [
    ...state.worshipElements.filter((element) => !existingSectionIdsForService.has(element.section_id)),
    ...rows.elements,
  ];
  suppressedItems.forEach((item) => {
    if (suppressedIds.get(item.id) === item) suppressedIds.delete(item.id);
  });
  if (unchanged) {
    state.serviceItems[serviceId] = projectWorshipServiceItemsFromTemplate(
      service,
      groupWorshipElements(rows.sections, rows.elements)[serviceId] || [],
    );
  } else {
    // Keep newer content, but acknowledge IDs assigned to newly persisted items.
    state.serviceItems[serviceId] = getServiceItems(serviceId).map((item) => {
      const identity = savedIdentities.get(item.id);
      if (!identity) return item;
      return {
        ...item,
        id: identity.id,
        _worshipSectionId: item._worshipSectionKey === identity.sectionKey
          ? identity.sectionId : item._worshipSectionId,
      };
    });
    const dirtyIds = state.dirtyServiceElementIds.get(serviceId);
    if (dirtyIds) state.dirtyServiceElementIds.set(serviceId,
      new Set([...dirtyIds].map((id) => savedIdentities.get(id)?.id || id)));
  }

  await syncSharedSundayContentAfterSave(service, items, {
    elementTypedStateColumns,
    previousItems: groupWorshipElements(existingSections, existingElements)[serviceId] || [],
  });
  refreshPresenterForService(serviceId, { renderControls: !serviceHasPendingTextEdits(serviceId) });
  return { unchanged, itemIds: new Map([...savedIdentities].map(([id, saved]) => [id, saved.id])) };
}

function serviceSaveMetadataSignature(service) {
  return JSON.stringify([
    service.type_id, service.date, service.date_end, service.title, service.alias,
    service.worshipLeader, service._worshipLeader, service.praiseLeader, service.leader,
    service._worshipStatus, service.raw_text, service._worshipSourceTextDraft,
  ]);
}

function serviceHasPendingTextEdits(serviceId) {
  return serviceSourceTextHasPendingChanges(serviceSourceTextareaForService(serviceId))
    || [...(refs.detailPane?.querySelectorAll("[data-service-item-field]") || [])]
    .some((field) => (field.dataset.serviceId || state.selectedServiceId) === serviceId
      && isDeferredServiceTextInput(field)
      && field.dataset.initialValue !== undefined
      && field.value !== field.dataset.initialValue);
}

function finishServiceSaveDirtyState(unchanged) {
  state.dirty.service = !unchanged || state.dirtyServiceElementIds.size > 0
    || state.dirtyServiceStructureIds.size > 0 || state.dirtyServiceTypeIds.size > 0
    || serviceHasPendingTextEdits(state.selectedServiceId);
  if (!state.dirty.service) captureCleanFingerprint("service");
}

async function saveServiceItemPatch(serviceId = state.selectedServiceId, index = -1, options = {}) {
  if (!requireClient()) return false;
  const itemId = options._itemId || getServiceItems(serviceId)[Number(index)]?.id;
  if (!itemId) return false;
  if (state.saving) {
    return waitForServiceSave(options,
      (id) => saveServiceItemPatch(serviceId, index, { ...options, _itemId: id }), itemId);
  }

  const service = state.services.find((candidate) => candidate.id === serviceId);
  const item = getServiceItems(serviceId).find((candidate) => candidate.id === itemId);
  if (!service || !item || service._isExpected) return false;
  if (!isUuid(item.id) || state.dirtyServiceStructureIds.has(serviceId)) {
    return saveService(serviceId, options);
  }

  let needsFullSave = false;
  const result = await runServiceSave({ ...options, feedbackServiceId: serviceId, feedbackItemId: itemId }, async () => {
    const scriptureSaveSnapshot = JSON.stringify(item);
    await validateServiceItemScriptureInput(item);
    if (scriptureSaveSnapshot !== JSON.stringify(getServiceItems(serviceId).find(candidate => candidate.id === itemId))) throw new Error("예배 입력이 변경되었습니다. 다시 저장해 주세요.");
    const saved = await saveWorshipServiceElementPatch(service, item.id);
    if (!saved) {
      needsFullSave = true;
      return false;
    }
    if (saved.unchanged) clearServiceElementDirty(serviceId, item);
    finishServiceSaveDirtyState(saved.unchanged);
    if (!options.silent) showToast("항목을 저장했습니다.");
    // The active editor already owns the saved value and the presenter has
    // refreshed incrementally. Avoid rebuilding the full detail pane after a
    // blur-save, which otherwise displaces focus and scroll in long boards.
    renderServiceList();
    return saved;
  });
  if (needsFullSave) return saveService(serviceId, options);
  return Boolean(result);
}

async function saveServiceItemMutation(serviceId = state.selectedServiceId, index = -1, options = {}) {
  const saved = await saveServiceItemPatch(serviceId, index, options);
  if (saved) return true;
  return saveService(serviceId, options);
}

async function saveWorshipServiceElementPatch(service, itemId) {
  const serviceId = service?.id || "";
  const targetItemId = String(itemId || "").trim();
  if (!serviceId || !targetItemId) return false;
  await ensureWorshipServiceRowsLoadedForPersistence(serviceId);
  await requireFullServiceSourceRef(serviceId);

  const inputItem = getServiceItems(serviceId).find((item) => item.id === targetItemId);
  const inputSignature = JSON.stringify(inputItem);
  const existingSections = state.worshipSections.filter((section) => section.service_id === serviceId);
  const existingElements = state.worshipElements.filter((element) =>
    existingSections.some((section) => section.id === element.section_id));
  const existingSectionById = Object.fromEntries(existingSections.map((section) => [section.id, section]));
  const existingElementById = Object.fromEntries(existingElements.map((element) => [element.id, element]));
  const items = ensureUniqueServiceItemPersistenceIds(normalizeServiceItemsForTemplateHierarchy(
    service,
    normalizeServiceItemsInCurrentOrder(structuredClone(getServiceItems(serviceId))),
  )).filter((item) => !isUnmodifiedTemplatePlaceholder(item));
  if (!items.some((item) => item.id === targetItemId)) return false;
  const documentService = structuredClone(service);

  const elementTypedStateColumns = await worshipElementTypedStateColumns();
  const rows = buildWorshipPersistenceRows(service, items, existingSectionById, existingElementById, {
    elementTypedStateColumns,
    singleSongCatalog: state.singleSongCatalog, singleSongStorage: state.singleSongStorage,
    targetElementId: targetItemId,
  });
  sanitizeWorshipPersistenceRows(rows, { elementTypedStateColumns });
  compactWorshipPersistenceRows(rows);
  validateWorshipPersistenceRows(rows, { serviceId });

  let elementRow = rows.elements.find((element) => element.id === targetItemId);
  if (!elementRow) return false;
  let sectionRow = existingSectionById[elementRow.section_id]
    || rows.sections.find((section) => section.id === elementRow.section_id);
  await captureWorshipRecoverySnapshot(service, "before-element-patch");
  const committedSections = sectionRow
    ? [...existingSections.filter(section => section.id !== sectionRow.id), sectionRow] : existingSections;
  const committedElements = [...existingElements.filter(element => element.id !== elementRow.id), elementRow];
  const committedItems = groupWorshipElements(committedSections, committedElements)[serviceId] || [];
  const previousItems = groupWorshipElements(existingSections, existingElements)[serviceId] || [];
  const previousItem = previousItems.find(item => item.id === targetItemId);
  const committedItem = committedItems.find(item => item.id === targetItemId);
  const previousDocument = serviceDocumentSnapshotFromRef(documentService);
  delete documentService._worshipSourceTextDraft;
  // A legacy truncated snapshot cannot supply a complete patch range. Rebuild from
  // committed canonical rows (including only this item edit, never sibling drafts).
  if (previousDocument?.sourceText && !previousDocument.sourceText.endsWith("\n[truncated]") && previousItem && committedItem) {
    documentService._worshipSourceTextDraft = sundayEditSyncSourceText(previousDocument, previousItem, committedItem, documentService);
  }
  let sourceRef = withServiceDocumentSnapshot(documentService, committedItems);
  const atomic = await worshipAtomicClient();
  const committed = await atomic.commit({ serviceId,
    rows: { sections: sectionRow ? [sectionRow] : [], elements: [elementRow] },
    document: sourceRef[MINDEX_SERVICE_DOCUMENT_SOURCE_REF_KEY],
  });
  elementRow = committed.elements.find(row => row.id === targetItemId);
  sectionRow = committed.sections.find(row => row.id === elementRow.section_id);
  sourceRef = committed.service.source_ref;
  service._worshipSourceRef = sourceRef;

  const currentItems = getServiceItems(serviceId);
  const unchanged = inputSignature === JSON.stringify(currentItems.find((item) => item.id === targetItemId));
  if (sectionRow) {
    state.worshipSections = [
      ...state.worshipSections.filter((section) => section.id !== sectionRow.id),
      sectionRow,
    ];
  }
  state.worshipElements = [
    ...state.worshipElements.filter((element) => element.id !== elementRow.id),
    elementRow,
  ];
  // A patch acknowledges one item, never the other items' unsaved drafts.
  const savedItem = (groupWorshipElements(
    state.worshipSections.filter((section) => section.service_id === serviceId),
    state.worshipElements,
  )[serviceId] || []).find((item) => item.id === targetItemId);
  state.serviceItems[serviceId] = currentItems.map((item) =>
    unchanged && savedItem && item.id === targetItemId
      ? {
        ...savedItem,
        // Non-template services sort directly by this editor ordinal.
        sort_order: item.sort_order,
        // A single receipt uses compact persisted ordinals, while sibling drafts
        // can still use spaced editor ordinals. Keep one ordering scale until
        // the whole collection is reloaded; otherwise projection moves this row.
        _worshipSectionOrder: item._worshipSectionOrder,
        _worshipElementOrder: item._worshipElementOrder,
      }
      : item);
  await syncSharedSundayContentAfterSave(
    service,
    items.filter((item) => item.id === targetItemId),
    {
      elementTypedStateColumns,
      previousItems: groupWorshipElements(existingSections, existingElements)[serviceId] || [],
    },
  );
  refreshPresenterForService(serviceId, { renderControls: !serviceHasPendingTextEdits(serviceId) });
  return { unchanged };
}

async function syncSharedSundayContentAfterSave(sourceService, sourceItems = [], options = {}) {
  const previousItems = options.previousItems || [];
  const persistedItems = groupWorshipElements(
    state.worshipSections.filter((section) => section.service_id === sourceService.id), state.worshipElements,
  )[sourceService.id] || [];
  for (const item of sourceItems) {
    if (!item._worshipSharedContentDirty && !state.dirtyServiceElementIds.get(sourceService.id)?.has(item.id)) continue;
    const key = sundaySharedContentKey(item, sourceService);
    const persisted = persistedItems.filter((candidate) => sundaySharedContentKey(candidate, sourceService) === key);
    if (persisted.length > 1) continue;
    const savedItem = persisted[0] || item;
    const previous = previousItems.filter((candidate) => sundaySharedContentKey(candidate, sourceService) === key);
    if (previous.length !== 1 || !sundayEditSyncEligible(savedItem, sourceService)
      || !sundayEditSyncEligible(previous[0], sourceService)
      || sundayEditSyncSignature(previous[0]) === sundayEditSyncSignature(savedItem)) continue;
    // Decide the scope from the persisted item, not the editor's stale object.
    // This keeps a cleared or retyped 1st-service item from inheriting an old
    // shared-content classification during the follow-up sync.
    const types = sundaySharedContentTypesForItem(savedItem, sourceService);
    if (!types.length) continue;
    for (const target of state.services.filter((service) => service.id !== sourceService.id
      && service.date === sourceService.date && types.includes(worshipAppServiceTypeId(service.type_id)))) {
      const jobKey = `${sourceService.id}:${target.id}:${key}`;
      const pending = pendingSundayEditSync.get(jobKey);
      pendingSundayEditSync.set(jobKey, {
        sourceServiceId: sourceService.id, targetId: target.id, key,
        // Retry records never need arbitrary element payloads. Keeping this
        // compact also avoids oversized server recovery records blocking a
        // live first/second-service sync.
        previous: sundayEditSyncItemSnapshot(previous[0]),
        item: sundayEditSyncItemSnapshot(savedItem),
        previousSignatures: uniqueList([...(pending?.previousSignatures || []),
          ...(pending ? [sundayEditSyncSignature(pending.previous), sundayEditSyncSignature(pending.item)] : [])]),
      });
    }
  }
  const failures = [];
  let retryRecordPersisted = await persistPendingSundayEditSync();
  for (const [jobKey, job] of pendingSundayEditSync) {
    const jobSource = state.services.find((service) => service.id === job.sourceServiceId);
    const jobTarget = state.services.find((service) => service.id === job.targetId);
    const targetTypeId = worshipAppServiceTypeId(jobTarget?.type_id);
    const jobTypes = sundaySharedContentTypesForItem(job.item, jobSource);
    // Rules can become narrower after an old retry was saved locally. Drop
    // those obsolete jobs instead of surfacing a false linked-service error.
    if (!jobSource || !jobTarget || !sundayEditSyncEligible(job.item, jobSource) || !jobTypes.includes(targetTypeId)) {
      pendingSundayEditSync.delete(jobKey);
      retryRecordPersisted = await persistPendingSundayEditSync() && retryRecordPersisted;
      continue;
    }
    if (job.sourceServiceId !== sourceService.id) continue;
    const savedSourceItems = groupWorshipElements(
      state.worshipSections.filter((section) => section.service_id === sourceService.id),
      state.worshipElements,
    )[sourceService.id] || [];
    const savedSource = savedSourceItems.filter((item) => sundaySharedContentKey(item, jobSource) === job.key);
    if (savedSource.length !== 1 || !sundayEditSyncEligible(savedSource[0], jobSource)
      || sundayEditSyncSignature(savedSource[0]) !== sundayEditSyncSignature(job.item)) {
      pendingSundayEditSync.delete(jobKey);
      retryRecordPersisted = await persistPendingSundayEditSync() && retryRecordPersisted;
      failures.push(`${job.item.label}: 원본이 바뀌어 이전 동기화 요청을 취소했습니다.`);
      continue;
    }
    try {
      await persistSundayEditSync(job, options);
      pendingSundayEditSync.delete(jobKey);
      retryRecordPersisted = await persistPendingSundayEditSync() && retryRecordPersisted;
    } catch (error) {
      failures.push(error.message || "연결 예배 저장 실패");
    }
  }
  if (failures.length) {
    const retryNote = retryRecordPersisted ? "" : " 서버에 재시도 기록을 보관하지 못했으니 화면을 닫기 전에 다시 저장해 주세요.";
    const message = `현재 예배는 저장됐지만 연결 예배 반영은 완료되지 않았습니다. ${uniqueList(failures).join(" / ")}${retryNote}`;
    showToast(message, "error");
    throw new Error(message);
  }
}

const SUNDAY_EDIT_SYNC_STORAGE_KEY = "mindex.worship.edit-sync.v1";
const pendingSundayEditSync = readPendingSundayEditSync();

function readPendingSundayEditSync() {
  try {
    const entries = JSON.parse(safeStorageGet("local", SUNDAY_EDIT_SYNC_STORAGE_KEY, "[]"));
    return new Map(Array.isArray(entries) ? entries.filter((entry) => Array.isArray(entry)
      && entry.length === 2 && entry[1]?.sourceServiceId && entry[1]?.targetId
      && entry[1]?.previous && entry[1]?.item) : []);
  } catch { return new Map(); }
}

function sundayEditSyncItemSnapshot(item = {}) {
  const memo = parseServiceItemMemo(item?.memo);
  const content = sundayEditSyncContent(item);
  const snapshotMemo = {
    elementType: serviceMemoElementType(memo),
    inputMode: content.inputMode || memo.inputMode || "",
  };
  if (Object.hasOwn(content, "references")) {
    snapshotMemo.scriptureReference = content.references[0] || "";
    snapshotMemo.scriptureReferences = content.references;
    snapshotMemo.scriptureReferencePayloads = content.payloads;
  } else if (Object.hasOwn(content, "song")) {
    Object.assign(snapshotMemo, {
      formHint: content.formHint,
      formPreset: content.formPreset,
      formPresetDisabled: content.formPresetDisabled,
      formPresetRules: content.formPresetRules,
      slides: content.slides,
      outputMode: memo.outputMode || "",
    });
  }
  return {
    id: String(item?.id || ""),
    label: String(item?.label || ""),
    raw_title: String(item?.raw_title || ""),
    assignee: String(item?.assignee || ""),
    song_id: item?.song_id || null,
    version_id: item?.version_id || item?.song_version_id || null,
    song_version_id: item?.song_version_id || item?.version_id || null,
    _worshipSectionKey: String(item?._worshipSectionKey || item?.section_key || ""),
    _worshipSectionTitle: String(item?._worshipSectionTitle || item?.section_title || ""),
    _worshipSlotKey: normalizeWorshipSlotKey(item?._worshipSlotKey || item?.slot_key || item?.source_ref?.slotKey),
    memo: serializeServiceItemMemo(snapshotMemo),
  };
}

async function persistPendingSundayEditSync() {
  return persistServerValue("local", SUNDAY_EDIT_SYNC_STORAGE_KEY,
    pendingSundayEditSync.size ? JSON.stringify([...pendingSundayEditSync]) : null);
}

function sundayEditSyncEligible(item = {}, service = null) {
  if (!worshipServiceParticipatesInSharedSundayContent(service, item)) return false;
  const memo = parseServiceItemMemo(item.memo);
  if (memo.asset?.url || memo.templateSuppressed || memo.hiddenInPresentation
    || (memo.slides || []).some((slide) => slide && typeof slide === "object")) return false;
  const key = sundaySharedContentKey(item, service);
  const label = compactSearchValue(item.label || "");
  const type = serviceMemoElementType(memo);
  if (key === "main-praise:3" && worshipAppServiceTypeId(service?.type_id) === "sunday-main") {
    return label === "찬송" && type === "praise" && !isAllGenerationsWorshipService(service);
  }
  if (key.startsWith("main-praise:")) return /^찬양[1-3]$/.test(label) && type === "praise";
  if (key === "offering-hymn") return label === "봉헌찬송" && type === "praise";
  if (key === "sermon-title") return ["설교", "설교제목"].includes(label) && ["title_person", "title_assignee"].includes(type);
  if (key === "scripture-reading") return label === "성경봉독" && type === "scripture_body";
  if (key === "sermon-scripture") return label === "설교본문" && type === "scripture_body";
  return key === "sermon-citation" && /^인용구절\d*$/.test(label) && type === "scripture_body";
}

function sundayEditSyncContent(item = {}) {
  const key = sundaySharedContentKey(item);
  const memo = parseServiceItemMemo(item.memo);
  if (key === "sermon-title") return { title: item.raw_title || "", assignee: item.assignee || "" };
  if (["scripture-reading", "sermon-scripture", "sermon-citation"].includes(key)) {
    return { references: serviceItemDirectScriptureReferences(item, memo), payloads: memo.scriptureReferencePayloads || [] };
  }
  return {
    song: item.song_id || "", version: item.version_id || item.song_version_id || "",
    inputMode: memo.inputMode || "",
    title: item.raw_title || "", formHint: memo.formHint || "", formPreset: memo.formPreset || null,
    formPresetDisabled: Boolean(memo.formPresetDisabled), formPresetRules: memo.formPresetRules || [],
    slides: item.song_id ? [] : memo.slides || [],
  };
}

function sundayEditSyncComparableContent(content) {
  // DB song selection is shared; score/lyrics presentation is local to each service.
  return ["score_db", "lyrics_db"].includes(content.inputMode)
    ? { ...content, inputMode: "linked-song" } : content;
}

function sundayEditSyncSignature(item) {
  return JSON.stringify(sundayEditSyncComparableContent(sundayEditSyncContent(item)));
}

function sundayEditSyncPreviousSignatureMatches(signature, item) {
  try {
    return JSON.stringify(sundayEditSyncComparableContent(JSON.parse(signature))) === sundayEditSyncSignature(item);
  } catch { return false; }
}

function applySundayEditSync(target, source, { preserveExistingForm = false } = {}) {
  const content = sundayEditSyncContent(source);
  const next = { ...target, _worshipElementTemplateModified: true, _worshipTemplatePlaceholder: false };
  const memo = parseServiceItemMemo(target.memo);
  if (Object.hasOwn(content, "references")) {
    next.raw_title = source.raw_title || "";
    next.memo = serializeServiceItemMemo({ ...memo, scriptureReference: content.references[0] || "",
      scriptureReferences: content.references, scriptureReferencePayloads: content.payloads, slides: [] });
  } else if (Object.hasOwn(content, "song")) {
    const preserveDisplayMode = ["score_db", "lyrics_db"].includes(content.inputMode)
      && ["score_db", "lyrics_db"].includes(memo.inputMode);
    Object.assign(next, { song_id: content.song || null, version_id: content.version || null,
      song_version_id: content.version || null, raw_title: content.title });
    // A vacant third-service hymn may already have an intentional form choice.
    const keepForm = preserveExistingForm && Boolean(memo.formHint || memo.formPreset
      || memo.formPresetDisabled || memo.formPresetRules?.length);
    const form = keepForm ? {} : { formHint: content.formHint, formPreset: content.formPreset,
      formPresetDisabled: content.formPresetDisabled, formPresetRules: content.formPresetRules };
    next.memo = serializeServiceItemMemo({ ...memo, ...form, slides: content.slides,
      inputMode: preserveDisplayMode ? memo.inputMode : content.inputMode,
      outputMode: preserveDisplayMode || memo.inputMode === content.inputMode ? memo.outputMode : parseServiceItemMemo(source.memo).outputMode });
  } else Object.assign(next, { raw_title: content.title, assignee: content.assignee });
  return next;
}

function sundayEditSyncHasLocalDraft(serviceId) {
  return Boolean(state.dirtyServiceElementIds.get(serviceId)?.size || state.dirtyServiceStructureIds.has(serviceId)
    || presenterControllerIsLive(serviceId)
    || serviceHasPendingTextEdits(serviceId)
    || (state.selectedServiceId === serviceId && state.dirty.service));
}

function sundayEditSyncSourceText(document, item, next, service) {
  const source = String(document.sourceText || "").replace(/\r\n?/g, "\n");
  const portable = /^\s*\[\[[^\]]+\]\]/m.test(source);
  const records = parseServiceSourceText(source, { includeRanges: true });
  const matches = records.filter((record) => serviceSourceLabelsMatch(record.label, item.label));
  const scoped = matches.filter((record) => record.sectionTitle === serviceSourceSectionTitle(item));
  const candidates = scoped.length ? scoped : matches;
  const sourceLines = source.split("\n");
  const appendLines = portable
    ? serviceSourceItemLines(next, service)
    : sundayEditSyncLegacySourceItemLines([], { label: item.label }, next, service);
  if (!candidates.length) {
    const heading = portable ? `[[${serviceSourceSectionTitle(item)}]]` : `[${serviceSourceSectionTitle(item)}]`;
    return `${source.trimEnd()}\n\n${heading}\n${appendLines.join("\n")}`.trim();
  }
  if (candidates.length !== 1) {
    const sameSection = candidates.every(record => record.sectionTitle === candidates[0].sectionTitle);
    const validRanges = candidates.every(record => Number.isInteger(record.startLine) && Number.isInteger(record.endLine)
      && record.startLine >= 0 && record.endLine > record.startLine && record.endLine <= sourceLines.length);
    const blocks = validRanges ? candidates.map(record => sourceLines.slice(record.startLine, record.endLine).join("\n").trimEnd()) : [];
    const liveMatches = getServiceItems(service?.id).filter(candidate =>
      serviceSourceLabelsMatch(candidate.label, item.label)
      && serviceSourceSectionTitle(candidate) === serviceSourceSectionTitle(item));
    if (!sameSection || !validRanges || liveMatches.length !== 1 || !blocks.every(block => block === blocks[0])) {
      throw new Error("연결 예배 원문의 항목 위치가 중복되어 반영하지 않았습니다.");
    }
    // Only identical source copies of one canonical item can be collapsed.
    for (const duplicate of candidates.slice(1).sort((a, b) => b.startLine - a.startLine)) {
      sourceLines.splice(duplicate.startLine, duplicate.endLine - duplicate.startLine);
    }
    return sundayEditSyncSourceText({ ...document, sourceText: sourceLines.join("\n") }, item, next, service);
  }
  const record = candidates[0];
  if (!Number.isInteger(record.startLine) || !Number.isInteger(record.endLine)
    || record.startLine < 0 || record.endLine <= record.startLine || record.endLine > sourceLines.length) {
    throw new Error("연결 예배 원문의 항목 범위를 확인하지 못해 반영하지 않았습니다.");
  }
  const replacementLines = portable
    ? serviceSourceItemLines(next, service)
    : sundayEditSyncLegacySourceItemLines(sourceLines, record, next, service);
  const replacement = replacementLines.join("\n");
  const trailing = sourceLines.slice(record.startLine, record.endLine).reverse().findIndex((line) => line.trim());
  const keepBlankLines = trailing < 0 ? 0 : trailing;
  return [...sourceLines.slice(0, record.startLine), replacement,
    ...Array(keepBlankLines).fill(""), ...sourceLines.slice(record.endLine)].join("\n");
}

function sundayEditSyncLegacySourceItemLines(sourceLines = [], record = {}, next = {}, service = null) {
  const lines = sourceLines.slice(record.startLine, record.endLine);
  const memo = parseServiceItemMemo(next.memo);
  const value = serviceSourceItemValue(next, service, memo);
  const label = String(record.label || next.label || "항목").trim();
  const firstLine = lines[0] || "";
  const firstMatch = firstLine.match(/^(\s*[^:\[\]\n][^:\n]*?):\s*.*$/);
  lines[0] = `${firstMatch ? `${firstMatch[1]}:` : `${label}:`} ${value}`;

  const assignee = serviceItemEditableAssigneeValue(next, service);
  const assigneeIndex = lines.findIndex((line, index) => index > 0 && /^\s{2,}담당\s*:/.test(line));
  if (assigneeIndex >= 0) {
    if (assignee) lines[assigneeIndex] = lines[assigneeIndex].replace(/^(\s{2,}담당\s*:)\s*.*/, `$1 ${assignee}`);
    else lines.splice(assigneeIndex, 1);
  } else if (assignee) {
    lines.splice(1, 0, `  담당: ${assignee}`);
  }
  return lines.filter((line, index) => index < lines.length - 1 || line.trim());
}

function serviceSourceLabelsMatch(left = "", right = "") {
  const normalize = (value) => {
    const key = compactSearchValue(value);
    if (["설교", "설교제목"].includes(key)) return "설교";
    return key;
  };
  return normalize(left) === normalize(right);
}

async function persistSundayEditSync(job, options = {}) {
  const target = state.services.find((service) => service.id === job.targetId);
  if (!target || !worshipServiceParticipatesInSharedSundayContent(target, job.item)) return;
  const label = `${target.date} ${serviceTypeDisplayName(target.type_id)} ${job.item.label}`;
  const conflict = () => new Error(`${label}: 별도 편집·송출 상태 또는 저장 충돌을 확인해 주세요. 덮어쓰지 않았습니다.`);
  if (sundayEditSyncHasLocalDraft(target.id)) throw conflict();
  const atomic = await worshipAtomicClient();
  let serviceRow, sections, elements;
  const aggregate = await atomic.read(target.id);
  serviceRow = aggregate.service;
  sections = aggregate.sections;
  elements = aggregate.elements;
  const freshService = normalizeWorshipService(serviceRow);
  if (freshService.date !== state.services.find((service) => service.id === job.sourceServiceId)?.date
    || freshService.type_id !== target.type_id || !worshipServiceParticipatesInSharedSundayContent(freshService, job.item)) return;
  const items = groupWorshipElements(sections, elements)[target.id] || [];
  if (job.key === "offering-hymn" && allGenerationsHasOfferingReplacement(freshService, items)) return;
  const matches = items.filter((item) => sundaySharedContentKey(item, freshService) === job.key);
  // Never create template placeholders or reinterpret substitute elements as shared content.
  if (!matches.length && job.key === "offering-hymn" && !allGenerationsHasOfferingReplacement(freshService, items)) {
    throw new Error(`${label}: 봉헌찬송 항목이 없습니다. 해당 예배 순서를 확인해 주세요. 다른 항목은 덮어쓰지 않았습니다.`);
  }
  if (matches.length !== 1 || !sundayEditSyncEligible(matches[0], freshService)) return;
  const item = matches[0];
  const emptyThirdHymn = (job.key === "offering-hymn"
    || (job.key === "main-praise:3" && freshService.type_id === "sunday-main"))
    && !item.song_id && !item.version_id && !item.song_version_id
    && !String(item.raw_title || "").trim()
    && !(parseServiceItemMemo(item.memo).slides || []).some(slide => String(slide || "").trim());
  if (!emptyThirdHymn && sundayEditSyncSignature(item) !== sundayEditSyncSignature(job.previous)
    && !(job.previousSignatures || []).some(signature => sundayEditSyncPreviousSignatureMatches(signature, item))
    && sundayEditSyncSignature(item) !== sundayEditSyncSignature(job.item)) throw conflict();
  await loadSongsForIds(uniqueList(items.map((candidate) => candidate.song_id).filter(Boolean)
    .concat(job.item.song_id || []).filter(Boolean)));
  if (sundayEditSyncHasLocalDraft(target.id)) throw conflict();
  const next = applySundayEditSync(item, job.item, { preserveExistingForm: emptyThirdHymn });
  const existing = elements.find((row) => row.id === item.id);
  const typed = options.elementTypedStateColumns || await worshipElementTypedStateColumns();
  const rows = buildWorshipPersistenceRows(freshService, [next],
    Object.fromEntries(sections.map((row) => [row.id, row])), { [existing.id]: existing }, { elementTypedStateColumns: typed, singleSongCatalog: state.singleSongCatalog, singleSongStorage: state.singleSongStorage });
  sanitizeWorshipPersistenceRows(rows, { elementTypedStateColumns: typed });
  compactWorshipPersistenceRows(rows);
  validateWorshipPersistenceRows(rows, { serviceId: target.id });
  const generated = rows.elements[0];
  const fields = ["title", "person", "body", "song_id", "song_version_id", "praise_record_id", "scripture_reference", "config", "content_state", "input_mode", "template_modified"];
  const patch = Object.fromEntries(fields.filter((key) => Object.hasOwn(generated, key)).map((key) => [key, generated[key]]));
  if (job.key === "sermon-citation") {
    patch.source_ref = { ...existing.source_ref };
    delete patch.source_ref.scriptureReferences;
    delete patch.source_ref.scripture_references;
    delete patch.source_ref.scriptureReference;
    delete patch.source_ref.scripture_reference;
  }
  if (next.song_id) patch.song_version_id = next.version_id || next.song_version_id || null;
  patch.updated_at = new Date().toISOString();
  const nextItems = items.map((candidate) => candidate.id === item.id ? next : candidate);
  const previousDocument = serviceDocumentSnapshotFromRef(freshService);
  const sourceText = previousDocument?.sourceText
    ? sundayEditSyncSourceText(previousDocument, item, next, freshService)
    : buildServiceSourceText(freshService, { items: nextItems, ignoreSnapshotFallback: true });
  const documentService = { ...freshService, _worshipSourceTextDraft: sourceText };
  let ref = withServiceDocumentSnapshot(documentService, nextItems);
  let saved = { ...existing, ...patch };
  const committed = await atomic.commit({ serviceId: target.id,
    rows: { sections: [], elements: [saved] },
    document: ref[MINDEX_SERVICE_DOCUMENT_SOURCE_REF_KEY],
  });
  saved = committed.elements.find(row => row.id === existing.id);
  ref = committed.service.source_ref;
  target._worshipSourceRef = ref;
  if (!sundayEditSyncHasLocalDraft(target.id)) {
    const sectionIds = new Set(sections.map((section) => section.id));
    state.worshipSections = [...state.worshipSections.filter((section) => section.service_id !== target.id), ...sections];
    state.worshipElements = [...state.worshipElements.filter((element) => !sectionIds.has(element.section_id)),
      ...elements.map((element) => element.id === saved.id ? saved : element)];
    state.serviceItems[target.id] = projectWorshipServiceItemsFromTemplate(target, nextItems);
    state.loadedWorshipServiceIds.add(target.id);
    refreshPresenterForService(target.id, { publish: false, renderControls: false });
  }
}


async function ensureWorshipServiceRowsLoadedForPersistence(serviceId = "") {
  const id = String(serviceId || "").trim();
  if (!id || !state.client || state.loadedWorshipServiceIds.has(id)) return;
  const previousSectionIds = new Set(
    state.worshipSections
      .filter((section) => section.service_id === id)
      .map((section) => section.id)
      .filter(Boolean),
  );
  const { sections, elements } = await fetchWorshipRowsForServiceIds([id]);
  const loadedSectionIds = new Set([
    ...previousSectionIds,
    ...sections.map((section) => section.id).filter(Boolean),
  ]);
  state.worshipSections = [
    ...state.worshipSections.filter((section) => section.service_id !== id),
    ...sections,
  ];
  state.worshipElements = [
    ...state.worshipElements.filter((element) => !loadedSectionIds.has(element.section_id)),
    ...elements,
  ];
  state.loadedWorshipServiceIds.add(id);
  const loadedService = state.services.find((service) => service.id === id);
  if (loadedService) {
    state.serviceItems[id] = projectWorshipServiceItemsFromTemplate(
      loadedService,
      groupWorshipElements(sections, elements)[id] || [],
    );
  }
}

const praisePendingSaves = new WeakMap();

function praiseSnapshotSong(snapshot) {
  if (!snapshot?.song || !Array.isArray(snapshot.versions) || !Array.isArray(snapshot.units) || !Array.isArray(snapshot.relations)) throw new Error("찬양 최신본을 확인하지 못했습니다. 입력은 유지됩니다.");
  const song = normalizeServerSong(snapshot.song);
  attachRelationalSongVersionRows(snapshot.versions, snapshot.units, [song.id], [song]);
  song.related_song_ids = [...new Set(snapshot.relations.map(row => row.source_song_id === song.id ? row.related_song_id : row.source_song_id))].sort();
  return song;
}

function praiseSaveComparable(song) {
  const fields = ['title','subtitle','original_title','hymn_no','praise_types','metadata','scripture','related_song_ids'];
  const value = Object.fromEntries(fields.map(key => [key, song?.[key] ?? null]));
  value.versions = (song?.versions || []).map(version => ({
    id: version.id, name: version.name, output_title: version.output_title || '',
    is_primary: !!version.is_primary, praise_types: version.praise_types || [],
    subtitle: version.subtitle || null, original_title: version.original_title || null,
    hymn_no: version.hymn_no || null, audio_set: version.audio_set || null,
    version_label:version.version_label||null,raw_section_name:version.raw_section_name||null,
    deck_key:version.deck_key||null,source_count:Number(version.source_count)||1,
    forms: normalizeForms(version.forms || []).map(form => ({id:form.id,part_type:form.part_type,
      part_number:form.part_number,part_variant:form.part_variant||'',label:form.label||'',lyrics:form.lyrics||'',
      review_status:form.review_status||'reviewed'}))
  }));
  return JSON.stringify(dirtyComparableValue(value));
}

function buildPraiseVersionSaveRows(song, versions, canonicalSongId, versionOrders, supportsPraiseTypes) {
  return versions.map((version, index) => ({
    id: version.id,
    canonical_song_id: canonicalSongId,
    source_song_id: song.id,
    version_order: versionOrders.get(version.id) || index + 1,
    version_label: version.raw_section_name || version.version_label || version.name || `Version ${index + 1}`,
    curated_version_name: normalizeGeneratedVersionName(version.name || `Version ${index + 1}`),
    version_review_status: versionNeedsFormReview(song, version) ? "pending" : "reviewed",
    deck_key: nullIfBlank(version.deck_key),
    raw_section_name: nullIfBlank(version.raw_section_name || version.version_label),
    subtitle: nullIfBlank(version.subtitle),
    original_title: nullIfBlank(version.original_title),
    hymn_no: nullIfBlank(version.hymn_no),
    ...(supportsPraiseTypes ? { praise_types: canonicalPraiseTypes(version.praise_types) } : {}),
    lyric_signature: versionLyricSignature(version),
    source_count: Number(version.source_count) > 0 ? Number(version.source_count) : 1,
    is_primary: Boolean(version.is_primary),
  }));
}

async function saveSongVersions(song, { detached = false, planOnly = false } = {}) {
  if (song?._singleSongRecord) throw new Error("SINGLE_SONG_NATIVE_SAVE_REQUIRED");
  if (!song?.id || !state.client) return;

  const canonicalSongId = await ensureCanonicalSongRow(song, {planOnly});
  if (!state.songVersionPraiseTypesSupported) {
    state.songVersionPraiseTypesSupported = await detectSongVersionPraiseTypesSupport();
  }

  const versions = normalizeSongVersions(song, song.versions?.length ? song.versions : [{
    id: createUuid(),
    name: "기본",
    is_primary: true,
    forms: [],
  }]);
  const previousSelectedVersionId = state.selectedVersionId;
  const versionIdMap = new Map();

  for (const version of versions) {
    const oldId = version.id;
    if (!isUuid(version.id)) version.id = createUuid();
    if (oldId && oldId !== version.id) versionIdMap.set(oldId, version.id);
    if (!detached && previousSelectedVersionId === oldId) state.selectedVersionId = version.id;
  }

  if (!detached && versionIdMap.size) {
    for (const form of state.forms) {
      if (versionIdMap.has(form.song_id)) form.song_id = versionIdMap.get(form.song_id);
    }
  }

  song.versions = versions;
  const [existingVersions, existingCanonicalVersions] = await Promise.all([
    fetchExistingSongVersions(song.id),
    fetchExistingCanonicalSongVersions(canonicalSongId),
  ]);
  const retainedVersionIds = new Set(versions.map(version => version.id));
  const approvedDeletes = new Set(song._pendingVersionDeletes || []);
  const deletedVersionIds = existingVersions.map(version => version.id).filter(id => !retainedVersionIds.has(id));
  if (deletedVersionIds.some(id => !approvedDeletes.has(id))) {
    throw new Error("다른 곳에서 버전 목록이 변경되었습니다. 새로고침 후 다시 확인해 주세요.");
  }
  await assertPraiseVersionsUnused(deletedVersionIds);
  const versionOrders = assignStableVersionOrders(versions, existingCanonicalVersions, song.id);
  const versionRows = buildPraiseVersionSaveRows(song, versions, canonicalSongId, versionOrders, state.songVersionPraiseTypesSupported);

  const existingVersionIds = existingVersions.map((version) => version.id);
  assignUniqueVersionLyricSignatures(versionRows, existingCanonicalVersions);

  if (!planOnly) {
  const { error: versionError } = await state.client
    .from("mindex_song_versions")
    .upsert(versionRows, { onConflict: "id" });
  if (versionError) throw versionError;
  versions.forEach((version) => {
    version._worshipVersionPersisted = true;
  });

  if (deletedVersionIds.length) {
    const { error: deleteError } = await state.client
      .from("mindex_song_versions")
      .delete()
      .in("id", deletedVersionIds)
      .eq("source_song_id", song.id);
    if (deleteError) throw deleteError;
  }

  }

  const unitRows = [];
  const versionIds = versions.map((version) => version.id);
  for (const version of versions) {
    version.forms = normalizeForms(version.forms || []);
    version.forms.forEach((form, index) => {
      if (!isUuid(form.id)) form.id = createUuid();
      form.song_id = version.id;
      const label = displayLabel(form);
      unitRows.push({
        id: form.id,
        version_id: version.id,
        canonical_song_id: canonicalSongId,
        source_unit_id: null,
        unit_order: index + 1,
        unit_label: label || `u${index + 1}`,
        unit_kind: normalizeTitle(form.part_type || "Lyrics") || "lyrics",
        trigger: "",
        slide_numbers: [],
        text: form.lyrics || "",
        curated_unit_type: PART_TYPES.includes(form.part_type) ? form.part_type : "Lyrics",
        curated_unit_label: label,
        curated_order: index + 1,
        review_status: form.review_status && form.review_status !== "pending" ? form.review_status : "reviewed",
        review_note: null,
        reviewed_at: form.review_status === "reviewed" ? new Date().toISOString() : null,
      });
    });
  }

  const existingUnits = await fetchExistingVersionUnits(versionIds);
  if (planOnly) {
    const retained = new Set(unitRows.map(row=>row.id));
    return {versions:versionRows,units:unitRows,deleteVersionIds:deletedVersionIds,
      deleteUnitIds:existingUnits.filter(row=>!retained.has(row.id)).map(row=>row.id),
      canonicalRows:song._pendingCanonicalRow ? [song._pendingCanonicalRow] : []};
  }
  await reserveExistingVersionUnitOrders(existingUnits);
  if (unitRows.length) {
    const { error: unitError } = await state.client
      .from("mindex_version_units")
      .upsert(unitRows, { onConflict: "id" });
    if (unitError) throw unitError;
  }

  const nextUnitIds = new Set(unitRows.map((unit) => unit.id));
  const deletedUnitIds = existingUnits.map((unit) => unit.id).filter((id) => !nextUnitIds.has(id));
  if (deletedUnitIds.length) {
    const { error: deleteUnitError } = await state.client
      .from("mindex_version_units")
      .delete()
      .in("id", deletedUnitIds);
    if (deleteUnitError) throw deleteUnitError;
  }

  const selectedVersion = getSelectedVersion();
  if (!detached && selectedVersion) {
    state.forms = normalizeForms((selectedVersion.forms || []).map((form) => withLocalId({ ...form, song_id: selectedVersion.id })));
  }
}

async function ensureCanonicalSongRow(song, {planOnly = false} = {}) {
  if (song?._singleSongRecord) throw new Error("SINGLE_SONG_NATIVE_SAVE_REQUIRED");
  const title = cleanSongTitleForSave(song) || "제목 없는 찬양";
  const normalizedTitle = await resolveCanonicalNormalizedTitle(song, title);
  const payload = {
    id: song.id,
    title,
    normalized_title: normalizedTitle,
    subtitle: nullIfBlank(song.subtitle),
    original_title: nullIfBlank(song.original_title),
    hymn_no: nullIfBlank(song.hymn_no),
    source_count: 1,
  };

  const existing = await fetchCanonicalSongByNormalizedTitle(normalizedTitle);
  if (existing?.id) {
    song._canonicalSongId = existing.id;
    return existing.id;
  }

  if (planOnly) { song._pendingCanonicalRow=payload; return song.id; }

  const { data, error } = await state.client
    .from("mindex_canonical_songs")
    .upsert(payload, { onConflict: "id" })
    .select("id")
    .single();
  if (error) {
    if (isUniqueConstraintError(error, "mindex_canonical_songs_normalized_title_key")) {
      const racedExisting = await fetchCanonicalSongByNormalizedTitle(normalizedTitle);
      if (racedExisting?.id) {
        song._canonicalSongId = racedExisting.id;
        return racedExisting.id;
      }
    }
    throw error;
  }
  song._canonicalSongId = data?.id || song.id;
  return song._canonicalSongId;
}

async function resolveCanonicalNormalizedTitle(song, title) {
  const baseTitle = normalizeCanonicalTitle(title);
  const candidateVariant = canonicalSongVariantKey(song);
  const candidateTitle = candidateVariant ? canonicalVariantTitle(baseTitle, candidateVariant) : baseTitle;
  const candidates = [candidateTitle, baseTitle].filter(Boolean);
  const existingRows = await fetchCanonicalSongsByNormalizedTitles(candidates);
  const exactVariant = existingRows.find((row) => row.normalized_title === candidateTitle);
  if (exactVariant && isCompatibleCanonicalSong(rowMetadataForCanonicalCompare(exactVariant), song)) {
    return candidateTitle;
  }
  const exactBase = existingRows.find((row) => row.normalized_title === baseTitle);
  if (!exactBase) return candidateTitle;
  if (isCompatibleCanonicalSong(rowMetadataForCanonicalCompare(exactBase), song)) return baseTitle;
  return candidateTitle;
}

function canonicalSongVariantKey(song) {
  const title = cleanSongTitleForSave(song);
  const types = normalizePraiseTypes(song?.praise_types || aggregateSongPraiseTypes(song));
  if (types.includes("children")) return "children";
  const subtitle = nullIfBlank(song?.subtitle);
  if (subtitle && normalizeCanonicalTitle(subtitle) !== normalizeCanonicalTitle(title)) {
    return normalizeCanonicalTitle(subtitle);
  }
  return "";
}

function canonicalVariantTitle(baseTitle, variantKey) {
  const base = String(baseTitle || "").trim();
  const variant = normalizeCanonicalTitle(variantKey);
  return base && variant ? `${base}::${variant}` : base;
}

function rowMetadataForCanonicalCompare(row = {}) {
  return {
    title: row.title,
    subtitle: row.subtitle,
    hymn_no: row.hymn_no,
    original_title: row.original_title,
  };
}

function isCompatibleCanonicalSong(existing, song) {
  const existingSubtitle = normalizeCanonicalTitle(existing?.subtitle || "");
  const songSubtitle = normalizeCanonicalTitle(song?.subtitle || "");
  if (existingSubtitle && songSubtitle && existingSubtitle !== songSubtitle) return false;

  const existingTypes = normalizePraiseTypes(existing?.praise_types || []);
  const songTypes = normalizePraiseTypes(song?.praise_types || aggregateSongPraiseTypes(song));
  if (existingTypes.includes("children") !== songTypes.includes("children")) return false;

  return true;
}

async function fetchCanonicalSongByNormalizedTitle(normalizedTitle) {
  if (!normalizedTitle) return null;
  const { data, error } = await state.client
    .from("mindex_canonical_songs")
    .select("id,title,subtitle,original_title,hymn_no,normalized_title")
    .eq("normalized_title", normalizedTitle)
    .maybeSingle();
  if (error) throw error;
  return data || null;
}

async function fetchCanonicalSongsByNormalizedTitles(normalizedTitles = []) {
  const titles = [...new Set(normalizedTitles.filter(Boolean))];
  if (!titles.length) return [];
  const rows = [];
  for (const title of titles) {
    const row = await fetchCanonicalSongByNormalizedTitle(title);
    if (row) rows.push(row);
  }
  return rows;
}

async function fetchExistingSongVersions(songId) {
  const { data, error } = await state.client
    .from("mindex_song_versions")
    .select("id")
    .eq("source_song_id", songId);
  if (error) throw error;
  return data || [];
}

async function fetchExistingCanonicalSongVersions(canonicalSongId) {
  const { data, error } = await state.client
    .from("mindex_song_versions")
    .select("id,source_song_id,version_order,lyric_signature")
    .eq("canonical_song_id", canonicalSongId);
  if (error) throw error;
  return data || [];
}

function assignUniqueVersionLyricSignatures(versionRows = [], existingRows = []) {
  const nextIds = new Set(versionRows.map((row) => row.id));
  const used = new Set(
    (existingRows || [])
      .filter((row) => row?.lyric_signature && !nextIds.has(row.id))
      .map((row) => row.lyric_signature),
  );

  versionRows.forEach((row, index) => {
    const baseSignature = row.lyric_signature || "mindex-0";
    let signature = baseSignature;
    if (used.has(signature)) {
      const source = String(row.source_song_id || row.id || index + 1).replace(/-/g, "").slice(0, 12) || index + 1;
      signature = `${baseSignature}:${source}:${index + 1}`;
      let suffix = 2;
      while (used.has(signature)) {
        signature = `${baseSignature}:${source}:${index + 1}:${suffix}`;
        suffix += 1;
      }
      row.lyric_signature = signature;
    }
    used.add(signature);
  });
}

async function fetchExistingVersionUnits(versionIds) {
  if (!versionIds.length) return [];
  const { data, error } = await state.client
    .from("mindex_version_units")
    .select("id,version_id,unit_order,curated_order")
    .in("version_id", versionIds);
  if (error) throw error;
  return data || [];
}

async function reserveExistingVersionUnitOrders(existingUnits = []) {
  const units = (existingUnits || []).filter((unit) => isUuid(unit?.id));
  if (!units.length || !state.client) return;

  const byVersion = new Map();
  units.forEach((unit) => {
    const versionId = unit.version_id || "";
    const list = byVersion.get(versionId) || [];
    list.push(unit);
    byVersion.set(versionId, list);
  });

  await Promise.all([...byVersion.values()].map(async (list) => {
    const offset = Math.max(10000, list.length + 1000);
    await Promise.all(list.map(async (unit, index) => {
      const reservedOrder = offset + index + 1;
      const { error } = await state.client
        .from("mindex_version_units")
        .update({
          unit_order: reservedOrder,
          curated_order: reservedOrder,
        })
        .eq("id", unit.id);
      if (error) throw error;
    }));
  }));
}

function assignStableVersionOrders(versions, existingCanonicalRows = [], sourceSongId = "") {
  const orders = new Map();
  const versionIds = new Set((versions || []).map((version) => version?.id).filter(Boolean));
  const used = new Set(
    (existingCanonicalRows || [])
      .filter((row) => row?.source_song_id !== sourceSongId && !versionIds.has(row?.id))
      .map((row) => Number(row?.version_order) || 0)
      .filter((order) => order > 0),
  );
  let nextOrder = 1;

  for (const version of versions || []) {
    const explicitOrder = Number(version?.version_order) || 0;
    if (explicitOrder > 0 && !used.has(explicitOrder)) {
      orders.set(version.id, explicitOrder);
      used.add(explicitOrder);
      nextOrder = Math.max(nextOrder, explicitOrder + 1);
    }
  }

  for (const version of versions || []) {
    if (orders.has(version.id)) continue;
    while (used.has(nextOrder)) nextOrder += 1;
    orders.set(version.id, nextOrder);
    used.add(nextOrder);
    nextOrder += 1;
  }

  return orders;
}

async function saveSongRelationsIfAvailable(song) {
  if (song?._singleSongRecord) throw new Error("SINGLE_SONG_RELATION_EDITOR_REQUIRED");
  if (!song?.id || !state.client) return false;
  if (!state.songRelationsSupported) {
    state.songRelationsSupported = await detectTableColumnSupport("mindex_song_relations", "source_song_id");
  }
  if (!state.songRelationsSupported) return false;

  const relatedIds = cleanList(song.related_song_ids).filter((id) => id && id !== song.id);
  const { error: deleteError } = await state.client
    .from("mindex_song_relations")
    .delete()
    .eq("source_song_id", song.id)
    .eq("relation_type", "related");
  if (deleteError) throw deleteError;

  if (!relatedIds.length) return true;
  const rows = relatedIds.map((relatedId) => ({
    source_song_id: song.id,
    related_song_id: relatedId,
    relation_type: "related",
    note: "",
  }));
  const { error } = await state.client
    .from("mindex_song_relations")
    .upsert(rows, { onConflict: "source_song_id,related_song_id,relation_type" });
  if (error) throw error;
  return true;
}

function writeFormsToSelectedVersion() {
  state.forms = normalizeForms(state.forms);
  const version = getSelectedVersion();
  if (!version) return;
  version.forms = state.forms.map((form, index) => ({
    id: form.id || createLocalId(),
    part_type: form.part_type,
    part_number: form.part_number,
    part_variant: form.part_variant || "",
    label: displayLabel(form),
    lyrics: form.lyrics || "",
    sort_order: index + 1,
    ...(form.review_status && form.review_status !== "reviewed" ? { review_status: form.review_status } : {}),
    ...(form.review_status === "reviewed" ? { review_status: "reviewed" } : {}),
    ...(form.import_source ? { import_source: form.import_source } : {}),
  }));
}

