function normalizePageTabsState(tabs = [], activeIndex = 0) {
  const sanitized = tabs.map(sanitizePageTab).filter(Boolean);
  state.pageTabs = sanitized.length ? sanitized : [homePageTab()];
  state.pageTabIndex = Math.max(0, Math.min(Number(activeIndex) || 0, state.pageTabs.length - 1));
}

function pageTabTitleForSnapshot(snapshot = {}) {
  if (snapshot.module === "bulletin" || (snapshot.module === "presenter" && snapshot.presenterBulletinServiceId)) return bulletinPageTabTitle(snapshot.presenterBulletinServiceId);
  const moduleName = snapshot.module || "home";
  if (moduleName === "presenter") {
    const serviceId = snapshot.selectedServiceId || state.presenter.serviceId;
    const service = state.services.find((svc) => svc.id === serviceId);
    return service ? serviceDisplayTypeName(service) : "예배";
  }
  if (moduleName === "service") {
    const service = state.services.find((svc) => svc.id === snapshot.selectedServiceId);
    if (service) return serviceDisplayTypeName(service);
    if (snapshot.selectedServiceTypeId === SERVICE_WEEK_PANEL_ID) return SERVICE_WEEK_PANEL_TITLE;
    if (snapshot.selectedServiceTypeId === SERVICE_LIST_PANEL_ID) return serviceBrowseCategory(snapshot.serviceFilter).label;
    if (snapshot.selectedServiceTypeId === SERVICE_TEMPLATES_PANEL_ID) return SERVICE_TEMPLATES_PANEL_TITLE;
    if (snapshot.selectedServiceTypeId === SERVICE_SETLIST_ARCHIVE_PANEL_ID) return SERVICE_SETLIST_ARCHIVE_PANEL_TITLE;
    return "예배";
  }
  if (moduleName === "scripture") {
    const book = getBibleBooks().find((item) => item.code === snapshot.selectedBookCode);
    return book ? book.koreanName || book.englishName || "말씀" : "말씀";
  }
  if (moduleName === "praise") {
    const song = songById(snapshot.selectedSongId);
    return song ? songListView(song).title || song.title || "찬양" : "찬양";
  }
  if (moduleName === "setlists") return SERVICE_SETLIST_ARCHIVE_PANEL_TITLE;
  if (moduleName === "operations") return "운영";
  if (moduleName === "calendar") return "교회력";
  if (moduleName === "references") return "참고자료";
  if (moduleName === "manuals") return "예배 매뉴얼";
  return HOME_PAGE_TAB_LABEL;
}

function recentWorkEntry(snapshot = {}, label = "") {
  if (!snapshot || typeof snapshot !== "object") return null;
  const module = snapshot.module;
  const fields = { module };
  let key = "";
  let kind = "";
  if (["service", "presenter", "bulletin"].includes(module)) {
    const bulletin = module === "bulletin" || Boolean(snapshot.presenterBulletinServiceId);
    const id = bulletin ? snapshot.presenterBulletinServiceId || snapshot.selectedServiceId : snapshot.selectedServiceId;
    if (!id || String(id).startsWith("__")) return null;
    fields.module = bulletin ? "bulletin" : "presenter";
    fields.selectedServiceId = String(id);
    fields.selectedServiceTypeId = snapshot.selectedServiceTypeId || null;
    fields.presenterBulletinServiceId = bulletin ? String(id) : null;
    key = `${fields.module}:${id}`;
    kind = bulletin ? "주보" : "예배";
  } else if (module === "praise" && snapshot.selectedSongId) {
    fields.selectedSongId = String(snapshot.selectedSongId);
    fields.selectedVersionId = snapshot.selectedVersionId || null;
    key = `praise:${fields.selectedSongId}`;
    kind = "찬양";
  } else if (module === "scripture" && (snapshot.selectedBookCode || snapshot.selectedScriptureId)) {
    for (const field of ["selectedBookCode", "selectedScriptureId", "selectedBibleTranslationId", "selectedBibleChapter", "selectedBibleVerse", "selectedBibleVerseEnd"]) fields[field] = snapshot[field] ?? null;
    key = snapshot.selectedBookCode ? `bible:${fields.selectedBibleTranslationId}:${fields.selectedBookCode}:${fields.selectedBibleChapter}` : `scripture:${fields.selectedScriptureId}`;
    kind = "말씀";
  } else if (["calendar", "references", "manuals", "setlists"].includes(module)) {
    key = module;
    kind = "운영";
  } else return null;
  return { key, kind, snapshot: fields, label: String(label || pageTabTitleForSnapshot(fields)).slice(0, 160) };
}

// Confirmed save metadata only; never persist editor contents here.
let homeRecentEditsCache = null;
function recentEditEntry(value) {
  const entry = recentWorkEntry(value?.snapshot, value?.label);
  const time = Date.parse(value?.savedAt);
  return entry && Number.isFinite(time) ? {...entry, savedAt:new Date(time).toISOString()} : null;
}
function rememberRecentEdit(snapshot, label, savedAt = new Date().toISOString()) {
  try {
    const entry = recentEditEntry({snapshot,label,savedAt});
    if (!entry) return;
    state.recentEdits = [entry,...(state.recentEdits || []).filter(item => item.key !== entry.key)].slice(0,6);
    if (homeRecentEditsCache) homeRecentEditsCache.readAt = 0;
    persistPageTabsState();
  } catch (error) { console.warn("Recent save metadata unavailable", error?.message); }
}
function homeRecentEditEntries() {
  const cached = homeRecentEditsCache?.client === state.client ? homeRecentEditsCache.entries : [];
  const seen = new Set();
  return [...(state.recentEdits || []),...(cached || [])]
    .sort((a,b) => Date.parse(b.savedAt)-Date.parse(a.savedAt))
    .filter(entry => !seen.has(entry.key) && seen.add(entry.key))
    .filter(entry => {
      const id=entry.snapshot.selectedServiceId;
      const service=state.services.find(item => item.id === id);
      if(id) return Boolean(service && !serviceIsNoGathering(service) && (entry.kind !== "주보" || serviceSupportsBulletin(service)));
      if(entry.kind === "찬양" && songCatalogLoaded) return Boolean(songById(entry.snapshot.selectedSongId));
      if(entry.kind === "말씀" && state.scripturesLoaded) return state.scriptures.some(item => item.id === entry.snapshot.selectedScriptureId);
      return true;
    }).slice(0,6);
}
async function loadHomeRecentEdits({force=false} = {}) {
  if(typeof state.client?.from !== "function") return;
  const client=state.client;
  if(homeRecentEditsCache?.client !== client) homeRecentEditsCache={client,entries:[],readAt:0,promise:null,error:false};
  const cache=homeRecentEditsCache;
  if(cache.promise || (!force && cache.readAt && Date.now()-cache.readAt<60000)) return cache.promise;
  const abort=new AbortController(), timer=setTimeout(()=>abort.abort(),15000);
  cache.promise=(async()=>{
    try {
      const results=await Promise.allSettled([
        client.from("mindex_worship_services").select("id,updated_at").order("updated_at",{ascending:false}).limit(12).abortSignal(abort.signal),
        client.from("mindex_bulletins").select("service_id,updated_at").order("updated_at",{ascending:false}).limit(12).abortSignal(abort.signal)
      ]);
      if(client !== state.client) return;
      cache.error=results.some(result=>result.status !== "fulfilled" || result.value.error);
      cache.entries=results.flatMap((result,index)=>result.status === "fulfilled" && !result.value.error ? (result.value.data || []).map(row=>recentEditEntry({snapshot:{module:index ? "bulletin":"presenter",selectedServiceId:row.service_id || row.id},savedAt:row.updated_at})).filter(Boolean) : []);
      cache.readAt=Date.now();
    } catch { cache.error=true;cache.readAt=Date.now(); } finally {
      clearTimeout(timer);cache.promise=null;
      if(client === state.client && state.module === "home" && state.homeRecentView === "edits" && !isGlobalSearchActive()) renderHomeStart();
    }
  })();
  return cache.promise;
}

function rememberRecentWork(snapshot) {
  const entry = recentWorkEntry(snapshot);
  if (!entry) return;
  state.recentWork = [entry, ...state.recentWork.filter(item => item.key !== entry.key)].slice(0, 6);
  persistPageTabsState();
}

function homeRecentWorkEntries() {
  return state.recentWork.filter(entry => {
    const snapshot = entry.snapshot;
    if (["presenter", "bulletin"].includes(snapshot.module) && state.serviceTypes.length) {
      const service = state.services.find(item => item.id === snapshot.selectedServiceId);
      return Boolean(service && !serviceIsNoGathering(service) && (snapshot.module !== "bulletin" || serviceSupportsBulletin(service)));
    }
    if (snapshot.module === "praise" && songCatalogLoaded) return Boolean(songById(snapshot.selectedSongId));
    if (snapshot.module === "scripture" && snapshot.selectedScriptureId && state.scripturesLoaded) return state.scriptures.some(item => item.id === snapshot.selectedScriptureId);
    return true;
  });
}

async function openHomeRecentWork(key) {
  const entry = (state.homeRecentView === "edits" ? homeRecentEditEntries() : homeRecentWorkEntries()).find(item => item.key === key);
  if (!entry || !(await confirmSaveBeforeLeaving())) return;
  clearDirtyState();
  await applyBrowserHistorySnapshot(entry.snapshot);
  syncBrowserHistory();
}

function renderHomeRecentWork() {
  const edits = state.homeRecentView === "edits";
  const entries = edits ? homeRecentEditEntries() : homeRecentWorkEntries();
  if(edits) void loadHomeRecentEdits();
  return `<section class="home-recent" aria-label="최근 항목"><div class="home-recent-switch" aria-label="최근 항목 보기">${[["work","최근 작업"],["edits","최근 수정"]].map(([key,label])=>`<button type="button" data-home-recent-view="${key}" aria-pressed="${state.homeRecentView === key}">${label}</button>`).join("")}${edits && homeRecentEditsCache?.error ? `<button type="button" data-home-recent-retry title="일부 수정 기록을 불러오지 못했습니다">다시 시도</button>` : ""}</div>
    <div class="home-recent-list">${entries.length ? `${entries.map(entry => {
      const snapshot = entry.snapshot;
      const service = state.services.find(item => item.id === snapshot.selectedServiceId);
      let title = pageTabTitleForSnapshot(snapshot);
      if (["찬양", "말씀", "예배", "주보"].includes(title)) title = entry.label || title;
      if (snapshot.module === "scripture" && snapshot.selectedScriptureId) title = state.scriptures.find(item => item.id === snapshot.selectedScriptureId)?.title || entry.label || title;
      if (snapshot.module === "scripture" && snapshot.selectedBookCode) {
        const verse = Number(snapshot.selectedBibleVerse) || 0;
        const end = Number(snapshot.selectedBibleVerseEnd) || verse;
        title += ` ${Number(snapshot.selectedBibleChapter) || 1}${verse ? `:${verse}${end > verse ? `–${end}` : ""}` : "장"}`;
      }
      const meta = service ? `${entry.kind} · ${formatServiceDate(service, {compact:true})}` : entry.kind;
      return `<button type="button" data-home-recent="${escapeAttr(entry.key)}"><span><small>${escapeHtml(meta)}</small><strong title="${escapeAttr(title)}">${escapeHtml(title)}</strong>${edits ? `<time datetime="${escapeAttr(entry.savedAt)}">${escapeHtml(new Intl.DateTimeFormat("ko-KR",{timeZone:"Asia/Seoul",month:"numeric",day:"numeric",hour:"numeric",minute:"2-digit"}).format(new Date(entry.savedAt)))}</time>` : ""}</span><i data-lucide="arrow-up-right"></i></button>`;
    }).join("")}` : `<p class="home-module-detail">${edits ? (homeRecentEditsCache?.promise ? '최근 수정 불러오는 중…' : '저장한 항목이 여기에 표시됩니다.') : '열어 본 항목이 여기에 표시됩니다.'}</p>`}
    </div>
    </section>`;
}

function readPageTabsState() {
  const raw = safeStorageGet("session", MINDEX_TAB_STATE_STORAGE_KEY);
  let parsed = null;
  try {
    parsed = raw ? JSON.parse(raw) : null;
  } catch {
    parsed = null;
  }
  state.homeRecentView = parsed?.homeRecentView === "edits" ? "edits" : "work";
  state.recentEdits = (Array.isArray(parsed?.recentEdits) ? parsed.recentEdits : []).map(recentEditEntry).filter(Boolean).slice(0,6);
  const tabs = Array.isArray(parsed?.tabs) ? parsed.tabs : [];
  normalizePageTabsState(tabs, Number(parsed?.index) || 0);
  state.recentWork = (Array.isArray(parsed?.recentWork) ? parsed.recentWork : []).map(entry => recentWorkEntry(entry?.snapshot, entry?.label)).filter(Boolean).filter((entry,index,entries) => entries.findIndex(item => item.key === entry.key) === index).slice(0,6);
}

function persistPageTabsState() {
  const payload = {
    tabs: state.pageTabs.map((tab) => ({
      id: tab.id,
      label: tab.label,
      openerTabId: tab.openerTabId || "",
      snapshot: tab.snapshot,
    })),
    index: state.pageTabIndex,
    recentWork: state.recentWork,
    recentEdits: state.recentEdits,
    homeRecentView: state.homeRecentView,
  };
  safeStorageSet("session", MINDEX_TAB_STATE_STORAGE_KEY, JSON.stringify(payload));
}

function syncActivePageTabState() {
  if (state.applyingPageTab) return;
  if (!state.pageTabs.length) normalizePageTabsState([], 0);
  const tab = state.pageTabs[state.pageTabIndex];
  if (!tab) return;
  tab.snapshot = sanitizePageTabSnapshot(currentBrowserHistorySnapshot());
  tab.label = currentPageTabTitle();
  persistPageTabsState();
}

function renderPageTabs() {
  if (!refs.pageTabs) {
    if (refs.pageTabLabel) refs.pageTabLabel.textContent = currentPageTabTitle();
    return;
  }
  if (!state.pageTabs.length) normalizePageTabsState([], 0);
  const addButton = refs.pageTabAddBtn;
  refs.pageTabs.innerHTML = state.pageTabs.map((tab, index) => {
    const active = index === state.pageTabIndex;
    const close = state.pageTabs.length > 1 || tab.snapshot?.module !== "home"
      ? `<button class="page-tab-close" type="button" data-page-tab-close="${escapeAttr(String(index))}" aria-label="${escapeAttr(tab.label)} 탭 닫기"><i data-lucide="x"></i></button>`
      : "";
    return `
      <div class="page-tab${active ? " active" : ""}" role="tab" tabindex="${active ? "0" : "-1"}" draggable="${state.pageTabs.length > 1 ? "true" : "false"}" data-page-tab-index="${escapeAttr(String(index))}" aria-selected="${active ? "true" : "false"}" ${active ? 'aria-current="page"' : ""}>
        <span title="${escapeAttr(tab.label)}">${escapeHtml(tab.label)}</span>
        ${close}
      </div>
    `;
  }).join("");
  if (addButton) refs.pageTabs.appendChild(addButton);
  refreshIcons(refs.pageTabs);
  if (pageTabVisibilityRaf) cancelAnimationFrame(pageTabVisibilityRaf);
  pageTabVisibilityRaf = requestAnimationFrame(() => {
    pageTabVisibilityRaf = 0;
    keepActivePageTabVisible();
  });
}

let pageTabVisibilityRaf = 0;

function keepActivePageTabVisible() {
  const list = refs.pageTabs;
  const active = list?.querySelector('.page-tab[aria-selected="true"]');
  if (!active || !list.clientWidth) return;
  const bounds = list.getBoundingClientRect();
  const tab = active.getBoundingClientRect();
  if (tab.left < bounds.left) list.scrollLeft += tab.left - bounds.left;
  else if (tab.right > bounds.right) list.scrollLeft += tab.right - bounds.right;
}

let pageTabDragIndex = null;
let pageTabDropIndex = null;

function clearPageTabDragState() {
  pageTabDragIndex = null;
  pageTabDropIndex = null;
  refs.pageTabs?.querySelectorAll(".page-tab.dragging, .page-tab.drag-before, .page-tab.drag-after").forEach((tab) => {
    tab.classList.remove("dragging", "drag-before", "drag-after");
    tab.removeAttribute("aria-grabbed");
  });
}

function handlePageTabDragStart(event) {
  if (event.target.closest("[data-page-tab-close]")) {
    event.preventDefault();
    return;
  }
  const tab = event.target.closest("[data-page-tab-index]");
  if (!tab || state.pageTabs.length < 2) return;
  pageTabDragIndex = Number(tab.dataset.pageTabIndex);
  event.dataTransfer.effectAllowed = "move";
  event.dataTransfer.setData("text/plain", String(pageTabDragIndex));
  tab.classList.add("dragging");
  tab.setAttribute("aria-grabbed", "true");
}

function handlePageTabDragOver(event) {
  if (!Number.isInteger(pageTabDragIndex)) return;
  const tab = event.target.closest("[data-page-tab-index]");
  if (!tab) return;
  event.preventDefault();
  event.dataTransfer.dropEffect = "move";
  const targetIndex = Number(tab.dataset.pageTabIndex);
  const bounds = tab.getBoundingClientRect();
  const after = event.clientX >= bounds.left + bounds.width / 2;
  pageTabDropIndex = targetIndex + (after ? 1 : 0);
  refs.pageTabs.querySelectorAll(".page-tab.drag-before, .page-tab.drag-after").forEach((item) => {
    item.classList.remove("drag-before", "drag-after");
  });
  tab.classList.add(after ? "drag-after" : "drag-before");
}

function reorderPageTab(fromIndex, insertionIndex) {
  if (!Number.isInteger(fromIndex) || !Number.isInteger(insertionIndex)) return false;
  if (fromIndex < 0 || fromIndex >= state.pageTabs.length) return false;
  const activeId = state.pageTabs[state.pageTabIndex]?.id;
  const [tab] = state.pageTabs.splice(fromIndex, 1);
  const targetIndex = Math.max(0, Math.min(insertionIndex > fromIndex ? insertionIndex - 1 : insertionIndex, state.pageTabs.length));
  state.pageTabs.splice(targetIndex, 0, tab);
  state.pageTabIndex = Math.max(0, state.pageTabs.findIndex((item) => item.id === activeId));
  persistPageTabsState();
  renderPageTabs();
  return targetIndex !== fromIndex;
}

function handlePageTabDrop(event) {
  if (!Number.isInteger(pageTabDragIndex) || !Number.isInteger(pageTabDropIndex)) return;
  event.preventDefault();
  const fromIndex = pageTabDragIndex;
  const insertionIndex = pageTabDropIndex;
  clearPageTabDragState();
  reorderPageTab(fromIndex, insertionIndex);
}

async function handlePageTabClick(event) {
  const close = event.target.closest("[data-page-tab-close]");
  if (close) {
    event.stopPropagation();
    await closePageTab(Number(close.dataset.pageTabClose));
    return;
  }
  const tab = event.target.closest("[data-page-tab-index]");
  if (!tab) return;
  await activatePageTab(Number(tab.dataset.pageTabIndex));
}

async function handlePageTabKeydown(event) {
  if (event.target.closest("[data-page-tab-close]")) return;
  const tab = event.target.closest("[data-page-tab-index]");
  if (!tab) return;
  if (event.key === "ArrowLeft" || event.key === "ArrowRight" || event.key === "Home" || event.key === "End") {
    event.preventDefault();
    const currentIndex = Number(tab.dataset.pageTabIndex);
    const lastIndex = state.pageTabs.length - 1;
    const nextIndex = event.key === "Home"
      ? 0
      : event.key === "End"
        ? lastIndex
        : (currentIndex + (event.key === "ArrowRight" ? 1 : -1) + state.pageTabs.length) % state.pageTabs.length;
    await activatePageTab(nextIndex);
    refs.pageTabs?.querySelector(`[data-page-tab-index="${nextIndex}"]`)?.focus();
    return;
  }
  if (event.key !== "Enter" && event.key !== " ") return;
  event.preventDefault();
  await activatePageTab(Number(tab.dataset.pageTabIndex));
}

async function openNewPageTab(snapshot = defaultPageTabSnapshot(), { openerTabId = "" } = {}) {
  syncActivePageTabState();
  state.pageTabs.splice(state.pageTabIndex + 1, 0, { ...newPageTab(snapshot), openerTabId });
  state.pageTabIndex += 1;
  persistPageTabsState();
  await applyPageTabSnapshot(state.pageTabIndex);
}

let pageTabClosePending = false;

async function closePageTab(index) {
  if (pageTabClosePending || !Number.isInteger(index) || !state.pageTabs[index]) return;
  const tab = state.pageTabs[index];
  const activeId = state.pageTabs[state.pageTabIndex]?.id;
  const closingActive = tab.id === activeId;
  pageTabClosePending = true;
  try {
    if (state.pageTabs.length === 1) {
      if (tab.snapshot?.module !== "home") await goHome();
      return;
    }
    if (closingActive && tab.snapshot?.module !== "bulletin" && !tab.snapshot?.presenterBulletinServiceId && !(await confirmSaveBeforeLeaving())) return;
    if (state.pageTabs[state.pageTabIndex]?.id !== activeId) return;
    index = state.pageTabs.findIndex((candidate) => candidate.id === tab.id);
    if (index < 0) return;
    bulletinTabSessions.delete(tab.id);
    state.pageTabs.splice(index, 1);
    const returnIndex = state.pageTabs.findIndex((candidate) => candidate.id === (closingActive ? tab.openerTabId : activeId));
    state.pageTabIndex = returnIndex >= 0 ? returnIndex : Math.max(0, Math.min(index, state.pageTabs.length - 1));
    persistPageTabsState();
    if (closingActive) await applyPageTabSnapshot(state.pageTabIndex);
    else {
      renderPageTabs();
    }
  } finally {
    pageTabClosePending = false;
  }
}

async function activatePageTab(index, { force = false } = {}) {
  if (!Number.isInteger(index) || index < 0 || index >= state.pageTabs.length) return;
  if (!force && index === state.pageTabIndex) return;
  window.MINDEX_SERVICE_ENTRY?.invalidate();
  if (!(state.module === "bulletin" || (state.module === "presenter" && state.presenterBulletinServiceId)) && !(await confirmSaveBeforeLeaving())) return;
  syncActivePageTabState();
  state.pageTabIndex = index;
  await applyPageTabSnapshot(index);
}

async function applyPageTabSnapshot(index) {
  state.applyingPageTab = true;
  try {
    await applyBrowserHistorySnapshot(state.pageTabs[index].snapshot || defaultPageTabSnapshot());
  } finally {
    state.applyingPageTab = false;
  }
  state.pageTabs[index].label = pageTabTitleForSnapshot(state.pageTabs[index].snapshot);
  persistPageTabsState();
  renderPageTabs();
  syncBrowserHistory({ replace: true });
}

function renderNavigationSidebarState() {
  refs.navButtons?.forEach((button) => {
    const moduleName = button.dataset.homeModule;
    const active = button.hasAttribute("data-operations-nav")
      ? isOperationsModule()
      : moduleName === state.module || (moduleName === "service" && state.module === "presenter");
    button.classList.toggle("active", active);
    button.setAttribute("aria-current", active ? "page" : "false");
  });
}

async function handleNavigationRailClick(button) {
  const moduleName = button.hasAttribute("data-operations-nav") ? "operations" : button.dataset.homeModule;
  if (moduleName === "home") {
    await goHome();
    return;
  }
  if (["service", "bulletin", "praise", "scripture", "operations"].includes(moduleName)) {
    if (!(await confirmSaveBeforeLeaving())) return;
    saveCurrentListScroll();
    state.newServiceForm = null;
    state.metadataPopupOpen = false;
    clearDirtyState();
    await applyBrowserHistorySnapshot({
      ...homePageTabSnapshot(),
      module: moduleName,
      selectedBibleTranslationId: state.selectedBibleTranslationId,
    });
    if (refs.detailPane) refs.detailPane.scrollTop = 0;
    syncBrowserHistory();
    return;
  }
  await switchModule(moduleName);
}

function serviceSupportsBulletin(service = null) {
  return Boolean(service?.id && !service._expected && ["young-adult","children"].includes(worshipAppServiceTypeId(service.type_id || service.service_type_id))
    && !serviceIsNoGathering(service));
}

function getBulletinSidebarServices() {
  const query=normalizeSearchValue(state.search);
  return state.services.filter(serviceSupportsBulletin).filter(service=>!query||normalizeSearchValue(`${service.date} ${bulletinPageTabTitle(service.id)} ${service.title||""}`).includes(query)).sort((a,b)=>b.date.localeCompare(a.date));
}

function renderBulletinList() {
  refs.songCount.textContent = "";
  if (!state.client || state.connectionError) {refs.songList.innerHTML=renderConnectionList(state.connectionError);return;}
  if (state.serviceError || !state.serviceTypes.length) {refs.songList.innerHTML=state.serviceError?renderListEmptyState("주보 목록을 불러오지 못했습니다",state.serviceError):renderLoadingList();return;}
  const services=getBulletinSidebarServices();
  refs.songList.innerHTML=`<div class="service-sidebar"><section class="service-sidebar-section"><div class="service-sidebar-head"><span>주보</span></div><div class="service-sidebar-stack service-sidebar-stack--navigation">${services.map(service=>`<button type="button" class="service-type-row${state.presenterBulletinServiceId===service.id?" active":""}" data-bulletin-open="${escapeAttr(service.id)}" aria-current="${state.presenterBulletinServiceId===service.id?"page":"false"}"><span>${escapeHtml(formatServiceDate(service))} · ${escapeHtml(bulletinPageTabTitle(service.id))}</span></button>`).join("")||'<p class="muted">표시할 주보가 없습니다.</p>'}</div></section></div>`;
  finishListRender();
}

function renderBulletinDetail() {
  setRightSidebarContent("");
  if (!state.client) {refs.detailPane.innerHTML=renderConnectionEmptyDetail();return;}
  if (state.serviceError) {refs.detailPane.innerHTML=renderUnavailableDetail("service","주보",state.serviceError);return;}
  if (!state.serviceTypes.length) {refs.detailPane.innerHTML=renderLoadingDetail();return;}
  const service=state.services.find(s=>s.id===state.presenterBulletinServiceId);
  if (service && serviceSupportsBulletin(service)) {mountServiceBulletinWorkbench(service);refreshIcons();return;}
  refs.detailPane.innerHTML=renderModuleEmptyDetail("bulletin", "주보", "왼쪽 목록에서 주보를 선택해 주세요.");
}

const bulletinTabSessions = new Map();

async function runServiceBulletinAction(action = "", serviceId = "") {
  const service = state.services.find(candidate => candidate.id === serviceId);
  if (!service || !serviceSupportsBulletin(service)) return;
  if (action !== "open") return;
  if (state.module === "bulletin" && state.presenterBulletinServiceId === serviceId) return;
  await applyBrowserHistorySnapshot({...currentBrowserHistorySnapshot(), module:"bulletin", search:"",
    selectedServiceId:serviceId, selectedServiceTypeId:service.type_id, presenterBulletinServiceId:serviceId});
  syncBrowserHistory();
}

async function loadServiceBulletinSource(serviceId, settings = {}) {
  if (!state.client) throw new Error("DB 연결이 필요합니다.");
  const read = async query => {
    const {data, error} = await query;
    if (error) throw error;
    return data;
  };
  // Read an independent committed aggregate. Never adopt it into the active
  // Presenter draft/baseline and never fall back to cached/emergency content.
  const atomic = await worshipAtomicClient();
  const aggregate = await atomic.read(serviceId, {adopt: false});
  if (!aggregate?.service || !Array.isArray(aggregate.sections) || !Array.isArray(aggregate.elements)) throw new Error("저장된 예배 자료를 확인하지 못했습니다.");
  const normalized = normalizeWorshipService(aggregate.service);
  if (!serviceSupportsBulletin(normalized)) throw new Error("청년부 또는 어린이부 예배를 선택해 주세요.");
  const months = [normalized.date.slice(0, 7), settings.eventsMonth, settings.rosterMonth]
    .filter(v => /^\d{4}-(0[1-9]|1[0-2])$/.test(v || "")).sort();
  const monthStart = `${months[0]}-01`;
  const [year, month] = months[months.length - 1].split("-").map(Number);
  const rangeEnd = new Date(Date.UTC(year, month, 7)).toISOString().slice(0, 10);
  const songIds = [...new Set(aggregate.elements.map(row => row.song_id).filter(Boolean))];
  const scriptureIds = [...new Set(aggregate.elements.map(row => row.scripture_id).filter(Boolean))];
  const [songs, scriptures, calendar, bulletinServices, history] = await Promise.all([
    songIds.length ? read(state.client.from("mindex_songs").select("id,title,hymn_no").in("id", songIds)) : [],
    scriptureIds.length ? read(state.client.from("mindex_scriptures").select("id,reference").in("id", scriptureIds)) : [],
    read(state.client.from("mindex_sunday_calendar").select("date,liturgical,note,church_schedule,young_adult_prayer,children_prayer").gte("date", monthStart).lte("date", rangeEnd).order("date")),
    read(state.client.from("mindex_worship_services").select("id,service_type_id,service_date,title,service_alias,source_ref").gte("service_date", monthStart).lte("service_date", rangeEnd).order("service_date")),
    loadBulletinReusableContent(aggregate.service),
  ]);
  const source = window.MindexBulletin.resolveSource({...aggregate, songs: songs || [], scriptures: scriptures || [], calendar: calendar || [], settings, history,
    services: (bulletinServices || []).map(normalizeWorshipService).filter(s => worshipAppServiceTypeId(s.type_id) === worshipAppServiceTypeId(normalized.type_id))
      .map(s => ({date: s.date, noGathering: serviceIsNoGathering(s), label: s.alias || (serviceIsNoGathering(s) ? (/연합|헌신예배/.test(s._worshipSourceRef?.no_gathering_reason||"")?"연합예배":"집회 없음") : s.title) || "집회 없음"}))});
  source.autoBackground = bulletinBackgroundForService(normalized, (calendar || []).find(row => row.date === normalized.date));
  return source;
}

function bulletinBackgroundForService(service, calendarRow) {
  // Printed July/August issues retained A3 after the Presenter moved to A4.
  const printFile=service.type_id==="young-adult"&&service.date>="2026-07-05"&&service.date<"2026-09-06"?"26-A3.png":null;
  const url = printFile?worshipBackgroundSourcesForFileName(printFile)[0]:presenterBackgroundSourcesForService(service, {includeChromakeyCleanSlides:true, calendarRow})[0];
  if (!url) return null;
  const registered = Object.entries(state.worshipBackgroundRegistry || {}).find(([,entry]) => entry.dataUrl === url);
  return {key:registered?.[0] || (/^(data:|blob:)/.test(url) ? "예배 지정 이미지" : worshipBackgroundFileNameFromPath(url)), url};
}

async function loadBulletinReusableContent(service) {
  const rows=[];
  for(let offset=0;;offset+=200) {
    const {data,error}=await state.client.from("mindex_bulletins")
      .select("service_id,content,mindex_worship_services!inner(service_date,service_type_id)")
      .eq("mindex_worship_services.service_type_id",service.service_type_id)
      .lte("mindex_worship_services.service_date",service.service_date)
      .neq("service_id",service.id).order("service_id").range(offset,offset+199);
    if(error)throw new Error(`주보 공통 내용을 불러오지 못했습니다: ${error.message}`);
    rows.push(...(data||[]).map(row=>({id:row.service_id,date:row.mindex_worship_services.service_date,content:row.content})));
    if(!data||data.length<200)return rows;
  }
}

async function loadBulletinDraft(serviceId) {
  const {data,error}=await state.client.from("mindex_bulletins").select("service_id,content,layout,revision").eq("service_id",serviceId).maybeSingle();
  if(error)throw new Error(`주보 DB를 불러오지 못했습니다: ${error.message}`);
  return data;
}

async function saveBulletinDraft(serviceId, value, revision) {
  const publishClient=state.client;
  const table=publishClient.from("mindex_bulletins");
  const query=revision
    ? table.update(value).eq("service_id",serviceId).eq("revision",revision)
    : table.insert({service_id:serviceId,...value});
  const {data,error}=await query.select("service_id,content,layout,revision,updated_at").maybeSingle();
  if(error?.code==="23505"||(!error&&!data))throw new Error("다른 곳에서 주보가 변경되었습니다. DB 다시 불러오기로 확인해 주세요. 현재 수정 내용은 이 화면에 남아 있습니다.");
  if(error)throw new Error(`주보 DB 저장 실패: ${error.message}`);
  if(publishClient===state.client) {
    rememberRecentEdit({module:"bulletin",selectedServiceId:serviceId},"",data.updated_at);
    window.MINDEX_CONTENT_LIVE?.publish("bulletin",serviceId);
  }
  return data;
}

async function loadBulletinTemplate(key) {
  const {data,error}=await state.client.from("mindex_bulletin_templates").select("template_key,title,department,effective_from,layout,common,revision").eq("template_key",key).maybeSingle();
  if(error)throw new Error(`공통 양식 저장소를 불러오지 못했습니다: ${error.message}`);
  return data;
}
async function saveBulletinTemplate(key,value,revision) {
  const publishClient=state.client;
  const table=publishClient.from("mindex_bulletin_templates");
  const query=revision?table.update(value).eq("template_key",key).eq("revision",revision):table.insert({template_key:key,...value});
  const {data,error}=await query.select("template_key,title,department,effective_from,layout,common,revision").maybeSingle();
  if(error?.code==="23505"||(!error&&!data))throw new Error("다른 곳에서 공통 양식을 변경했습니다. 편집 내용은 유지됩니다. 창을 다시 열어 최신 양식을 확인해 주세요.");
  if(error)throw new Error(`공통 양식 저장 실패: ${error.message}`);
  if(publishClient===state.client)window.MINDEX_CONTENT_LIVE?.publish("bulletin-template",key);
  return data;
}

function mountServiceBulletinWorkbench(service) {
  const tabId = state.pageTabs[state.pageTabIndex]?.id;
  const mounted = refs.detailPane.querySelector("[data-bulletin-owner]");
  if (mounted?.dataset.bulletinOwner === service.id && mounted.dataset.bulletinTab === tabId) return;
  refs.detailPane.innerHTML = `<div data-bulletin-owner="${escapeAttr(service.id)}" style="height:100%;min-height:0"></div>`;
  const host = refs.detailPane.firstElementChild;
  host.dataset.bulletinTab = tabId;
  if (!bulletinTabSessions.has(tabId)) bulletinTabSessions.set(tabId, new Map());
  const bulletinClient = state.client;
  host.bulletinController = window.MindexBulletin.mount(host, {
    remoteBlocked: () => state.client !== bulletinClient || departmentRefreshBlocked(),
    documents: bulletinTabSessions.get(tabId),
    onStateChange: () => syncSaveButtonChrome(),
    serviceId: service.id,
    services: state.services.filter(serviceSupportsBulletin).sort((a,b) => b.date.localeCompare(a.date))
      .map(s => ({id:s.id, label:`${formatServiceDate(s)} · ${serviceDisplayTypeName(s)}`})),
    scope: state.client?.supabaseUrl || window.MINDEX_SUPABASE?.url || "local",
    getBackgrounds: () => worshipBackgroundTargets()
      .filter(({fileName}) => state.worshipBackgroundRegistry[fileName]?.dataUrl || WORSHIP_BACKGROUND_STATIC_FILES.has(fileName))
      .map(({fileName,path}) => ({key:fileName,url:state.worshipBackgroundRegistry[fileName]?.dataUrl || path})),
    loadDraft: loadBulletinDraft,
    saveDraft: saveBulletinDraft,
    loadTemplate: loadBulletinTemplate,
    saveTemplate: saveBulletinTemplate,
    loadSource: loadServiceBulletinSource,
    onServiceChange: id => {
      const selected = state.services.find(candidate => candidate.id === id);
      if (!selected || !serviceSupportsBulletin(selected)) return false;
      state.presenterBulletinServiceId = id;
      state.selectedServiceId = id;
      state.selectedServiceTypeId = selected.type_id;
      if (state.module === "presenter") state.presenter.viewServiceId = id;
      renderBulletinList();
      host.dataset.bulletinOwner = id;
      syncBrowserHistory({replace:true});
    },
  });
}

function canCreatePraiseSong() {
  return state.module === "praise" && !state.loading && !songLoadPromise;
}

function syncPraiseCreateControls() {
  const canCreate = canCreatePraiseSong();
  const showSidebarCreate = state.module === "praise";
  if (refs.sidebarCreateSongBtn) {
    refs.sidebarCreateSongBtn.hidden = !showSidebarCreate;
    refs.sidebarCreateSongBtn.disabled = !canCreate;
  }
  if (refs.newSongBtn) {
    refs.newSongBtn.hidden = !canCreate;
    refs.newSongBtn.disabled = !canCreate;
  }
  document.querySelectorAll("[data-create-song]").forEach((button) => {
    if (button === refs.sidebarCreateSongBtn) return;
    button.hidden = !canCreate;
    button.disabled = !canCreate;
  });
}

