function renderServiceScriptureDatalist() {
  const options = getBibleBooks()
    .flatMap((book) => [
      book.koreanName,
      book.shortName,
      KOREAN_BIBLE_BOOK_ABBREVIATIONS[book.code],
      book.englishName,
    ])
    .filter(Boolean)
    .filter((value, index, list) => list.indexOf(value) === index)
    .map((label) => `<option value="${escapeAttr(label)} 1:1"></option>`)
    .join("");
  return `<datalist id="serviceScriptureOptions">${options}</datalist>`;
}

function renderServiceEditorHeader(typeId) {
  const defaultCount = typeId ? getServiceDefaultItems(typeId).length : 0;
  return `
    <div class="svc-editor-header">
      <span></span>
      <span>섹션</span>
      <span>담당</span>
      <span>항목</span>
      <span>
        ${typeId ? `<button class="icon-btn" type="button" data-service-default-action="add" data-service-default-index="${defaultCount}" aria-label="공통 항목 추가">
          <i data-lucide="plus"></i>
        </button>` : ""}
      </span>
    </div>`;
}

function serviceDefaultMainPraiseTeamName(service) {
  const typeId = worshipAppServiceTypeId(service?.type_id);
  if (typeId === "monthly") return "썸프레이즈";
  if (typeId === "sunday-main") {
    return isAllGenerationsWorshipService(service)
      ? "테힐라 찬양단"
      : "헤세드 찬양단";
  }
  return "";
}

function serviceUsesPraiseLeader(typeId) {
  return Boolean(typeId);
}

function renderServiceMetaEditor(service) {
  if (!service) return "";
  const leaderHidden = !serviceUsesPraiseLeader(service.type_id);
  return `
    <div class="svc-meta-editor">
      <label>
        <span>예배 별명</span>
        <input class="svc-meta-input svc-meta-input--title" type="text" data-service-meta-field="alias"
          value="${escapeAttr(serviceAlias(service))}"
          placeholder="온세대 찬양예배"
          aria-label="예배 별명" />
      </label>
      ${leaderHidden ? "" : `
      <label>
        <span>찬양 인도자</span>
        <input class="svc-meta-input" type="text" data-service-meta-field="leader"
          value="${escapeAttr(servicePraiseLeaderLabel(service))}"
          placeholder="이름/직분"
          aria-label="찬양 인도자" />
      </label>`}

    </div>
  `;
}

function renderServiceOrderTemplate(typeObj) {
  const template = serviceOrderTemplate(typeObj?.id);
  if (!template.length) return "";
  return `
    <details class="svc-template-guide" aria-label="섹션 템플릿" ${MindexDisclosure.attrs(["template-guide",typeObj?.id])}>
      <summary class="svc-template-head">
        <span>섹션 추가</span>
      </summary>
      <div class="svc-template-flow">
        ${template.map((step, index) => renderServiceTemplateStep(step, index, typeObj?.id)).join("")}
      </div>
    </details>`;
}

function renderServiceTemplateStep(step, index, typeId = "") {
  const label = step.label || step.name || `Step ${index + 1}`;
  const badge = renderServiceTemplateBadge(typeId, step);
  return `
    <button
      class="svc-template-step${step.required ? " is-required" : ""}${step.flex ? " is-flex" : ""}"
      type="button"
      data-service-item-action="add"
      data-service-item-label="${escapeAttr(step.label || "")}"
      data-service-item-title="${escapeAttr(step.default_text || "")}"
    >
      <span class="svc-template-step-label">${escapeHtml(label)}</span>
      ${badge}
    </button>`;
}

function renderServiceItemGroups(items) {
  if (!items.length) return `<p class="service-no-results">섹션과 항목을 추가해 주세요.</p>`;

  const selectedService = state.services.find((service) => service.id === state.selectedServiceId);
  const groups = [];
  for (let i = 0; i < items.length; i++) {
    const item = items[i];
    const groupInfo = serviceEditorGroupInfo(item);
    const last = groups[groups.length - 1];
    if (!item._isDefault && groupInfo.key && last && !last.entries[0].item._isDefault && last.key === groupInfo.key) {
      last.entries.push({ item, mergedIndex: i });
    } else {
      groups.push({
        key: groupInfo.key,
        kind: groupInfo.kind,
        label: groupInfo.label,
        assignee: groupInfo.kind === "main-praise" ? servicePraiseAssignee(selectedService, [item]) : "",
        entries: [{ item, mergedIndex: i }],
      });
    }
  }

  let html = "";
  let groupNum = 0;
  for (const group of groups) {
    groupNum++;
    if (group.kind === "main-praise") {
      group.assignee = servicePraiseAssignee(selectedService, group.entries.map((entry) => entry.item));
    }
    if (group.entries.length === 1) {
      html += renderServiceEditorItem(group.entries[0].item, group.entries[0].mergedIndex, items, groupNum);
    } else {
      const groupFirst = group.entries[0].item;
      const groupFirstIndex = groupFirst._origIndex;
      const groupFirstModel = serviceItemEditorModel(groupFirst, { service: selectedService });
      html += `<div class="svc-group${group.kind === "main-praise" ? " svc-group--praise" : ""}">
        <div class="svc-group-head">
          <span class="svc-edit-order">${groupNum}</span>
          <span class="svc-group-label-wrap">
            <span class="svc-group-label">${escapeHtml(group.label)}</span>
            ${renderServiceTemplateBadge(selectedService?.type_id, groupFirst)}
            ${renderServiceEditorFormControls(groupFirst, groupFirstIndex, groupFirstModel, { compact: true, placeholder: "송폼/범위" })}
          </span>
          ${group.kind === "main-praise" && serviceUsesPraiseLeader(selectedService?.type_id) ? `
            <input
              class="svc-group-assignee svc-group-assignee-input"
              type="text"
              data-service-meta-field="leader"
              value="${escapeAttr(servicePraiseLeaderLabel(selectedService))}"
              placeholder="인도자"
              aria-label="찬양 인도자"
            />`
            : group.assignee ? `<span class="svc-group-assignee">${escapeHtml(group.assignee)}</span>` : ""}
        </div>
        ${renderServiceItemMemoEditor(groupFirst, groupFirstIndex, { compact: true })}`;
      for (const { item, mergedIndex } of group.entries) {
        const origIndex = item._origIndex;
        const upDisabled = findAdjacentSameType(items, mergedIndex, -1) === -1;
        const downDisabled = findAdjacentSameType(items, mergedIndex, 1) === -1;
        const localNumber = group.entries.findIndex((entry) => entry.item === item && entry.mergedIndex === mergedIndex) + 1;
        const subModel = serviceItemEditorModel(item, { service: selectedService });
        html += `
        <article class="svc-edit-item svc-edit-item--sub${group.kind === "main-praise" ? " svc-edit-item--praise-sub" : ""}">
          ${group.kind === "main-praise" ? "" : renderServiceEditorAssigneeControl(item, origIndex, { service: selectedService }, subModel)}
          <div class="svc-edit-title-wrap${subModel.strictSong ? " svc-edit-title-wrap--song" : ""}${subModel.titleInvalid ? " is-invalid" : ""}">
            <span class="svc-subsection-chip">${escapeHtml(`${group.label} ${localNumber}`)}</span>
            ${renderServicePraiseInputModeControl(item, origIndex, subModel)}
            ${subModel.showTitle ? `
              <input
                class="svc-edit-title${subModel.titleInvalid ? " is-invalid" : ""}"
                type="text"
                data-service-item-field="raw_title"
                data-service-item-index="${origIndex}"
                value="${escapeAttr(subModel.titleValueOverride !== undefined ? subModel.titleValueOverride : subModel.titleValue || item.raw_title || "")}"
                placeholder="${escapeAttr(subModel.titlePlaceholder)}"
                onkeydown="handleDetailKeydown(event)"
                ${subModel.song ? `autocomplete="off" spellcheck="false"` : ""}
                ${subModel.scripture ? `list="serviceScriptureOptions"` : ""}
                ${subModel.strictSong ? `data-service-song-required="true"` : ""}
                ${subModel.titleInvalid ? `aria-invalid="true"` : ""}
                aria-label="항목 내용"
              />`
              : `<span class="svc-edit-empty" aria-hidden="true"></span>`}
            ${renderServiceSongPicker(item, origIndex, subModel)}
            ${renderServiceEditorFormControls(item, origIndex, subModel, { compact: true, placeholder: "송폼" })}
            ${renderServiceItemLinkControl(item, origIndex)}
          </div>
          <div class="svc-edit-actions">
            ${renderServiceItemMoveButton({ actionAttr: "data-service-item-action", indexAttr: "data-service-item-index", index: origIndex, direction: "up", disabled: upDisabled, label: "항목 위로 이동" })}
            ${renderServiceItemMoveButton({ actionAttr: "data-service-item-action", indexAttr: "data-service-item-index", index: origIndex, direction: "down", disabled: downDisabled, label: "항목 아래로 이동" })}
            <button class="icon-btn" type="button" data-service-item-action="duplicate" data-service-item-index="${origIndex}" aria-label="항목 복제" title="복제"><i data-lucide="copy"></i></button>
            <button class="icon-btn danger" type="button" data-service-item-action="delete" data-service-item-index="${origIndex}" aria-label="항목 삭제" title="삭제"><i data-lucide="trash-2"></i></button>
          </div>
        </article>
        ${servicePraiseUsesDirectLyrics(subModel.praiseInputMode) ? renderServiceManualPraiseLyricsEditor(item, origIndex, { compact: true }) : ""}
        ${servicePraiseUsesDirectLyrics(subModel.praiseInputMode) ? renderServiceItemMemoEditor(item, origIndex, { compact: true }) : ""}`;
      }
      html += `</div>`;
    }
  }
  return html;
}

function serviceEditorGroupInfo(item) {
  const label = String(item?.label || "").trim();
  if (isMainPraiseServiceItem(item)) {
    return { key: "main-praise", kind: "main-praise", label: "찬양" };
  }
  return label
    ? { key: `label:${label}`, kind: "label", label }
    : { key: "", kind: "", label: "" };
}

function renderServiceEditorLabelCell(item, origIndex, attrs = {}, model = serviceItemEditorModel(item, attrs)) {
  const isDefault = Boolean(attrs.isDefault);
  const fieldAttr = attrs.fieldAttr || "data-service-item-field";
  const indexAttr = attrs.indexAttr || "data-service-item-index";
  const service = model.service || selectedServiceForEditor();
  if (model.showLabelInput) {
    return `
      <input
        class="svc-edit-label"
        type="text"
        ${fieldAttr}="label"
        ${indexAttr}="${origIndex}"
        value="${escapeAttr(item.label || "")}"
        placeholder="${isDefault ? "섹션" : "찬양"}"
        aria-label="${isDefault ? "기본 섹션" : "섹션"}"
      />`;
  }
  return `
    <span class="svc-edit-label svc-edit-label--static">${escapeHtml(serviceElementDisplayLabel(item.label) || "항목")}</span>
    ${renderServiceTemplateBadge(service?.type_id, item)}
    ${model.showTitle ? "" : renderServiceEditorFormControls(item, origIndex, model)}`;
}

function renderServiceEditorFormControls(item, origIndex, model = serviceItemEditorModel(item), options = {}) {
  if (servicePraiseInputMode(item, model.parsed, model.service) === "children_audio") return `<span class="svc-song-picker-hint">음원 세트에 저장된 송폼</span>`;
  const parsed = model.parsed || parseServiceItemMemo(item?.memo);
  const hasFormData = Boolean(parsed.formHint || parsed.formPreset || parsed.formPresetRules?.length);
  if (!model.song && !hasFormData) return "";
  return `
    ${renderServiceFormHintInput(item, origIndex, options)}
    ${options.hideProgression ? "" : renderPresenterProgressionAdd(item, origIndex, model.service?.id)}`;
}

function renderServiceEditorAssigneeControl(item, origIndex, attrs = {}, model = serviceItemEditorModel(item, attrs)) {
  if (!model.showAssignee) return `<span class="svc-edit-empty" aria-hidden="true"></span>`;
  const fieldAttr = attrs.fieldAttr || "data-service-item-field";
  const indexAttr = attrs.indexAttr || "data-service-item-index";
  const placeholder = inferServiceItemAssignee(item) || serviceItemAssigneeInputLabel(item);
  return `
    <input
      class="svc-edit-assignee"
      type="text"
      ${fieldAttr}="assignee"
      ${indexAttr}="${origIndex}"
      value="${escapeAttr(model.assigneeValue || "")}"
      placeholder="${escapeAttr(placeholder)}"
      aria-label="${attrs.isDefault ? "기본 항목 담당" : "항목 담당"}"
    />`;
}

function renderServiceEditorTitleControl(item, origIndex, attrs = {}, model = serviceItemEditorModel(item, attrs)) {
  const fieldAttr = attrs.fieldAttr || "data-service-item-field";
  const indexAttr = attrs.indexAttr || "data-service-item-index";
  if(fieldAttr==="data-service-item-field" && !attrs.isDefault && isAnnouncementTextInputItem(item))return renderServiceAnnouncementEditor(item,origIndex,attrs.service?.id||state.selectedServiceId,parseServiceItemMemo(item.memo));
  const listAttr = model.scripture
      ? `list="serviceScriptureOptions"`
      : "";
  const songInputAttrs = model.song ? ` autocomplete="off" spellcheck="false"` : "";
  const invalidAttr = model.titleInvalid ? ` aria-invalid="true"` : "";
  const invalidClass = model.titleInvalid ? " is-invalid" : "";
  const strictAttr = model.strictSong ? ` data-service-song-required="true"` : "";
  if (!model.showTitle) {
    return `<div class="svc-edit-title-wrap svc-edit-title-wrap--empty">${renderServiceItemLinkControl(item, origIndex)}</div>`;
  }
  return `
    <div class="svc-edit-title-wrap${model.strictSong ? " svc-edit-title-wrap--song" : ""}${invalidClass}">
      ${renderServicePraiseInputModeControl(item, origIndex, model)}
      <input
        class="svc-edit-title${invalidClass}"
        ${isAnnouncementTextInputItem(item)?"data-inline-bold":""}
        type="text"
        ${fieldAttr}="raw_title"
        ${indexAttr}="${origIndex}"
        value="${escapeAttr(model.titleValueOverride !== undefined ? model.titleValueOverride : model.titleValue || (model.strictSong ? "" : item.raw_title || ""))}"
        placeholder="${escapeAttr(model.titlePlaceholder)}"
        ${listAttr}
        ${songInputAttrs}
        ${strictAttr}
        ${invalidAttr}
        aria-label="${escapeAttr(attrs.titleAriaLabel || (attrs.isDefault ? "기본 항목 내용" : "항목 내용"))}"
      />
      ${renderServiceSongPicker(item, origIndex, model)}
      ${attrs.hideFormControls ? "" : renderServiceEditorFormControls(item, origIndex, model, { compact: true, placeholder: "송폼", hideProgression: attrs.hideProgression })}
      ${renderServiceItemLinkControl(item, origIndex)}
    </div>`;
}

function renderServicePraiseInputModeControl(item, index, model = serviceItemEditorModel(item)) {
  if (!model.song) return "";
  const selected = model.praiseInputMode || servicePraiseInputMode(item, model.parsed, model.service);
  return `
    <span class="svc-song-version-control svc-praise-input-mode-control"><select
      class="svc-song-version-select svc-praise-input-mode-select"
      data-service-item-field="praise_input_mode"
      data-service-item-index="${index}"
      aria-label="찬양 출력 유형"
      title="${escapeAttr(Object.fromEntries(SERVICE_PRAISE_INPUT_MODES)[selected] || "찬양 출력 유형")}"
    >
      ${SERVICE_PRAISE_INPUT_MODES.map(([value, label]) => `
        <option value="${escapeAttr(value)}"${value === selected ? " selected" : ""}>${escapeHtml(label)}</option>
      `).join("")}
    </select></span>`;
}

function renderServiceSongPicker(item, index, model = serviceItemEditorModel(item)) {
  if (!model.strictSong) return "";
  const song = model.linkedSong;
  const linkedSongId = String(item?.song_id || "").trim();
  if (linkedSongId && !song) {
    // Loading belongs to the service loader or an explicit retry, never rendering.
    const pending = linkedSongLoadPromises.has(linkedSongId);
    return `<div class="svc-song-picker svc-song-picker--linked"><span class="svc-song-picker-hint">${pending ? "연결된 찬양 불러오는 중" : "연결된 찬양을 불러오지 못했습니다"}</span>${pending ? "" : `<button class="icon-btn" type="button" data-service-song-retry="${escapeHtml(linkedSongId)}" aria-label="연결된 찬양 다시 불러오기" title="연결된 찬양 다시 불러오기"><i data-lucide="refresh-cw"></i></button>`}</div>`;
  }
  const query = String(item?.raw_title || "").trim();
  const versionPicker = renderServiceSongVersionPicker(item, index, model);
  if (song) {
    const typeWarning = serviceItemRequiresNewHymnalScoreSong(item) && !isNewHymnalScoreSong(song)
      ? `<span class="svc-song-picker-warning">새찬송가 곡만 선택 가능</span>`
      : "";
    return `
      <div class="svc-song-picker svc-song-picker--linked">
        ${versionPicker}
        ${typeWarning}
      </div>`;
  }
  // Keep the preview replacement target without floating text or layout space.
  if (!query) return `<div class="svc-song-picker" hidden></div>`;
  const results = serviceSongPickerResults(query, item, model.service);
  if (!results.length) {
    return `<div class="svc-song-picker"><span class="svc-song-picker-warning">검색 결과 없음</span><button class="svc-song-create" type="button" data-service-song-create="${index}">새 곡 등록</button></div>`;
  }
  return `
    <div class="svc-song-picker" role="listbox" aria-label="찬양 검색 결과">
      ${results.map((songResult) => renderServiceSongPickerResult(songResult, index)).join("")}
    </div>`;
}

function renderServiceSongVersionPicker(item, index, model = serviceItemEditorModel(item)) {
  const versions = model.songVersions || [];
  if (!versions.length && !item.song_id) return "";
  const selectedId = item.version_id
    || item.song_version_id
    || "";
  return `
    <span class="svc-song-version-control"><select
      class="svc-song-version-select${selectedId ? "" : " is-invalid"}"
      data-service-item-field="version_id"
      data-service-item-index="${index}"
      aria-label="찬양 버전"
      ${selectedId ? "" : `aria-invalid="true"`}
    >
      <option value="">버전을 선택해 주세요</option>
      ${versions.map((version) => `
        <option value="${escapeAttr(version.id)}"${version.id === selectedId ? " selected" : ""}>
          버전: ${escapeHtml(versionDisplayName(model.linkedSong, version))}
        </option>
      `).join("")}
	    </select></span>`;
}

function renderServiceManualPraiseLyricsEditor(item, index, options = {}) {
  const lyrics = formatServiceManualPraiseLyricsInput(item?.memo);
  const rows = Math.max(2, Math.min(12, lyrics.split(/\r?\n/).length));
  return `
    <label class="svc-manual-praise-lyrics${options.compact ? " compact" : ""}">
      <span>가사</span>
      <textarea
        data-service-item-field="manual_praise_lyrics"
        data-service-item-index="${index}"
        rows="${rows}"
        placeholder="가사를 붙여 넣으세요.&#10;빈 줄마다 슬라이드가 나뉩니다."
      >${escapeHtml(lyrics)}</textarea>
    </label>`;
}

function serviceSongPickerResults(query, item = {}, service = selectedServiceForEditor(), limit = 6) {
  const normalizedQuery = presenterPreparationSongContent(query);
  const directMatch = resolveExistingPraiseSongForServiceInput(normalizedQuery, item, service);
  const tokens = getSearchTokens(normalizedQuery);
  if (!tokens.length) return [];
  const requiresNewHymnal = serviceItemRequiresNewHymnalScoreSong(item);
  const requiresChildren = servicePraiseInputMode(item, parseServiceItemMemo(item.memo), service) === "children_audio";
  const includeLyrics = getSearchPhrase(tokens).compact.length >= 4;
  const cacheKey = [
    normalizeSearchValue(normalizedQuery),
    requiresNewHymnal ? "hymn" : requiresChildren ? "children" : "all",
    includeLyrics ? "lyrics" : "summary",
    service?.id || "",
    state.songs.length,
    limit,
  ].join("::");
  if (state.searchCache.songPicker.has(cacheKey)) return state.searchCache.songPicker.get(cacheKey);
  const candidates = state.songs
    .filter((song) => (!requiresNewHymnal || isNewHymnalScoreSong(song))
      && (!requiresChildren || serviceSelectableSongVersions(song, item, service).length))
    .map((song) => ({ song, match: getSongSearchMatch(song, tokens, { includeLyrics }) }))
    .filter((entry) => entry.match);
  const phraseMatches = candidates.filter((entry) => entry.match.phraseMatched);
  const results = phraseMatches.length ? phraseMatches : candidates;
  const songs = uniqueSongsById([
    ...(directMatch && (!requiresNewHymnal || isNewHymnalScoreSong(directMatch)) && (!requiresChildren || serviceSelectableSongVersions(directMatch, item, service).length) ? [directMatch] : []),
    ...results
    .sort((a, b) => b.match.score - a.match.score || sortSongsForCurrentList(a.song, b.song))
    .slice(0, limit)
    .map((entry) => entry.song),
  ]).slice(0, limit);
  if (state.searchCache.songPicker.size > 80) state.searchCache.songPicker.clear();
  state.searchCache.songPicker.set(cacheKey, songs);
  return songs;
}

function uniqueSongsById(songs = []) {
  const seen = new Set();
  return songs.filter((song) => {
    const id = String(song?.id || "").trim();
    if (!id || seen.has(id)) return false;
    seen.add(id);
    return true;
  });
}

function renderServiceSongPickerResult(song, index) {
  const meta = joinMetaItems([
    song.subtitle,
    song.original_title,
    window.MindexSetlistLinks?.artistHint(song, state.songs.filter(peer => window.MindexSetlistLinks.titleKey(peer.title) === window.MindexSetlistLinks.titleKey(song.title))),
    songPraiseTypes(song).join(" · "),
  ]);
  return `
    <button
      class="svc-song-picker-result"
      type="button"
      data-service-song-select="${escapeAttr(song.id)}"
      data-service-song-index="${index}"
      role="option"
    >
      <strong title="${escapeAttr(songServiceOptionLabel(song) || song.title || "제목 없음")}">${escapeHtml(songServiceOptionLabel(song) || song.title || "제목 없음")}</strong>
      ${meta ? `<span title="${escapeAttr(meta)}">${escapeHtml(meta)}</span>` : ""}
    </button>`;
}

function renderServiceEditorItem(item, mergedIndex, mergedItems, groupNum) {
  const isDefault = item._isDefault;
  const origIndex = item._origIndex;
  const actionAttr = isDefault ? "data-service-default-action" : "data-service-item-action";
  const indexAttr = isDefault ? "data-service-default-index" : "data-service-item-index";
  const fieldAttr = isDefault ? "data-service-default-field" : "data-service-item-field";
  const upDisabled = findAdjacentSameType(mergedItems, mergedIndex, -1) === -1;
  const downDisabled = findAdjacentSameType(mergedItems, mergedIndex, 1) === -1;
  const model = serviceItemEditorModel(item, { isDefault, service: selectedServiceForEditor() });
  const attrs = { isDefault, fieldAttr, indexAttr, service: model.service };
  return `
    <article class="svc-edit-item${isDefault ? " svc-edit-item--default" : ""}">
      <span class="svc-edit-order">${groupNum || mergedIndex + 1}</span>
      <span class="svc-edit-section-cell">
        ${renderServiceEditorLabelCell(item, origIndex, attrs, model)}
      </span>
      ${renderServiceEditorAssigneeControl(item, origIndex, attrs, model)}
      ${renderServiceEditorTitleControl(item, origIndex, attrs, model)}
      <div class="svc-edit-actions">
        ${renderServiceItemMoveButton({ actionAttr, indexAttr, index: origIndex, direction: "up", disabled: upDisabled, label: isDefault ? "기본 항목 위로 이동" : "항목 위로 이동" })}
        ${renderServiceItemMoveButton({ actionAttr, indexAttr, index: origIndex, direction: "down", disabled: downDisabled, label: isDefault ? "기본 항목 아래로 이동" : "항목 아래로 이동" })}
        <button class="icon-btn" type="button" ${actionAttr}="duplicate" ${indexAttr}="${origIndex}" aria-label="${isDefault ? "기본 항목 복제" : "항목 복제"}" title="복제"><i data-lucide="copy"></i></button>
        <button class="icon-btn danger" type="button" ${actionAttr}="delete" ${indexAttr}="${origIndex}" aria-label="${isDefault ? "기본 항목 삭제" : "항목 삭제"}" title="삭제"><i data-lucide="trash-2"></i></button>
      </div>
    </article>
    ${!isDefault && servicePraiseUsesDirectLyrics(model.praiseInputMode) ? renderServiceManualPraiseLyricsEditor(item, origIndex) : ""}
    ${!isDefault ? renderServiceItemMemoEditor(item, origIndex) : ""}`;
}

function renderServiceItemMemoEditor(item, index, options = {}) {
  const parsed = parseServiceItemMemo(item?.memo);
  const service = options.service || state.services.find((candidate) => candidate.id === item?.service_id) || selectedServiceForEditor();
  const praiseInputMode = isSongServiceLabel(item?.label) || isSpecialSongServiceItem(item)
    ? servicePraiseInputMode(item, parsed, service)
    : "";
  const manualPraise = servicePraiseUsesDirectLyrics(praiseInputMode);
  const preparation = isServicePreparationItemForEditor(item, parsed);
  const preparationRole = preparation
    ? servicePreparationDefaultRoleForService(
      normalizeServicePresenterRole(parsed.presenterRole) || servicePreparationRoleForEditor(item, parsed),
      service,
      service?.type_id || state.selectedServiceTypeId,
    )
    : "";
  const elementType = preparation ? servicePreparationElementTypeForRoleAndService(preparationRole, service, service?.type_id || state.selectedServiceTypeId) : serviceMemoElementType(parsed);
  const generatedScriptureSlides = Boolean(isScriptureBodyServiceItem(item) && parsed.scriptureReference && parsed.slides.length);
  const showSlideOverrideInput = !manualPraise;
  const operationalSettings = Boolean(
    preparation
    || parsed.note
    || (showSlideOverrideInput && parsed.slides.length && !generatedScriptureSlides)
    || parsed.formHint
    || parsed.formPreset
    || parsed.formPresetRules?.length
    || parsed.inputMode
    || hasServiceAsset(parsed.asset)
    || parsed.presenterRole
    || parsed.playback?.autoAdvanceAt
  );
  if (!operationalSettings) return "";
  const assetNameLabel = elementType === "image" ? "이미지명" : elementType === "audio" ? "음원명" : "파일명";
  const assetNamePlaceholder = elementType === "image" ? "예배 첫 슬라이드 이미지" : elementType === "audio" ? "MR · 성가대 음원 · 광고 BGM" : "준비 영상";
  const assetUrlPlaceholder = elementType === "image" ? "assets/.../first-slide.jpg" : elementType === "audio" ? "assets/.../song.mp3 또는 YouTube 링크" : "assets/.../ready.mp4";
  const autoAdvanceAt = String(parsed.playback?.autoAdvanceAt || "").trim();
  const hasContent = Boolean(preparation || parsed.note || (showSlideOverrideInput && parsed.slides.length) || parsed.formHint || parsed.formPreset || parsed.formPresetRules?.length || elementType || hasServiceAsset(parsed.asset) || parsed.presenterRole || autoAdvanceAt);
  const summary = renderServiceItemMemoSummary({ parsed, preparation, elementType, autoAdvanceAt });
  return `
    <details class="svc-item-note${options.compact ? " compact" : ""}${hasContent ? " has-content" : ""}" ${MindexDisclosure.attrs(["item-settings",item.service_id,item.id||index],servicePraiseUsesDirectLyrics(praiseInputMode))}>
      <summary>
        <span>설정</span>
        ${summary}
      </summary>
      <div class="svc-item-note-grid">
        <label>
          <span>타입</span>
          <select
            data-service-item-field="element_type"
            data-service-item-index="${index}"
          >
            ${renderServiceElementTypeOptions(elementType)}
          </select>
        </label>
        <label>
          <span>설명</span>
          <input
            type="text"
            data-service-item-field="memo_note"
            data-service-item-index="${index}"
            value="${escapeAttr(parsed.note)}"
            placeholder="카메라 2 · 조명 낮게 · 마이크 4"
          />
        </label>
        <label>
          <span>역할</span>
          <select
            data-service-item-field="presenter_role"
            data-service-item-index="${index}"
          >
            ${renderPresenterRoleOptions(parsed.presenterRole)}
          </select>
        </label>
        <label>
          <span>자동 전환 시각</span>
          <input
            type="text"
            data-service-item-field="auto_advance_at"
            data-service-item-index="${index}"
            value="${escapeAttr(autoAdvanceAt)}"
            placeholder="10:40 또는 2026-07-12T10:40:00+09:00"
          />
        </label>
        <label>
          <span>${escapeHtml(assetNameLabel)}</span>
          <input
            type="text"
            data-service-item-field="asset_name"
            data-service-item-index="${index}"
            value="${escapeAttr(parsed.asset?.name || "")}"
            placeholder="${escapeAttr(assetNamePlaceholder)}"
          />
        </label>
        ${renderServiceItemMemoAssetUrlInput(parsed.asset, index, assetUrlPlaceholder)}
        ${showSlideOverrideInput ? `
          <label>
            <span>슬라이드 직접 지정</span>
            <textarea
              data-service-item-field="slide_overrides"
              data-service-item-index="${index}"
              rows="3"
              placeholder="Verse 1&#10;가사 두 줄&#10;---&#10;Chorus&#10;후렴 두 줄"
            >${escapeHtml(formatServiceSlideOverrideInput(item?.memo))}</textarea>
          </label>` : ""}
      </div>
    </details>`;
}

function renderServiceItemMemoAssetUrlInput(asset, index, placeholder) {
  const source = String(asset?.url || "").trim();
  if (source) {
    return `<input type="hidden" data-service-item-field="asset_url" data-service-item-index="${index}" value="${escapeAttr(source)}" />`;
  }
  return `
    <label>
      <span>파일/링크</span>
      <input
        type="text"
        data-service-item-field="asset_url"
        data-service-item-index="${index}"
        value=""
        placeholder="${escapeAttr(placeholder)}"
      />
    </label>`;
}

function renderServiceItemMemoSummary({ parsed, preparation, elementType, autoAdvanceAt } = {}) {
  const asset = normalizeServiceAsset(parsed?.asset);
  const role = normalizeServicePresenterRole(parsed?.presenterRole);
  const inputMode = normalizeServiceInputMode(parsed?.inputMode || parsed?.input_mode);
  const praiseInputLabel = Object.fromEntries(SERVICE_PRAISE_INPUT_MODES)[inputMode] || "";
  const chips = [];
  cleanList([
    elementType ? worshipElementTypeLabel(elementType) : "",
    praiseInputLabel,
    role ? presenterPreparationRoleLabel(role) : "",
    parsed?.note ? "설명" : "",
    autoAdvanceAt ? "자동 전환" : "",
    parsed?.slides?.length ? `슬라이드 ${parsed.slides.length}장` : "",
    parsed?.formHint || parsed?.formPreset || parsed?.formPresetRules?.length ? "송폼" : "",
    hasServiceAsset(asset) ? (asset.name || (asset.url ? "파일" : "")) : "",
    preparation && !role ? "준비" : "",
  ]).forEach((chip) => {
    if (!chips.some((existing) => compactSearchValue(existing) === compactSearchValue(chip))) chips.push(chip);
  });
  chips.splice(4);
  if (!chips.length) return `<span class="svc-item-note-summary is-empty">기본값</span>`;
  return `
    <span class="svc-item-note-summary">
      ${chips.map((chip) => `<span>${escapeHtml(chip)}</span>`).join("")}
    </span>`;
}

function renderServiceElementTypeOptions(selectedType = "") {
  const selected = normalizeServiceElementType(selectedType) || normalizeWorshipElementType(selectedType);
  const placeholder = selected
    ? ""
    : `<option value="" disabled selected>타입 선택</option>`;
  return placeholder + SERVICE_ELEMENT_TYPE_UI_OPTIONS
    .map(([value, label]) => `<option value="${escapeAttr(value)}"${value === selected ? " selected" : ""}>${escapeHtml(label)}</option>`)
    .join("");
}

function renderPresenterRoleOptions(selectedRole = "") {
  const selected = normalizeServicePresenterRole(selectedRole);
  const options = [
    ["", "자동"],
    ["ready", "준비"],
    ["waiting_loop", "대기 영상"],
    ["intro", "인트로"],
    ["still", "첫 화면"],
  ];
  return options
    .map(([value, label]) => `<option value="${escapeAttr(value)}"${value === selected ? " selected" : ""}>${escapeHtml(label)}</option>`)
    .join("");
}


async function openServiceDbTab(button) {
  if (button.disabled) return;
  const songId = button.dataset.serviceDbSong;
  const reference = button.dataset.serviceDbReference;
  const parsed = songId ? null : parseBibleReference(reference);
  if (!songId && !parsed) return;
  button.disabled = true;
  try {
    if (!(await confirmSaveBeforeLeaving())) return;
    const snapshot = songId ? {
      ...defaultPageTabSnapshot(),
      module: "praise",
      selectedSongId: songId,
      selectedVersionId: getPreferredVersionId(state.songs.find((song) => song.id === songId)),
    } : {
      ...defaultPageTabSnapshot(),
      module: "scripture",
      selectedBookCode: parsed.book.code,
      selectedBibleChapter: parsed.chapter || 1,
      selectedBibleVerse: parsed.verse,
      selectedBibleVerseEnd: parsed.verseEnd,
      selectedBibleTranslationId: state.selectedBibleTranslationId,
    };
    await openNewPageTab(snapshot, { openerTabId: state.pageTabs[state.pageTabIndex]?.id || "" });
  } finally {
    button.disabled = false;
  }
}

function renderServicePraiseLinkControl(item, index) {
  if (!isSongServiceLabel(item?.label) && !isSpecialSongServiceItem(item)) return "";
  if (item?.song_id) {
    return `<button class="svc-item-link svc-item-link--linked" type="button" data-service-db-song="${escapeAttr(item.song_id)}" aria-label="찬양 DB 새 탭에서 열기" title="찬양 DB 새 탭에서 열기">DB</button>`;
  }
  return "";
}

function renderServiceItemLinkControl(item, index) {
  return renderServicePraiseLinkControl(item, index) || renderServiceScriptureLinkControl(item);
}

function isOneOffSpecialPraiseItem(item = {}, service = selectedServiceForEditor()) {
  return isSpecialSongServiceItem(item) && !item.song_id && serviceItemAllowsManualSongText(item, service);
}

function renderServiceScriptureLinkControl(item) {
  if (!isScriptureBodyServiceItem(item) && !isScriptureServiceLabel(item?.label)) return "";
  const parsed = parseServiceItemMemo(item?.memo);
  const payload = isScriptureBodyServiceItem(item)
    ? serviceScriptureTextPayload(item, parsed, selectedServiceForEditor())
    : null;
  const reference = normalizeServiceItemReferenceSpacing(payload?.reference || item?.raw_title);
  if (!parseBibleReference(reference)) return "";
  return `<button class="svc-item-link svc-item-link--linked" type="button" data-service-db-reference="${escapeAttr(reference)}" aria-label="말씀 DB 새 탭에서 열기" title="말씀 DB 새 탭에서 열기">DB</button>`;
}

function openServiceListPanel(filter = "public") {
  if (!confirmDiscardServiceChanges()) return;
  state.serviceFilter = serviceBrowseCategory(filter).key;
  state.selectedServiceTypeId = SERVICE_LIST_PANEL_ID;
  state.selectedServiceId = null;
  state.selectedServiceItemIndex = null;
  state.newServiceForm = null;
  renderServiceList();
  renderCurrentServiceModuleDetail();
  syncBrowserHistory();
}

function renderServiceDashboard(options = {}) {
  if (!state.serviceTypes.length) {
    refs.detailPane.innerHTML = state.serviceError
      ? renderUnavailableDetail("service", "예배", state.serviceError)
      : renderLoadingDetail();
    return;
  }

  const services = getServiceDashboardServices();
  const q = normalizeSearchValue(state.search);
  const title = options.title || SERVICE_HOME_WEEK_TITLE;
  const weeks = recentServiceWeeks();
  const servicesByDate = new Map();
  for (const service of services) {
    const key = service.date;
    if (!servicesByDate.has(key)) servicesByDate.set(key, []);
    servicesByDate.get(key).push(service);
  }
  refs.detailPane.innerHTML = `
    <div class="service-dashboard" role="region" aria-label="${escapeAttr(title)}">
      ${q ? `<section class="service-dashboard-section">
        <div class="service-section-head">
          <div>
            <h2 class="service-date-list-title">검색 결과</h2>
          </div>
          <button class="reference-new-btn secondary" type="button" data-service-list>예배 보기</button>
        </div>
        ${q ? (services.length ? `<div class="service-date-grid service-date-grid--dashboard">
          ${services.map((service) => renderServiceDateCard(service, { showType: true })).join("")}
        </div>` : `<p class="service-no-results">검색 결과가 없습니다.</p>`) : ""}
      </section>` : ""}
      ${!q ? weeks.map((week, index) => `
        <section class="service-dashboard-section">
          <div class="service-section-head">
            <div>
              <h3 class="service-date-list-title">${week.label}</h3>
              <p class="service-week-range">${escapeHtml(formatServiceWeekRange(week.start, week.end))}</p>
            </div>
            ${index === 0 ? '<button class="reference-new-btn secondary" type="button" data-service-list>예배 보기</button>' : ""}
          </div>
          <div class="service-week-board">
            ${week.days.map(date => renderServiceWeekDay(date, servicesByDate.get(toLocalDateStr(date)) || [])).join("")}
          </div>
        </section>
      `).join("") : ""}
    </div>`;
  refreshIcons();
}

function formatServiceWeekRange(start, end) {
  return `${start.getMonth() + 1}월 ${start.getDate()}일–${end.getMonth() + 1}월 ${end.getDate()}일`;
}

function serviceDateStatus(service) {
  const today = toLocalDateStr(new Date());
  const start = String(service?.date || "");
  const end = String(service?.date_end || start);
  if (!/^\d{4}-\d{2}-\d{2}$/.test(start)) return {key:"", label:""};
  return end < today ? {key:"past", label:"지난 예배"}
    : start > today ? {key:"upcoming", label:"다가오는 예배"}
    : {key:"today", label:"오늘 예배"};
}

function renderServiceDateStatus(service) {
  const status = serviceDateStatus(service);
  return status.key ? `<span class="service-date-status is-${status.key}">${status.label}</span>` : "";
}

function renderPastServiceEditingNotice(service) {
  return serviceDateStatus(service).key === "past"
    ? `<p class="service-past-editing-notice">지난 예배 · ${escapeHtml(formatServiceIsoDate(service))} — 편집하면 이 날짜의 예배에 저장됩니다.</p>` : "";
}

function renderServiceWeekDay(date, services) {
  const weekdays = ["주일","월","화","수","목","금","토"];
  const dateStr = toLocalDateStr(date);
  const today = toLocalDateStr(new Date());
  return `
    <section class="service-week-day${dateStr < today ? " is-past" : dateStr > today ? " is-upcoming" : ""}${dateStr === today ? " is-today" : ""}${services.length ? "" : " is-empty"}"${dateStr === today ? ' aria-current="date"' : ""}>
      <header>
        <strong>${escapeHtml(weekdays[date.getDay()])}</strong>
        <span class="service-week-date">${dateStr === today ? '<small class="service-week-today">오늘</small>' : ""}${escapeHtml(`${date.getMonth() + 1}/${date.getDate()}`)}</span>
      </header>
      ${services.length ? renderServiceDateStatus({date:dateStr}) : ""}
      <div class="service-week-stack">
        ${services.length
          ? services.map((service) => renderServiceWeekCard(service)).join("")
          : ""}
      </div>
    </section>`;
}

function renderServiceWeekCard(service) {
  const noGathering = serviceIsNoGathering(service);
  const preview = serviceItemPreviewParts(service.id, { compact: true });
  const variant = serviceVariantDisplayName(service);
  const serviceName = serviceDisplayTypeName(service);
  return `
    <button
      class="service-week-card"
      type="button"
      ${noGathering ? 'disabled aria-disabled="true"' : `data-service-id="${escapeAttr(service.id)}"`}
    >
      <strong>${escapeHtml(serviceName)}</strong>
      ${noGathering ? '<span class="service-week-card-preview">집회 없음</span>' : ""}
      ${variant && compactSearchValue(variant) !== compactSearchValue(serviceName) ? `<span class="service-week-card-preview">${escapeHtml(variant)}</span>` : ""}
      ${preview.text ? renderServiceCardPreviewHtml(preview, "service-week-card-preview") : ""}
    </button>`;
}

function renderServiceDateCard(service, options = {}) {
  const noGathering = serviceIsNoGathering(service);
  const preview = serviceItemPreviewParts(service.id);
  const calendarRow = (state.calendarData || []).find((row) => String(row?.date || "").trim() === String(service?.date || "").trim());
  const variant = serviceVariantDisplayName(service);
  const serviceName = serviceDisplayTypeName(service);
  const note = cleanList([
    variant,
    calendarRow?.note,
    serviceIsNoGathering(service) ? "집회 없음" : "",
  ]).filter((value) => compactSearchValue(value) !== compactSearchValue(serviceName)).join(" · ");
  return `
    <button
      class="service-date-card ${serviceDateStatus(service).key === "past" ? "is-past" : ""}"
      type="button"
      ${noGathering ? 'disabled aria-disabled="true"' : `data-service-id="${escapeAttr(service.id)}"`}
      aria-label="${escapeAttr(`${formatServiceDate(service, { compact: true })} ${cleanList([serviceName, variant]).join(" ")} ${noGathering ? "집회 없음" : "열기"}`)}"
    >
      <span class="service-date-card-top">
        <span class="service-date-card-date">${escapeHtml(formatServiceDate(service, { compact: true }))}</span>
        ${noGathering ? "" : '<span class="service-date-card-open">열기</span>'}
      </span>
      ${renderServiceDateStatus(service)}
      ${options.showType ? `<span class="service-date-card-type">${escapeHtml(serviceName)}</span>` : ""}
      ${note ? `<span class="service-date-card-note">${escapeHtml(note)}</span>` : ""}
      ${preview.text ? renderServiceCardPreviewHtml(preview, "service-date-card-preview") : ""}
    </button>`;
}

function renderDeferredPastServiceDetail(service) {
  return `
    <div class="empty-detail">
      <section class="empty-detail-inner service-deferred-empty">
        <h2>${escapeHtml(serviceDisplayTypeName(service))}</h2>
        <p>${escapeHtml(`${formatServiceDate(service)} · 지난 예배`)}</p>
        <p>예배 자료를 불러오면 내용을 확인할 수 있습니다.</p>
        <button class="btn secondary" type="button" data-open-presenter-service="${escapeAttr(service.id)}">예배 불러오기</button>
      </section>
    </div>`;
}

function formatServiceDate(service, options = {}) {
  const start = new Date(`${service.date}T00:00:00`);
  const startText = options.compact
    ? `${start.getMonth() + 1}/${start.getDate()} ${serviceWeekdayLabel(start)}`
    : `${start.getMonth() + 1}월 ${start.getDate()}일${options.weekday === false ? "" : ` (${serviceWeekdayLabel(start)})`}`;
  if (!service.date_end) return startText;
  const end = new Date(`${service.date_end}T00:00:00`);
  const endText = options.compact
    ? `${end.getMonth() + 1}/${end.getDate()} ${serviceWeekdayLabel(end)}`
    : `${end.getMonth() + 1}월 ${end.getDate()}일${options.weekday === false ? "" : ` (${serviceWeekdayLabel(end)})`}`;
  return `${startText} - ${endText}`;
}

function serviceWeekdayLabel(date) {
  return ["주일","월","화","수","목","금","토"][date.getDay()] || "";
}

function formatServiceIsoDate(service) {
  const start = String(service?.date || "").trim();
  const end = String(service?.date_end || "").trim();
  if (!start) return "";
  const startLabel = formatServiceIsoDatePart(start);
  if (!end || end === start) return startLabel;
  return `${startLabel} - ${formatServiceIsoDatePart(end)}`;
}

function formatServiceIsoDatePart(value) {
  const date = new Date(`${value}T00:00:00`);
  const label = Number.isNaN(date.getTime()) ? "" : serviceWeekdayLabel(date);
  return label ? `${value} (${label})` : value;
}

function serviceItemPreviewParts(serviceId, options = {}) {
  const service = state.services.find((candidate) => candidate.id === serviceId) || null;
  const items = getServiceOutputItems(serviceId)
    .filter((item) => serviceItemDisplayText(item) && serviceItemDisplayText(item) !== "-")
  if (!items.length) return { text: "", title: "", reference: "" };
  const sermonTitleItem = items.find((item) => isPresenterPreparationSermonTitleItem(item));
  const scriptureReadingItem = items.find((item) => isSharedScriptureReadingServiceItem(item));
  const sermonTitle = sermonTitleItem
    && !presenterTitleAssigneeTitleIsGeneric(String(sermonTitleItem.raw_title || "").trim(), sermonTitleItem.label || "")
    ? serviceItemDisplayText(sermonTitleItem)
    : "";
  const sermonReferences = scriptureReadingItem
    ? serviceItemScriptureReferences(scriptureReadingItem, parseServiceItemMemo(scriptureReadingItem.memo), service)
    : [];
  const sermonReference = formatServiceScriptureReferenceList(sermonReferences, { abbreviated: options.compact });
  const assignee = options.compact && sermonTitleItem
    ? serviceTitlePersonEffectiveParts(sermonTitleItem, parseServiceItemMemo(sermonTitleItem.memo), service).assignee
    : "";
  if (sermonTitle) {
    return {
      text: sermonReference ? `${sermonTitle} (${sermonReference})` : sermonTitle,
      title: sermonTitle,
      reference: [sermonReference, assignee].filter(Boolean).join(" / "),
    };
  }
  return { text: "", title: "", reference: "" };
}

function renderServiceCardPreviewHtml(preview = {}, className = "service-date-card-preview") {
  const title = String(preview.title || "").trim();
  const reference = String(preview.reference || "").trim();
  if (title) {
    return `
      <span class="${escapeAttr(className)} service-card-sermon-preview">
        <span class="service-card-sermon-title">${escapeHtml(title)}</span>
        <span class="service-card-sermon-reference" title="${escapeAttr(reference)}">${escapeHtml(reference)}</span>
      </span>`;
  }
  return preview.text ? `<span class="${escapeAttr(className)}">${escapeHtml(preview.text)}</span>` : "";
}

function serviceItemDisplayText(item) {
  const service = state.services.find((candidate) => candidate.id === item?.service_id) || null;
  item = serviceItemWithSharedSundayContent(item, service);
  const linkedSong = serviceItemLinkedSong(item);
  if (linkedSong) return songServiceOptionLabel(linkedSong) || cleanSongTitleForSave(linkedSong) || linkedSong.title || "";
  const memo = parseServiceItemMemo(item?.memo);
  if (serviceMemoElementType(memo) === "title_person") {
    const { title, assignee, rawTitleAssignee } = serviceTitlePersonEffectiveParts(item, memo, service);
    if (rawTitleAssignee) {
      return normalizeServiceItemReferenceSpacing(cleanList([title, assignee]).join(" · "));
    }
  }
  const rawTitle = String(item?.raw_title || "").trim();
  if (rawTitle) {
    const contentTitle = serviceItemContentTitleWithoutElementName(item, rawTitle);
    return normalizeServiceItemReferenceSpacing(contentTitle ?? rawTitle);
  }
  return normalizeServiceItemReferenceSpacing(String(item?.label || "").trim());
}

function serviceItemContentTitleWithoutElementName(item = {}, rawTitle = "") {
  const memo = parseServiceItemMemo(item.memo);
  if (serviceMemoElementType(memo) !== "title_content") return null;
  const labelKey = compactSearchValue(item.label || "");
  if (!labelKey) return null;
  const lines = String(rawTitle || "").split(/\r?\n/).map((line) => line.trim()).filter(Boolean);
  if (!lines.length || compactSearchValue(lines[0]) !== labelKey) return null;
  return lines.slice(1).join("\n");
}

function normalizeServiceItemReferenceSpacing(value) {
  const text = String(value || "").trim();
  if (!text) return "";

  const inspection = inspectScriptureReferences(text);
  if (!inspection.valid) return text;
  const references = normalizeServiceScriptureReferenceList(text);
  if (references.length > 1) return formatServiceScriptureReferenceList(references);

  const wholeReference = parseBibleReference(text);
  if (wholeReference) return formatServiceBibleReference(wholeReference, text);

  return text
    .replace(/([1-3]?\s?[A-Za-z가-힣.]{1,16})\s*(\d{1,3})\s*:\s*(\d{1,3})(?:\s*[-–—~]\s*(\d{1,3}))?/g, (match, book, chapter, verse, verseEnd) =>
      formatServiceBibleReferenceMatch(book, chapter, verse, verseEnd) || match)
    .replace(/\s+/g, " ");
}

function normalizeServiceScriptureReferenceList(value) {
  const result = inspectScriptureReferences(value);
  return result.valid ? uniqueList(mergeConsecutiveServiceScriptureReferences(result.references)) : [];
}

function formatServiceScriptureReferenceList(value, options = {}) {
  const references = normalizeServiceScriptureReferenceList(value);
  return references.reduce((formatted, referenceText, index) => {
    const reference = parseBibleReference(referenceText);
    const previous = index > 0 ? parseBibleReference(references[index - 1]) : null;
    if (!reference) {
      const separator = index ? "; " : "";
      return `${formatted}${separator}${referenceText}`;
    }
    const versePart = reference.verse
      ? `${bibleChapterDisplayLabel(reference.book,reference.chapter)}:${reference.verse}${reference.verseEnd ? `–${reference.verseEnd}` : ""}`
      : bibleChapterDisplayLabel(reference.book,reference.chapter);
    const sameBook = previous
      && previous.book?.code === reference.book?.code;
    const sameBookAndChapter = sameBook
      && previous.chapter === reference.chapter;
    const display = sameBookAndChapter
      ? versePart.replace(`${reference.chapter}:`, "")
      : sameBook
        ? versePart
        : options.abbreviated
          ? `${KOREAN_BIBLE_BOOK_ABBREVIATIONS[reference.book.code] || reference.book.shortName || reference.book.koreanName || reference.book.code} ${versePart}`
          : formatServiceBibleReference(reference, referenceText);
    const separator = index ? (sameBookAndChapter ? ", " : "; ") : "";
    return `${formatted}${separator}${display}`;
  }, "");
}

function mergeConsecutiveServiceScriptureReferences(references = []) {
  return references.reduce((merged, referenceText) => {
    const reference = parseBibleReference(referenceText);
    const previousText = merged.at(-1);
    const previous = previousText ? parseBibleReference(previousText) : null;
    if (
      reference?.book?.code
      && previous?.book?.code === reference.book.code
      && previous.chapter === reference.chapter
      && previous.verse
      && reference.verse
      && reference.verse === ((previous.verseEnd || previous.verse) + 1)
    ) {
      merged[merged.length - 1] = formatServiceBibleReference({
        ...previous,
        verseEnd: reference.verseEnd || reference.verse,
      }, previousText);
      return merged;
    }
    merged.push(referenceText);
    return merged;
  }, []);
}

function expandServiceScriptureReferenceText(value = "", context = null) {
  const parts = String(value || "")
    .split(/[，,]/)
    .map((part) => part.trim())
    .filter(Boolean);
  const references = [];
  let lastBookName = context?.lastBookName || "";
  let lastChapter = context?.lastChapter || null;

  for (const part of parts) {
    const candidates = [part];
    if (lastBookName) {
      if (lastChapter && /^\d{1,3}(?:\s*[-–—~]\s*\d{1,3})?$/.test(part)) {
        candidates.push(`${lastBookName} ${lastChapter}:${part}`);
      }
      candidates.push(`${lastBookName} ${part}`);
    }
    const reference = candidates.map(parseBibleReference).find(Boolean);
    if (!reference) continue;
    references.push(formatServiceBibleReference(reference, part));
    lastBookName = KOREAN_BIBLE_BOOK_ABBREVIATIONS[reference.book.code]
      || reference.book.shortName
      || reference.book.koreanName
      || reference.book.code;
    lastChapter = reference.chapter || lastChapter;
  }

  if (context) {
    context.lastBookName = lastBookName;
    context.lastChapter = lastChapter;
  }
  return references;
}

function serviceItemSupportsScriptureReferenceList(item = {}) {
  const slotKey = serviceItemSlotKey(item);
  return isSermonCitationSlotKey(slotKey)
    || compactSearchValue(item.label || "") === "인용구절"
    || isSermonScriptureBodyServiceItem(item)
    || isSharedScriptureReadingServiceItem(item);
}

function markServiceItemSharedContentDirty(item = {}, service = null) {
  if (!item || !sundaySharedContentKey(item) || !sundaySharedContentTypesForItem(item, service).length) return;
  item._worshipSharedContentDirty = true;
}

function sundaySharedContentKey(item = {}, service = null) {
  const slotKey = serviceItemSlotKey(item);
  const typeId = worshipAppServiceTypeId(service?.type_id);
  const sectionKey = String(item?._worshipSectionKey || item?.sectionKey || item?.section_key || "").trim();
  const label = compactSearchValue(item?.label || item?.raw_title || "");
  if (slotKey === "hymn.main" || (sectionKey === "hymn_praise" && label === "찬송")) return "main-praise:3";
  // Third-service praise is independent; only its separate hymn receives song 3.
  if (typeId === "sunday-main" && (sectionKey === "praise" || /^praise\.song\./.test(slotKey))) return "";
  if (/^praise\.song\.[1-3]$/.test(slotKey)) return `main-praise:${slotKey.split(".").pop()}`;
  if (slotKey === "word.reading" || slotKey === "word.body") return "scripture-reading";
  if (slotKey === "sermon.title") return "sermon-title";
  if (slotKey === "sermon.scripture") return "sermon-scripture";
  if (isSermonCitationSlotKey(slotKey)) return "sermon-citation";
  if (["봉헌특송", "봉헌영상"].includes(label) || ["offering.special", "offering.media"].includes(slotKey)) return "";
  if (slotKey === "offering.praise") return "offering-hymn";
  const praiseMatch = label.match(/^찬양(\d+)$/);
  if (sectionKey === "praise" && praiseMatch && Number(praiseMatch[1]) >= 1 && Number(praiseMatch[1]) <= 3) {
    return `main-praise:${Number(praiseMatch[1])}`;
  }
  if (sectionKey === "scripture_reading" && label === "성경봉독") return "scripture-reading";
  if (sectionKey === "sermon" && ["설교", "설교제목"].includes(label)) return "sermon-title";
  if (sectionKey === "sermon" && ["설교본문", "본문", "성경본문"].includes(label)) return "sermon-scripture";
  if (sectionKey === "sermon" && /^인용구절(\d*)$/.test(label)) return "sermon-citation";
  if (sectionKey === "offering" && label === "봉헌찬송") return "offering-hymn";
  return "";
}

function sundaySharedContentTypesForItem(item = {}, service = null) {
  if (!worshipServiceParticipatesInSharedSundayContent(service, item)) return [];
  const typeId = worshipAppServiceTypeId(service?.type_id);
  const key = sundaySharedContentKey(item, service);
  if (!key) return [];
  if (key.startsWith("main-praise:") && ["sunday-first", "sunday-second"].includes(typeId)) {
    if (key === "main-praise:3") return ["sunday-first", "sunday-second", "sunday-main"];
    return ["sunday-first", "sunday-second"];
  }
  if (key === "scripture-reading" && ["sunday-second", "sunday-main"].includes(typeId)) {
    return ["sunday-second", "sunday-main"];
  }
  // 1부 설교는 별도 메시지로 준비한다. 본문·설교 제목·인용 구절은 2부와
  // 3부(주일대예배) 사이에서만 공유하고, 1부 저장을 다른 예배에 전파하지 않는다.
  if (["sermon-title", "sermon-scripture", "sermon-citation"].includes(key)
    && ["sunday-second", "sunday-main"].includes(typeId)) {
    return ["sunday-second", "sunday-main"];
  }
  if (key === "offering-hymn" && ["sunday-first", "sunday-second", "sunday-main"].includes(typeId)) {
    return ["sunday-first", "sunday-second", "sunday-main"];
  }
  return [];
}

function serviceItemHasDirectSundaySharedContent(item = {}, service = null) {
  const key = sundaySharedContentKey(item);
  if (!key) return false;
  const memo = parseServiceItemMemo(item?.memo);
  if (["scripture-reading", "sermon-scripture", "sermon-citation"].includes(key)) {
    return Boolean(serviceItemDirectScriptureReferences(item, memo).length || serviceScriptureTextPayload(item, memo).verses.length);
  }
  if (key === "sermon-title") {
    const rawTitle = String(item?.raw_title || "").trim();
    const hasSpecificTitle = Boolean(rawTitle && !presenterTitleAssigneeTitleIsGeneric(rawTitle, item?.label || ""));
    return hasSpecificTitle;
  }
  if (key.startsWith("main-praise:") || key === "offering-hymn") {
    if (serviceItemRequiresSongSelection(item, service)) {
      return Boolean(item?.song_id && !serviceItemSongSelectionInvalid(item, service));
    }
    return Boolean(item?.song_id || String(item?.raw_title || "").trim() || (memo.slides || []).some((slide) => String(slide || "").trim()));
  }
  void service;
  return false;
}

function sharedSundayContentSourceItem() {
  return null;
}

function serviceItemWithSharedSundayContent(item = {}) {
  return item;
}

function isSharedScriptureReadingServiceItem(item = {}) {
  const slotKey = serviceItemSlotKey(item);
  if (slotKey === "word.reading" || slotKey === "word.body") return true;
  return String(item?._worshipSectionKey || "").trim() === "scripture_reading"
    && compactSearchValue(item?.label || "") === "성경봉독";
}

function isSermonScriptureBodyServiceItem(item = {}) {
  const slotKey = serviceItemSlotKey(item);
  if (slotKey === "sermon.scripture") return true;
  if (isSermonCitationSlotKey(slotKey)) return false;
  const sectionKey = String(item?._worshipSectionKey || item?.sectionKey || item?.section_key || "").trim();
  const label = compactSearchValue(item?.label || "");
  const memo = parseServiceItemMemo(item?.memo);
  const elementType = serviceMemoElementType(memo);
  const citation = isOptionalCitationScriptureServiceItem(item);
  // A projected or newly pasted item can briefly lack its section metadata.
  // Its explicit sermon-body label must still retain the scripture workflow.
  return ["설교본문", "성경본문", "말씀본문"].includes(label)
    || (sectionKey === "sermon" && !citation && (elementType === "scripture_body" || label === "본문"));
}

function isOptionalCitationScriptureServiceItem(item = {}) {
  const slotKey = serviceItemSlotKey(item);
  if (isSermonCitationSlotKey(slotKey)) return true;
  return /^인용구절\d*$/.test(compactSearchValue(item?.label || ""));
}

function isSermonCitationSlotKey(slotKey = "") {
  return normalizeWorshipSlotKey(slotKey) === "sermon.citation";
}

function serviceItemPresentationHidden(item = {}, memo = parseServiceItemMemo(item?.memo)) {
  return !isOptionalCitationScriptureServiceItem(item) && Boolean(memo.hiddenInPresentation);
}

function serviceItemDirectScriptureReferences(item = {}, memo = parseServiceItemMemo(item.memo)) {
  const configured = normalizeServiceScriptureReferenceList(memo.scriptureReferences);
  const titleReferences = normalizeServiceScriptureReferenceList(item.raw_title);
  const references = preferCompleteServiceScriptureReferenceList(configured, titleReferences);
  if (references.length) return references;
  return normalizeServiceScriptureReferenceList(memo.scriptureReference);
}

function preferCompleteServiceScriptureReferenceList(configured = [], displayed = []) {
  if (!displayed.length) return configured;
  if (!configured.length || displayed.length > configured.length) return displayed;
  if (displayed.length < configured.length) return configured;
  return displayed.every((reference, index) => reference === configured[index]) ? configured : displayed;
}

function serviceScriptureReadingReferencesForService(service = null) {
  const serviceId = String(service?.id || "").trim();
  if (!serviceId) return [];
  const readingItem = (state.serviceItems[serviceId] || []).find((candidate) => isSharedScriptureReadingServiceItem(candidate));
  if (!readingItem) return [];
  return serviceItemDirectScriptureReferences(readingItem, parseServiceItemMemo(readingItem.memo));
}

function serviceSermonScriptureReferencesForService(service = null) {
  const serviceId = String(service?.id || "").trim();
  if (!serviceId) return [];
  const sermonItem = (state.serviceItems[serviceId] || []).find((candidate) => isSermonScriptureBodyServiceItem(candidate));
  if (!sermonItem) return [];
  return serviceItemDirectScriptureReferences(sermonItem, parseServiceItemMemo(sermonItem.memo));
}

function serviceItemScriptureReferences(item = {}, memo = parseServiceItemMemo(item.memo), service = null) {
  const effectiveItem = serviceItemWithSharedSundayContent(item, service);
  const effectiveMemo = effectiveItem !== item ? parseServiceItemMemo(effectiveItem.memo) : memo;
  const direct = serviceItemDirectScriptureReferences(effectiveItem, effectiveMemo);
  if (!direct.length && isSermonScriptureBodyServiceItem(item)) {
    return serviceScriptureReadingReferencesForService(service);
  }
  if (!direct.length && isSharedScriptureReadingServiceItem(item)) {
    return serviceSermonScriptureReferencesForService(service);
  }
  return direct;
}

function independentServiceContentTitle(label, value, elementType) {
  const text = String(value || "").trim();
  return ["title", "title_person"].includes(elementType)
    && compactSearchValue(text) === compactSearchValue(label) ? "" : text;
}

function normalizeServiceItemRawTitle(label, value, elementType = "") {
  const raw = independentServiceContentTitle(label, value, elementType);
  if (isSongServiceLabel(label) && compactSearchValue(raw) === compactSearchValue(label)) return "";
  return isScriptureServiceLabel(label) ? normalizeServiceItemReferenceSpacing(raw) : raw;
}

function normalizeServiceItemRawTitleForItem(item = {}, value = "") {
  const raw = independentServiceContentTitle(item.label, value, serviceMemoElementType(parseServiceItemMemo(item.memo)));
  if (serviceItemSupportsScriptureReferenceList(item)) {
    const references = normalizeServiceScriptureReferenceList(raw);
    return references.length ? formatServiceScriptureReferenceList(references) : raw;
  }
  if (isSongServiceLabel(item?.label) && compactSearchValue(raw) === compactSearchValue(item?.label)) return "";
  return isScriptureBodyServiceItem(item) || isScriptureServiceLabel(item?.label)
    ? normalizeServiceItemReferenceSpacing(raw)
    : raw;
}

function isScriptureServiceLabel(label) {
  return /성경|봉독|말씀/.test(compactSearchValue(label || ""));
}

function formatServiceBibleReferenceMatch(bookName, chapter, verse, verseEnd) {
  const book = String(bookName || "").replace(/\s+/g, " ").trim();
  const candidate = `${book} ${chapter}:${verse}${verseEnd ? `-${verseEnd}` : ""}`;
  const reference = parseBibleReference(candidate);
  return reference ? formatServiceBibleReference(reference, candidate) : "";
}

function formatServiceBibleReference(reference, fallback = "") {
  if (!reference?.book || !reference?.chapter) return normalizeServiceItemReferenceSpacing(fallback);
  const book = reference.book.koreanName || reference.book.shortName || reference.book.code;
  const versePart = reference.verse
    ? `${bibleChapterDisplayLabel(reference.book,reference.chapter)}:${reference.verse}${reference.verseEnd ? `–${reference.verseEnd}` : ""}`
    : bibleChapterDisplayLabel(reference.book,reference.chapter);
  return [book, versePart].filter(Boolean).join(" ");
}

function songServiceOptionLabel(song) {
  if (!song) return "";
  const no = String(song.hymn_no || "").trim();
  const title = stripHymnNumber(song.title || "").trim();
  return [no, title].filter(Boolean).join(" ");
}

var SERVICE_PRAISE_TITLE_ALIASES;

function servicePraiseLookupCandidates(value) {
  const raw = stripServiceSongInputPrefix(stripServicePraiseTrailingMusicKey(value));
  if (!raw) return [];
  const hymnless = stripHymnNo(raw).title || raw;
  const withoutPrefix = stripServiceSongInputPrefix(hymnless);
  const primary = withoutPrefix
    .split(/\s*[+＋]\s*/)[0]
    .replace(/^\s*메들리\s*[(（]\s*/u, "")
    .trim();
  const candidates = [
    hymnless,
    withoutPrefix,
    primary,
    stripTitleDecorations(withoutPrefix),
    stripTitleDecorations(primary),
  ];
  for (const match of withoutPrefix.matchAll(/[(\[（]([^)\]）]+)[)\]）]/g)) {
    candidates.push(match[1]);
  }
  const expanded = [];
  for (const candidate of candidates) {
    const text = String(candidate || "").trim();
    if (!text) continue;
    expanded.push(text);
    if (!SERVICE_PRAISE_TITLE_ALIASES) {
      SERVICE_PRAISE_TITLE_ALIASES = new Map([
        [normalizeTitle("내 안에 부어주소서"), "내 안에 부어 주소서"],
        [normalizeTitle("하나님의 뜻 이뤄지네 꿈꾸는 어린이부"), "하나님의 뜻 이뤄지네"],
        [normalizeTitle("모든 이름 위에 뛰어난 이름"), "이 땅 위에 오신"],
      ]);
    }
    const alias = SERVICE_PRAISE_TITLE_ALIASES.get(normalizeTitle(text));
    if (alias) expanded.push(alias);
  }
  return [...new Set(expanded)];
}

function stripServicePraiseTrailingMusicKey(value = "") {
  return String(value || "")
    .normalize("NFKC")
    .replace(/\s+/g, " ")
    .trim()
    .replace(/\s*[(\[]\s*[A-G](?:#|b)?(?:m|M|maj7|sus[24]|add\d+|\d+)?\s*[)\]]\s*$/u, "")
    .replace(/\s+[A-G](?:#|b)?(?:m|M|maj7|sus[24]|add\d+|\d+)?$/u, "")
    .trim();
}

function stripServiceSongInputPrefix(value = "") {
  let text = String(value || "").normalize("NFKC").replace(/\s+/g, " ").trim();
  const prefix = /^(?:response|결단찬양|봉헌찬양|봉헌찬송|파송찬양|파송찬송|폐회찬송|입례찬양|기도\s*찬양|특송|찬양|찬송)(?:\s*\d+)?(?:\s+|[/：:·ㆍ•.-]\s*)/iu;
  for (let i = 0; i < 2; i += 1) {
    const next = text.replace(prefix, "").trim();
    if (next === text) break;
    text = next;
  }
  return text;
}

function servicePraiseExactTitlePriority(song = {}) {
  if (song?.hymn_no || songHasPraiseType(song, "hymn")) return 0;
  if (songHasPraiseType(song, "ccm")) return 1;
  if (songHasPraiseType(song, "children")) return 2;
  return 3;
}

// Title normalization is shared by repeated template/render lookups. The name
// signature also detects in-place title/version edits; retired songs can be GC'd.
const servicePraiseLookupNamesCache = new WeakMap();
function servicePraiseSongMatchesLookupName(song = {}, lookups = [], options = {}) {
  const names = options.titleOnly
    ? [song.title, stripHymnNumber(song.title || "")]
    : [
      songServiceOptionLabel(song),
      song.title,
      stripHymnNumber(song.title || ""),
      song.subtitle,
      song.original_title,
      ...(song.versions || []).map((version) => versionDisplayName(song, version)),
    ];
  const signature = JSON.stringify(names);
  const kind = options.titleOnly ? "title" : "all";
  let entry = servicePraiseLookupNamesCache.get(song);
  if (!entry) {
    entry = {};
    servicePraiseLookupNamesCache.set(song, entry);
  }
  if (entry[kind]?.signature !== signature) {
    entry[kind] = {
      signature,
      names: names.map((name) => {
        const stripped = stripTitleDecorations(stripHymnNo(name).title || name);
        return { lookup: normalizeTitle(stripped), compact: compactSearchValue(stripped) };
      }),
    };
  }
  return entry[kind].names.some((name) =>
    lookups.some((candidate) => name.lookup === candidate.lookup || name.compact === candidate.compact));
}

function findServicePraiseSong(value) {
  const lookups = servicePraiseLookupCandidates(value)
    .map((candidate) => ({
      lookup: normalizeTitle(candidate),
      compact: compactSearchValue(candidate),
    }))
    .filter((candidate) => candidate.lookup || candidate.compact);
  if (!lookups.length) return null;
  const exactTitleMatches = state.songs.filter((song) => servicePraiseSongMatchesLookupName(song, lookups, { titleOnly: true }));
  if (exactTitleMatches.length) {
    return exactTitleMatches
      .sort((a, b) => servicePraiseExactTitlePriority(a) - servicePraiseExactTitlePriority(b) || sortSongsForCurrentList(a, b))[0];
  }
  return state.songs.find((song) => servicePraiseSongMatchesLookupName(song, lookups)) || null;
}

function splitHymnNo(raw) {
  const text = String(raw || "");
  const prefixedHymn = /^(?:새\s*)?(?:찬송가|찬)\s*(\d{1,4})\s*장?(?:\s+(.+))?$/.exec(text);
  if (prefixedHymn) return { no: String(Number(prefixedHymn[1])), title: String(prefixedHymn[2] || "—").trim() || "—" };
  const match = /^(통\s*\d+|\d+)\s+/.exec(text);
  if (match) return { no: match[1].replace(/\s+/, " "), title: text.slice(match[0].length) };
  const hymnStyle = /^(\d{1,4})\s*장\s+(.+)$/.exec(text);
  if (hymnStyle) return { no: String(Number(hymnStyle[1])), title: hymnStyle[2] };
  return { no: null, title: text || "—" };
}

function stripHymnNo(raw) {
  const { no, title } = splitHymnNo(String(raw || "").trim());
  return { no, title: title === "—" ? "" : title };
}

function isMainPraiseServiceItem(item, options = {}) {
  const sectionKey = String(item?._worshipSectionKey || "").trim();
  if (sectionKey.startsWith("source-")) {
    return isMainPraiseLabel(item?._worshipSectionTitle || sectionKey.slice("source-".length));
  }
  if (sectionKey) return sectionKey === "praise";
  const label = String(item?.label || "").trim();
  if (isMainPraiseLabel(label)) return true;
  return Boolean(options.allowUnlabeled && !label && String(item?.raw_title || "").trim());
}

function isMainPraiseLabel(label) {
  const compact = String(label || "").replace(/\s+/g, "");
  return /^찬양\d*$/.test(compact);
}

function serviceAllowsDynamicMainPraiseCount(service = null) {
  return Boolean(service);
}

function createDynamicMainPraiseProjectedItem(service, label) {
  if (!serviceAllowsDynamicMainPraiseCount(service)) return null;
  const match = compactSearchValue(label).match(/^찬양(\d+)$/);
  const ordinal = Number(match?.[1]) || 0;
  if (ordinal < 1) return null;
  const existingPraiseItems = servicePrepEditorItems(service.id)
    .filter((item) => isMainPraiseServiceItem(item))
    .sort((a, b) => (Number(a._worshipElementOrder) || 0) - (Number(b._worshipElementOrder) || 0));
  const base = existingPraiseItems.find((item) => compactSearchValue(item.label || "") === "찬양1")
    || existingPraiseItems[0];
  if (!base) return null;
  return normalizeServiceItem({
    ...base,
    id: `template:dynamic-main-praise:${service.id}:${ordinal}`,
    service_id: service.id,
    label: `찬양 ${ordinal}`,
    raw_title: "",
    song_id: null,
    version_id: null,
    song_version_id: null,
    assignee: "",
    _worshipSectionKey: "praise",
    _worshipSectionTitle: base._worshipSectionTitle || "찬양",
    _worshipElementOrder: ordinal * 10,
    _worshipTemplateProjected: true,
    _worshipTemplatePlaceholder: true,
    _worshipElementTemplateModified: false,
  }, ordinal - 1);
}

function servicePraiseAssignee(service, items = []) {
  if (!serviceUsesPraiseLeader(service?.type_id)) return "";
  const itemAssignee = items.map((item) => cleanServiceAssignee(item?.assignee)).find(Boolean);
  if (itemAssignee) return itemAssignee;
  const leader = servicePraiseLeaderLabel(service);
  if (leader) return leader;
  return "";
}

function servicePraiseBoardMetaCandidate(service, items = []) {
  const introAssignee = items
    .map((item) => item?.praiseIntro ? cleanServiceAssignee(item.assignee) : "")
    .find(Boolean);
  if (introAssignee) return { text: introAssignee, priority: 2.75 };
  const itemAssignee = items.map((item) => cleanServiceAssignee(item?.assignee)).find(Boolean);
  if (itemAssignee && isPraiseTeamName(itemAssignee)) return { text: itemAssignee, priority: 2.6 };
  const leader = servicePraiseLeaderLabel(service);
  if (leader && isPraiseTeamName(leader)) return { text: leader, priority: 2.6 };
  const defaultTeam = serviceDefaultMainPraiseTeamName(service);
  if (defaultTeam) return { text: defaultTeam, priority: 2.5 };
  if (itemAssignee) return { text: `인도 ${itemAssignee}`, priority: 1 };
  if (!leader) return { text: "", priority: 0 };
  return { text: `인도 ${leader}`, priority: 1 };
}

function isPraiseTeamName(value = "") {
  return /(?:찬양\s*(?:팀|단)|성가대|콰이어|워십|밴드|썸프레이즈|praise\s*team|choir|worship|band|sum\s*praise|sumpraise)/i.test(String(value || ""));
}

function isCreedServiceItem(item = {}) {
  const sectionKey = String(item?._worshipSectionKey || "").trim();
  if (sectionKey === "creed") return true;
  const label = compactSearchValue(item?.label || "");
  const title = compactSearchValue(item?.raw_title || item?.title || "");
  return label === "사도신경" || (label === "신앙고백" && title === "사도신경");
}

function isSidebarLiturgicalSummaryItem(item = {}) {
  const sectionKey = String(item?._worshipSectionKey || "").trim();
  if (["creed", "lords_prayer", "community_confession"].includes(sectionKey)) return true;
  const label = compactSearchValue(item?.label || "");
  const title = compactSearchValue(item?.raw_title || item?.title || "");
  return label === "사도신경"
    || label === "주기도문"
    || label === "공동체고백"
    || (label === "신앙고백" && title === "사도신경");
}

function isCreedPresenterItem(item = {}, label = "", displayText = "") {
  if (isCreedServiceItem(item)) return true;
  const compactLabel = compactSearchValue(label || item?.label || "");
  const compactText = compactSearchValue(displayText || item?.raw_title || item?.title || "");
  return compactLabel === "사도신경" || (compactLabel === "신앙고백" && compactText === "사도신경");
}

function inferServiceItemAssignee(item) {
  const label = String(item?.label || "").replace(/\s+/g, "");
  const note = String(item?.raw_title || "").trim();
  if (!label) return "";
  if (/특송/.test(label)) return "담당";
  if (/말씀|설교/.test(label)) return "담임목사";
  if (/^기도$/.test(label) && looksLikePersonOrGroup(note)) return "담당";
  return "";
}

function looksLikePersonOrGroup(value) {
  const text = String(value || "").trim();
  if (!text) return false;
  return /(목사|전도사|장로|권사|집사|청년|구역|전도회|기관|일동)$/.test(text);
}

function normalizePresenterScreen(screen = {}, index = 0, currentScreen = null) {
  const left = Number(screen.availLeft ?? screen.left ?? 0);
  const top = Number(screen.availTop ?? screen.top ?? 0);
  const width = Number(screen.availWidth ?? screen.width ?? window.screen?.availWidth ?? 1920);
  const height = Number(screen.availHeight ?? screen.height ?? window.screen?.availHeight ?? 1080);
  const safeLeft = Number.isFinite(left) ? left : 0;
  const safeTop = Number.isFinite(top) ? top : 0;
  const safeWidth = Number.isFinite(width) && width > 0 ? width : 1920;
  const safeHeight = Number.isFinite(height) && height > 0 ? height : 1080;
  const isCurrent = Boolean(screen.isCurrent) || screen === currentScreen;
  const isPrimary = Boolean(screen.isPrimary);
  const resolution = `${Math.round(safeWidth)}x${Math.round(safeHeight)}`;
  const screenLabel = String(screen.label || "").trim();
  const key = [
    Math.round(safeLeft),
    Math.round(safeTop),
    Math.round(safeWidth),
    Math.round(safeHeight),
    isPrimary ? "primary" : "display",
  ].join(":");
  const labelParts = [
    screenLabel || (isPrimary ? "기본 화면" : `출력 화면 ${index + 1}`),
    resolution,
    isPrimary && !screenLabel ? "기본" : "",
    isCurrent ? "현재" : "",
  ].filter(Boolean);
  return {
    key,
    label: labelParts.join(" · "),
    isPrimary,
    isCurrent,
    rect: {
      left: safeLeft,
      top: safeTop,
      width: safeWidth,
      height: safeHeight,
    },
  };
}

async function requestPresenterScreens({ silent = false } = {}) {
  const electronDisplays = window.mindexElectron?.getPresenterDisplays;
  if (electronDisplays) {
    try {
      const result = await electronDisplays();
      const screens = Array.from(result?.displays || [])
        .map((screen, index) => normalizePresenterScreen(screen, index))
        .filter((screen) => screen.rect.width > 0 && screen.rect.height > 0);
      applyPresenterScreens(screens);
      renderPresenterControlState(presenterViewServiceId());
      if (!silent) showToast(screens.length > 1 ? "출력 화면을 감지했습니다." : "출력 화면을 확인했습니다.", "success");
      return screens;
    } catch (error) {
      console.warn("Could not detect Electron presenter screens.", error);
      if (!silent) showToast("출력 화면을 감지하지 못했습니다.", "error");
      return [];
    }
  }
  if (!window.getScreenDetails || !window.isSecureContext) {
    if (!silent) showToast("이 브라우저에서는 화면 감지를 지원하지 않습니다.", "error");
    return [];
  }
  try {
    // Restore coordinates only with an existing grant; never prompt during boot.
    if (silent) {
      if (!navigator.permissions?.query) return [];
      const permission = await navigator.permissions.query({ name: "window-management" });
      if (permission.state !== "granted") return [];
    }
    const details = await window.getScreenDetails();
    const screens = Array.from(details?.screens || [])
      .map((screen, index) => normalizePresenterScreen(screen, index, details?.currentScreen))
      .filter((screen) => screen.rect.width > 0 && screen.rect.height > 0);
    observePresenterScreenDetails(details);
    applyPresenterScreens(screens);
    renderPresenterControlState(presenterViewServiceId());
    if (!silent) showToast(screens.length > 1 ? "출력 화면을 감지했습니다." : "감지된 외부 화면이 없습니다.", screens.length > 1 ? "success" : "info");
    return screens;
  } catch (error) {
    console.warn("Could not detect presenter screens.", error);
    if (!silent) {
      const message = error?.name === "NotAllowedError"
        ? "화면 감지가 허용되지 않았습니다. 브라우저의 이 사이트 설정에서 ‘창 관리’ 권한을 확인한 뒤 다시 시도해 주세요."
        : "출력 화면을 감지하지 못했습니다. 모니터 연결을 확인한 뒤 다시 시도해 주세요.";
      showToast(message, "error");
    }
    return [];
  }
}

function observePresenterScreenDetails(details) {
  if (presenterScreenDetails === details) return;
  presenterScreenDetails?.removeEventListener?.("screenschange", refreshPresenterScreenDetails);
  presenterScreenDetails?.removeEventListener?.("currentscreenchange", refreshPresenterScreenDetails);
  presenterScreenDetails = details;
  details?.addEventListener?.("screenschange", refreshPresenterScreenDetails);
  details?.addEventListener?.("currentscreenchange", refreshPresenterScreenDetails);
}

function refreshPresenterScreenDetails() {
  const details = presenterScreenDetails;
  if (!details) return;
  const screens = Array.from(details.screens || [])
    .map((screen, index) => normalizePresenterScreen(screen, index, details.currentScreen))
    .filter((screen) => screen.rect.width > 0 && screen.rect.height > 0);
  // Update the next launch target only; never move or reopen a live output.
  applyPresenterScreens(screens);
  renderPresenterControlState(presenterViewServiceId());
}

function applyPresenterScreens(screens = []) {
  state.presenter.screens = screens;
  const selectedStillAvailable = screens.some((screen) => screen.key === state.presenter.selectedScreenId);
  if (!selectedStillAvailable) {
    state.presenter.selectedScreenId = screens.find((screen) => !screen.isCurrent && !screen.isPrimary)?.key
      || screens.find((screen) => !screen.isPrimary)?.key
      || screens[0]?.key
      || null;
  }
  if (state.presenter.selectedScreenId) {
    safeStorageSet("local", PRESENTER_TARGET_SCREEN_STORAGE_KEY, state.presenter.selectedScreenId);
  } else {
    safeStorageRemove("local", PRESENTER_TARGET_SCREEN_STORAGE_KEY);
  }
}

function resolvePresenterTargetScreenRect() {
  const screens = state.presenter.screens || [];
  if (!screens.length) return null;
  const selected = screens.find((screen) => screen.key === state.presenter.selectedScreenId)
    || screens.find((screen) => !screen.isCurrent && !screen.isPrimary)
    || screens.find((screen) => !screen.isPrimary)
    || null;
  if (!selected?.rect) return null;
  return selected.rect;
}

function presenterPreparationDisplayTextForService(service) {
  const drafts = state.presenterPreparationDrafts;
  if (Object.prototype.hasOwnProperty.call(drafts, service.id)) return drafts[service.id] || "";
  return presenterPreparationDefaultDraftForService(service);
}

function presenterPreparationDefaultDraftForService(service) {
  if (!service?.id) return "";
  const fields = presenterPreparationFieldsForService(service);
  const values = new Map(fields.map((field) => [compactSearchValue(field.label), ""]));
  const setValue = (label, value) => {
    const key = compactSearchValue(label);
    const text = String(value || "").trim();
    if (key && text && values.has(key)) values.set(key, text);
  };

  for (const item of servicePrepEditorItems(service.id)) {
    const context = presenterServiceInputItem(item, service);
    if (!context || !presenterServiceInputHasEditableField(item, service)) continue;
    const { mode, model, memo } = context;

    if (isMonthlyCorporatePrayerGroupItem(item, memo)) {
      const ordinals = monthlyCorporatePrayerOrdinalsForItem(item);
      monthlyCorporatePrayerEntries(item, memo).forEach((prayer, index) => {
        const value = [prayer.title, prayer.assignee].filter(Boolean).join(" / ");
        setValue(`공동기도 ${ordinals[index] || index + 1}`, value);
      });
      continue;
    }

    const songMode = ["praise_db", "score_db", "lyrics_db", "children_audio"].includes(mode)
      || servicePraiseUsesDirectLyrics(servicePraiseInputMode(item, memo, service))
      || serviceItemRequiresSongSelection(item, service);
    if (songMode) {
      const song = serviceItemLinkedSong(item);
      const title = song?.title || String(item.raw_title || "").trim();
      // An assignee alone would be parsed as the song title on bulk apply.
      // Leave an untitled slot empty; its existing assignee stays on the item.
      const value = isSpecialSongServiceItem(item) && title
        ? [title, cleanServiceAssignee(item.assignee)].filter(Boolean).join(" / ")
        : title;
      setValue(presenterPreparationPlaceholderSongLabel(item), value);
      continue;
    }

    if (mode === "scripture" || isScriptureBodyServiceItem(item)) {
      const references = serviceItemScriptureReferences(item, memo, service);
      setValue(presenterPreparationPlaceholderTextLabel(item), references.length
        ? formatServiceScriptureReferenceList(references)
        : normalizeServiceItemReferenceSpacing(memo.scriptureReference || item.raw_title || ""));
      continue;
    }

    const { needsTitle, needsAssignee } = presenterServiceTextInputSpec(item, model, memo);
    if (!needsTitle && !needsAssignee) continue;
    const state = presenterServiceRequiredTextInputState(item, model, memo, service);
    const value = needsTitle && needsAssignee
      ? [state.titleText, state.assignee].filter(Boolean).join(" / ")
      : needsTitle ? state.titleText : state.assignee;
    setValue(presenterPreparationPlaceholderTextLabel(item), value);
  }

  return presenterPreparationDraftFromFields(service, fields.map((field) => ({
    label: field.label,
    value: values.get(compactSearchValue(field.label)) || "",
  })));
}

function presenterPreparationFieldsForService(service) {
  return presenterPreparationPlaceholderForService(service)
    .split(/\r\n?|\n/)
    .map((line) => {
      const colon = line.search(/[:：]/);
      if (colon < 1) return null;
      return {
        label: line.slice(0, colon).trim(),
        example: line.slice(colon + 1).trim(),
      };
    })
    .filter(Boolean);
}

function presenterPreparationFieldValues(service, draft = "") {
  const fields = presenterPreparationFieldsForService(service);
  const values = new Map(fields.map((field) => [compactSearchValue(field.label), ""]));
  const lines = String(draft || "").split(/\r\n?|\n/);
  const labeled = lines.some((line) => {
    const colon = String(line).search(/[:：]/);
    return colon > 0 && values.has(compactSearchValue(String(line).slice(0, colon)));
  });
  if (labeled) {
    for (const line of lines) {
      const colon = String(line).search(/[:：]/);
      if (colon < 1) continue;
      const key = compactSearchValue(String(line).slice(0, colon));
      if (values.has(key)) values.set(key, String(line).slice(colon + 1).trim());
    }
  } else {
    lines.forEach((line, index) => {
      if (fields[index]) values.set(compactSearchValue(fields[index].label), String(line || "").trim());
    });
  }
  return fields.map((field) => ({ ...field, value: values.get(compactSearchValue(field.label)) || "" }));
}

function presenterPreparationDraftFromFields(service, fields) {
  const definitions = presenterPreparationFieldsForService(service);
  const values = new Map(fields.map((field) => [compactSearchValue(field.label), String(field.value || "").trim()]));
  return definitions.map(({ label }) => {
    const value = values.get(compactSearchValue(label)) || "";
    return value ? `${label}: ${value}` : "";
  }).join("\n");
}

function presenterPreparationRenderedFields(root, service) {
  if (!root || !service) return [];
  return [...root.querySelectorAll("[data-presenter-preparation-field]")].map((input) => ({
    label: input.dataset.presenterPreparationFieldLabel || "",
    value: input.value || "",
  }));
}

function presenterPreparationDraftFromRoot(root, service) {
  return presenterPreparationDraftFromFields(service, presenterPreparationRenderedFields(root, service));
}

function presenterPreparationDraftHasValues(service, draft = "") {
  return presenterPreparationFieldValues(service, draft).some((field) => field.value.trim());
}

function renderPresenterPreparationFieldRows(service, draft = "") {
  const fields = presenterPreparationFieldValues(service, draft);
  if (!fields.length) return '<p class="svc-presenter-preparation-empty">입력할 항목이 없습니다.</p>';
  return `<div class="svc-presenter-preparation-fields">
    ${fields.map((field) => `
      <label class="svc-presenter-preparation-field-row">
        <span class="svc-presenter-preparation-field-label">${escapeHtml(field.label)}</span>
        <input class="svc-presenter-preparation-field-value" type="text" data-presenter-preparation-field data-service-id="${escapeAttr(service.id)}" data-presenter-preparation-field-label="${escapeAttr(field.label)}" value="${escapeAttr(field.value)}" placeholder="${escapeAttr(field.example)}" aria-label="${escapeAttr(`${field.label} 값`)}" />
      </label>`).join("")}
  </div>`;
}

function presenterPreparationValueSlotLabelsForService(service) {
  return presenterPreparationFormFromExamples(presenterPreparationPlaceholderForService(service))
    .split(/\r\n?|\n/)
    .map((line) => line.replace(/[:：]\s*$/, "").trim())
    .filter(Boolean);
}

function presenterPreparationDraftForApply(service, draft = "") {
  const raw = String(draft || "");
  const lines = raw.split(/\r\n?|\n/);
  // Labeled schedules copied from older workflows retain their original grammar.
  const usesLabels = lines.some((line) => {
    const text = normalizePresenterPreparationLineText(line);
    if (parseKnownPresenterPreparationLine(text)) return true;
    return Boolean(parsePresenterPreparationLine(text)) && !/\d+\s*[:：]\s*\d+/.test(text);
  });
  if (usesLabels) return { value: raw, error: "" };
  const slots = presenterPreparationValueSlotLabelsForService(service);
  const overflow = lines.findIndex((line, index) => String(line || "").trim() && !slots[index]);
  if (overflow >= 0) return { value: "", error: `${overflow + 1}번째 줄은 이 예배에 입력할 항목이 없습니다.` };
  return {
    value: lines.map((line, index) => {
      const value = String(line || "").trim();
      return value ? `${slots[index]}: ${value}` : "";
    }).join("\n"),
    error: "",
  };
}

function presenterPreparationDraftNearApplyButton(button) {
  const serviceId = button?.dataset?.serviceId || state.selectedServiceId;
  const service = state.services.find((candidate) => candidate.id === serviceId);
  if (!service) return "";
  const root = button?.closest?.(".svc-presenter-preparation-input")
    || button?.closest?.("[data-presenter-right-sidebar], .service-sidebar-presenter-context, .svc-presenter-input-rail")
    || button?.parentElement
    || null;
  return presenterPreparationDraftFromRoot(root, service);
}

function focusPresenterPreparationTarget(serviceId, target = {}) {
  if (!serviceId || !target) return;
  requestAnimationFrame(() => {
    const roots = [refs.rightSidebar, refs.detailPane];
    const root = roots.find((candidate) => candidate?.querySelector?.(`[data-presenter-preparation-field][data-service-id="${cssEscape(serviceId)}"]`));
    if (!root) return;
    const inputRoot = root.querySelector(".svc-presenter-input-rail .svc-presenter-preparation-input");
    const selector = target.apply
      ? `[data-presenter-preparation-apply][data-service-id="${cssEscape(serviceId)}"]`
      : `[data-presenter-preparation-field][data-service-id="${cssEscape(serviceId)}"][data-presenter-preparation-field-label="${cssEscape(target.label || "")}"]`;
    const field = inputRoot?.querySelector(selector) || root.querySelector(selector);
    field?.focus?.();
    if (!target.apply && typeof field?.select === "function") field.select();
  });
}

function presenterPreparationDraftForService(serviceId, options = {}) {
  if (options.draft != null) return String(options.draft || "").trim();
  const service = state.services.find((candidate) => candidate.id === serviceId);
  const selector = `[data-presenter-preparation-field][data-service-id="${cssEscape(serviceId)}"]`;
  const input = refs.rightSidebar?.querySelector(selector)
    || refs.detailPane?.querySelector(selector)
    || null;
  const draft = input && service
    ? presenterPreparationDraftFromRoot(input.closest(".svc-presenter-preparation-input"), service)
    : state.presenterPreparationDrafts[serviceId];
  return String(draft || "").trim();
}

function presenterPreparationPlaceholderForService(service) {
  if (!service?.id) return "";
  const lines = [];
  const seen = new Set();
  const addLine = (line) => {
    const text = String(line || "").trim();
    const key = compactSearchValue(text);
    if (!text || seen.has(key)) return;
    seen.add(key);
    lines.push(text);
  };
  const items = servicePrepEditorItems(service.id)
    .filter((item) => presenterServiceInputHasEditableField(item, service));
  for (const item of items) {
    const context = presenterServiceInputItem(item, service);
    if (!context) continue;
    for (const line of presenterPreparationPlaceholderLinesForItem(item, service, { ...context, exampleIndex: lines.length })) {
      const sameLabelItems = items.filter((candidate) => compactSearchValue(candidate.label) === compactSearchValue(item.label));
      const numberedLine = sameLabelItems.length > 1 && !/\d$/.test(compactSearchValue(item.label))
        ? `${item.label}${sameLabelItems.indexOf(item) + 1}${line.slice(line.indexOf(":"))}`
        : line;
      addLine(numberedLine);
    }
  }
  return lines.length ? lines.join("\n") : "입력할 항목이 없습니다";
}

function presenterPreparationPlaceholderLinesForItem(item, service, context) {
  const label = compactSearchValue(item?.label || "");
  const sectionKey = String(item?._worshipSectionKey || "").trim();
  const mode = context.mode;
  if (mode === "asset" || context.memo?.benedictionReplacement) return [];
  if (isMonthlyCorporatePrayerGroupItem(item, context.memo)) {
    const start = Number(String(item.label).match(/\d+/)?.[0]);
    return [start, start + 1].map((ordinal) => `공동기도 ${ordinal}: 교회를 위해 / 홍길동 집사`);
  }
  if (isAnnouncementTextInputItem(item)) return ["광고: 다음 주 예배 후 모임이 있습니다."];
  if (["praise_db", "score_db", "lyrics_db", "children_audio", "audio_praise", "manual_praise"].includes(mode)
    || servicePraiseUsesDirectLyrics(servicePraiseInputMode(item, context.memo, service))
    || serviceItemRequiresSongSelection(item, service)) {
    const base = presenterPreparationPlaceholderSongLabel(item);
    if (!base) return [];
    const special = isSpecialSongServiceItem(item);
    const ordinal = Number(label.match(/\d+$/)?.[0] || 1);
    const exampleIndex = context.exampleIndex ?? (ordinal - 1);
    const songs = ["주 은혜임을", "꽃들도", "주 품에", "주님의 선하심", "주님 큰 영광 받으소서",
      "나의 반석이신 하나님", "부르신 곳에서", "주 예수보다 더 귀한 것은 없네", "그 크신 하나님의 사랑", "내 주 되신 주를 참 사랑하고"];
    const hymns = [250, 288, 35, 180, 314, 310, 305, 428, 545, 620];
    const song = mode === "score_db" ? `찬 ${hymns[exampleIndex % hymns.length]}장`
      : special && context.exampleIndex === undefined ? "그 크신 하나님의 사랑"
        : songs[exampleIndex % songs.length];
    return [`${base}: ${song}${special ? " / 찬양대" : ""}`];
  }
  if (mode === "scripture" || isScriptureBodyServiceItem(item)) {
    return [`${presenterPreparationPlaceholderTextLabel(item) || "성경봉독"}: 히브리서 10:38-39`];
  }
  const { needsTitle, needsAssignee } = presenterServiceTextInputSpec(item, context.model, context.memo);
  if (sectionKey === "sermon" && ["설교", "설교제목"].includes(label)) {
    if (needsTitle) return [`설교: 은혜로 사는 삶${needsAssignee ? " / 홍길동 목사" : ""}`];
    return needsAssignee ? ["설교: 홍길동 목사"] : [];
  }
  const inputLabel = presenterPreparationPlaceholderTextLabel(item);
  if (!inputLabel) return [];
  if (needsTitle && needsAssignee) return [`${inputLabel}: 교회를 위해 / 홍길동 집사`];
  if (needsAssignee) return [`${inputLabel}: 홍길동 ${label === "축도" ? "목사" : "집사"}`];
  if (needsTitle) return [`${inputLabel}: 교회를 위해`];
  return [];
}

function isPresenterPreparationCitationItem(item = {}) {
  const slotKey = serviceItemSlotKey(item);
  if (isSermonCitationSlotKey(slotKey)) return true;
  return String(item._worshipSectionKey || "") === "sermon"
    && /^인용구절\d*$/.test(compactSearchValue(item.label || ""));
}

function presenterPreparationCitationItems(service, items, references) {
  const anchor = items.find((item) =>
      String(item?._worshipSectionKey || "").trim() === "sermon"
      && ["설교", "설교제목"].includes(compactSearchValue(item?.label || "")))
    || (() => {
      const projected = findPresenterPreparationProjectedItem(service, "설교");
      if (!projected) return null;
      return items[materializePresenterPreparationItem(service, items, projected)] || null;
    })();
  if (!anchor) return { error: "인용 구절을 넣을 설교 항목을 찾지 못했습니다.", items };

  const existing = items.filter(isPresenterPreparationCitationItem);
  const next = items.filter((item) => !isPresenterPreparationCitationItem(item));
  const insertionIndex = next.findIndex((item) => item.id === anchor.id) + 1;
  const baseOrder = Number(anchor._worshipElementOrder) || 2;
  const current = existing[0] || {};
  const parsed = parseServiceItemMemo(current.memo || "");
  parsed.elementType = "scripture_body";
  parsed.componentType = "scripture_body";
  parsed.inputMode = "scripture";
  parsed.scriptureReference = references[0] || "";
  parsed.scriptureReferences = [...references];
  parsed.slides = [];
  const citation = normalizeServiceItem({
    ...current,
    id: current.id || createLocalId(),
    service_id: service.id,
    label: "인용 구절",
    raw_title: formatServiceScriptureReferenceList(references),
    song_id: null,
    version_id: null,
    memo: serializeServiceItemMemo(parsed),
    _worshipSectionId: anchor._worshipSectionId || "",
    _worshipSectionKey: anchor._worshipSectionKey || "sermon",
    _worshipSectionTitle: anchor._worshipSectionTitle || "설교",
    _worshipSectionOrder: Number(anchor._worshipSectionOrder) || 0,
    _worshipElementOrder: baseOrder + 0.01,
    _worshipSlotKey: "sermon.citation",
    _worshipElementTemplateModified: true,
    _worshipSharedContentDirty: true,
    _worshipTemplateProjected: false,
    _worshipTemplatePlaceholder: false,
  }, insertionIndex);
  next.splice(Math.max(0, insertionIndex), 0, citation);
  return { items: next, citationIds: [citation.id] };
}

async function applyPresenterPreparationInput(serviceId = state.selectedServiceId, options = {}) {
  const service = state.services.find((candidate) => candidate.id === serviceId);
  const draft = presenterPreparationDraftForService(serviceId, options);
  if (!service || !draft) return;
  if (state.presenterPreparationApplyingServiceIds.has(serviceId)) return;

  state.presenterPreparationApplyingServiceIds.add(serviceId);
  renderServiceList();

  let applied = false;
  try {
    const prepared = presenterPreparationDraftForApply(service, draft);
    if (prepared.error) {
      showToast(prepared.error, "error");
      return;
    }
    const { entries, errors, skipped } = parsePresenterPreparationInput(prepared.value, { skipEmptyLabels: true });
    if (errors.length) {
      showToast(errors[0], "error");
      return;
    }
    if (!entries.length && skipped.length) {
      showToast("내용을 채운 항목이 없습니다. 항목 뒤에 내용을 입력해 주세요.", "info");
      return;
    }

    const plan = planPresenterPreparationEntries(entries, service);
    if (plan.errors.length) {
      showToast(plan.errors.join("\n"), "error");
      return;
    }
    if (!entries.length) return;

    let items = getServiceItems(serviceId).map((item) => ({ ...item }));
    const scriptureItemIds = new Set();
    const versionWarnings = [];
    const createdSongTitles = [];
    const textFieldUpdates = [];
    let citationReferences = null;

    for (const { entry, projected, content, assignee, mode, corporatePrayerIndex } of plan.planned) {
      if (entry.key === "인용구절") {
        const references = normalizeServiceScriptureReferenceList(entry.content);
        if (!references.length || references.some((reference) => !parseBibleReference(reference))) {
          errors.push("인용 구절의 성경 주소를 확인해 주세요.");
        } else {
          citationReferences = references;
        }
        continue;
      }

      const existingGroupIndex = corporatePrayerIndex === undefined ? -1 : items.findIndex((candidate) =>
        isMonthlyCorporatePrayerGroupItem(candidate) && candidate.label === projected.label);
      const targetIndex = existingGroupIndex >= 0 ? existingGroupIndex
        : materializePresenterPreparationItem(service, items, projected);
      const item = items[targetIndex];
      const memo = parseServiceItemMemo(item.memo);

      if (corporatePrayerIndex !== undefined) {
        const prayers = monthlyCorporatePrayerEntries(item, memo);
        prayers[corporatePrayerIndex] = { ...prayers[corporatePrayerIndex], title: content,
          assignee: assignee || prayers[corporatePrayerIndex].assignee };
        item.memo = serializeServiceItemMemo({ ...memo, corporatePrayers: prayers, slides: [] });
        item._worshipElementTemplateModified = true;
        item._worshipTemplatePlaceholder = false;
        continue;
      }

      if (servicePraiseUsesDirectLyrics(mode) && isSpecialSongServiceItem(item)) {
        const existingSong = await resolveExistingPraiseSongForServiceInputAfterCatalogLoad(content, item, service);
        if (existingSong) {
          linkServiceItemToPraiseSong(item, existingSong, service, { forceLyricsMode: true });
          if (assignee) item.assignee = assignee;
          item._worshipElementTemplateModified = true;
          markServiceItemSharedContentDirty(item, service);
          item._worshipTemplatePlaceholder = false;
          continue;
        }
      }

      if (["praise_db", "score_db", "lyrics_db", "children_audio"].includes(mode) || serviceItemRequiresSongSelection(item, service)) {
        if (presenterPreparationSongContentHasConnection(content)) {
          const segments = content.split(/\s+[+＋]\s+/u).map((part) => part.trim()).filter(Boolean);
          const resolvedSongs = [];
          let unresolvedSegment = "";
          for (const segment of segments) {
            let segmentSong = resolvePresenterPreparationSong(segment, item, service);
            if (!segmentSong && !serviceItemRequiresNewHymnalScoreSong(item)) {
              try {
                segmentSong = await createBlankPraiseSongForServiceInput(segment, service, item);
                if (segmentSong) createdSongTitles.push(segmentSong.title || segment);
              } catch (error) {
                errors.push(error.message || `${entry.label} 빈 곡을 만들지 못했습니다.`);
                segmentSong = null;
              }
            }
            if (!segmentSong) { unresolvedSegment = segment; break; }
            if (serviceItemRequiresNewHymnalScoreSong(item) && !isNewHymnalScoreSong(segmentSong)) {
              errors.push(`${entry.label}은 새찬송가 곡만 선택할 수 있습니다.`);
              unresolvedSegment = segment;
              break;
            }
            resolvedSongs.push(segmentSong);
          }
          // Every song in a "+"-joined medley line must resolve to a distinct DB
          // record before any row is written; a partial link would silently
          // orphan the unresolved segment's lyrics with no way to fix it later.
          if (unresolvedSegment || resolvedSongs.length !== segments.length) {
            if (unresolvedSegment) errors.push(`${entry.label} "${unresolvedSegment}" 곡을 찬양 DB에서 하나로 찾지 못했습니다.`);
            continue;
          }
          const groupId = createLocalId();
          const groupIndexes = [targetIndex];
          for (let ordinal = 1; ordinal < resolvedSongs.length; ordinal += 1) {
            groupIndexes.push(materializeSecondaryConnectedPraiseItem(service, items, item, ordinal));
          }
          const groupItemIds = groupIndexes.map((index) => items[index].id);
          const groupTitle = resolvedSongs.map((song) => song.title).filter(Boolean).join(" + ");
          groupIndexes.forEach((index, ordinal) => {
            const groupItem = items[index];
            const song = resolvedSongs[ordinal];
            const groupMemo = ordinal === 0 ? memo : parseServiceItemMemo(groupItem.memo);
            groupItem.song_id = song.id;
            groupItem.raw_title = "";
            if (ordinal === 0 && assignee) groupItem.assignee = assignee;
            groupItem._worshipElementTemplateModified = true;
            markServiceItemSharedContentDirty(groupItem, service);
            groupItem._worshipTemplatePlaceholder = false;
            const defaultVersion = defaultServiceSongVersion(song, groupItem, service);
            groupItem.version_id = defaultVersion?.id || null;
            if (serviceSongHasMultipleSelectableVersions(song, groupItem, service)) versionWarnings.push(entry.label);
            groupItem.song_version_id = groupItem.version_id;
            groupItem.memo = serializeServiceItemMemo({
              ...groupMemo,
              connectedPraise: {
                groupId,
                role: ordinal === 0 ? "primary" : "secondary",
                primaryItemId: groupItemIds[0],
                itemIds: groupItemIds,
                title: groupTitle,
              },
            });
          });
          continue;
        }
        let song = resolvePresenterPreparationSong(content, item, service);
        if (!song && !serviceItemRequiresNewHymnalScoreSong(item)) {
          try {
            song = await createBlankPraiseSongForServiceInput(content, service, item);
            if (song) createdSongTitles.push(song.title || content);
          } catch (error) {
            errors.push(error.message || `${entry.label} 빈 곡을 만들지 못했습니다.`);
            continue;
          }
        }
        if (!song) {
          errors.push(`${entry.label} 곡을 찬양 DB에서 하나로 찾지 못했습니다.`);
          continue;
        }
        if (serviceItemRequiresNewHymnalScoreSong(item) && !isNewHymnalScoreSong(song)) {
          errors.push(`${entry.label}은 새찬송가 곡만 선택할 수 있습니다.`);
          continue;
        }
        item.song_id = song.id;
        item.version_id = null;
        item.song_version_id = null;
        item.raw_title = "";
        if (assignee) item.assignee = assignee;
        item._worshipElementTemplateModified = true;
        markServiceItemSharedContentDirty(item, service);
        item._worshipTemplatePlaceholder = false;
        const defaultVersion = defaultServiceSongVersion(song, item, service);
        item.version_id = defaultVersion?.id || null;
        if (serviceSongHasMultipleSelectableVersions(song, item, service)) versionWarnings.push(entry.label);
        item.song_version_id = item.version_id;
        continue;
      }

      if (servicePraiseUsesDirectLyrics(mode)) {
        item.version_id = null;
        item.song_version_id = null;
        item.raw_title = content;
        if (assignee) item.assignee = assignee;
        item._worshipElementTemplateModified = true;
        markServiceItemSharedContentDirty(item, service);
        item._worshipTemplatePlaceholder = false;
        item.memo = serializeServiceItemMemo({
          ...memo,
          elementType: "praise",
          inputMode: mode,
          outputMode: "lyrics",
        });
        continue;
      }

      if (mode === "scripture" || isScriptureBodyServiceItem(item)) {
        const references = normalizeServiceScriptureReferenceList(content);
        if (!references.length || references.some((reference) => !parseBibleReference(reference))) {
          errors.push(`${entry.label}의 성경 주소를 확인해 주세요.`);
          continue;
        }
        item.raw_title = formatServiceScriptureReferenceList(references);
        item._worshipElementTemplateModified = true;
        markServiceItemSharedContentDirty(item, service);
        item._worshipTemplatePlaceholder = false;
        item.memo = serializeServiceItemMemo({
          ...memo,
          elementType: "scripture_body",
          inputMode: "scripture",
          scriptureReference: references[0] || "",
          scriptureReferences: references,
          slides: [],
        });
        scriptureItemIds.add(item.id);
        continue;
      }

      if (entry.key === "대표기도" || entry.rawKey === "대표기도") {
        item.assignee = assignee || content;
      } else if ((entry.rawKey || entry.key) === "설교" && isPresenterPreparationSermonTitleItem(item) && !assignee && presenterPreparationContentLooksAssignee(content)) {
        item.assignee = content;
      } else if (assignee) {
        item.raw_title = normalizeServiceItemRawTitleForItem(item, content);
        item.assignee = assignee;
      } else {
        item.raw_title = normalizeServiceItemRawTitleForItem(item, content);
      }
      item._worshipElementTemplateModified = true;
      markServiceItemSharedContentDirty(item, service);
      item._worshipTemplatePlaceholder = false;
      textFieldUpdates.push({
        id: item.id,
        slotKey: serviceItemSlotKey(item),
        sectionKey: item._worshipSectionKey || "",
        label: item.label,
        assignee: item.assignee,
        raw_title: item.raw_title,
        memo: item.memo,
      });
    }

    if (citationReferences) {
      const citations = presenterPreparationCitationItems(service, items, citationReferences);
      if (citations.error) errors.push(citations.error);
      else {
        items = citations.items;
        citations.citationIds.forEach((id) => scriptureItemIds.add(id));
      }
    }

    if (errors.length) {
      showToast(errors[0], "error");
      return;
    }

    finalizePresenterPreparationApply({
      service, serviceId, items, entries, skipped, scriptureItemIds, textFieldUpdates,
      createdSongTitles, versionWarnings,
    });
    applied = true;
  } finally {
    state.presenterPreparationApplyingServiceIds.delete(serviceId);
    renderServiceList();
    if (applied && options.focusTarget) focusPresenterPreparationTarget(serviceId, options.focusTarget);
  }
}

function presenterServiceInputItem(item, service) {
  const model = serviceItemEditorModel(item, { service });
  const memo = model.parsed || parseServiceItemMemo(item.memo);
  const inputMode = model.song ? servicePraiseInputMode(item, memo, service) : serviceMemoInputMode(memo, item);
  if (serviceItemCanReplaceBenediction(item, memo)) return { mode: "benediction", model, memo };
  if (presenterServiceInputIsStatic(item, memo)) return null;
  if (inputMode === "none" || inputMode === "config") return null;
  if (servicePraiseUsesDirectLyrics(inputMode)) return { mode: "text", model, memo };
  return { mode: inputMode, model, memo };
}

function presenterServiceInputIsStatic(item = {}, memo = parseServiceItemMemo(item.memo)) {
  const label = compactSearchValue(item.label || "");
  const sectionKey = String(item._worshipSectionKey || "").trim();
  const service = state.services.find((service) => service.id === item?.service_id) || null;
  const usesSharedSundayContent = Boolean(sharedSundayContentSourceItem(item, service));
  return !isPresenterReferenceMediaItem(item, memo) && (isServicePreparationItemForEditor(item, memo)
    || (Boolean(presenterFixedTitleText(item)) && !independentServiceContentTitle(item.label, item.raw_title, serviceMemoElementType(memo)))
    || isPublicFixedDoxologyServiceItem(
      item,
      memo,
      state.services.find((candidate) => candidate.id === item?.service_id) || null,
    )
    || (isLiturgicalBodyServiceItem(item) && !isAnnouncementTextInputItem(item))
    || isConfessionPrayerServiceItem(item)
    || usesSharedSundayContent
    || label === "환영"
    || (sectionKey === "announcements" && !isAnnouncementTextInputItem(item))
    || sectionKey === "closing_visual");
}

function presenterServiceInputControls(item, index, service, options = {}) {
  const context = presenterServiceInputItem(item, service);
  if (!context) return "";
  const { mode, model, memo } = context;
  const offeringToggle = options.offeringToolbar ? "" : renderServiceOfferingSpecialToggle(item, service);
  if (mode === "benediction") return `
    ${memo.benedictionReplacement ? "" : renderPresenterServiceTextInputs(item, index, model, memo)}
    <button class="btn ghost" type="button" data-service-benediction-toggle="${memo.benedictionReplacement ? "benediction" : "lords_prayer"}"
      data-service-id="${escapeAttr(service.id)}" data-service-item-id="${escapeAttr(item.id)}">
      <i data-lucide="repeat-2"></i>${memo.benedictionReplacement ? "축도로 되돌리기" : "주기도문으로 변경"}
    </button>`;
  if (isMonthlyCorporatePrayerGroupItem(item, memo)) {
    return renderPresenterMonthlyCorporatePrayerInputs(item, index, memo, service?.id || model?.service?.id);
  }
  if (["praise_db", "score_db", "lyrics_db", "children_audio"].includes(mode)) {
    return renderPresenterServicePraiseInput(item, index, model, options) + offeringToggle;
  }
  if (mode === "scripture") {
    return renderPresenterServiceScriptureInput(item, index, memo, service);
  }
  if (mode === "asset") {
    return renderPresenterServiceAssetInput(item, index, memo, options) + offeringToggle;
  }
  return renderPresenterServiceTextInputs(item, index, model, memo) + offeringToggle;
}

function presenterServiceTextInputSpec(item, model, memo) {
  const elementType = serviceMemoElementType(memo);
  const label = compactSearchValue(item.label || "");
  const monthlyCorporatePrayerGroup = isMonthlyCorporatePrayerGroupItem(item, memo);
  const specialSong = isSpecialSongServiceItem(item);
  const manualPraise = servicePraiseUsesDirectLyrics(servicePraiseInputMode(item, memo, model?.service));
  const genericTitle = presenterTitleAssigneeTitleIsGeneric(item.raw_title || "", item.label || "");
  const needsTitle = manualPraise
    || (!monthlyCorporatePrayerGroup && /설교(?:제목)?|특송|공동기도/.test(label))
    || serviceTitlePersonNeedsTitleInput(item, memo)
    || specialSong
    || isAnnouncementTextInputItem(item)
    || (Boolean(String(item.raw_title || "").trim()) && !genericTitle && elementType !== "title_person");
  const needsAssignee = (
    elementType === "title_person" && !monthlyCorporatePrayerGroup
  ) || specialSong;
  return { needsTitle, needsAssignee };
}

function presenterServiceRequiredTextInputState(item = {}, model = null, memo = parseServiceItemMemo(item.memo), service = null) {
  const { needsTitle, needsAssignee } = presenterServiceTextInputSpec(item, model, memo);
  const titlePersonParts = serviceMemoElementType(memo) === "title_person"
    ? serviceTitlePersonEffectiveParts(item, memo, service)
    : null;
  const rawText = String(item?.raw_title || item?.title || "").trim();
  const titleText = titlePersonParts?.rawTitleAssignee
    ? ""
    : (presenterTitleAssigneeTitleIsGeneric(rawText, item?.label || "") ? "" : rawText);
  const assignee = titlePersonParts?.assignee || cleanServiceAssignee(item?.assignee);
  const missingTitle = needsTitle && !titleText;
  const missingAssignee = needsAssignee && !assignee;
  return {
    needsTitle,
    needsAssignee,
    titleText,
    assignee,
    missingTitle,
    missingAssignee,
    missingReason: missingTitle ? "title_empty" : missingAssignee ? "assignee_empty" : "",
    complete: !missingTitle && !missingAssignee,
  };
}

function isAnnouncementTextInputItem(item = {}) {
  const label = compactSearchValue(item?.label || "");
  if (["청소년부광고", "청년부광고"].includes(label)) return true;
  return label === "광고"
    && String(item._worshipSectionKey || item.section_key || "") === "announcements"
    && ["body", "plain_text"].includes(serviceMemoElementType(parseServiceItemMemo(item.memo)));
}

function presenterServiceInputHasEditableField(item, service) {
  const context = presenterServiceInputItem(item, service);
  if (!context) return false;
  if (context.mode === "benediction") return true;
  if (isMonthlyCorporatePrayerGroupItem(item, context.memo)) return true;
  if (["praise_db", "score_db", "lyrics_db", "children_audio", "scripture", "asset"].includes(context.mode)) return true;
  if (context.mode === "text" && servicePraiseUsesDirectLyrics(servicePraiseInputMode(item, context.memo, service))) return true;
  const { needsTitle, needsAssignee } = presenterServiceTextInputSpec(item, context.model, context.memo);
  return needsTitle || needsAssignee;
}

function renderPresenterServicePraiseInput(item, index, model, options = {}) {
  const assigneeLabel = presenterServiceAssigneeInputLabel(item);
  return `
    <div class="svc-presenter-input-field svc-presenter-input-field--song" role="group" aria-label="찬양 입력">
      <span>찬양</span>
      ${renderServiceEditorTitleControl(item, index, { service: model.service, titleAriaLabel: "곡명", hideProgression: options.headerActions }, model)}
    </div>
    ${model.showAssignee ? `
      <label class="svc-presenter-input-field svc-presenter-input-field--assignee">
        <input class="svc-presenter-input-control" type="text" data-service-item-field="assignee" data-service-item-index="${index}"
          value="${escapeAttr(model.assigneeValue || "")}" placeholder="${escapeAttr(assigneeLabel)}" aria-label="${escapeAttr(`${item.label || "항목"} 담당`)}" />
      </label>` : ""}`;
}

function renderPresenterServiceScriptureInput(item, index, memo, service = null) {
  const serviceId = service?.id || item?.service_id || state.selectedServiceId;
  const draftValue = deferredServiceScriptureReferenceDraftValue(serviceId, index);
  const references = draftValue === null
    ? serviceItemScriptureReferences(item, memo, service)
    : normalizeServiceScriptureReferenceList(draftValue);
  const value = draftValue === null && references.length
    ? formatServiceScriptureReferenceList(references)
    : draftValue === null
      ? normalizeServiceItemReferenceSpacing(memo.scriptureReference || item.raw_title || "")
      : draftValue;
  const draftProblem = serviceScriptureDraftProblem(item, value);
  const citation = isPresenterCitationScriptureItem(item);
  const selectedTranslationId = serviceItemBibleTranslation(item, memo)?.id || "";
  const perReferencePayloads = normalizeServiceScriptureReferencePayloads(memo.scriptureReferencePayloads, references);
  const payloadByReference = new Map(perReferencePayloads.map((payload) => [normalizeServiceScriptureReferenceKey(payload.reference), payload]));
  const legacyManual = references.length === 1 ? normalizeServiceManualScripture(memo.manualScripture) : null;
  const translationEditorKey = JSON.stringify([serviceId, item.id || index]);
  const perReferenceControls = citation && references.length ? `
    <details class="svc-presenter-input-field svc-presenter-input-field--scripture-parts" data-citation-translations="${escapeAttr(translationEditorKey)}" ${MindexDisclosure.attrs(["citation-translations",serviceId,item.id||index])}>
      <summary>인용별 역본</summary>
      <div class="svc-presenter-scripture-parts">
        ${references.map((reference, referenceIndex) => {
          const payload = payloadByReference.get(normalizeServiceScriptureReferenceKey(reference)) || {};
          const manual = legacyManual || normalizeServiceManualScripture(payload.manualScripture);
          const selectedId = payload.scriptureTranslationId || selectedTranslationId;
          const hasManual = Boolean(manual?.verses?.length || payload.manualTranslationLabel || payload.manualInput);
          return `
            <div class="svc-presenter-scripture-part">
              <div class="svc-presenter-scripture-part-head">
                <strong>${escapeHtml(reference)}</strong>
                <select class="svc-presenter-input-control" data-service-item-field="scripture_reference_translation_id" data-service-item-index="${index}" data-scripture-reference-index="${referenceIndex}" aria-label="${escapeAttr(`${reference} 역본`)}">
                  <option value=""${!hasManual && !selectedId ? " selected" : ""}>기본 역본</option>
                  ${state.bibleTranslations.map((translation) => `
                    <option value="${escapeAttr(translation.id)}"${!hasManual && translation.id === selectedId ? " selected" : ""}>${escapeHtml(serviceBibleTranslationDisplayLabel(translation))}</option>`).join("")}
                  <option value="__manual__"${hasManual ? " selected" : ""}>직접 입력</option>
                </select>
              </div>
              <div class="svc-presenter-scripture-manual"${hasManual ? "" : " hidden"}>
                <input class="svc-presenter-input-control" type="text" data-service-item-field="manual_scripture_translation_label" data-service-item-index="${index}" data-scripture-reference-index="${referenceIndex}"
                  value="${escapeAttr(manual?.translationLabel || payload.manualTranslationLabel || "")}" placeholder="역본명 (예: 새한글성경)" aria-label="${escapeAttr(`${reference} 수동 역본명`)}" />
                <textarea class="svc-presenter-input-control" data-service-item-field="manual_scripture_text" data-service-item-index="${index}" data-scripture-reference-index="${referenceIndex}"
                  rows="3" placeholder="7 본문&#10;8 본문" aria-label="${escapeAttr(`${reference} 수동 본문`)}">${escapeHtml(formatServiceManualScriptureInput(manual))}</textarea>
              </div>
            </div>`;
        }).join("")}
      </div>
    </details>` : "";
  return `
    <label class="svc-presenter-input-field svc-presenter-input-field--scripture">
      <div class="svc-presenter-input-control-wrap">
        <input class="svc-presenter-input-control${draftProblem ? " is-invalid" : ""}" type="text" aria-invalid="${Boolean(draftProblem)}" title="${escapeAttr(draftProblem)}"
          data-service-item-field="raw_title" data-service-item-index="${index}"
          value="${escapeAttr(value)}" list="serviceScriptureOptions" placeholder="말씀 (예: ${serviceItemSupportsScriptureReferenceList(item) ? "렘 3:22; 마 3:11" : "출애굽기 23:14-19"})" aria-label="${escapeAttr(`${item.label || "성경"} 구절`)}" />
        ${renderServiceItemLinkControl(item, index)}
      </div>
    </label>
    ${perReferenceControls}`;
}

function isMonthlyCorporatePrayerGroupItem(item = {}, memo = parseServiceItemMemo(item?.memo)) {
  const sectionKey = String(item?._worshipSectionKey || item?.section_key || "").trim();
  const ordinals = String(item?.label || "").match(/\d+/g)?.map(Number) || [];
  const pairedMonthlyLabel = /^공동기도/.test(compactSearchValue(item?.label || ""))
    && ([1, 2].every((ordinal, index) => ordinals[index] === ordinal)
      || [3, 4].every((ordinal, index) => ordinals[index] === ordinal));
  return sectionKey === "corporate_prayer"
    && serviceMemoElementType(memo) === "title_person"
    && (memo.templateKey === "monthly_corporate_prayer_group" || pairedMonthlyLabel);
}

function normalizeCorporatePrayers(entries = []) {
  return (Array.isArray(entries) ? entries : []).slice(0, 2).map((entry) => ({
    title: String(entry?.title || "").trim(),
    assignee: String(entry?.assignee || "").trim(),
    sourceElementId: String(entry?.sourceElementId || "").trim(),
  }));
}

function monthlyCorporatePrayerDefaultTopics() {
  return [
    "교회 부흥을 위해",
    "선교와 민족을 위해",
    "치유와 회복을 위해",
    "교회학교를 위해",
  ];
}

function monthlyCorporatePrayerEntries(item, memo = parseServiceItemMemo(item?.memo)) {
  const stored = normalizeCorporatePrayers(memo.corporatePrayers);
  if (stored.length === 2) return stored;
  const defaults = monthlyCorporatePrayerOrdinalsForItem(item)
    .map((ordinal) => monthlyCorporatePrayerDefaultTopics()[ordinal - 1] || "");
  return [0, 1].map((index) => ({
    // Preserve a partially saved group exactly; only the missing slot needs a fallback.
    ...(stored[index] || {
      title: String(memo.slides?.[index] || defaults[index] || ""),
      assignee: "",
      sourceElementId: "",
    }),
  }));
}

function mergeMonthlyCorporatePrayerItems(items = []) {
  let result = [...items];
  for (const start of [1, 3]) {
    const inSection = (item) => templateProjectionSectionKey(item) === "corporate_prayer";
    const label = `공동기도 ${start}·${start + 1}`;
    const groups = result.filter((item) => inSection(item) && item.label === label);
    const members = [start, start + 1].map((ordinal) => result.filter((item) => inSection(item)
      && compactSearchValue(item.label) === `공동기도${ordinal}`));
    if (groups.length > 1 || members.some((list) => list.length > 1)) continue;
    const group = groups[0];
    const groupMemo = group ? parseServiceItemMemo(group.memo) : null;
    if (groupMemo?.corporatePrayers?.length === 2) {
      const incorporated = new Set(groupMemo.corporatePrayers.map((entry) => entry.sourceElementId).filter(Boolean));
      result = result.filter((item) => item === group || !inSection(item) || !incorporated.has(item.id));
      continue;
    }
    if (members.some((list) => list.length !== 1)) continue;
    const pair = members.map((list) => list[0]);
    const comparableTitle = (value) => String(value || "").trim().replace(/^['"“”‘’]+|['"“”‘’]+$/g, "");
    if (groupMemo?.slides?.some((title, index) => title && comparableTitle(title) !== comparableTitle(pair[index]?.raw_title))) continue;
    if (pair.some((item) => {
      const memo = parseServiceItemMemo(item.memo);
      return item.song_id || serviceMemoElementType(memo) !== "title_person"
        || memo.slides.length || memo.note || hasServiceAsset(memo.asset) || hasServiceAsset(memo.audioAsset)
        || memo.hiddenInPresentation || memo.templateSuppressed;
    })) continue;
    const base = group || pair[0];
    const prayers = pair.map((item) => ({ title: String(item.raw_title || ""), assignee: String(item.assignee || ""), sourceElementId: item.id }));
    const merged = { ...base, label, raw_title: label, assignee: "",
      _worshipSlotKey: `prayer.corporate.${start}${start + 1}`,
      _worshipElementOrder: start === 1 ? 1 : 3,
      _worshipElementTemplateModified: true,
      memo: serializeServiceItemMemo({ ...parseServiceItemMemo(base.memo),
        elementType: "title_person", templateKey: "monthly_corporate_prayer_group",
        corporatePrayers: prayers, slides: [] }),
    };
    const insertion = Math.min(...[group, ...pair].filter(Boolean).map((item) => result.indexOf(item)));
    result = result.filter((item) => item !== group && !pair.includes(item));
    result.splice(insertion, 0, merged);
  }
  return result;
}

function monthlyCorporatePrayerOrdinalsForItem(item = {}) {
  const ordinals = String(item?.label || "")
    .match(/\d+/g)
    ?.map((value) => Number(value))
    .filter((value) => Number.isFinite(value) && value > 0) || [];
  if (ordinals.length) return ordinals.slice(0, 2);
  const compact = compactSearchValue(item?.label || "");
  return compact.includes("34") ? [3, 4] : [1, 2];
}

function renderPresenterMonthlyCorporatePrayerInputs(item, index, memo, serviceId = state.selectedServiceId) {
  const ordinals = monthlyCorporatePrayerOrdinalsForItem(item);
  const prayers = monthlyCorporatePrayerEntries(item, memo);
  const topics = prayers.map((entry) => entry.title);
  const serviceIdAttr = serviceId ? ` data-service-id="${escapeAttr(serviceId)}"` : "";
  return `
    <div class="svc-presenter-input-group svc-presenter-input-group--corporate-prayer">
      ${ordinals.map((ordinal, topicIndex) => `
        <div class="svc-presenter-input-field" role="group" aria-label="${escapeAttr(`공동기도 ${ordinal}`)}">
          <span>${escapeHtml(`공동기도 ${ordinal}`)}</span>
          <input class="svc-presenter-input-control" type="text" data-service-item-field="corporate_prayer_topic"
            data-service-item-index="${index}"${serviceIdAttr} data-corporate-prayer-topic-index="${topicIndex}"
            value="${escapeAttr(String(topics[topicIndex] || "").replace(/^['"“”‘’]+|['"“”‘’]+$/g, ""))}"
            placeholder="기도 제목" onkeydown="handleDetailKeydown(event)" aria-label="${escapeAttr(`공동기도 ${ordinal} 제목`)}" />
          <input class="svc-presenter-input-control" type="text" data-service-item-field="corporate_prayer_assignee"
            data-service-item-index="${index}"${serviceIdAttr} data-corporate-prayer-topic-index="${topicIndex}"
            value="${escapeAttr(prayers[topicIndex].assignee)}" placeholder="담당"
            aria-label="${escapeAttr(`공동기도 ${ordinal} 담당`)}" />
        </div>`).join("")}
    </div>`;
}

function renderPresenterAssetUpload(item, index, memo, serviceId) {
  const reference = isPresenterReferenceMediaItem(item, memo);
  const asset = normalizeServiceAsset(memo.asset);
  const kind = asset.kind || serviceMemoElementType(memo);
  const acceptsMultiple = reference || kind === "image";
  return `<label class="svc-reference-media-upload">
    <input type="file" ${acceptsMultiple ? "multiple" : ""} accept="${escapeAttr(memo.mediaPlacement ? "image/*" : reference ? PRESENTER_REFERENCE_MEDIA_ACCEPT : serviceAssetFileAcceptForKind(kind))}"
      ${reference ? "data-presenter-reference-media-file" : "data-service-item-asset-file"}
      data-service-id="${escapeAttr(serviceId)}" data-service-item-index="${index}" />
    <i data-lucide="upload"></i><span>${kind === "image" ? "이미지 추가" : "파일 선택"}</span>
  </label>${asset.pptx ? `<label class="svc-reference-media-upload"><input type="file" accept=".pptx" data-presenter-pptx-file data-service-id="${escapeAttr(serviceId)}" data-service-item-index="${index}" aria-label="PPT 교체" /><i data-lucide="presentation"></i><span>PPT 교체</span></label>` : ""}`;
}

function renderPresenterServiceAssetInput(item, index, memo, options = {}) {
  const asset = normalizeServiceAsset(memo.asset);
  const elementType = serviceMemoElementType(memo);
  const serviceId = item.service_id || state.selectedServiceId;
  if (isPresenterReferenceMediaItem(item, memo)) {
    const detectedKind = presenterReferenceMediaKindForSource(asset.url);
    const kind = asset.pptx ? "imported_deck" : detectedKind || (["image", "video", "audio"].includes(elementType) ? elementType : "image");
    const needsKindSelection = Boolean(asset.url && !detectedKind);
    return `
      <div class="svc-reference-media-input">
        ${renderPresenterMediaPlacementInput(item, serviceId)}
        <div class="svc-reference-media-toolbar">
          ${needsKindSelection ? `<label class="svc-presenter-input-field">
            <span>종류</span>
            <select class="svc-presenter-input-control" data-service-item-field="element_type" data-service-item-index="${index}" data-service-id="${escapeAttr(serviceId)}" aria-label="참고 화면 종류">
              <option value="image"${kind === "image" ? " selected" : ""}>이미지</option>
              <option value="video"${kind === "video" ? " selected" : ""}>영상</option>
              <option value="audio"${kind === "audio" ? " selected" : ""}>음원</option>
            </select>
          </label>` : detectedKind ? `<span class="svc-reference-media-kind">${escapeHtml(serviceAssetFileKindLabel(kind))}</span>` : ""}
          ${options.headerActions ? "" : renderPresenterAssetUpload(item, index, memo, serviceId)}
        </div>
        <label class="svc-presenter-input-field svc-reference-media-title">
          <input class="svc-presenter-input-control" type="text" data-service-item-field="asset_name" data-service-item-index="${index}" data-service-id="${escapeAttr(serviceId)}"
            value="${escapeAttr(asset.name)}" placeholder="참고 화면 제목" aria-label="참고 화면 제목" />
        </label>
        ${renderPresenterServiceAssetUrlInput(asset, index, serviceId, "참고 화면 공개 링크", "공개 링크", "파일을 선택하거나 공개 URL 입력")}
        ${renderPresenterReferenceMediaPreview(asset, kind, [serviceId,item.id||index])}
        ${renderPresenterMediaOrder(item, serviceId)}
      </div>`;
  }
  const kind = ["image", "video", "audio"].includes(elementType) ? elementType : "";
  const assetKind = asset.kind && asset.kind !== kind ? asset.kind : kind || asset.kind || elementType || "file";
  const typeLabel = serviceAssetFileKindLabel(assetKind || elementType);
  return `
    <div class="svc-reference-media-input svc-reference-media-input--asset svc-reference-media-input--${escapeAttr(assetKind)}">
      <div class="svc-reference-media-toolbar svc-reference-media-toolbar--asset">
        ${options.headerActions ? "" : renderPresenterAssetUpload(item, index, memo, serviceId)}
      </div>
      <label class="svc-presenter-input-field svc-reference-media-title">
        <input class="svc-presenter-input-control" type="text" data-service-item-field="asset_name" data-service-item-index="${index}" data-service-id="${escapeAttr(serviceId)}"
          value="${escapeAttr(asset.name)}" placeholder="${escapeAttr(`${typeLabel} 이름`)}" aria-label="${escapeAttr(`${item.label || "파일"} 이름`)}" title="${escapeAttr(asset.name)}" />
      </label>
      ${renderPresenterServiceAssetUrlInput(asset, index, serviceId, `${item.label || "파일"} 링크`, "파일/링크", "파일을 선택하거나 공개 URL 입력")}
      ${renderPresenterReferenceMediaPreview(asset, assetKind, [serviceId,item.id||index])}
    </div>`;
}

function renderPresenterServiceAssetUrlInput(asset, index, serviceId, ariaLabel, label, placeholder) {
  const source = String(asset?.url || "").trim();
  if (source) {
    return `<input type="hidden" data-service-item-field="asset_url" data-service-item-index="${index}" data-service-id="${escapeAttr(serviceId)}" value="${escapeAttr(source)}" />`;
  }
  return `
    <label class="svc-presenter-input-field">
      <span>${escapeHtml(label)}</span>
      <input class="svc-presenter-input-control" type="text" data-service-item-field="asset_url" data-service-item-index="${index}" data-service-id="${escapeAttr(serviceId)}"
        value="" placeholder="${escapeAttr(placeholder)}" aria-label="${escapeAttr(ariaLabel)}" />
    </label>`;
}

function renderPresenterReferenceMediaPreview(asset, kind, disclosureScope = []) {
  const source = String(asset?.url || "").trim();
  if (!source) return "";
  const normalizedKind = String(kind || asset?.kind || "file").trim().toLowerCase();
  const slides = normalizeServiceAssetSlides(asset.slides);
  const slideCount = slides.length;
  const statusLabel = normalizedKind === "imported_deck"
    ? (slideCount ? `${asset.pptx ? "PPT · " : ""}슬라이드 ${slideCount}장 연결됨` : "슬라이드 연결됨")
    : normalizedKind === "video" ? "영상 연결됨"
      : normalizedKind === "audio" ? "음원 연결됨"
        : normalizedKind === "image" ? (slideCount > 1 ? `이미지 ${slideCount}장 연결됨` : "이미지 연결됨") : "파일 연결됨";
  const icon = normalizedKind === "imported_deck" ? "presentation"
    : normalizedKind === "video" ? "file-video"
      : normalizedKind === "audio" ? "audio-lines"
        : normalizedKind === "image" ? "image" : "file";
  const name = String(asset?.name || "").trim() || statusLabel;
  const previewLabel = ["image", "video"].includes(normalizedKind) ? "미리보기" : normalizedKind === "audio" ? "듣기" : "파일 정보";
  const body = normalizedKind === "image"
    ? `<img data-reference-media-preview-image src="${escapeAttr(source)}" alt="${escapeAttr(name)}" loading="lazy" onerror="handlePresenterMediaPreviewError(this)" />
       <span data-reference-media-preview-error role="status" hidden>이미지를 불러오지 못했습니다. 파일 연결을 확인해 주세요.</span>`
    : normalizedKind === "audio"
      ? `<audio controls preload="metadata" src="${escapeAttr(source)}"></audio>`
      : normalizedKind === "video" ? renderPresenterInputVideoPreview(source, name)
        : renderPresenterStaticAssetPreview(asset.pptx ? { ...asset, url: asset.pptx.url } : asset, icon, statusLabel);
  const slideStrip = normalizedKind === "image" && slideCount > 1
    ? `<div class="svc-reference-media-slide-strip" aria-label="연결된 이미지 ${slideCount}장">
      ${slides.map((slide, index) => {
        const slideName = String(slide.name || `${index + 1}번 이미지`).trim();
        return `<button type="button" class="svc-reference-media-slide-chip" data-reference-media-slide="${escapeAttr(slide.url)}" data-reference-media-name="${escapeAttr(slideName)}" aria-label="${escapeAttr(`${index + 1}. ${slideName} 미리보기`)}" aria-pressed="${index === 0}" title="${escapeAttr(`${index + 1}. ${slideName}`)}">
          <img src="${escapeAttr(slide.url)}" alt="${escapeAttr(slideName)}" loading="lazy" onerror="handlePresenterMediaPreviewError(this)" />
          <span class="svc-reference-media-slide-error" data-reference-media-preview-error hidden>불러오기 실패</span>
          <span class="svc-reference-media-slide-caption">${escapeHtml(`${index + 1}. ${slideName}`)}</span>
        </button>`;
      }).join("")}
    </div>`
    : "";
  return `<div class="svc-reference-media-preview-group">
    <details ${normalizedKind === "video" ? 'ontoggle="pauseClosedPresenterInputVideo(this)"' : ""} class="svc-reference-media-preview svc-reference-media-preview--collapsible svc-reference-media-preview--${escapeAttr(normalizedKind)}" ${MindexDisclosure.attrs(["media-preview",...disclosureScope])}>
      <summary>
        <span>${escapeHtml(statusLabel)}</span>
        <b><i data-lucide="${normalizedKind === "audio" ? "headphones" : normalizedKind === "image" ? "eye" : "info"}"></i>${previewLabel}</b>
      </summary>
      <div class="svc-reference-media-preview-content">${body}${slideStrip}</div>
    </details>
  </div>`;
}

function handlePresenterMediaPreviewError(image) {
  image.hidden = true;
  const message = image.parentElement?.querySelector("[data-reference-media-preview-error]");
  if (message) message.hidden = false;
}

function selectPresenterMediaPreviewSlide(button) {
  const group = button.closest(".svc-reference-media-preview-group");
  const image = group?.querySelector("[data-reference-media-preview-image]");
  const details = group?.querySelector("details");
  if (!image || !details) return;
  const message = group.querySelector("[data-reference-media-preview-error]");
  if (message) message.hidden = true;
  image.hidden = false;
  image.alt = button.dataset.referenceMediaName || "이미지";
  image.src = button.dataset.referenceMediaSlide;
  details.open = true;
  group.querySelectorAll("[data-reference-media-slide]").forEach((candidate) => {
    candidate.setAttribute("aria-pressed", String(candidate === button));
  });
}

function renderPresenterStaticAssetPreview(asset, icon, statusLabel) {
  const name = String(asset?.name || "").trim() || statusLabel;
  return `
    <div class="svc-reference-media-preview svc-reference-media-preview--file">
      <i data-lucide="${escapeAttr(icon)}"></i>
      <strong title="${escapeAttr(name)}">${escapeHtml(name)}</strong>
      <span>${escapeHtml(statusLabel)}</span>
    </div>`;
}

function renderPresenterManualLyricsField(item, index, serviceId = "") {
  const key = JSON.stringify([serviceId, item.id || index]);
  const expanded = MindexDisclosure.read(["presenter-lyrics",key]);
  const lyrics = formatServiceManualPraiseLyricsInput(item.memo);
  const title = expanded ? "가사 접기" : "가사 펼치기";
  return `<div class="svc-presenter-input-field svc-presenter-input-field--lyrics${expanded ? "" : " is-collapsed"}">
    <span class="svc-presenter-lyrics-heading">가사<button class="icon-btn" type="button" data-presenter-lyrics-toggle="${escapeAttr(key)}" aria-expanded="${expanded}" aria-label="${title}" title="${title}"><i data-lucide="${expanded ? "chevron-up" : "chevron-down"}"></i></button></span>
    <textarea class="svc-presenter-input-control svc-presenter-input-control--multiline" data-service-item-field="manual_praise_lyrics" data-service-item-index="${index}"
      rows="${expanded ? Math.max(2, Math.min(12, lyrics.split("\n").length)) : 3}" placeholder="가사를 붙여 넣으세요.&#10;빈 줄마다 슬라이드가 나뉩니다." onkeydown="handleDetailKeydown(event)" aria-label="${escapeAttr(`${item.label || "특송"} 가사`)}">${escapeHtml(lyrics)}</textarea>
  </div>`;
}

function renderPresenterServiceTextInputs(item, index, model, memo) {
  const { needsTitle, needsAssignee } = presenterServiceTextInputSpec(item, model, memo);
  const manualPraise = servicePraiseUsesDirectLyrics(servicePraiseInputMode(item, memo, model?.service));
  if (!needsTitle && !needsAssignee && !manualPraise) return "";
  const specialSong = isSpecialSongServiceItem(item);
  const announcementText = isAnnouncementTextInputItem(item);
  const titleLabel = presenterServiceTitleInputLabel(item, memo, { manualPraise });
  const titlePlaceholder = presenterServiceTitleInputPlaceholder(item, memo, titleLabel);
  const assigneeLabel = presenterServiceAssigneeInputLabel(item);
  const assigneePlaceholder = assigneeLabel;
  return `
    ${announcementText ? renderServiceAnnouncementEditor(item,index,model?.service?.id,memo):""}
    ${needsTitle && !announcementText ? `
      <label class="svc-presenter-input-field">
        ${presenterServiceTitleFieldShowsLabel(titleLabel) ? `<span>${escapeHtml(titleLabel)}</span>` : ""}
        ${manualPraise ? renderServiceEditorTitleControl(item, index, { service: model?.service, hideFormControls: true }, model) : `
          <input class="svc-presenter-input-control" type="text" data-service-item-field="raw_title" data-service-item-index="${index}"
            value="${escapeAttr(model.titleValueOverride ?? item.raw_title ?? "")}" placeholder="${escapeAttr(titlePlaceholder)}" onkeydown="handleDetailKeydown(event)" ${specialSong ? `autocomplete="off" spellcheck="false"` : ""} aria-label="${escapeAttr(`${item.label || "항목"} ${titleLabel}`)}" />`}
      </label>` : ""}
    ${manualPraise ? renderPresenterManualLyricsField(item, index, model?.service?.id || state.presenter.serviceId) : ""}
    ${needsAssignee ? `
      <label class="svc-presenter-input-field">
        <input class="svc-presenter-input-control" type="text" data-service-item-field="assignee" data-service-item-index="${index}"
          value="${escapeAttr(model.assigneeValue || "")}" placeholder="${escapeAttr(assigneePlaceholder)}" onkeydown="handleDetailKeydown(event)" aria-label="${escapeAttr(`${item.label || "항목"} 담당`)}" />
      </label>` : ""}`;
}

function presenterServiceTitleInputLabel(item = {}, memo = parseServiceItemMemo(item?.memo), options = {}) {
  if (isSpecialSongServiceItem(item) || options.manualPraise) return "찬양";
  if (isScriptureBodyServiceItem(item) || isScriptureServiceLabel(item?.label || "")) return "말씀";
  if (isAnnouncementTextInputItem(item)) return "내용";
  return "제목";
}

function presenterServiceTitleFieldShowsLabel(label = "") {
  return !["제목", "내용"].includes(label);
}

function presenterServiceTitleInputPlaceholder(item = {}, memo = parseServiceItemMemo(item?.memo), label = presenterServiceTitleInputLabel(item, memo)) {
  if (label === "찬양") return "곡명";
  if (label === "말씀") return "성경 구절";
  if (isAnnouncementTextInputItem(item)) return "내용을 입력";
  return "제목";
}

function presenterServiceAssigneeInputLabel() {
  return "담당";
}

function serviceItemAssigneeInputLabel(item = {}) {
  return "담당";
}

function renderPresenterControlsTop(service, slides, active, index) {
  const count = slides.length;
  const safeIndex = clampPresenterIndex(index, count);
  const activeSlide = slides[safeIndex] || null;
  const showLiveScriptureControl = (state.presenter.serviceId === service.id && state.presenter.liveScripture?.active) || presenterSlideIsLiveScriptureElement(activeSlide);
  const current = active && state.presenter.safetyBlank ? 0 : count ? safeIndex + 1 : 0;
  const anyOutputOpen = isPresenterOutputWindowOpen();
  const outputOpen = active && anyOutputOpen;
  const outputOpenElsewhere = anyOutputOpen && state.presenter.serviceId && state.presenter.serviceId !== service.id;
  const outputConnected = active && isPresenterOutputHeartbeatOpen();
  const outputPending = active
    && !outputConnected
    && Boolean(state.presenter.outputPendingAt)
    && state.presenter.outputAttemptServiceId === service.id;
  const outputPendingDelayed = outputPending
    && Date.now() - state.presenter.outputPendingAt > PRESENTER_OUTPUT_HEARTBEAT_TTL_MS * 2;
  const outputBlocked = !anyOutputOpen
    && Boolean(state.presenter.outputBlockedAt)
    && state.presenter.outputAttemptServiceId === service.id
    && Date.now() - state.presenter.outputBlockedAt <= PRESENTER_OUTPUT_HEARTBEAT_TTL_MS * 3;
  const jumpInputValue = active && state.presenter.jumpDraft
    ? state.presenter.jumpDraft
    : (count || current === 0 ? current : "");
  const statusLabel = outputBlocked
    ? "창 열기 실패"
    : outputPending
      ? outputPendingDelayed ? "연결 지연" : "연결 중"
      : outputOpen
    ? uiText("presenter.status.live")
    : outputOpenElsewhere
      ? uiText("presenter.status.otherLive")
      : uiText("presenter.status.ready");
  const statusTone = outputBlocked ? "blocked" : outputPending ? "pending" : outputOpen ? "live" : outputOpenElsewhere ? "other" : "ready";
  const mode = presenterControllerMode(service, { active, count, current, outputOpen, outputOpenElsewhere, safeIndex });
  const warmup = presenterOutputWarmupUiState(service.id, { active, outputOpen });
  const launchAction = anyOutputOpen ? "stop" : "open";
  const launchLabel = uiText(anyOutputOpen ? "presenter.action.stop" : "presenter.action.present");
  const launchIcon = anyOutputOpen ? "screen-share-off" : "screen-share";
  const launchTone = anyOutputOpen ? "stop" : "start";
  const remoteLabel = window.MindexRemote?.buttonLabel() || "원격 조작";
  const fullscreenLabel = anyOutputOpen ? "송출 화면 전체 화면" : "송출을 시작하면 전체 화면을 사용할 수 있습니다";
  const fullscreenControl = `<button class="icon-btn svc-presenter-fullscreen svc-presenter-window-button" type="button" data-presenter-action="fullscreen" aria-label="${escapeAttr(fullscreenLabel)}" title="${escapeAttr(fullscreenLabel)}" ${anyOutputOpen ? "" : "disabled"}><i data-lucide="maximize"></i><span>전체 화면</span></button>`;
  return `
      <div class="svc-presenter-top">
        <div class="svc-presenter-output-group">
          <div class="svc-presenter-display-slot">${renderPresenterScreenControl()}</div>
          <button class="svc-present-btn svc-presenter-launch svc-presenter-launch--${launchTone}${anyOutputOpen ? " is-stop" : ""}" type="button" data-presenter-action="${escapeAttr(launchAction)}" data-service-id="${escapeAttr(service.id)}" aria-label="${escapeAttr(launchLabel)}">
            <i data-lucide="${escapeAttr(launchIcon)}"></i>
            <span>${escapeHtml(launchLabel)}</span>
          </button>
          <div class="svc-presenter-window-controls">
          ${anyOutputOpen ? fullscreenControl : `<span class="svc-presenter-disabled-control" title="${escapeAttr(fullscreenLabel)}">${fullscreenControl}</span>`}
          </div>
          ${renderPresenterAlwaysOnTopControl({ buttonStyle: true })}
          <button class="icon-btn" type="button" data-presenter-remote aria-label="${escapeAttr(/^\d{6}$/.test(remoteLabel) ? "원격 연결 코드 " + remoteLabel : remoteLabel)}" title="${escapeAttr(remoteLabel)}" ${["연결 준비", "종료 중"].includes(remoteLabel) ? "disabled" : ""}><i data-lucide="smartphone"></i><span data-remote-button-label>${escapeHtml(remoteLabel)}</span></button>
          <button class="icon-btn" type="button" data-presenter-music-manager popovertarget="globalPlaybackPanel" aria-label="미디어 관리" title="미디어 관리"><i data-lucide="video"></i><span>미디어 관리</span></button>
        </div>
        <div class="svc-presenter-main" aria-live="polite">
          <span class="svc-slide-counter" aria-label="${escapeAttr(uiText("presenter.aria.slideCount", { current, count }))}">
            <span class="svc-presenter-mini-label">${escapeHtml(uiText("presenter.label.slide"))}</span>
            <input class="svc-slide-jump-input" type="number" inputmode="numeric" min="0" max="${escapeAttr(count || 1)}" value="${escapeAttr(jumpInputValue)}" data-presenter-jump-input data-service-id="${escapeAttr(service.id)}" aria-label="${escapeAttr(uiText("presenter.aria.slideNumber"))}" ${count ? "" : "disabled"} />
            <span>/ ${escapeHtml(count)}</span>
          </span>
          <button class="icon-btn" type="button" data-presenter-action="jump" data-presenter-index="${active && state.presenter.safetyBlank ? safeIndex : -1}" data-service-id="${escapeAttr(service.id)}" aria-label="${active && state.presenter.safetyBlank ? "암전 해제" : "암전"}" title="${active && state.presenter.safetyBlank ? "암전 해제" : "암전"}" aria-pressed="${Boolean(active && state.presenter.safetyBlank)}" ${count && outputOpen ? "" : "disabled"}><i data-lucide="${active && state.presenter.safetyBlank ? "eye" : "eye-off"}"></i></button>
          <button class="icon-btn" type="button" data-presenter-action="return" data-service-id="${escapeAttr(service.id)}" aria-label="직전 송출 슬라이드로 돌아가기" title="직전 송출 슬라이드로 돌아가기" ${presenterReturnTarget(service.id) ? "" : "disabled"}><i data-lucide="undo-2"></i></button>
          <span class="svc-presenter-action-group svc-presenter-action-group--nav" aria-label="${escapeAttr(uiText("presenter.aria.slideNav"))}">
            <button class="icon-btn" type="button" data-presenter-action="prev" data-service-id="${escapeAttr(service.id)}" ${count ? "" : "disabled"} aria-label="${escapeAttr(uiText("presenter.action.prev"))}" title="${escapeAttr(uiText("presenter.action.prev"))}">
              <i data-lucide="chevron-left"></i>
            </button>
            <button class="icon-btn" type="button" data-presenter-action="next" data-service-id="${escapeAttr(service.id)}" ${count ? "" : "disabled"} aria-label="${escapeAttr(uiText("presenter.action.next"))}" title="${escapeAttr(uiText("presenter.action.next"))}">
              <i data-lucide="chevron-right"></i>
            </button>
          </span>
        </div>
        <div class="svc-presenter-actions">
          ${renderPresenterLiveStatusPanel(service, slides, {
            active,
            safeIndex,
            statusLabel,
            statusTone,
            mode,
            warmup,
            outputOpen,
            outputOpenElsewhere,
          })}
          <span class="svc-presenter-action-group svc-presenter-action-group--scripture" ${showLiveScriptureControl ? "" : "hidden"}>
            ${renderLiveScriptureControl(service.id)}
          </span>
        </div>
      </div>`;
}

function renderPresenterLiveStatusPanel(service, slides = [], options = {}) {
  const previewSlide = presenterLiveStatusPreviewSlide(slides, options.safeIndex, options);
  const previewTitle = presenterLiveStatusPreviewTitle(previewSlide, options);
  return `
    <aside class="svc-presenter-live-panel${options.outputOpen ? " is-live" : ""}" aria-label="송출 미리보기" aria-live="polite">
      <div class="svc-presenter-live-copy">
        <span class="svc-presenter-live-label">${previewSlide?.pptx ? `PPT 정지 미리보기 · 클릭 ${presenterPptxStep(state.presenter, previewSlide)}/${Number(previewSlide.pptx.clicks) || 0}` : "미리보기"}</span>
        ${previewSlide?.pptx?.mediaCount && options.outputOpen ? `<span class="svc-presenter-action-group" aria-label="PPT 영상·음원 제어">
          <button type="button" class="icon-btn" data-presenter-action="pptx-play" data-service-id="${escapeAttr(service.id)}" aria-label="PPT 영상·음원 재생" title="PPT 영상·음원 재생"><i data-lucide="play"></i></button>
          <button type="button" class="icon-btn" data-presenter-action="pptx-pause" data-service-id="${escapeAttr(service.id)}" aria-label="PPT 영상·음원 일시정지" title="PPT 영상·음원 일시정지"><i data-lucide="pause"></i></button>
        </span>` : ""}
        <span class="svc-presenter-state-group">
          <span class="svc-presenter-status svc-presenter-status--${escapeAttr(options.statusTone || "ready")}" aria-label="${escapeAttr(uiText("presenter.aria.status", { status: options.statusLabel || "" }))}">${escapeHtml(options.statusLabel || "")}</span>
          ${options.mode?.label ? `<span class="svc-presenter-mode svc-presenter-mode--${escapeAttr(options.mode.tone)}" aria-label="${escapeAttr(uiText("presenter.aria.mode", { mode: options.mode.label }))}">${escapeHtml(options.mode.label)}</span>` : ""}
          ${options.warmup ? `<span class="svc-presenter-warmup svc-presenter-warmup--${escapeAttr(options.warmup.tone)}" aria-label="${escapeAttr(options.warmup.aria)}">${escapeHtml(options.warmup.label)}</span>` : ""}
        </span>
        <div class="svc-presenter-preview-caption">
          <strong title="${escapeAttr(previewTitle)}">${escapeHtml(previewTitle)}</strong>
          <div class="svc-presenter-video-health" data-presenter-video-health data-service-id="${escapeAttr(service.id)}">${options.outputOpen ? renderPresenterVideoHealthControl(service.id) : ""}</div>
        </div>
      </div>
      <div class="svc-presenter-live-preview" aria-hidden="true">
        ${previewSlide ? renderPresenterSlideMiniPreview(previewSlide, service.id) : `<span class="svc-presenter-live-preview-empty"></span>`}
      </div>
    </aside>`;
}

function renderPresenterVideoHealthControl(serviceId) {
  const health = state.presenter.videoHealth;
  if (!health || health.serviceId !== serviceId || serviceId !== state.presenter.serviceId
    || health.index !== state.presenter.index || state.presenter.safetyBlank || state.presenter.liveScripture?.active
    || Date.now() - health.receivedAt > 5000) return "";
  const labels = { loading: "영상 불러오는 중", error: "영상 재생 실패", paused: "영상 일시정지 · 송출 창 확인", blocked: "자동재생 차단" };
  const label = labels[health.status];
  if (!label) return "";
  const retry = ["error", "paused", "blocked"].includes(health.status);
  return `<span role="status">${label}</span>${retry ? `<button type="button" class="icon-btn" data-presenter-action="retry-video" data-service-id="${escapeAttr(serviceId)}" aria-label="영상 재생 재시도" title="영상 재생 재시도"><i data-lucide="rotate-cw"></i></button>` : ""}`;
}

function syncPresenterVideoHealthControl() {
  window.MindexRemote?.notify();
  renderGlobalPlaybackControls();
  document.querySelectorAll("[data-presenter-video-health]").forEach((host) => {
    const html = renderPresenterVideoHealthControl(host.dataset.serviceId);
    if (host.dataset.healthMarkup === html) return;
    host.dataset.healthMarkup = html;
    host.innerHTML = html;
    refreshIcons(host);
  });
}

function presenterLiveStatusPreviewSlide(slides = [], safeIndex = 0, options = {}) {
  if (!options.active || !options.outputOpen) return null;
  if (state.presenter.liveScripture?.active && state.presenter.liveScripture.slide) return state.presenter.liveScripture.slide;
  if (state.presenter.safetyBlank) return presenterSafetyBlankSlide();
  return slides[clampPresenterIndex(safeIndex, slides.length)] || null;
}

function presenterLiveStatusPreviewTitle(slide = null, options = {}) {
  if (options.outputOpenElsewhere) return "다른 예배 송출 중";
  if (!options.outputOpen) return "송출 대기";
  if (state.presenter.safetyBlank) return "빈 화면";
  if (state.presenter.liveScripture?.active) return state.presenter.liveScripture.reference || slide?.title || "실시간 말씀";
  return String(slide?.title || slide?.label || slide?.elementTitle || slide?.text || "현재 화면").split(/\r?\n/)[0].trim() || "현재 화면";
}

function presenterSlideIsLiveScriptureElement(slide = null) {
  if (!slide) return false;
  return Boolean(slide.liveScriptureControl)
    || presenterSlideElementType(slide) === PRESENTER_ELEMENT_TYPES.LIVE_SCRIPTURE;
}

function presenterControlsClassName(active, chromakey) {
  return `svc-presenter-strip${active ? " is-active" : ""}${chromakey ? "" : " is-clean-output"}`;
}

function presenterControllerIsLive(serviceId = state.selectedServiceId) {
  return Boolean(serviceId && state.presenter.serviceId === serviceId && isPresenterOutputWindowOpen());
}

function presenterSlideInteractionHint(serviceId, title = "슬라이드") {
  return `${title} 선택 · 더블클릭해 송출`;
}

function presenterBoardActiveIndex(slides, active, index) {
  if (!active || !presenterControllerIsLive(state.presenter.serviceId) || state.presenter.safetyBlank || state.presenter.liveScripture?.active) return -1;
  return clampPresenterIndex(index, slides.length);
}

function presenterSlideRenderKeyText(slide = {}) {
  const value = `${slide?.title || ""}\u0000${slide?.text || ""}\u0000${slide?.bodyText || ""}`;
  if (value.length <= 96) return value;
  return `${value.length}:${value.slice(0, 64)}:${value.slice(-24)}`;
}

function presenterControlBoardKey(service, slides = [], active = false, chromakey = true) {
  const theme = presenterOutputTheme(service?.type_id);
  const slideKey = slides.map((slide, index) => [
    index,
    slide?.id || "",
    slide?.type || "",
    presenterSlideElementType(slide),
    presenterSlideLayout(slide),
    slide?.formKey || "",
    slide?.marker || "",
    slide?.imageSrc || "",
    slide?.videoSrc || "",
    slide?.audioSrc || "",
    presenterSlideRenderKeyText(slide),
  ].join(":")).join("|");
  const scriptureDraftKey = [...deferredServiceScriptureReferenceDrafts.entries()]
    .filter(([key]) => key.startsWith(`${service?.id || ""}:`))
    .map(([key, value]) => `${key}=${value}`)
    .join("|");
  // Escape control characters before round-tripping this key through HTML attributes.
  return JSON.stringify([
    service?.id || "",
    theme,
    chromakey ? "chroma" : "clean",
    active ? "active" : "preview",
    presenterControllerIsLive(service?.id) ? "live" : "offline",
    globalThis.MindexSongTiming?.revision || 0,
    slides.length,
    slideKey,
    scriptureDraftKey,
  ]);
}

function presenterOutputWarmupUiState(serviceId, options = {}) {
  const warmup = state.presenter.outputWarmup;
  if (!options.active || !options.outputOpen || !warmup) return null;
  if (warmup.serviceId && serviceId && warmup.serviceId !== serviceId) return null;
  if (Date.now() - (Number(warmup.updatedAt) || 0) > PRESENTER_OUTPUT_HEARTBEAT_TTL_MS * 2) return null;
  const total = Math.max(0, Number(warmup.total) || 0);
  if (!total) return null;
  const ready = Math.max(0, Math.min(total, Number(warmup.ready) || 0));
  const complete = Boolean(warmup.complete) || ready >= total;
  return {
    label: complete ? "이미지 준비 완료" : `이미지 준비 ${ready}/${total}`,
    tone: complete ? "ready" : "warming",
    aria: complete ? "출력 이미지 준비 완료" : `출력 이미지 준비 중 ${ready} / ${total}`,
  };
}

function presenterControllerMode(service, context = {}) {
  if (context.outputOpenElsewhere) return { label: uiText("presenter.mode.otherService"), tone: "other" };
  if (!context.active) return { label: "", tone: "preview" };
  if (state.presenter.safetyBlank) return { label: uiText("presenter.mode.blank"), tone: "blank" };
  if (state.presenter.liveScripture?.active) return { label: uiText("presenter.mode.scripture"), tone: "scripture" };
  if (context.count) return { label: uiText("presenter.mode.slide", { number: context.safeIndex + 1 }), tone: context.outputOpen ? "slide-live" : "slide-ready" };
  return { label: uiText("presenter.mode.noSlides"), tone: "empty" };
}

function serviceMusicSourceIsSlotOwned(source = state.serviceMusic.sourceKey) {
  return Boolean(source) && Object.values(SERVICE_SLOT_MUSIC).some(config => config.source === source);
}

function renderServiceMusicPlayer(options = {}) {
  const slotOwned = !options.source && serviceMusicSourceIsSlotOwned();
  const music = slotOwned ? { ...state.serviceMusic, sourceKey: "", sourceLabel: "", objectUrl: "", fileName: "", playing: false, pending: false } : state.serviceMusic;
  const context = slotOwned ? {} : currentPresenterAudioContext();
  const activeLabel = music.sourceLabel && music.sourceKey ? music.sourceLabel : "";
  const fileLabel = activeLabel || context.label || (music.fileName ? music.fileName : uiText("presenter.music.default"));
  const hasSource = Boolean(options.source || music.sourceKey || context.source || music.objectUrl);
  const inline = Boolean(options.source);
  const active = !inline || options.source === music.sourceKey && options.serviceId === music.ownerServiceId;
  const pending = active && music.pending;
  const playing = active && !pending && music.playing;
  const key = pending ? "loading" : playing ? "playing" : "idle";
  const volumePercent = Math.round(music.volumeLevel * 20);
  return `
    <span class="svc-music-player${inline ? " svc-music-player--inline" : ""}" data-service-music-player data-service-music-service-id="${escapeAttr(options.serviceId || "")}" data-service-music-source="${escapeAttr(options.source || "")}" data-service-music-label="${escapeAttr(options.label || "")}" data-service-music-repeat-allowed="${options.repeatAllowed !== false}">
      ${inline ? `<span class="svc-music-label">${escapeHtml(options.label)}</span>` : `
      <input class="svc-music-file" type="file" accept="audio/*" data-service-music-file hidden />
      <button class="svc-music-name" type="button" data-service-music-action="choose" title="음악 선택">
        <i data-lucide="${context.source ? "volume-2" : "music"}"></i>
        <span>${escapeHtml(fileLabel)}</span>
      </button>
      `}
      <span class="svc-music-transport">
      ${hasSource ? `
        <button class="icon-btn svc-music-toggle" type="button" data-service-music-action="toggle" data-playback-state="${key}" aria-busy="${Boolean(pending)}" aria-pressed="${Boolean(playing)}" aria-label="${pending ? "음악 준비 중, 누르면 취소" : playing ? "일시정지" : "재생"}">
          <i data-lucide="${pending ? "loader-circle" : playing ? "pause" : "play"}"></i>${inline ? pending ? "준비 중" : playing ? "일시정지" : "재생" : ""}
        </button>
        ${inline ? `<button type="button" class="icon-btn" data-service-music-action="stop" aria-label="음악 정지" ${active && (music.pending || music.playing || music.audio?.currentTime) ? "" : "disabled"}><i data-lucide="square"></i></button>` : ""}
        ${options.repeatAllowed !== false && music.repeatAllowed !== false ? `<button class="icon-btn svc-music-repeat" type="button" data-service-music-action="repeat" aria-label="음악 반복 재생" aria-pressed="${Boolean(music.repeat ?? context.playback?.loop)}"><i data-lucide="repeat"></i></button>` : ""}
        <span class="svc-volume-control">
          <i data-lucide="volume-2" aria-hidden="true"></i>
          <input class="svc-music-volume" type="range" min="0" max="5" step="0.05" value="${music.volumeLevel}" data-service-music-volume aria-label="${escapeAttr(uiText("presenter.music.volume"))}" aria-valuetext="${volumePercent}%">
          <output data-service-music-volume-value aria-hidden="true">${volumePercent}%</output>
        </span>` : ""}
      </span>
      ${inline ? globalThis.MindexSongTiming?.transport({ source: options.source, serviceId: options.serviceId }) || "" : ""}
    </span>`;
}

function renderLiveScriptureControl(serviceId) {
  const live = state.presenter.serviceId === serviceId ? state.presenter.liveScripture || {} : {};
  const draft = state.presenterScriptureDrafts?.[serviceId] ?? live.draft ?? live.reference ?? "";
  return `
    <span class="svc-live-scripture${live.active ? " is-active" : ""}">
      <input class="svc-live-scripture-input" type="text" value="${escapeAttr(draft)}" data-live-scripture-input data-service-id="${escapeAttr(serviceId)}" placeholder="${escapeAttr(uiText("presenter.scripture.placeholder"))}" />
      <button class="icon-btn svc-action-text-btn svc-live-scripture-show" type="button" data-live-scripture-action="show" data-service-id="${escapeAttr(serviceId)}" aria-label="${escapeAttr(uiText("presenter.action.showScripture"))}" title="${escapeAttr(uiText("presenter.action.showScripture"))}">
        <i data-lucide="send"></i>
        <span>${escapeHtml(uiText("presenter.action.send"))}</span>
      </button>
      <button class="icon-btn svc-action-text-btn svc-live-scripture-clear" type="button" data-live-scripture-action="clear" data-service-id="${escapeAttr(serviceId)}" aria-label="${escapeAttr(uiText("presenter.action.hideScripture"))}" title="${escapeAttr(uiText("presenter.action.hideScripture"))}" ${live.active ? "" : "disabled"}>
        <i data-lucide="eye-off"></i>
        <span>${escapeHtml(uiText("presenter.action.hide"))}</span>
      </button>
    </span>`;
}

const SERVICE_SLOT_MUSIC = Object.freeze({
  "prayer.meeting.free": { source: "./assets/presenter/friday-free-prayer.m4a?v=faststart-20260919", label: "자율기도 음악", repeatAllowed: false },
});

let serviceMusicWarmup = null;
function warmServiceSlotMusic(target) {
  const button = target?.closest?.('[data-service-music-action="toggle"]');
  const source = button?.closest('[data-service-music-player]')?.dataset.serviceMusicSource;
  if (!source || !Object.values(SERVICE_SLOT_MUSIC).some(item => item.source === source)
      || source === state.serviceMusic.sourceKey || serviceMusicWarmup?.source === source) return;
  // Separate metadata-only request: never select, replace, or play the shared audio.
  const audio = new Audio();
  const warmup = {source, audio};
  serviceMusicWarmup = warmup;
  audio.preload = "metadata";
  audio.muted = true;
  const finish = (retry = false) => {
    clearTimeout(warmup.timer);
    audio.removeAttribute("src");
    audio.load();
    if (retry && serviceMusicWarmup === warmup) serviceMusicWarmup = null;
  };
  audio.addEventListener("loadedmetadata", () => finish(), {once:true});
  audio.addEventListener("error", () => finish(true), {once:true});
  warmup.timer = setTimeout(() => finish(true), 10000);
  audio.src = source;
}

function renderServiceSlotMusic(context) {
  const config = SERVICE_SLOT_MUSIC[context?.item?._worshipSlotKey];
  if (!config) return "";
  return renderServiceMusicPlayer({ ...config, serviceId: context.service?.id || "" });
}

function updateServiceMusicTransportControls() {
  window.MindexRemote?.notify();
  renderGlobalPlaybackControls();
  syncPresenterFocusMusic();
  const music = state.serviceMusic;
  document.querySelectorAll("[data-service-music-player]").forEach(root => {
    const source = root.dataset.serviceMusicSource;
    const slotOwned = !source && serviceMusicSourceIsSlotOwned();
    const transport = root.querySelector(".svc-music-transport");
    if (transport) transport.hidden = slotOwned;
    const active = !slotOwned && (!source || (source === music.sourceKey && root.dataset.serviceMusicServiceId === music.ownerServiceId));
    const pending = active && music.pending;
    const playing = active && !pending && music.playing;
    const key = pending ? "loading" : playing ? "playing" : "idle";
    const toggle = root.querySelector('[data-service-music-action="toggle"]');
    if (toggle) {
      if (toggle.dataset.playbackState !== key) {
        toggle.innerHTML = `<i data-lucide="${pending ? "loader-circle" : playing ? "pause" : "play"}"></i>${source ? pending ? "준비 중" : playing ? "일시정지" : "재생" : ""}`;
        toggle.dataset.playbackState = key;
        refreshIcons(toggle);
      }
      toggle.setAttribute("aria-busy", String(Boolean(pending)));
      toggle.setAttribute("aria-pressed", String(Boolean(playing)));
      toggle.setAttribute("aria-label", pending ? "음악 준비 중, 누르면 취소" : playing ? "일시정지" : "재생");
    }
    const stop = root.querySelector('[data-service-music-action="stop"]');
    if (stop) stop.disabled = !active || !(music.pending || music.playing || music.audio?.currentTime);
    const repeat = root.querySelector('[data-service-music-action="repeat"]');
    if (repeat) {
      repeat.hidden = music.repeatAllowed === false;
      repeat.setAttribute("aria-pressed", String(Boolean(music.repeat)));
    }
    const volume = root.querySelector('[data-service-music-volume]');
    if (volume) {
      volume.value = String(music.volumeLevel);
      volume.setAttribute("aria-valuetext", `${Math.round(music.volumeLevel * 20)}%`);
    }
    const volumeValue = root.querySelector("[data-service-music-volume-value]");
    if (volumeValue) volumeValue.textContent = `${Math.round(music.volumeLevel * 20)}%`;
  });
}

function handleGlobalPlaybackAction(event) {
  // Safari does not focus buttons on pointer clicks. Give the native popover
  // a stable return target without overriding outside-click focus.
  event.target.closest('.global-playback-trigger')?.focus({ preventScroll: true });
  const button = event.target.closest("[data-global-playback-action]");
  if (!button) return;
  const action = button.dataset.globalPlaybackAction;
  if (action.startsWith("video-")) { void runPresenterManagedVideoAction(action.slice(6)); return; }
  if (action === "return") { void returnToLiveService(); return; }
  if (action === "output-stop") {
    if (isPresenterOutputWindowOpen()) runPresenterAction("stop", state.presenter.serviceId);
    return;
  }
  if (!["toggle", "stop"].includes(action)) return;
  const music = state.serviceMusic;
  const binding = serviceMusicSourceIsSlotOwned() ? {
    serviceMusicSource: music.sourceKey,
    serviceMusicServiceId: music.ownerServiceId,
    serviceMusicLabel: music.sourceLabel,
    serviceMusicRepeatAllowed: String(music.repeatAllowed !== false),
  } : null;
  void runServiceMusicAction(action, binding);
}

function visibleGlobalPlaybackTrigger() {
  return [...document.querySelectorAll(".global-playback-trigger, [data-presenter-music-manager]")].find(button => button.getClientRects().length);
}

function positionGlobalPlaybackPanel() {
  const panel = document.getElementById("globalPlaybackPanel");
  const trigger = visibleGlobalPlaybackTrigger();
  if (!panel || !trigger) return;
  const rect = trigger.getBoundingClientRect();
  const top = Math.min(rect.bottom + 8, window.innerHeight - 40);
  panel.style.left = `clamp(8px, ${rect.left}px, calc(100vw - min(320px, calc(100vw - 16px)) - 8px))`;
  panel.style.top = `${top}px`;
  panel.style.maxHeight = `${Math.max(24, window.innerHeight - top - 8)}px`;
}

function renderGlobalPlaybackControls() {
  const root = document.getElementById("globalPlaybackControls");
  if (!root) return;
  const music = state.serviceMusic;
  const hasMusic = Boolean(music.sourceKey && music.audio);
  const musicState = music.fadeStop ? "음악 서서히 정지 중" : music.pending ? "음악 준비 중" : music.playing ? "음악 재생 중"
    : music.audio?.currentTime ? "음악 일시정지" : "음악 정지";
  const toggleLabel = music.pending ? "음악 준비 취소" : music.playing ? "음악 일시정지" : "음악 재생";
  const icon = music.pending ? "loader-circle" : music.playing ? "pause" : "play";
  const video = presenterManagedVideoState();
  const available = hasMusic || !!video || state.module === "presenter";
  const html = `<button class="icon-btn global-playback-trigger" type="button" popovertarget="globalPlaybackPanel" title="미디어 관리" aria-label="미디어 관리" data-active="${Boolean(music.playing || music.pending || video?.status === "playing")}"><i data-lucide="video"></i><span class="global-playback-indicator" aria-hidden="true"></span></button>
    <section id="globalPlaybackPanel" class="global-playback-panel" popover aria-label="미디어 관리">
      <header class="global-playback-panel-head"><strong>미디어 관리</strong><button class="icon-btn" type="button" popovertarget="globalPlaybackPanel" popovertargetaction="hide" aria-label="미디어 관리 닫기"><i data-lucide="x"></i></button></header>
      <section class="global-media-section" aria-label="음원"><h3>음원</h3>
      <p class="global-playback-empty" ${hasMusic ? "hidden" : ""}>선택된 음악이 없습니다.</p>
      <div class="global-playback-group" role="group" aria-label="현재 음악" ${hasMusic ? "" : "hidden"}>
        <span class="global-playback-label"><span class="global-playback-name">${escapeHtml(music.sourceLabel || music.fileName || "음악")}</span><span class="global-playback-state" role="status">${musicState}</span></span>
      </div>
      ${globalThis.MindexSongTiming?.transport() || ""}
      <div class="global-playback-actions" role="group" aria-label="음악 재생 제어" ${hasMusic ? "" : "hidden"}>
        <button type="button" class="btn secondary" data-global-playback-action="toggle" title="${toggleLabel}" aria-label="${toggleLabel}" aria-pressed="${Boolean(music.playing)}"><i data-lucide="${icon}"></i><span>${music.pending ? "준비 취소" : music.playing ? "일시정지" : "재생"}</span></button>
        <button type="button" class="btn secondary global-playback-stop" data-global-playback-action="stop" aria-label="음악 정지" ${music.pending || music.playing || music.audio?.currentTime ? "" : "disabled"}><i data-lucide="square"></i><span>정지</span></button>
        <label class="global-playback-fade-stop"><input type="checkbox" data-service-music-fade-stop${music.fadeStopEnabled ? " checked" : ""}>페이드아웃 정지</label>
      </div>
      </section>
      ${renderPresenterVideoManagement(video)}
    </section>`;
  if (!available) root.querySelector(':popover-open')?.hidePopover();
  root.hidden = !available;
  if (root._playbackMarkup === html) { syncPresenterVideoTransport(video); return; }
  root._playbackMarkup = html;
  const template = document.createElement("template");
  template.innerHTML = html;
  refreshIcons(template.content);
  if (root.childNodes.length) {
    const next = root.cloneNode(false);
    next.append(template.content);
    patchPresenterControlTree(root, next);
  } else root.append(template.content);
  if (root.querySelector(":popover-open")) positionGlobalPlaybackPanel();
  syncPresenterVideoTransport(video);
}

function renderLiveServiceReturnControl() {
  const button = document.getElementById("returnLiveServiceBtn");
  if (button) button.hidden = true;
  renderGlobalPlaybackControls();
}

async function returnToLiveService() {
  if (!isPresenterOutputWindowOpen() || !(await confirmSaveBeforeLeaving())) return;
  const id = state.presenter.serviceId;
  const service = state.services.find(item => item.id === id);
  if (!service || !isPresenterOutputWindowOpen()) return;
  saveCurrentListScroll();
  markWorshipServiceExplicitlyRequested(id);
  state.presenter.viewServiceId = id;
  state.selectedServiceId = id;
  state.selectedServiceTypeId = service.type_id;
  state.presenterBulletinServiceId = null;
  state.module = "presenter";
  state.search = "";
  refs.searchInput.value = "";
  clearBibleTextSearch();
  persistUiState();
  render();
  syncBrowserHistory();
}

// ─── end Service module ───────────────────────────────────────────────────────

window.Mindex = {
  normalizeTitle,
  normalizeForms,
  displayLabel,
  computePartNumberSuggestion,
  formatFullLyrics,
  formatScriptureForCopy,
  formatScriptureSlidesForCopy,
  formatFreeShowShowJson,
  formatSongXml,
  buildFreeShowShow,
};
